window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_002"]={"n":"陈恭尹","dyn":"清","poems":[{"t":"读秦纪","f":"七言绝句","c":["谤声易弭怨难除，秦法虽严亦甚疏。","夜半桥边呼孺子，人间犹有未烧书。"]},{"t":"厓门谒三忠祠","f":"七言律诗","c":["山木萧萧风又吹，两厓波浪至今悲。","一声望帝啼荒殿，十载愁人拜古祠。","海水有门分上下，江山无地限华夷。","停舟我亦艰难日，畏向苍苔读旧碑。"]},{"t":"虎丘题壁","f":"七言律诗","c":["虎迹苍茫霸业沈，古时山色尚阴阴。","半楼月影千家笛，万里天涯一夜砧。","南国干戈征士泪，西风刀剪美人心。","市中亦有吹篪客，乞食吴门秋又深。"]},{"t":"宿高台寺","f":"五言古诗","c":["山南势盘郁，开豁独斯宇。","中天置茅屋，上与祝融伍。","阶下俯众峰，窗间括南土。","夜冥江火近，日出寒檐雨。","托宿此最高，终身未更数。"]},{"t":"王将军挽歌","f":"五言古诗","c":["南方有义士，姓王名曰兴。","十三学杀人，十五手搏狼。","三十建义旗，姓名惊一方。","天子锡虎符，作镇鼍江阳。","翠华日以远，地绝军弥张。","百战环冈州，九死披残疆。","海滨富斥卤，重林与连冈。","高者掩云日，远者浮沧茫。","煮波致财货，铸冶成刀枪。","宫室何所居，天家侯与王。","稿粟何所馈，从驾子与娘。","心胆何所赠，海内豪与英。","献客合浦珠，薰客珠厓香。","客处未觉寒，袄褥先盈箱。","客寝始觉单，妻妾忽侍旁。","敌兵四面来，众士各逞强。","将军跃上马，命客持一觞。","独出挥长戈，两目流电光。","直取首来将，生挟归戎行。","顾饮所持酒，昔热犹未凉。","相持及三月，敌骑皆奔亡。","来时三万人，半还仍重伤。","奏功自间道，涉瘴徂昆明。","黄金三千镒，玉帛各有筐。","天驷方驱驰，下臣效刍浆。","臣兴昧死上，帝曰兴卿良。","赉爵列五等，高兽盘银章。","其名曰虎贲，将军荡南荒。","敌人闻之惧，选士盈千骑。","来者左右贤，其军督责之。","不得此弹丸，若辈何生为。","上天仍助虐，其年兼荐饥。","将军察天命，命匠搜良材。","斫以为巨棺，彩霎悬葳蕤。","约日出合战，敌怯不敢来。","坚壁十里外，迤逦兴长围。","沟垒内外防，突援无所施。","始从戊戌夏，两及中秋期。","战士饭草土，抱骨还登陴。","所忧负将军，吾侪死犹归。","将军曰呜呼，共尽终何裨。","我乃报深恩，汝当存宗支。","乃命幼子九，先出卑其辞。","卜吉结欢会，敌将不致疑。","是夜一更终，将军诀所知。","皎月当中天，千秋同此时。","语已还闭门，沐浴更裳衣。","夫人翠凤冠，有母头如丝。","侍妾十五人，左右皆肩随。","肃肃何雍雍，俱集园东陲。","上有古梅树，樛结垂高枝。","白石为几席，月露明苍苔。","将军命夫人，拜别而慈闱。","拜毕与将军，四拜中间居。","十五妾罗拜，窈窕无参差。","夫人命斗酒，有脯形如圭。","深藏待今夕，各当行一卮。","卮尽且先起，母与君稍须。","将军及母入，烛影何迷离。","夫人十五妾，自挂临中闺。","阿母大惊呼，将军言勿悲。","著我锦绣袍，麒麟当心开。","戴我七梁冠，簪缨郁崔嵬。","玉带与玺书，次第皆抱怀。","置敕中堂上，花烛荣且辉。","望阙遥谢恩，臣死有馀辜。","下阶十二拜，天地及四隅。","徘徊望西堂，有虎顾其儿。","平生爱此图，拜汝今同灰。","卷图附敕下，释服趋房间。","房中何穹隆，火药堆如山。","将军踏小几，自解夫人缳。","次及妾十五，列置火药端。","出户著朝衣，捧敕仍来还。","一声母急出，火烈焰贯天。","鸡鸣部曲入，白骨空巑岏。","举哀建素旒，合敛归巨棺。","敌人亦流涕，况在同肺肝。","卜葬三山阳，隐约题墓门。","陈子作挽歌，播之永不刊。"]},{"t":"怀古十首 其一 燕台","f":"七言律诗","c":["燕南燕北战争馀，白草漫漫雪色初。","河渡坚冰通下博，关门沙路走居胥。","死求马骨言终验，生揕秦胸计已疏。","犹有兴亡数行泪，夜来弹与乐君书。"]},{"t":"怀古十首 其二 姑苏","f":"七言律诗","c":["澹烟疏雨阖闾城，潮水千年恨未平。","宝剑赐来吴命短，美人恩重父仇轻。","宫梧叶落随流出，台鹿春归引子行。","何处扁舟人去后，铸金犹得似平生。"]},{"t":"怀古十首 其三 楚中","f":"七言律诗","c":["衡云巫雨暗江津，江上孤吟过一春。","二女庙边逢泪竹，大王风急到青蘋。","虚无玉驷朝天阙，惨澹云旗降楚神。","终古灵均词赋在，湘南山水倍关人。"]},{"t":"怀古十首 其四 咸阳","f":"七言律诗","c":["关门一夜柳条春，今古芒芒草色新。","龙虎片云终王汉，诗书馀火竟烧秦。","瑶池西望犹通鸟，渭水东流不待人。","最是五陵游侠客，年年磨剑候风尘。"]},{"t":"怀古十首 其五 沛中","f":"七言律诗","c":["汉王生长难忘处，尺土犹书故宅名。","四海自飞鸿鹄羽，中宵人哭白蛇声。","轻沙浅草堪调马，习俗群儿敢说兵。","千载英雄同一辙，徐州南是凤阳城。"]},{"t":"怀古十首 其六 洛阳","f":"七言律诗","c":["敝车驽马雒城边，盛事空凭故老传。","嵩室有声君万岁，土圭无影日中天。","礼亡已验伊川发，涕下徒伤贾傅年。","莫问汉家图画处，丹青磨灭化苔钱。"]},{"t":"怀古十首 其七 蜀中","f":"七言律诗","c":["子规啼罢客天涯，蜀道如天古所嗟。","诸葛威灵存八阵，汉朝终始在三巴。","通牛峡路连云栈，如马瞿塘走浪花。","拟酹昔贤鱼水地，海棠开遍酒人家。"]},{"t":"怀古十首 其八 邺中","f":"七言律诗","c":["山河百战鼎终分，叹息漳南日暮云。","乱世奸雄空复尔，一家词赋最怜君。","铜台未散吹笙伎，石马先传出水文。","七十二坟秋草遍，更无人表汉将军。"]},{"t":"怀古十首 其九 金陵","f":"七言律诗","c":["山飞楼阁水飞霞，冷落春城宿乳鸦。","天阙双峰铦似戟，海门高浪白如花。","空劳御辇销王气，曾画长江作帝家。","五马渡边龙化后，南方文物掩中华。"]},{"t":"怀古十首 其十 隋宫","f":"七言律诗","c":["谷洛通淮日夜流，渚荷宫树不曾秋。","十年士女河边骨，一笑君王镜里头。","月下虹蜺生水殿，天中丝管在迷楼。","繁华往事邗沟外，风起杨花无那愁。"]},{"t":"戊辰正月十日舟泊端州王础尘自开建适至令子紫巘招同李苍水过集高云客所寓华严精舍纵饮达夜即事成歌","f":"七言古诗","c":["正月溪山馀暖气，炎方别自为天地。","乘兴拿舟入峡来，故人恰自康州至。","客中无地可为欢，高君况在郊南寺。","落落乾坤数老翁，天涯想见俱憔悴。","贤郎高燕为客开，李生后至初挥杯。","登楼旷望见原野，定山数点青崔嵬。","园桃一树红如火，折向瓶中如笑我。","东风只自恋新枝，何处林间寻硕果。","年当壮盛好努力，白发生来无一可。","且烧高烛佛灯前，狂歌纵饮开新年。","东南之美略已具，人间此会非徒然，为君白眼望青天。"]},{"t":"登湛祯士新阁","f":"七言律诗","c":["新构闲斋事事幽，帘栊清寂胜前游。","疏篱引蔓时妨帽，老树扶人共上楼。","暮雨千家闻短笛，东风一绿遍平畴。","园林烟景元堪画，况有数峰来上头。"]},{"t":"八月八夜王子千招同陈韶州毅斋迟灵山屏万梁药亭廖南炜屈翁山集广州行署咏月","f":"七言律诗","c":["高会仍同赵尉楼，上弦新月近中秋。","半轮似欲依华毂，破镜唯能照白头。","银汉欹斜初雁过，金风萧瑟暮云收。","更怜一片如轻舫，明夕随君到惠州。"]},{"t":"秋夜同梁巨川卢俊斯过宿潘子登寓斋早起别去与巨川登锦岩次子登韵","f":"七言律诗","c":["步屧闲阶月满堂，更浮香茗对幽篁。","人过中岁衰难寐，酒到深更醒亦狂。","竹榻梦回馀旧泪，絺衣朝起趁新凉。","不堪共上高岩望，江水迢迢似恨长。"]},{"t":"同王阮亭宫詹黄忍庵太史高谡苑廷评张超然屈翁山两处士五羊访古作三首 其三 海珠石","f":"五言古诗","c":["泛广倦邅回，陵高苦奔峭。","江中得孤屿，足以雄登眺。","西睇苍梧云，东望罗浮峤。","遥天落峰影，远水明残照。","五羊古都会，往事堪凭吊。","中原时逐鹿，一隅常虎啸。","丸泥横浦关，左纛炎州徼。","赵刘及何冼，异曲元同调。","各自一时豪，宁贻千载诮。","兹丘隔城市，兴亡非所召。","如何游衍地，繁盛乖年少。","遗碑卧苔藓，壁垒环颓庙。","东风吹古台，归潮鸣石窍。","觞咏对同人，临流成一笑。","骊颔君所探，鱼竿吾欲钓。"]},{"t":"拜恩感赋","f":"七言律诗","c":["御史封章更表忠，诏书前后出行宫。","家门已积沦胥痛，国典犹追式遏功。","唐祀睢阳存两庙，汉崇司马列三公。","孤儿拜舞威颜下，血泪凭添汗简中。"]},{"t":"庞祖如见访","f":"五言律诗","c":["重岩行乐处，回首但云阴。","别我岁华改，逢君秋色深。","出门遍衰草，托足惟空林。","欲谢人间世，论文与素心。"]},{"t":"哭外舅湛公","f":"五言古诗","c":["硕德堪千载，高名重一时。","黄槐随凤诏，彩笔对彤墀。","下座人皆仰，微言世所思。","游轻驷马贵，归尽彩衣嬉。","问讼中途反，评才满月移。","不安林下席，将饱路傍饥。","当食推盘粟，妨民拔露葵。","郭生难得友，钟子信堪师。","以德应能寿，论年不及衰。","坏梁歌已矣，朝菌忽先之。","罢市乡人哭，怜芳楚老悲。","酸风朝飒沓，寒雨夏凄其。","吊客来飞鹤，闲窗怨子规。","自嗟逢世难，饮恨向天涯。","望海情何极，寻乡梦每疑。","烟尘销未得，书札到何迟。","昔者趋庭训，因之拜羽仪。","稍能酬客语，才解诵亲诗。","不以东床傲，殊深户牖知。","国忧期共奋，家难忽相随。","庑下依皋伯，舟中学范蠡。","提携无异父，期许欲过儿。","离别奄逾岁，风流渺莫追。","长歌泪如霰，何待岘山碑。"]},{"t":"西樵旅怀五首 其一","f":"七言律诗","c":["罗浮风暖鹧鸪啼，山下梅花客未迷。","十里娇歌传玉笛，一竿残月泊沙堤。","生存华屋人何处，营垒清秋马独嘶。","扶醉西州他日路，潘郎怀旧岂堪题。"]},{"t":"西樵旅怀五首 其二","f":"七言律诗","c":["牂牁滚滚向东流，绿浦黄龙识御舟。","初日平沙群跃马，二年杯酒独登楼。","星连牛斗曾传檄，寒报湘沅尽赐裘。","孤棹一辞天万里，几回风雨吼吴钩。"]},{"t":"西樵旅怀五首 其三","f":"七言律诗","c":["高楼斜月倒银河，长路朝天响玉珂。","雉堞影连飞旆密，马蹄香踏落花多。","风中短笛翔鹓鹭，树底轻尘散绮罗。","只有数峰名石室，著书留待史臣过。"]},{"t":"西樵旅怀五首 其四","f":"七言律诗","c":["江城北面是山家，细雨西桥石路斜。","九日归来浇绿酒，几年人去落黄花。","牙签旧架唯馀蠹，玉树空庭但噪鸦。","犹有邻翁思手泽，壁书珍重与笼纱。"]},{"t":"西樵旅怀五首 其五","f":"七言律诗","c":["涕泣经年自一身，南天回首又风尘。","低徊不死缘无子，潦倒何颜复向人。","犬马岂能忘旧主，梦魂犹恐负先臣。","西山有屋临溪水，新种桃花欲避秦。"]},{"t":"答何友大","f":"七言古诗","c":["昨夜月明梦君庐，今夜月明得君书。","书中历历何所有，半幅蛮笺诗一首。","上言所苦在有家，羡君山中看桃花。","桃花如锦覆山春，此时山中望故人。","别时有约今中止，把札自疑犹梦里。","山楼初筑西山西，山池三月草应齐。","池头濯足清溪水，何日山中与吾子。"]},{"t":"送莫休倩英卓今","f":"五言律诗","c":["手持青竹杖，相送白云端。","山里逢人少，君来作别难。","乱泉侵宿梦，疏柳隔垂竿。","舍此空归去，重期能不叹。"]},{"t":"寄家赉予","f":"七言古诗","c":["小池之南摘莲子，记得摇舟弄江水。","龙津渡头秋风起，布帆一别三百里。","飞乌西飞何其急，歌者何人怅然立。","深树凉蝉晓鸣涩，疏帘细雨当窗入。","桐叶如啼柳如烟，昨日梦君今日眠。"]},{"t":"送饶侍御石帆","f":"古风","c":["玉骢踏尽天南路，更挂征帆向何处。","林木还留海燕巢，归人却背秋鸿去。","飞云飞叶满前山，和月和霜度庾关。","庾关北下乡园迩，五老香炉相对起。","荷锄且作种瓜人，铁面人知真御史。","一疏曾令死者生，又令生者心为死。","西风寒，山酒旨。","捧离觞，酌君子。","灵蛇有珠蛟有泪，愿借丰城三尺水，报恩报仇报知己。"]},{"t":"梅子潭纪梦","f":"古风","c":["浮云离离，飒其风雨。","扁舟独寐，梦我严父。","曰嗟曰嗟，汝行良苦。","悠悠道路，矧兹鼙鼓。","自汝之先，未绝如缕。","有孑其传，于今为五。","无曰予薄，诸灵所怙。","敬汝慎汝，无忘先祖。","再拜以跽，小子稽首。","暂别我父，日月以久。","郁郁予心，如结予口。","牵衣欲言，捧亲之手。","其衣烨然，其手载温。","乃欣乃奔，乃蹶于门。","起而傍偟，尚闻其言。","疾呼我父，其人曷存。","维舟摇摇，维雨彭彭。","风回一壑，万竹之声。","牛衣转侧，如卧春冰。","行渐老大，实惭所生。","激激潭水，舟乎济之。","浩浩亲恩，心乎系之。","烈已前人，乌乎继之。","我歌我谣，庶几励之。"]},{"t":"发闽中向匡庐寄蔡艮若","f":"五言律诗","c":["劳生同逆旅，何处是他乡。","渐听人声改，才知客路长。","买舟彭蠡月，回首洛桥霜。","指却飞花笑，闲身尔亦忙。"]},{"t":"建昌河上二首 其一","f":"五言古诗","c":["十月辞西山，苍茫日东走。","迟迟闽越路，东风变杨柳。","扁舟乱河曲，旅泊成搔首。","无衣知春寒，独宿知夜久。","茕茕远行子，才知慕父母。"]},{"t":"建昌河上二首 其二","f":"五言律诗","c":["莫折棠梨花，花枝刺君手。","莫恋春风时，春风白人首。","春风低野草，遥见原与阜。","昨日少年人，长松生左肘。"]},{"t":"杂诗","f":"五言律诗","c":["骏马黑貂弓，悲歌燕市东。","少年尚意气，不数古英雄。","侠骨穷逾壮，冰心老渐空。","浮云无定所，舒卷任秋风。"]},{"t":"夜中叹","f":"七言律诗","c":["秋风萧萧吹黄榆，黄榆上有双啼乌。","寒霜满枝栖不得，夜久无人时相呼。","西樵有客匡山里，一闻此声夜中起。","十年含叹为谁来，啸倚芙蓉匣中水。"]},{"t":"过金陵不泊","f":"五言律诗","c":["故都残照在，一望尚峥嵘。","山拥吴云峻，天连楚水平。","到秋禾黍意，为客古今情。","高寝长松外，遗臣怯近城。"]},{"t":"西湖","f":"七言律诗","c":["山中麋鹿若为群，岭外双鱼杳不闻。","贫甚独存冯客剑，雪深持上岳王坟。","西湖歌舞春无价，南宋楼台暮有云。","休恨议和奸相国，大江犹得百年分。"]},{"t":"送人","f":"五言律诗","c":["不辞行数里，相送及河桥。","北路邯郸远，东风赭白骄。","归身征战后，洗耳圣明朝。","未有重期日，题书莫惮遥。"]},{"t":"忆昔","f":"五言古诗","c":["忆昔十五六，形容一何好。","高谈溢四座，宾客惊绝倒。","日月易以迈，春华岂长保。","我行如昨日，两度见青草。","天涯劳苦远，异路风霜早。","相逢少年子，自顾已枯槁。","何待两鬓白，然后始谓老。"]},{"t":"西湖杂兴四首 其一","f":"五言律诗","c":["隔江山万叠，相对不知名。","野寺宜孤梦，春风懒独行。","涧阴云乍上，林暗叶初生。","自住西湖后，何曾暂到城。"]},{"t":"西湖杂兴四首 其二","f":"五言律诗","c":["岳王犹有庙，宋帝更无宫。","水夹层城丽，山盘万户雄。","园陵深夜雨，松槚冷春风。","无泪挥前代，吴燕在眼中。"]},{"t":"西湖杂兴四首 其三","f":"五言律诗","c":["明月有相忆，天涯只自亲。","江山不可语，意气向何人。","莺踏落花暮，燕衔孤屋春。","年年别离尽，无泪与罗巾。"]},{"t":"西湖杂兴四首 其四","f":"五言律诗","c":["别来无信息，归雁入残霞。","故国应芳草，连宵梦落花。","吹篪吴市月，垂钓越溪槎。","见说佗封地，依然属汉家。"]},{"t":"京口舟中","f":"古风","c":["小小舟，长数尺。","濛濛雨，移水驿。","西风起，淫淫黑。","羁孤臣，年年客。","釜中着水当自乾，腹中着愁当自宽。","男儿眼大天地小，麒麟阁，虮虱肝。"]},{"t":"归自吴越与家皖翁庞艺长赉予弟握手龙津醉后成诗","f":"七言律诗","c":["松溪残雨湿征衣，小泊村桥叩竹扉。","万里共惊吾尚在，三年偏讶信何稀。","棘林雪尽铜驼冷，苜蓿春生铁马肥。","醉死君家都莫惜，天涯多有未能归。"]},{"t":"与蔡艮若杨无见夜话","f":"五言律诗","c":["中夜不成寐，忆君前可知。","乍从灯下到，犹似梦归时。","屈指论年月，开襟对酒卮。","谁能更碌碌，辛苦话天涯。"]},{"t":"过何知澹新筑","f":"五言律诗","c":["主人既不俗，能使林园清。","未雨小池浅，将昏初月明。","结庐七八尺，啼鸟两三声。","种得忘忧草，如今花又生。"]},{"t":"舟经故里不泊","f":"五言律诗","c":["东林日未出，一望但苍苍。","旧宅诸峰下，寒江绕郭长。","十年春涕泪，二月雨帆樯。","不为营先冢，何因对故乡。"]},{"t":"叶世颖蔡艮若同登金紫峰作","f":"五言律诗","c":["空林采药倦，寂寞憩禅扉。","买得山村酒，遥从风雨归。","云生层嶂合，春尽落花希。","向晚平畴上，闲闲一鹤飞。"]},{"t":"旱夜","f":"五言律诗","c":["饥岁苏犹未，农时旱可怜。","无田春望雨，不寐夜观天。","朱鸟垂檐没，银蟾入户圆。","邻家桔槔叟，潮上独撑船。"]},{"t":"僦居新塘送叶世颖蔡艮若何友大不偕归里","f":"五言律诗","c":["虎门送君晚，白日落蒹葭。","故里不同去，他乡独作家。","多离愁觉减，入世懒逾加。","已有西来约，还山待菊花。"]},{"t":"乞食翁","f":"古风","c":["冥冥青枫林，戢戢归飞翼。","飞鸟亦有巢，老翁行乞食。","问翁何方人，挥涕答不得。","良久前自言：“家在东山侧。","薄田五十亩，父子艺黍稷。","宿昔天地平，黾勉努筋力。","中妇提壶浆，小妇当机织。","老妻低白头，扶孙共匍匐。","冬日农事歇，斗酒呼亲识。","鸡豚稻粱饭，壮我衰颜色。","宁知属戎马，秋毫见取索。","一岁耕且锄，不足供赋役。","芸田倦未起，肢体被鞭策。","贫家力已竭，公家求日益。","有田以自养，反以速穷厄。","欲卖与豪家，乡邻少人迹。","当时富贵者，荒草生空宅。","回头语孙子：‘流离任所适。","重恐官吏至，岂能受逼迫。","黄泉亦相见，何必人间客’。","欲呼一饭别，盎无半升麦。","出门各分手，痛哭辞阡陌。","哀哉竟至今，两不闻消息。","老身一葛衣，朽烂委荆棘。","饿死污人乡，不死长悽恻。","新朝泽万物，我独罹斯极”。","下民日憔悴，上天安可测。"]},{"t":"卧病","f":"五言律诗","c":["海门送人地，人去见波涛。","东路离居久，西风病骨高。","背墙施枕簟，当暑着绨袍。","颇悟无生理，蝉声在远皋。"]},{"t":"新别","f":"五言律诗","c":["户外犹残月，江边已晓春。","轻装来去易，孤烛别离新。","角枕回怜汝，牛衣莫笑人。","请看原上骨，岂得在生贫。"]},{"t":"送梁器圃归顺德","f":"五言律诗","c":["汀洲初雁飞，送客钓鱼矶。","故里我曾梦，深秋君独归。","荻花迎棹起，枫叶到城稀。","为问先人宅，门前柳几围。"]},{"t":"闲居 其一","f":"五言律诗","c":["闲居冬已尽，独坐念将衰。","霜叶不亲树，寒花多苦枝。","单衣勤向日，薄命拙逢时。","莫作将来计，人生未可知。"]},{"t":"闲居 其二","f":"五言律诗","c":["羚羊千丈峡，铁马一秋尘。","巾帼遗诸将，干戈战市人。","析骸犹可爨，三版未成湮。","只恐东南亩，明年不用春。"]},{"t":"新塘早春怀蔡艮若何不偕","f":"七言律诗","c":["春云漠漠虎头东，几日移居杏再红。","三径草生残雨后，数家门掩落花中。","乡山久别吟兼梦，水驿多情浪与风。","有约扁舟未能去，幽期空负钓鱼翁。"]},{"t":"宿梁器圃寒塘","f":"七言律诗","c":["衰柳亭边酒数杯，扁舟昨日虎头回。","结成茅屋竟何事，开到黄花人又来。","小郭乍寒山有雨，平池经旱水兼苔。","旧家正在江城外，深夜无人莫上台。"]},{"t":"四时白纻歌五首 其一 春白纻","f":"七言古诗","c":["新林生叶花交飞，珠帘初日流素晖。","洞房夜烛光力微，起舞君前歌露晞。","宛如游龙翩如鸿，骨柔态变不可终，高举长袖云回风。","凤文双履金缕衣，长跪为君擎玉卮，芳年逝者已若斯。"]},{"t":"四时白纻歌五首 其二 夏白纻","f":"七言古诗","c":["草萤本质昔已枯，化身今比明月珠。","飞君华堂缀交疏，何况贱妾不肖躯。","能歌巧笑工步趋，长眉的皪承清矑。","不敢自许众道殊，幸离下土升阶除。","云房别馆如天居，奉君颜色今夕初。","秣君驷马豆以刍，醉君吏士人石醹。","愿因微风达区区，昼长夜促乐斯须。"]},{"t":"四时白纻歌五首 其三 秋白纻","f":"七言律诗","c":["素衣轻举襳袿红，朱唇不动音微通。","如骄似怨不自容，翩若芙蕖秋被风。","轻弦细语传纤手，寄心赠君君不有。","白云东下雁南飞，令颜一去不复归。"]},{"t":"四时白纻歌五首 其四 冬白纻","f":"七言古诗","c":["氍毹匝地朱复殷，鸣环顾步何姗姗。","文犀约臂辟重寒，含声未吐气若兰，左顾右盼生光澜。","堂上清歌林外啭，积雪遥光凝玉面。","双心一意俱回旋，百媚邀君流一眄，千秋万岁非所羡。"]},{"t":"四时白纻歌五首 其五 夜白纻","f":"七言古诗","c":["天阶璧月霜始凝，玉绳西倚银汉横。","杯疲客醉不自胜，佳人含笑烛下兴。","垂辉振彩四座惊，轩轩忽若朝霞升。","人生快意不在他，高贤嘉会酒且多。","秦箫激越齐瑟和，日月逝矣如流波。","永夜如年君弗歌，百年如夜将奈何。"]},{"t":"钜鹿公主歌辞","f":"七言古诗","c":["官家出游乘驷驖，毳殿连房象宫阙。","殿前女子持绛节，手弹琵琶颜照雪。","中宫西宫同羽猎，何以知之双鬟结。"]},{"t":"琅琊王歌辞八首 其一","f":"五言绝句","c":["新买五尺刀，烂熳芙蓉焰。","晓夕时一开，取照幽人胆。"]},{"t":"琅琊王歌辞八首 其二","f":"五言绝句","c":["人言琅琊贤，我独未曾说。","长揖交戟中，左右惊吐舌。"]},{"t":"琅琊王歌辞八首 其三","f":"五言绝句","c":["飞花亦有蒂，浮梗故有根。","四体如轻埃，因风集谁门。"]},{"t":"琅琊王歌辞八首 其四","f":"五言绝句","c":["长安八水背，清渭流最急。","一夜西北风，怒涛寒自立。"]},{"t":"琅琊王歌辞八首 其五","f":"五言绝句","c":["琅琊大道王，更唱琅琊曲。","侧有如花人，许以英雄目。"]},{"t":"琅琊王歌辞八首 其六","f":"五言绝句","c":["剑室双金龙，夜夜鸣中箧。","不能青天飞，枉用张鳞鬣。"]},{"t":"琅琊王歌辞八首 其七","f":"五言绝句","c":["天不借日月，日月终经天。","虎不借深山，藜藿生路边。"]},{"t":"琅琊王歌辞八首 其八","f":"五言绝句","c":["宝马鸣春风，马上人如龙。","下马道姓名，言是广平公。"]},{"t":"雀劳利歌","f":"七言古诗","c":["苍鹰飞飞雀劳利，高者逢之下得计。"]},{"t":"折杨柳歌五首 其一","f":"五言绝句","c":["白羽照秋月，丽服明春风。","朝来试马蹄，踯躅垂杨东。"]},{"t":"折杨柳歌五首 其二","f":"五言绝句","c":["家居杨柳下，直路西北驰。","望郎不可见，折尽门前枝。"]},{"t":"折杨柳歌五首 其三","f":"五言绝句","c":["放马在南涧，马嘶时向北。","龙出渥洼中，万人皆辟易。"]},{"t":"折杨柳歌五首 其四","f":"五言绝句","c":["河北望河南，杨柳郁森森。","蕃汉虽二域，春风无两心。"]},{"t":"折杨柳歌五首 其五","f":"五言绝句","c":["左手櫜健弓，右手结柔辔。","抽出腰下刀，深勒燕山字。"]},{"t":"企喻歌四首 其一","f":"五言绝句","c":["男儿欲作健，不用持弓槊。","狮子一顾笑，百兽毛自落。"]},{"t":"企喻歌四首 其二","f":"五言绝句","c":["放马在大野，草浅马腾跃。","铁作身上衣，明朝为君着。"]},{"t":"企喻歌四首 其三","f":"五言绝句","c":["前营看后营，万马肃无声。","前军看后军，大旆蔽平原。"]},{"t":"企喻歌四首 其四","f":"五言绝句","c":["男儿堕地日，会有冲天时。","泰山与鸿毛，各是人所为。"]},{"t":"捉搦歌四首 其一","f":"七言绝句","c":["好月在天常患缺，硬弓在櫜常患折。","男儿穷居苦无骨，老女不嫁忌嫁毕。"]},{"t":"捉搦歌四首 其二","f":"七言绝句","c":["两株银杏江边老，花者是公实者母。","天生神物必有偶，独坐空房今白首。"]},{"t":"捉搦歌四首 其三","f":"七言绝句","c":["路傍古井人所食，清浅分明辨沙砾。","可邻照影多行客，不见须眉见巾帼。"]},{"t":"捉搦歌四首 其四","f":"七言绝句","c":["江东蔗竿长丈二，中间可啖两头弃。","少年往矣老不济，四十五十无多岁。"]},{"t":"陇头流水歌辞三首","f":"古风","c":["陇头流水，流离四注。","念我劳人，终身霜露。","弱水可途，坚冰在须。","时无英雄，咄哉丈夫。","上阪下阪，秦川在眼。","左手把鞭，足不能前。"]},{"t":"月节折杨柳歌十三首 其一 正月歌","f":"古风","c":["野雪犹未开，水边与林上，次第送青来。","折杨柳，不知思已深，只讶春何久。"]},{"t":"月节折杨柳歌十三首 其二 二月歌","f":"古风","c":["红碧两参差，芳香满林薄，望欢殊未来。","折杨柳，我有千里心，愿寄双飞鸟。"]},{"t":"月节折杨柳歌十三首 其三 三月歌","f":"古风","c":["采薇薇已柔，东西复南北，念子何时休。","折杨柳，持为七宝鞭，追逐骅骝后。"]},{"t":"月节折杨柳歌十三首 其四 四月歌","f":"古风","c":["寒消时未暑，梅子欲成黄，摽落当谁取。","折杨柳，青春不可追，长条已堪扫。"]},{"t":"月节折杨柳歌十三首 其五 五月歌","f":"古风","c":["家带辟兵符，螳螂诚有斧，不足禦隆车。","折杨柳，刻作孟尝君，才堪役鸡狗。"]},{"t":"月节折杨柳歌十三首 其六 六月歌","f":"古风","c":["大鸟怒而飞，海水方飘扬，浩涆将焉归。","折杨柳，天作飓母风，四面来吹子。"]},{"t":"月节折杨柳歌十三首 其七 七月歌","f":"古风","c":["杨州牛女纪，孟月渡河秋，人间复何似。","折杨柳，蟢子识窗前，誇道天孙巧。"]},{"t":"月节折杨柳歌十三首 其八 八月歌","f":"古风","c":["云气方四除，明月有正色，依依照吾庐。","折杨柳，斫尽碍门枝，不患秋光少。"]},{"t":"月节折杨柳歌十三首 其九 九月歌","f":"古风","c":["零露已为霜，秾华不堪玩，晚菊馀芬芳。","折杨柳，疏密葺藩篱，不负重阳酒。"]},{"t":"月节折杨柳歌十三首 其十 十月歌","f":"古风","c":["天净北风高，鹰隼盘空中，意气真雄豪。","折杨柳，镞取董泽蒲，一试穿杨手。"]},{"t":"月节折杨柳歌十三首 其十一 十一月歌","f":"古风","c":["大野极群阴，万物方嗷嗷，一复见天心。","折杨柳，立表测土中，短长占日晷。"]},{"t":"月节折杨柳歌十三首 其十二 十二月歌","f":"古风","c":["水泽腹已坚，坎险化为夷，走马渡长川。","折杨柳，杨柳不成阴，濯濯青松老。"]},{"t":"月节折杨柳歌十三首 其十三 闰月歌","f":"古风","c":["历象有前期，天王在门中，百辟盛威仪。","折杨柳，四序相周流，盈虚信天道。"]},{"t":"日重光","f":"古风","c":["日重光，奈何鸡方鸣。","日重光，昨日之日，固当舍我而行。","日重光，懔乎若渊上之春冰。","日重光，过中则昃西倾。","日重光，年在壮盛难恒。","日重光，譬如大将，背水阵兵。","日重光，照是下土下氓。","日重光，追膻逐臭如蝇。","日重光，唯有达者成名。"]},{"t":"月重轮","f":"古风","c":["月重轮，照天下。","使天若无明月，万古当为长夜。","何夜无月，月有虚盈。","谁为匪民，达者成名。"]},{"t":"秋行四首 其一","f":"古风","c":["乱竹微开一角，莫云远带孤村。","人到绿杨下马，屋迎秋水开门。"]},{"t":"秋行四首 其二","f":"古风","c":["万峰谷里村路，独木桥西酒家。","对客山翁白发，当垆老妇黄花。"]},{"t":"秋行四首 其三","f":"古风","c":["旧宫荒草何处，莫日芦花系船。","渔子数灯归尽，江潭一雨萧然。"]},{"t":"秋行四首 其四","f":"古风","c":["酒醒已离孤店，灯残莫写乡书。","晓月啼猿未已，秋山匹马归欤。"]},{"t":"何友大问余病于寒塘","f":"五言律诗","c":["十里雕胡渚，劳君艇子来。","棹移花下雨，人上水边台。","少别经三月，深情尽一杯。","病馀存舌在，今夜话能陪。"]},{"t":"醉夜","f":"五言律诗","c":["黄云峰外雨，雨后别山公。","客醉溪桥滑，人归夜火红。","旅魂思北首，病骨入西风。","长叹厓门上，明朝路又东。"]},{"t":"七月八日早行","f":"五言律诗","c":["行子及清晨，鸣鸡在四邻。","星沈牛女夜，烛照别离人。","树势迷前侣，江涛怯病身。","遥遥荡舟子，招手荻花津。"]},{"t":"病柳","f":"五言律诗","c":["黄落亦复好，青青将若何。","受人怜不久，当路折偏多。","艳节成虚往，严霜幸未过。","金城旧栽处，流涕怨蹉跎。"]},{"t":"拟古三首 其一","f":"五言古诗","c":["橘子始可食，往往辞其枝。","孝子方欲养，父母长别离。","墓上椎牛羊，不如生蒸梨。","高爵耀闾里，无亲持慰谁。","魂梦中夜来，九原知不知。"]},{"t":"拟古三首 其二","f":"五言古诗","c":["寄生在高树，树枯枝不繁。","托身共生死，所惜非同根。","昔我三小弟，俊迈难具论。","国难一时尽，反令愚者存。","岂无友朋好，终念骨肉恩。","不见蒲苇中，鸿雁相飞翻。","双雁飞上天，孤雁无与言。"]},{"t":"拟古三首 其三","f":"五言古诗","c":["射虎射石头，始知箭锋利。","居世逢乱离，始辨英雄士。","我生良不辰，京洛风尘起。","生死白刃间，壮心未云已。","猛士不带剑，威武岂得申。","丈夫不报国，终为愚贱人。","中夜召仆夫，将适赵与秦。","方建金石名，安念血肉身。","抗手谢俦侣，明日西问津。"]},{"t":"夜发甘竹滩","f":"七言律诗","c":["滩头潮落树昏昏，夜半移舟出水村。","一渚暗云迷大雁，片帆春雨下江门。","愁来每失芳菲节，老去多惭父母恩。","明日冈州花下醉，此心持与故人言。"]},{"t":"代闺人新月","f":"五言律诗","c":["夫婿远邀勋，金鞍西入秦。","空闺见新月，终夜惜青春。","似镜难全掩，如眉不解颦。","为衔将落影，持照未归人。"]},{"t":"宿董无休五羊寓舍留别","f":"七言律诗","c":["雨歇空堂秋气生，酒杯无惜坐深更。","扁舟此去复为客，一宿缘君暂到城。","夜月几时还共照，楚山应恨不同行。","西风万里传书处，待汝题诗赠屈平。"]},{"t":"别杨无见因柬冈州同人","f":"五言律诗","c":["结束远行迈，未行先送君。","秋江下白露，今夜向黄云。","此别渺难定，临岐何易分。","还将努力意，传语故人闻。"]},{"t":"发舟寄湛用喈钟裴仙湛天石","f":"七言律诗","c":["扶胥古渡水凄凄，雨后移舟望转迷。","数口寄居秋草外，一身为客楚云西。","家无兄弟依良友，地夹河山畏鼓鼙。","知己片言应不负，乱离妻子藉提携。"]},{"t":"留别诸同人","f":"七言律诗","c":["霏微残月晓风寒，生死交情话别难。","入楚客无燕匕首，送行人有白衣冠。","舟辞香浦鸿初到，马踏梅关雪渐看。","后会不须期故国，中原天地本来宽。"]},{"t":"度大庾岭","f":"七言律诗","c":["向风长叹草萧萧，山压重门石气骄。","千古霸图俱寂寞，再来行迹尚渔樵。","寄书黄木湾何处，走马红梅驿渐遥。","欲扫苍厓记名姓，少年时已薄题桥。"]},{"t":"江上别卢非玉","f":"七言律诗","c":["重逢又是异乡行，一月孤帆共北征。","江上路分彭蠡泽，雪中人向岳阳城。","停舟此地丹枫色，买醉当垆玉笛声。","别后想君歌舞夜，姑苏南望倍含情。"]},{"t":"送涤公","f":"五言律诗","c":["涤公到城久，忽忆丘中琴。","积雪移孤棹，寒湘共此心。","独归红树外，相待白云深。","语我茅庵路，衡山在隔林。"]},{"t":"自励诗","f":"五言古诗","c":["闻道岂必早，立德苦不固。","嗟余困蒙弱，老大犹未树。","五十不称夭，蹉跎已中路。","逝者诚已矣，来兹可无惧。","先民诏遗矩，乃在行其素。","外物焉足希，澄心任所遇。","每戒出位思，恒存周身虑。","毋曰独居暗，几微渐成著。","毋曰戏谑小，君子有常度。","穴防终以决，往水不返溯。","庶几日三复，反躬永无恶。"]},{"t":"湘潭除夕","f":"五言古诗","c":["束屩志万里，岁尽犹在兹。","茅堂闭积雪，高卧湘川湄。","邻家节序意，寒笛参差吹。","佳人急刀剪，中夜闻声辞。","留滞感未弭，景物情难持。","褰衾盖蓬首，托寐通所思。","故乡有馀梦，所思渺无期。","寤叹击床蓐，反侧伤肝脾。","人言有彼此，道远不可知。","吁嗟壮士怀，岁尽增遥悲。"]},{"t":"赠郭幼隗 其一","f":"五言古诗","c":["陶公羲皇人，济世心复苦。","违时弃经纶，养节薄簪组。","微言寄简策，容色尚可睹。","昔人云已邈，之子蹈前矩。","林园发新咏，往往见肺腑。","以置彭泽中，识者昧去取。","匪直英华美，秉心亦犹古。"]},{"t":"赠郭幼隗 其二","f":"五言古诗","c":["驽马出大宛，絷之在汉闼。","长鸣眷西极，万里走空阔。","物老德不称，筋衰力先夺。","繁阴盛淫雨，修途泞不达。","侧首见骅骝，尘中问饥渴。","言恋父母国，已恐贰师拔。","踟蹰立长坂，泪杂沟中沫。","苜蓿未可希，生刍欲归秣。"]},{"t":"湘上寄梁器圃","f":"五言古诗","c":["湘皋气候暖，风物犹近粤。","雪在野际青，春迟柳间蘖。","出郊践芳草，怨与王孙别。","河桥一分手，六满汀洲月。","靡月不相思，矧伊艳阳节。","想见山阿人，行歌散玄发。","衡阳有归雁，逖矣嵇生札。"]},{"t":"送雪公归耕苍梧歌","f":"古风","c":["苍鹰六翮不上天，化为春鸠啄人田。","壮士有力不搏虎，两角肥牛耕瘠土。","毛摧羽落君莫叹，龙屈蛇伸自终古。","送君耕，耕何所。","上有苍梧之深山，下有牂牁之长浦。","浦下山田田上墅，荷锸来归日当午。","曲枕右肱树左股，万事不理望膏雨。"]},{"t":"湘上读书柬郭幼隗","f":"五言律诗","c":["高天何寥廓，茅屋十馀尺。","上有飞晨风，下有不归客。","重衣垢以敝，散帙黯无色。","仰首惭壮夫，垂心事雕刻。"]},{"t":"答别郭幼隗","f":"七言律诗","c":["天涯何意返征骖，惨澹离怀酒不酣。","匝地柳条青汉上，断肠春草绿湘南。","难归故国生多恨，有约乘桴去亦堪。","沧海茫茫一回首，美人迟暮在江潭。"]},{"t":"发舟中湘将登南岳","f":"五言律诗","c":["芳草绿未已，孤舟发南湘。","还当上巳日，远适衡山阳。","石积水光碎，竹多风响长。","客途春有酒，波荡感浮觞。"]},{"t":"宿罗克生","f":"五言律诗","c":["衡山三十里，樵子识君家。","一路杉松雨，开门桃李花。","乍逢如宿昔，未老亦烟霞。","叹息青灯夜，春衣冷欲加。"]},{"t":"谒南岳庙","f":"五言古诗","c":["秩礼咸百王，兹山奠南服。","如何奕奕庙，朴樕今有屋。","镛钟仰东序，高瓦坠平陆。","谷风飘崇基，枯草下更绿。","上帝当板板，百神亦倾覆。","周檐盼层阿，出涕立空谷。"]},{"t":"石浪庵访破门上人","f":"七言绝句","c":["樱桃花落正黄昏，谷鸟惊飞客在门。","想得老僧春未出，竹根深雪屐无痕。"]},{"t":"赠大化上人","f":"七言绝句","c":["草屋苍凉老此身，重岩花木不知春。","故乡南岳三千里，君在山中见几人。"]},{"t":"南岳道中从石浪庵上至高台寺","f":"五言古诗","c":["晨饭气始晴，初日在山缺。","纡回出林莽，揖与老僧别。","抠衣陟天路，百里上积雪。","适来历崔嵬，反视若丘垤。","清冷坠冰响，淅沥霜枝折。","中峰方眇然，将登且当歇。"]},{"t":"登祝融峰","f":"五言律诗","c":["祝融高不测，云雨及其半。","濛濛在太古，乾坤犹未判。","九州有馀览，旭日夜中旦。","临睨怀百忧，因高发南叹。"]},{"t":"下祝融峰向白门寺道中作","f":"五言古诗","c":["披离中林雪，厌浥下山路。","缘高凛若坠，身外不敢顾。","藤藟援我行，飞鸟争我度。","我下群木鸣，我上寒云冱。","迹从逝溪远，心与幽赏住。","万里方自今，重期岂能预。","迟迟闻远钟，懔懔日将暮。"]},{"t":"白门别诺诺和尚","f":"七言律诗","c":["南岳千峰一衲栖，小桥流水入招提。","山端远影湘江尽，竹外闲窗楚岫低。","十日淹留春色暮，中宵谈笑月华西。","岐途不用悲游子，芳草天涯路未迷。"]},{"t":"过洞庭湖","f":"五言律诗","c":["灌注合梁荆，苍茫四望平。","江山俱不到，天水自相生。","失路行湘浦，期舟渡郢城。","风波此瞻眺，真信地维倾。"]},{"t":"赤壁舟中歌","f":"七言古诗","c":["曹家老瞒狡而武，百万戈矛下荆土。","赘阉小丑夷群雄，当时意气无江东。","江东少年剑斫案，驱风走火乌林岸。","北船烟烬西蜀都，吴王宫殿飞赤乌。","谁为此谋葛与周，两郎年几二十头。","雄图已矣勿谁道，赤壁舟中人已老。"]},{"t":"将发汉口毛子霞在武昌不得更别舟中夜坐作诗寄之","f":"七言律诗","c":["沧波芳草暮生烟，东望离心倍黯然。","短棹拟过黄鹄渡，轻装催上白门船。","遥从江汉分流地，坐到星河欲晓天。","明日五更应已远，故人残月正高眠。"]},{"t":"过昭关","f":"五言古诗","c":["萧条半生事，驱马行中原。","人影乱马蹄，䟤跋沙尘昏。","马饥走衔草，人饥那得飧。","西徂岘阳阪，伫立昭关门。","古人伍子胥，聊可与之言。"]},{"t":"次凤阳逢中秋","f":"五言律诗","c":["未到问沽酒，早投城北闉。","莫令亡国月，得照渡江人。","世薄功名士，秋销战伐尘。","馀生付樽杓，留醉上车轮。"]},{"t":"舟泊长淮关怀去年别者","f":"五言律诗","c":["长淮今夜月，此是故人心。","万里送行者，徘徊枫树林。","维舟怅前别，把酒恋同斟。","自我不相见，知君愁至今。"]},{"t":"吹台","f":"五言古诗","c":["风吹吹台树，树叶高下飞。","嗟哉两游子，远适不念归。","马蹇负橐行，鞭断持竹枝。","徬徨吹台下，据地擢素髭。","借问客游子，飘飖欲何之。","乃云适西北，又不入帝畿。","闻有燕赵士，尚义如渴饥。","虽则如渴饥，昔是而今非。","高冈多蒺藜，下室多伊威。","黄河问清水，升斗不可希。","风吹吹台树，树叶落不远。","嗟尔两游子，远行莫如返。"]},{"t":"夷山谣","f":"古风","c":["古夷山，今平地。","车马东西驰，屠儿倚刀醉。","梁园枯草鹰啸风，公子翩翩持角弓。"]},{"t":"博浪谣","f":"古风","c":["前椎晋鄙，后椎秦始。","地并大梁，不信海西驰，久饮东京水。"]},{"t":"黄河谣二首 其一","f":"古风","c":["口哆声嗔，招舟孟津。","马饮浊浪，人立浊尘。"]},{"t":"黄河谣二首 其二","f":"古风","c":["贵舆贱骑，飞躯逐利。","老反山阿，白头入地。"]},{"t":"山阳送赵客入燕","f":"七言绝句","c":["漳河东是帝京尘，匹马看君发孟津。","欲寄悲歌向燕市，荆卿行后更无人。"]},{"t":"山阳逢亡友蔡艮若生日感赋","f":"五言律诗","c":["夭寿各归尽，三年悲亦衰。","胡然既死后，转忆始生时。","寡过我何赖，多才人未知。","山阳今有作，不为笛声吹。"]},{"t":"儿赣晬日旅山阳作","f":"五言古诗","c":["游云极八表，出山如有恋。","我孤望儿子，及产不相见。","我行马蹄西，儿子初生啼。","我行马蹄北，儿生已匍匐。","此日一岁成，此时邻妪盈。","空堂杂百物，嗜欲开其情。","昏来各出户，拍手嗤其父。","阿妇入闺房，抱儿心望郎。"]},{"t":"卖驴","f":"五言律诗","c":["归鞍太行下，南及汉川湄。","远历风霜苦，难为蹇劣姿。","在予常惜力，于汝亦忘疲。","去落他人手，筋骸愁自兹。"]},{"t":"岁暮登黄鹤楼","f":"七言律诗","c":["郊原草树正凋零，历历高楼见杳冥。","鄂渚地形浮浪动，汉阳山色渡江青。","昔人去路空云水，粤客归心向洞庭。","莫怨鹤飞终不返，世间无处托仙翎。"]},{"t":"庚子元旦毛子霞招同何不偕登黄鹤楼","f":"七言律诗","c":["君子羁心积此晨，鹤楼斟酌岁华新。","城头江汉一千里，座上罗浮两个人。","细草暗催行处绿，落梅飞尽隔年春。","谁堪天下无穷路，来伴微生易老身。"]},{"t":"归舟四首 其一","f":"五言律诗","c":["积雨江汉绿，归心杨柳初。","芳菲空复尔，少壮已全虚。","白发何难得，青山不易居。","从今向田里，所惧世情疏。"]},{"t":"归舟四首 其二","f":"五言律诗","c":["舟路翠微上，了然知寂机。","溪声虚自答，山色静相晖。","饮鹿妨人去，栖禽择木飞。","物情从所好，吾亦薄言归。"]},{"t":"归舟四首 其三","f":"五言律诗","c":["楚县逾山尽，章流向粤初。","映花溪路闭，含水石根虚。","淹泊时仍杳，羁愁日以疏。","殊方归亦尔，吾自笑怀居。"]},{"t":"归舟四首 其四","f":"五言律诗","c":["水气动群木，虚楼飞叶声。","风灯无定照，峡月不终明。","托宿维舟夜，临泷未济情。","寸心平自若，应任险中行。"]},{"t":"杂诗九首 其一","f":"五言古诗","c":["浟浟东逝水，怆怆南征子。","水逝水所归，苍天曷为此。","衔悲历君庭，宵风动茅苇。","东井嘒方中，天弧曜其矢。","闻君旅其下，长跪愿有启。","梁土多黑波，马渴君安恃。"]},{"t":"杂诗九首 其二","f":"五言古诗","c":["雁度葭菼黄，月悬江汉秋。","离人喟清夜，挟瑟临高楼。","西瞻赤壁涯，东思沧海流。","朱弦感英声，磊砢不可收。","下阶重太息，古调今谁酬。","哀彼促织虫，有生亦何求。","衣裳非所温，唧唧怀殷忧。"]},{"t":"杂诗九首 其三","f":"五言古诗","c":["杖策有所适，乃至南山阿。","飞雪曜峻涂，高冰积嵯峨。","仰见双羽人，被服扬轻霞。","揖我升丹梯，飞步游天河。","下窥失五岳，累块存中华。","群星与日月，熠若流萤过。","命我一丸药，天陨子不磨。","长揖谢羽人，蓄志不慕多。","兹生有馀责，区区计其他。","回车复吾路，路有张鸟罗。","凤鸟易高飞，罗雀如之何。"]},{"t":"杂诗九首 其四","f":"五言古诗","c":["霜至草木寒，关河凄以风。","扁舟越湘水，迟暮予何心。","美人彩云端，欲往闻遗音。","云端不可即，离别销颜色。","三朝掩明镜，对面不相识。"]},{"t":"杂诗九首 其五","f":"五言古诗","c":["商风自何来，白云起秋色。","梧柯下一叶，百卉萋未息。","天地方疾威，美者先受抑。","捐生故有人，困馁焉足惜。","丰此百年躯，只为蝼蚁德。"]},{"t":"杂诗九首 其六","f":"五言古诗","c":["萧萧君马鸣，夜夜闻歌声。","马悲慕俦侣，独歌谁和汝。","结束下空阶，仰瞻霜与露。","缺月衔东隅，旄头没何处。","思为伺晨鸟，举舌催天曙。"]},{"t":"杂诗九首 其七","f":"五言古诗","c":["家临青山侧，前望白杨道。","遥遥孤坟下，有士怀其宝。","存思泽万物，一身乃先槁。","驾言采杜衡，涉野多秋草。","同心复几人，相看日趋老。"]},{"t":"杂诗九首 其八","f":"五言古诗","c":["金节天地肃，白日遄西飞。","繁星不照物，流萤有馀辉。","灼灼宵征子，车马轻且肥。","明灯集倡楼，四角扬清丝。","佳人映瑶席，仿佛凝幽姿。","回眸粲一顾，百万焉足挥。","锦衾既以陈，鸳鸯罥重帏。","欢乐永今夕，此生不愿馀。","佳人含笑言，生死齐所归。"]},{"t":"杂诗九首 其九","f":"五言古诗","c":["旭日临高城，城中何浩浩。","楼台动丝管，金碧相照耀。","在野方为鱼，太康无乃早。","浩歌感畴昔，瞻望淇园道。","下有流汤汤，上有竹窈窈。","河流日以溢，竹生日以老。"]},{"t":"古有乘车戴笠之谣其相逢必有歌盖逸之也戴笠者歌曰","f":"古风","c":["南园道，萧兰不同芳，共是三春草。"]},{"t":"答歌","f":"古风","c":["墓门道，高下不同茔，一种生春草。"]},{"t":"送董无休归会稽歌二首 其一","f":"古风","c":["奈何别，感予悲，思昔与君初相知。","我之北，君在南，解君之策策两骖。","我之南，君将北，我马玄黄不如昔。","五羊城东百尺浪，欲送归人行不得。","行不得，为君歌。","风乎谷中，云乎山阿。","雷入于地，雨伏于河。","风云雷雨飒然合，下天上地为滂沱。","云摇雨散西风好，愿君且向山阴道。","南北分飞自偶然，丈夫不受炎洲老。"]},{"t":"送董无休归会稽歌二首 其二","f":"古风","c":["江水秋以洚，关河上西而风。","翼翼之篷，我友于东。","东何归，归会稽。","稽山阳，稻与粱。","稽山背，蒿与艾。","何以赠君赠自爱。","独女不嫁邻儿大，欲往从之慎其对。"]},{"t":"子夜歌二首 其一","f":"五言绝句","c":["新妆尚未成，览镜自太息。","折取丹若花，榴子何能得。"]},{"t":"子夜歌二首 其二","f":"五言绝句","c":["待欢不下帘，春风灭寒烛。","云中见一星，今夜成单宿。"]},{"t":"感怀十七首 其一","f":"五言古诗","c":["纤纤西林月，待日生辉光。","幸假羽翼资，与君同颉颃。","左提而右挈，万夫莫能当。","况我为仁义，相辅唯文章。","斫桐为两琴，异形同宫商。","中心一相知，异身同肺肠。","智慧如丹华，华盛无再扬。","勖哉二三子，久要期勿忘。"]},{"t":"感怀十七首 其二","f":"五言古诗","c":["密云自西郊，良苗望膏泽。","长虹久不散，小雨滋蟊贼。","日月煎本根，青黄变生色。","结发为老农，终年不一穫。","高门纵杯酒，大笑糟糠客。","感念愚公言，子孙世其力。","努力饰镃基，春明候南陌。"]},{"t":"感怀十七首 其三","f":"五言古诗","c":["往者不可追，来者不可期。","俯首为今人，举体无一宜。","有目厌兵革，有耳闻号啼。","有腹饱糠覈，有足履祸枢。","赤舌有如火，更以焚其躯。"]},{"t":"感怀十七首 其四","f":"五言古诗","c":["高台临广池，梧桐百馀尺。","上有一尊酒，可以永今夕。","明月生东隅，浩荡无拘迫。","君子多暇豫，小人聊燕息。","人生有如影，终始为形役。","拔箭射虚空，箭尽弓亦折。","步出城北门，垒垒山上石。","下有忘忧人，千秋托松柏。"]},{"t":"感怀十七首 其五","f":"五言古诗","c":["荷丝织为衣，禦寒终不温。","章句小儒生，安识经与纶。","高冠带金玉，端坐如鬼神。","轻车从肥马，游宴无冬春。","志士沈下僚，能智岂获伸。","大盗从西来，击钟召群臣。","空复见异类，何以张吾军。","大者为鸡狗，鸣吠从他人。","小者如蛹蚕，只自营其身。"]},{"t":"感怀十七首 其六","f":"五言古诗","c":["九月悲风始，边土何惨慄。","积雪齐高城，惊沙蔽寒日。","斧冰持饮马，凿地求鼠实。","月盛角弓强，三军夜恒出。","合战阴山下，矢尽归途失。","手斩郅支头，献俘凤凰阙。","阙庭侍从士，卧起佳人侧。","日晏下朝归，酌酒弹鸣瑟。","十年为汉将，甲胄行虮虱。","一语不相能，投身对刀笔。"]},{"t":"感怀十七首 其七","f":"五言古诗","c":["事君如四时，成功者为客。","君子慎其言，只以求忠益。","小人躁于名，噭噭沽其直。","疾疢卒不除，上下成乖隔。","为臣固当戒，为君独宜择。","曲突弗先图，头额为焦灼。","忠言有如鸦，佞言有如鹊。","鹊鸣人所喜，鸦鸣人所唶。"]},{"t":"感怀十七首 其八","f":"五言古诗","c":["海滨何遥遥，遥遥三千里。","一里一千家，家家生荆杞。","空房乳狐兔，荒沼游蛇虺。","居人去何之，散作他乡鬼。","新鬼无人葬，旧鬼无人祀。","相逢尽一哭，万事今如此。","国家启封疆，尺地千弧矢。","人民古所贵，弃之若泥滓。","大风断松根，小风落松子。","松根尚不惜，松子亦何有。"]},{"t":"感怀十七首 其九","f":"五言古诗","c":["番禺古都会，佳哉郁嵯峨。","三江交洪流，海水扬清波。","刘项争帝业，闭关自秦佗。","黄屋与左纛，老夫聊自娱。","山川足霸气，往往开雄图。","中原鼎沸日，肝脑涂干戈。","光岳气虽分，生齿存亦多。","海国诚富强，金铁兼盐鹾。","百货走天下，五兵雄诸华。","盛朝为外府，乱政求金车。","使者道相望，下民方荐瘥。","北临汉台上，怅望伤如何。"]},{"t":"感怀十七首 其十","f":"五言古诗","c":["野犬吠行人，深巷闻荒鸡。","荡子今何之，有司在门闾。","朝出伏草间，夜起匍匐归。","有亲谁当养，有田莫耘耔。","岂敢负公家，有罪诚当治。","甘瓜生井傍，百尺蔓其枝。","祸来常无根，免身为令谋。"]},{"t":"感怀十七首 其十一","f":"五言古诗","c":["梦登首阳山，郁哉何巍巍。","上有二子坟，下有蕨与薇。","宁从白鹤巢，不从凤鸟飞。","白鹤来有常，凤鸟来无时。","子胥耕吴野，少伯困会稽。","一旦先埃尘，千秋有馀悲。"]},{"t":"感怀十七首 其十二","f":"五言古诗","c":["太息复太息，百年同木石。","富贵比春华，一落谁相识。","不如求令名，高誉流丹青。","丹青虽可慕，人命如朝露。","一身尚不存，令名亦何附。","不如齐死生，无我亦无名。","诚恐朽落时，亦与木石并。","百足既怜夔，蝮蛇复怜风。","是非百年内，展转何能穷。"]},{"t":"感怀十七首 其十三","f":"五言古诗","c":["览镜在中夜，莫辨影与形。","人苦不自知，所赖友与朋。","圭璧贵攻瑕，龙阿期发硎。","如何末世士，怀利忘平生。","责望疑似间，谗间忽然兴。","陈张交里门，白刃生侯王。","富贵尚相负，贫贱宁相能。","结交始以义，全交终以明。","安得兼黄金，以铸鲍子灵。"]},{"t":"感怀十七首 其十四","f":"五言古诗","c":["著我远游冠，插我忘归羽。","命驾将何之，三星在南户。","夕鸟下高林，翩翩赴其侣。","人生各有志，荣辱何常主。","浩歌击白石，与此聊终古。","谁能共碌碌，身没名不举。","蒿里足黄尘，徒增一棺土。"]},{"t":"感怀十七首 其十五","f":"五言古诗","c":["豫章下山时，顾与山灵语。","不为栋与楹，慎勿为木偶。","木偶盛容姿，曳裾复拱手。","大匠持斧斤，视之若无有。","叔孙名大儒，绵蕞何草草。","萧何刀笔吏，无功独居首。"]},{"t":"感怀十七首 其十六","f":"五言古诗","c":["人饮浊河水，不食古井泉。","古井非不清，浊河诚有源。","大人略细故，琐琐安足论。","鹦鹉立樊笼，焉用能人言。","苍鹰无羽仪，一日翔九天。"]},{"t":"感怀十七首 其十七","f":"五言古诗","c":["秋气不成寐，出户月皎皎。","我生多忧虞，及壮已衰老。","如彼霜下叶，未落忽先槁。","当前一尊酒，举觞问苍昊。","毕昴出东方，天阶静如扫。","玉衡无右移，白日不西晓。","如何六合内，有此颠与倒。"]},{"t":"叶世颖重之中湘茅屋别后有寄","f":"五言律诗","c":["楚国木叶下，故人行有霜。","离忧在湘水，古色满衡阳。","几日歇兰棹，此时开草堂。","山川教儿子，指点洞庭傍。"]},{"t":"夏夜同梁药亭朱竹庵","f":"五言律诗","c":["百感在深夜，夜凉开小扉。","梧桐下阶影，蝙蝠上堂飞。","初月清光少，中年旧友稀。","春来恋携手，空谷未成归。"]},{"t":"喜陶苦子还自鹿步","f":"五言律诗","c":["无言终夕坐，一雨散微凉。","自有碧天月，随君归草堂。","荒池馀溜上，高柳小星藏。","世难兼多事，为欢苦不常。"]},{"t":"月夜怀王东村","f":"五言律诗","c":["王子知名早，而今似老夫。","诗教流俗怪，痴爱美人扶。","隔岁书归岭，他乡月在湖。","滕王高阁上，今夜捋虬须。"]},{"t":"夏日寄铁机上人","f":"五言律诗","c":["自得传心印，年来出院稀。","苦吟诗体瘦，蔬食病身肥。","地静风吹竹，池凉水溅衣。","空江相忆处，白鸟夕东飞。"]},{"t":"宿罗浮飞云峰候日出","f":"七言律诗","c":["仙山终古少行踪，绝顶良宵不易逢。","暗积落花归上界，倒悬明月照西峰。","江潮应瀑声千里，海气成霞色万重。","一线日轮天已晓，远鸡才报下方钟。"]},{"t":"宿冲虚观","f":"七言律诗","c":["碧削群峰列四垣，仙宫高坐不知寒。","春前萤火明丹灶，夜静流星落斗坛。","几穴雕梁巢白蚁，一家衰草住黄冠。","山尊对语梅花下，福地而今路亦难。"]},{"t":"过薛剑公不值","f":"七言律诗","c":["竹窗虚掩读书堂，远近游踪日已黄。","舍瑟定偕童子去，采芝还入老人行。","苔侵旧绿缘金井，花散高红点石床。","一度不留君未惜，年年归路属春阳。"]},{"t":"雨后登楼迟梁器圃不至","f":"七言律诗","c":["江楼频约落花间，乱世幽期岂待闲。","几度莺声逢旧国，二年春色各柴关。","新虹映日收残雨，积水浮天出断山。","目极故人居可见，布帆无恙夕空还。"]},{"t":"赠别屈翁山二首 其一","f":"五言古诗","c":["落日临大河，游子有叹声。","与君结交初，十五侍亲庭。","中间一杯酒，各有万里行。","飘飖沅湘水，迢递辽阳城。","归来何所得，白发三四茎。","云中有哀鸟，遗我一尺缯。","上言所相思，乘龙冉遐征。","呜呼永决绝，况当别良朋。","踟蹰欲有言，泪下先承缨。","丈夫射桑弧，岂曰期一身。","大耻且不雪，独善有何称。"]},{"t":"赠别屈翁山二首 其二","f":"五言古诗","c":["画布作鸿鹄，天下齐张弓。","哀哉晚世士，不幸有其心。","有心尚可容，有口能兴戎。","愿君为坚金，不愿为贞松。","松高风飕飕，众草难为秋。"]},{"t":"屈翁山见过二首 其一","f":"五言古诗","c":["潜鱼脱于渊，濡沫犹相依。","何况双鹓雏，羽翼当未飞。","别子未经旬，中心恒苦饥。","析我园中薪，言烹菽与葵。","小子从外来，有客缁其衣。","披衣急出户，果谐心所思。","相携历堂阶，欢极无文仪。","素琴为君弦，浊酒为君开。"]},{"t":"屈翁山见过二首 其二","f":"五言古诗","c":["酒浊不可饮，弦悲难重陈。","平生废蓼莪，念子有老亲。","虽无爵与禄，色养逾八珍。","胡风自西来，四海同其尘。","枭獍言大孝，乌哺为不仁。","勉哉反古道，独立如披榛。","葵花虽不实，犹能安其根。","君子垂令名，所以扬二人。"]},{"t":"海中吟","f":"五言古诗","c":["海中何所有，有树名三珠。","上有同巢鸟，分飞从鹓雏。","西飞黑水头，北飞越黄河。","远者啄玉门，戛戛鸣天都。","路长羽翼短，力尽归其居。","上天天有弧，入地地无涂。","口饥不谋食，终日衔枯芦。","人情有独嗜，此鸟宁谓愚。","解纷不以拳，吊死不以乌。","凤凰其不来，吾衰已矣夫。"]},{"t":"珠厓歌送魏和公","f":"古风","c":["海之四壁天，珠厓浮其间。","夫子客于斯，则愿祝安而往，速而还。","已而已而，使夫子客于斯，后来者可以知其时也。"]},{"t":"崇祯皇帝御琴歌","f":"古风","c":["孤桐何生生峄阳，天家巧斫含宫商。","乾坤四序在胸臆，七宝交盘双凤皇。","烈皇宵衣坐璇殿，欲奏南薰和赤县。","朱丝七轸轸七弦，一时迸绝君王前。","君王三月骑龙去，神物潜行越河泗。","罗浮道士搜遗弓，五拜亲瞻翔凤字。","来归泣语临秋浦，白日晶晶倏飞雨。","况乃风高水波立，海隅咫尺非吾土。","豹之斑，下人间，鳄之横，出深阻。","掩君泪，为君吟。","彼琴者木木有心，四海男儿何至今。"]},{"t":"春夜城西对酒歌","f":"七言古诗","c":["苍天胡为使我老，百年饮酒苦不早。","学书学剑将何求，富贵何如一春草。","西城北郭狐狸穴，一坟未兴一坟灭。","英雄事业满丹青，欲向何丘问枯骨。","且当把烛对朋侪，千卮酬酢开中怀。","身后那能有知己，有如月坠西江水，万丈光芒终已矣。"]},{"t":"秋日西郊宴集同岑梵则张穆之陈乔生王说作高望公庞祖如梁药亭梁颙若屈泰士屈翁山时翁山归自塞上","f":"七言律诗","c":["黍苗无际雁高飞，对酒心知此日稀。","珠海寺边游子合，玉门关外故人归。","半生岁月看流水，百战山河见落晖。","欲洒新亭数行泪，南朝风景已全非。"]},{"t":"寄答方楚卿","f":"七言律诗","c":["羚羊峡里忆同船，江水盈盈十五年。","汉业不安分鼎地，楚臣谁定胜人天。","思莼酒客归乡井，攀柏孤儿守墓田。","三十无成惭父友，报书惟有一潸然。"]},{"t":"耕田歌","f":"古风","c":["耕田乐，耕田苦。","乐哉乐有年，苦哉不可言。","春未至，先扶犁。","霜华重，土气肥。","春已至，农事始。","鸡未鸣，耕者起。","泥汨汨，水光光。","二月稻芽，三月打秧。","五月收花，六月垂垂黄。","再熟之田始有望。","三月打秧，六月薅草。","一熟之田，九月始得穫稻。","近路畏马，马食犹寡。","近水畏兵，兵刈何名。","上官不待熟不熟，昨日取钱今取谷。","西邻典衣东卖犊。","黄犊用力且勿苦，屠家明日悬尔股。"]},{"t":"日本刀歌","f":"七言古诗","c":["白日所出金铁流，铁之性刚金性柔。","铸为宝刀能屈伸，屈以防身伸杀人。","星流电激光离合，日华四射曈曈湿。","阴风夜半刮面来，百万愁魂鞘中泣。","中原岁岁飞白羽，世人见刀皆不顾。","为恩为怨知是谁，宝刀何罪逢君怒。","为君昼盛威与仪，为君夜伏魍与魑。","水中有蛟贯其颐，山中有虎抉其皮。","以杀止杀天下仁，宝刀所愿从圣人。"]},{"t":"缫丝歌","f":"古风","c":["小虫之大小指如，君子之躯七尺馀。","镬烹小虫胡为乎，将以为衣荣君躯。","君躯长，君躯短。","小虫之小丝有限，中心抽尽君未暖。"]},{"t":"祭幽歌","f":"七言古诗","c":["天低野黑钟磬冷，高台火炬红无影。","招魂竹竿垂至地，万众无声大师睡。","林根水际光窅冥，欲动不动如有形。","阴风吹沙利如箭，蚱蜢横飞扑人面。","鬼王丈六须发丹，金铃召鬼争盘餐。","黄香插筵月皛皛，瓦簋不盈纸衣小。","倏如闻笑忽而啼，笑何丈夫啼女儿。","残形败血生荒草，有棺无棺安可保。","骨肉当前唤不闻，半夜依人思一饱。","绿杨丝绕白杨树，魂来作风归作雨。","西头落日东头来，后人仍为今人哀。"]},{"t":"猿声歌","f":"七言古诗","c":["十八滩头波突兀，孤舟十夕不得发。","蒹葭败叶鸣括括，江天霜满坠小月，乌猿一声一白发。"]},{"t":"寄曾省之","f":"五言律诗","c":["分居岭北南，异地幸同心。","匪石能攻玉，如兰即断金。","君从卜肆隐，予卧海门深。","春别不曾送，秋风劳夜吟。"]},{"t":"雨夜怀屈翁山","f":"五言律诗","c":["风雨怀人坐，无灯亦到明。","流萤分夜色，疏竹聚秋声。","别酒尚馀醉，春花今不荣。","终知吾与子，白发路傍生。"]},{"t":"送马仲融之粤西","f":"五言律诗","c":["天际万重滩，滩边万仞山。","山风吹落叶，只在客船间。","多难晦冥日，少年离别颜。","倚闾方白发，莫不看刀环。"]},{"t":"秋夕梁素子载酒过宿","f":"五言律诗","c":["悠悠成老大，处处闭柴关。","秋水鹭鸶外，江村禾黍间。","何期良夜月，得照故人颜。","把酒因成笑，劳生不易闲。"]},{"t":"得梁药亭燕台书因怀石埭之行","f":"五言律诗","c":["国门三献玉，岐路已沾衣。","复铩双鸾翮，居然后雁归。","乘风潮荡漾，临水叶翻飞。","牛渚高吟夜，相思方掩扉。"]},{"t":"江上","f":"五言律诗","c":["青山此川上，终古见如新。","可叹浮生者，蹉跎即老人。","暮云高不动，白鸟立无邻。","独往秋光里，双桡与病身。"]},{"t":"送雁","f":"七言律诗","c":["数声嘹呖起汀沙，乱点晴空暮影斜。","六翮欲冲辽海雪，一行先别岭南花。","但令处处无飞缴，莫恨年年不到家。","荇叶芦芽春渐遍，无穷烟水在天涯。"]},{"t":"望燕","f":"七言律诗","c":["封侯重颔黑衣袿，锦臆如花剪尾齐。","岁岁自来蓬户里，双双飞出柳塘西。","清秋别我知何去，旧垒归心想未迷。","郭外沃田抛弃尽，不忧无处觅春泥。"]},{"t":"易宣人过访","f":"七言律诗","c":["衰草闲园鸟不飞，海楼高坐每斜晖。","是谁肯问幽栖地，有客身披隐士衣。","独往肝肠怜汝小，后来风雅见人希。","深谈三日还三夜，未放江门一棹归。"]},{"t":"同何不偕梁器圃魏和公梁药亭陶苦子宿灵洲山寺柬王说作王大雁","f":"七言律诗","c":["灵洲秋色净无烟，水匝山隅浪匝天。","落日客寻江上寺，出林僧放月中船。","渔依别港灯侵阁，鹤宿高巢影在泉。","欲与故人同梦到，夜来吟咏不曾眠。"]},{"t":"寄易宣人","f":"七言律诗","c":["碧云芳草遍河洲，心逐归潮到海楼。","谢氏门中多翰墨，卫郎年少最风流。","入群野鹤能惊众，出土新松即傲秋。","近得孟光为伴侣，知君从此不低头。"]},{"t":"太息","f":"七言律诗","c":["高台为陆沼为尘，一半扬州是海滨。","白鸟自飞烟水上，青山不似乱离春。","松楸永隔兴哀地，陌路多逢太息人。","共道君恩怜物命，不教鱼鳖近居民。"]},{"t":"丙午岁旦漫题","f":"七言律诗","c":["鹊噪莺鸣在四邻，鬓毛羞与岁争新。","山妻漉酒相娱老，稚子牵衣出拜人。","道不偶时聊自放，诗非繇命莫教贫。","可能更得闲无事，三十六回春草春。"]},{"t":"送何左王客游","f":"七言律诗","c":["平生林下共幽期，至德如君是我师。","一日未曾离奉养，十年不拟到城池。","贫当乱世娱心少，老畏名山入眼迟。","暂脱彩衣行万里，春江杨柳绿丝丝。"]},{"t":"同诸子再泛甘溪","f":"七言律诗","c":["停舟昨日荫枫林，不道江天便有阴。","落木寒皋前路在，断桥流水此时深。","逢山每作终身计，见雁重惊万里心。","暂抱衾裯就渔父，月夜同听枻歌音。"]},{"t":"送屈翁山","f":"七言绝句","c":["万里还家着彩衣，三春惆怅别慈闱。","期君得似衔芦雁，半岁南飞半北飞。"]},{"t":"游猎词","f":"七言绝句","c":["白凤襜褕白玉骢，银鞍煜爚坐春风。","弯弓偶失青门兔，心在天山雪色中。"]},{"t":"增城村居即事五首 其一","f":"七言绝句","c":["渚西佳丽旧层层，彩薄朱栏画未能。","却好夜来徵檄过，黄茅初见一家灯。"]},{"t":"增城村居即事五首 其二","f":"七言绝句","c":["青枫成血立河旁，新筑河桥百尺长。","犹是君侯留爱地，县人不肯种甘棠。"]},{"t":"增城村居即事五首 其三","f":"七言绝句","c":["丝丝寒雨湿飞尘，草绿平田不是春。","伏犊山中虽有虎，农夫争避带刀人。"]},{"t":"增城村居即事五首 其四","f":"七言绝句","c":["死生由吏不由天，鸩毒随身始出门。","即怪比邻新病者，七星坛上更招魂。"]},{"t":"增城村居即事五首 其五","f":"七言绝句","c":["才生文字即风波，鬼哭虽然吏亦歌。","三尺龙泉方寸印，不知谁较杀人多。"]},{"t":"秋晚杂兴八首 其一","f":"五言律诗","c":["怅望百年内，寂寥天地间。","遥山宛然绿，秋水澹何闲。","风细鹤声去，月高渔火还。","贫居无不可，但惜酒卮悭。"]},{"t":"秋晚杂兴八首 其二","f":"五言律诗","c":["酒醒山衣薄，萧条林馆秋。","夜虫争客语，萤火共星流。","老态悲黄叶，新髭报白头。","深惭北窗下，终日见罗浮。"]},{"t":"秋晚杂兴八首 其三","f":"五言律诗","c":["月在日还上，追飞遄向西。","西风昨夜梦，知是武陵溪。","被服尚前古，贤愚同一畦。","因悲少年意，高气吐虹蜺。"]},{"t":"秋晚杂兴八首 其四","f":"五言律诗","c":["冷榻眠无次，闲阶立不归。","池花向影落，河雁带声飞。","水畔为渔父，城东即布衣。","平生随分得，未觉此心非。"]},{"t":"秋晚杂兴八首 其五","f":"五言律诗","c":["绕屋落寒叶，日高闻雁时。","纸窗明野马，斋鼎熟蹲鸱。","少事门开晚，多吟卧起迟。","百年行已矣，辛苦立名为。"]},{"t":"秋晚杂兴八首 其六","f":"五言律诗","c":["已矣复何道，悠悠斯世间。","日唯催貌老，天不与人闲。","水定风频起，松高春未还。","薄田仍恶岁，欹枕对秋山。"]},{"t":"秋晚杂兴八首 其七","f":"五言律诗","c":["莫上荒台望，无端是旅情。","云光过沼慢，山影出林轻。","宇宙何其旷，蜉蝣似此生。","旧时歌舞地，花落美人茔。"]},{"t":"秋晚杂兴八首 其八","f":"五言律诗","c":["枯草郭门西，泉声不辨溪。","虎林人让路，鱼沼鹤争泥。","托宿乱离后，当时桃李蹊。","赦书宽酷吏，啧啧在蒸黎。"]},{"t":"宿西台精舍","f":"五言律诗","c":["无意成投宿，心知此地稀。","楼台衔石壁，灯火聚渔矶。","叠浪千峰出，当门百谷归。","一宵吟咏冷，多谢老僧衣。"]},{"t":"南海神祠下作前有浴日亭","f":"五言律诗","c":["望远孤亭尽，凭高古殿尊。","碑留千岁字，神降百王言。","汇水成天堑，排山作海门。","登临何限意，稽首候朝暾。"]},{"t":"答家中洲","f":"五言古诗","c":["鸠鸟出草飞，毛羽何翛翛。","昔为鞲上鹰，今者居无巢。","岂若彩凤皇，高举乘回飙。","小音合笙管，大音中咸韶。","揽德一来下，至今空寂寥。","肃肃虞人罗，千仞安可招。","倚伏本无门，变化谁能料。","何时戾天翰，从君鸣九宵。"]},{"t":"早发新塘浦向广州东山舟中作","f":"五言古诗","c":["寡出春已生，多愁老先及。","穷檐思良友，冻浦命朝楫。","依依海日上，稍稍寒霏入。","物象交晦明，峰云屡开阖。","火田赤尚烧，水岸青犹湿。","秀色兴远林，芳华冒平隰。","去目方屡延，归流一何急。","前禽如退飞，昔屿乍遗粒。","菱蔓或浮没，石窍有呼吸。","伤哉逝川叹，恸矣岐途泣。","百年曾几何，三十未能立。"]},{"t":"罗浮蝴蝶歌送屈翁山","f":"五言古诗","c":["罗浮大蝴蝶，言是小凤皇。","六足盘胸间，四翅交文章。","修眉若杨叶，绣腹如垂囊。","仙人爱文采，挟之游帝傍。","云霞为友朋，沆瀣为酒浆。","倦息珠阙上，饥采若木英。","四海安足飞，来下君子堂。","堂中有行者，比德共翱翔。"]},{"t":"怀何不偕三首 其一","f":"五言古诗","c":["地平如板舆，天广如穹庐。","与君百年间，托足曾无途。","右臂七宝鞭，左肩五岳图。","跨鞍一俯仰，去如流电趋。","朝饮易水头，夕秣越与吴。","道旁皆拊手，太息此名驹。"]},{"t":"怀何不偕三首 其二","f":"五言古诗","c":["南客见毳毛，安知可为旃。","英雄在史册，宁无行路间。","夫子久飞遁，徒步来南山。","长歌宫阙下，北首望燕然。","龙德而蛇行，谁能测其全。","夕醉王侯宅，朝游侠少年。"]},{"t":"怀何不偕三首 其三","f":"五言古诗","c":["昨日异今日，今吾犹故吾。","春风此何时，白发不我谋。","平生两干邪，动止必相须。","子抱荆山珍，我握灵蛇蛛。","良价不一值，千驷犹泥涂。","埋骨置土中，焉辨贤与愚。","修名惧不立，归哉南山隅。"]},{"t":"寄方蒙章","f":"五言古诗","c":["古道日以寡，新知宁不欢。","与子别城隅，恻恻还山间。","高窗落寒木，白雁飞河干。","凉风改秋序，永夜衣裳单。","十梦九见君，不自知其端。","白璧照路衢，过者皆盘桓。","谅无千尺绳，系我心与肝。"]},{"t":"入高峡怀梁药亭","f":"五言古诗","c":["两厓气争高，千仞皆竦峙。","上窥摩苍穹，下视裂地纪。","丛峰互奔辏，乱石相触抵。","棱棱树牙角，跃跃列虎兕。","有如两敌国，各自坚壁垒。","汪洋牂牁江，到兹伏不起。","我来霜雪后，木落见山髓。","篙痕在半壁，石路或倾圮。","缅想涨未消，崩腾复何似。","维天有设险，今则胡须此。","江海无波澜，雄图怅已矣。","扬舲玩苍翠，吹笛娱心耳。","宁忧峡路长，所恨风潮驶。","人生何以乐，佳游对知己。","知己各西来，一帆念东指。","思同山上石，独立望君子。"]},{"t":"游七星岩","f":"五言古诗","c":["立马眺平芜，萧萧见苍壁。","不知何处云，飞作兹山石。","嵯峨各异势，纷诡非一色。","旁通类户牖，中虚成室宅。","藤根上郁盘，石乳下涓滴。","时闻钟磬鸣，宛若仙源隔。","灵峰互亏蔽，微径缘空隙。","颇疑混沌初，有此机巧迹。","遨游兹已屡，岁月真如掷。","川原无古今，世事空畴昔。","徘徊倚层巅，北风感行客。"]},{"t":"登罗浮","f":"五言古诗","c":["八桂秘南经，双山雄粤望。","伟哉昔所闻，于今觏其状。","弥天列青霭，绝地联层嶂。","掩苒草木平，陂陀溪谷壮。","谁言盛积阻，极目何超旷。","云峦时绝续，泉声日奔放。","飞楼候朝暾，倒影排溟涨。","相传蓬岛来，夐矣陶唐尚。","事往诚莫稽，迹湮理无妄。","捣禽应臼杵，喑虎怀仁让。","虫书篆符竹，蝶化遗衣桁。","繄维羽人宅，信此馀风畅。","阴崖饶异产，神药滋盖藏。","名遗炎帝书，类绝嵇含访。","伊昔休明会，位与王侯抗。","时勤玉玺封，未昧高山向。","望秩礼久虚，旱魃人犹仰。","我来仲夏月，溽暑阳方亢。","卧闻夜来雨，飞出龙池上。","何因霈九州，苍生企灵贶。"]},{"t":"宿宝积寺","f":"五言古诗","c":["跻险力未疲，白日停西峰。","将酌石上泉，迤逦投云松。","幽寺肃古苔，绝壁悬高窗。","列席就清阴，开襟面凉风。","石床倚林标，远眺千里江。","原野渐微没，井邑方空濛。","今古一朝暮，宇宙何终穷。","茫茫大梦内，往哲留其踪。","聊为命觞壶，冥寄开心胸。"]},{"t":"游黄龙洞","f":"五言古诗","c":["春草夏更长，洞门蔼馀绿。","晨兴理孤策，衣露时沾渥。","缅邈睇众峰，逶纡赴长谷。","粼粼涉溪影，萧萧翳岩竹。","风磴炫杂花，云潭乱双瀑。","沫雨晴骤飞，游鳞清可掬。","荒宫久榛莽，石岸多隈曲。","方齐昔人踪，兹焉遂幽筑。"]},{"t":"冲虚观","f":"五言古诗","c":["浮生无百年，脆质今二毛。","言寻仙人居，焉惮登陟劳。","褰衣遵涧曲，辍棹逾平皋。","轻风澹馀云，仰见岩岫高。","真宫敞峻宇，飞陛临层霄。","群峰列垣墉，众壑潨溪桥。","石池曜红蕖，乳窦凝金膏。","猿鸟分夜鸣，林泉声相遭。","缅怀著书人，丹砂乐南交。","幽洞俯日月，天路流云璈。","虑释神必凝，理得形自超。","安知后来者，澹荡非吾曹。"]},{"t":"赠别朱子蓉","f":"五言古诗","c":["石鼓响枯桐，琥珀拾纤芥。","声气各有期，类聚焉足怪。","夫子本世胄，弱冠怀慷慨。","著书东溪阳，四海方横溃。","抗志师古人，屈身惭后代。","昨来匡庐顶，更蹑罗浮背。","中夜见朝曦，陵高阅九派。","清旷惬奇怀，浩涆资挥洒。","长揖王侯前，矩步炎州外。","虽抱柳下和，无伤首阳隘。","蹇予卧丘园，贞疾恒不瘥。","握手涉旬时，方舟更逾迈。","高曲虽和稀，宿心为一快。","如何万里别，复此三秋届。","草木变以衰，溪山明可画。","去燕恋匹俦，归雁投蒲稗。","离居易永久，触物多叹喟。","何时御轻风，相寻越江介。"]},{"t":"夏初郊行","f":"五言古诗","c":["仆本草泽人，信宿滞城阙。","出郊见苍翠，超然百忧失。","连峰上不穷，众芳渺如一。","凝云远树杂，冒水新苗出。","升高望海郡，千里何飘忽。","极浦映日明，沧流际天毕。","旷心既以怡，素交复投漆。","挥杯酹流光，百年偶兹日。"]},{"t":"答别余生生","f":"五言古诗","c":["升高望千里，我心伤如何。","何况千里外，送子归岩阿。","岩穴匪君乡，甲第在京华。","莽莽戎马时，伏处亦已多。","霖雨不泽物，积之犹为波。","至人不为龙，无乃将为蛇。","及时念先人，匪独为君歌。"]},{"t":"进帆石门怀古","f":"五言古诗","c":["春至景渐暄，舟行日堪玩。","矧抱昔人心，而怀斯世叹。","平陂互倚伏，今古如宵旦。","石门虽夙游，风物亦殊观。","积峡启奔流，平沙衍高岸。","帆回断飙急，棹去馀萍散。","融融出渚云，役役将归雁。","卷舒宁自期，寒暑为谁换。","浮生贵不朽，金石有销烂。","仰羡楼船人，英声烜西汉。"]},{"t":"赠别陈岱清司李","f":"五言古诗","c":["旌旗集枉渚，舟楫辞河湄。","玄冬首北路，白日方南驰。","霜江无浊流，落叶纵横飞。","扬越非殊乡，山川中间之。","离别忽千里，浩歌临路岐。"]},{"t":"乙巳清明日拟杜七歌 其一","f":"楚辞体","c":["我祖之冢萝山阳，昔者沃土今遐荒。","十里燃烽五里堠，白日黯黯旗飞扬。","手栽三松何松长，谁其守者豺与狼。","呜呼一歌兮歌声促，海隅是日家家哭。"]},{"t":"乙巳清明日拟杜七歌 其二","f":"楚辞体","c":["有墓有墓江一隅，我之祖妣从其姑。","连山百里郁相望，雕虎白昼乘黄狐。","牂牁水长坠飞乌，篙师较计钱有无。","呜呼二歌兮歌不得，苍天贫我曷有极。"]},{"t":"乙巳清明日拟杜七歌 其三","f":"楚辞体","c":["父兮母兮曾城侧，饥乌巢我墓上柏。","清明重九始一来，人寿几何天罔极。","瘗中龙剑跃且鸣，有子虽长不得力。","呜呼三歌兮泪未歇，馀名岂足荣枯骨。"]},{"t":"乙巳清明日拟杜七歌 其四","f":"楚辞体","c":["丹水之山白玉英，我昔三弟皆才良。","三岁读书惊座客，六岁通经言有章。","凤凰巢覆卵亦毁，举杯酹汝来何方。","孤飞之鸟落后行，一矢可折十矢强。","呜呼四歌兮伤怀抱，汝兄虽存今已老。"]},{"t":"乙巳清明日拟杜七歌 其五","f":"楚辞体","c":["青青者蓑下见足，小民命此以为屋。","朝餐薇芜暮黄独，旧陇有苗不得熟。","父兄母子各一方，空山白骨无人哭。","呜呼五歌兮歌思悲，我生犹及承平时。"]},{"t":"乙巳清明日拟杜七歌 其六","f":"楚辞体","c":["平原纸飞挂长棘，幼子孤坟在西北。","桄榔生风溪水黑，青坭污汝好颜色。","去年四岁解学书，今日闻歌莫应识。","呜呼六歌兮歌且疑，天道反覆难得知。"]},{"t":"乙巳清明日拟杜七歌 其七","f":"楚辞体","c":["生不能弯弓骑大马，含毫伸纸徒然者。","千钧之重悬以丝，低头淟涊聊复为。","下有管乐上伯夷，高人嗤我今何之。","呜呼七歌兮歌声阕，男儿盖棺是非决。"]},{"t":"广州客舍夜雪歌","f":"七言古诗","c":["季冬二十日始暝，玄云四塞天气凝。","小雨初从屋角来，渐觉萧萧骇群听。","开轩出立白照眼，把烛低看雪填径。","纷翍相属声更希，委积争高色逾瑩。","童子盛归锦袖中，主人为续清尊兴。","千卮酬酢未颜酡，百巧雕镂随手应。","入馔犹疑虎作盐，迎春不数银为胜。","夜深气象惨更急，卧久衾裯寒不瞑。","俱言黍稷兆维丰，满把琼瑶晓相赠。","从来见少怪者多，亦似西人惊海波。","岁维丙午日亦丙，支寅时戌还相加。","南州炎德济以水，此物或匪干天和。","将无治世气自北，却恐侵人鬓先白。","俟河之清尚有时，如粤之雪难再得。","如粤之雪难再得，为君作歌兴殊极，彼苍此意谁能测。"]},{"t":"麦叔夏斋中留别","f":"五言律诗","c":["结侣即诸昆，深居不凿门。","小梯行木末，虚牖纳山根。","念别来初夏，心伤是故园。","辞君返寥寂，形影自相存。"]},{"t":"扶胥观日出歌","f":"七言古诗","c":["天外千峰沈不起，铜龙漏断银蟾死。","天鸡大叫惊海水，海水蒸变生火云，赤轮微转天地分。"]},{"t":"张穆之画鹰马歌","f":"七言古诗","c":["张公捉笔初无意，乱点离离墨光渍。","袖手方回惨澹思，满堂忽作飞腾势。","尤工画鹰与画马，岂有鬼神立其臂。","是何意态奇且杰，历落高深见胸次。","盖闻夫子侠者流，少年唾手燕然地。","纵横青史一千年，颠倒文韬三万字。","破胆亲持与众尝，许身不惜为人碎。","老来伏枥有馀悲，纸上鹰扬犹负气。","叩心自昔飞炎霜，白虹乃为荆轲至。","况君精诚委笔墨，僧繇破壁将无是。","我有填胸万古愁，百神不语群仙醉。","请君放笔作双鸾，夜半骑之问天帝。"]},{"t":"柏舟行为区母陈太君赋","f":"古风","c":["柏舟两髦犹可仪，陶婴黄鹄曾双飞。","夫人为妇已头白，眼中未识君容辉。","自言生长大夫女，经史胸襟炳如炬。","父母有命儿有心，纵不言承已心许。","心期颉颃同一林，天教殊绝成辰参。","人生意气贵一诺，妾宁负天不负心。","妾父有男妾有姊，君家大夫只一子。","有妻于俗得立孤，无妻为殇终已矣。","素车白马入君门，繇来为义非为恩。","身安分命甘若荠，半生衣枕无啼痕。","当年十五今五十，嗣子成立皆有孙。","呜呼，男儿陷胸绝脰死容易，就义从容人所畏。","青闺冉冉盛年徂，谁能独宿终不渝。","千金之剑赠墓树，至今谈者犹区区，何况赠以千金躯。","乃知未仕报韩者，古今所以为丈夫。"]},{"t":"王华姜哀词","f":"五言古诗","c":["大风覆鸟巢，有雏东南飞。","妾生始三朝，将军陷重围。","臣忠子孝死，父兄同日糜。","城中数万人，斩掠无一遗。","男为刀下肉，女为爨下泥。","阿母任夫人，毁貌为僮奚。","纳妾于中怀，祝天儿勿啼。","诚祷理或应，凶祸中脱离。","奔走依诸姑，不幸先而摧。","丈人为侯公，孤子未及期。","抱儿揖阿母，愿得相提携。","阿母左乳儿，右手与妾乳。","中间缀两泪，不绝陨如雨。","六岁教妾书，八岁教针缕。","十四女工成，馀巧及弦柱。","生世本将家，上马殊跋扈。","秋千及围棋，事事过俦伍。","阿母虽暂欢，亦约之规矩。","时时垂训言，言言称阿父。","十七母捐背，妾念不欲生。","阿母与父兄，节烈当谁明。","食则忘酸咸，衣则忘炎凉。","忍死待须臾，岂复有他望。","侯公后夫人，有弟曰赵公。","结客满天下，好义为士雄。","建牙古雁门，白马如游龙。","侯公家固原，音问时交通。","闻有代州骑，欢跃趋堂中。","玉帛杂遝陈，箫鼓何逢逢。","姊妹私相语，此事来何从。","侯公发书喜，顾妾言从容。","阿舅为汝媒，嘉礼今来降。","云有屈氏郎，才妙时无双。","闻命掩耳走，面颊为之红。","良吉既有期，妾岂得自专。","兼云盛文藻，私心亦惬焉。","先君与母兄，庶几藉言传。","固原至代州，长途弥三千。","后车载帐幕，导骑明旌旃。","和铃鸣我侧，悲笳纷我前。","与君为兄弟，恩义相缠绵。","方君读经史，为君缉韦编。","方君弄柔翰，为君拂华笺。","君歌妾按节，君琴妾操缦。","君行妾接迹，君立妾比肩。","当坐共茵缛，当酒共杯棬。","当镜共形影，当食共芳鲜。","当烛共更漏，当月共棂轩。","于梦共所适，于心同所怜。","君母在岭南，妾得不言旋。","北风缩马毛，驱之出雁门。","产女未弥月，怀中尝苦寒。","忆我初生时，念母涕涟涟。","北首出云州，东路从幽燕。","柁舟下直沽，天冻泽腹坚。","水工日椎凿，冰利舟为穿。","挥鞭历齐鲁，南渡逾长川。","时登秦淮上，怅望东南天。","烹我榆肉羹，开我蒲桃尊。","为君慰劳倦，中夜鸣清弦。","东南诚水国，舟路多洄沿。","举首辄触篷，引足即抵舷。","妾本鞍马人，动止颇非便。","炎洲况蒸湿，恒虑不自全。","既至见君姑，霜鬓无一玄。","子妇堂下拜，姑喜倍万千。","鸡鸣天欲晨，妾起拭衣巾。","上堂问安否，下堂膳羞珍。","承志于未形，纤细敢不勤。","小姑与叔姒，爱我逾所亲。","君家朋好多，一一皆令闻。","切磋及文笔，相与期千春。","从容论前烈，及我先将军。","每从壁后听，慰幸窃自安。","苟活二十年，微愿今获伸。","昔我母夫人，同穴情所敦。","岂不以妾故，忍死为后殉。","男生图嗣续，女生亦何云。","但令父母兄，大义炳无泯。","妾敢恋今乐，而忘昔苦辛。","赋命固有涯，皇天良不仁。","既孕不终育，凶疾婴其身。","上负七十姑，供养谁朝昏。","下顾所怜女，肝心毒如焚。","鬼伯一相催，欲留终无因。","愿君垂令名，妾下报二人。"]},{"t":"赠别","f":"五言律诗","c":["彩凤初育羽，高梧方引枝。","赠君如白玉，追琢在今时。","极浦对遥夜，新知还远离。","平生颇自惜，衰苶已如斯。"]},{"t":"寻家中洲于雁水庵先寄以诗","f":"五言律诗","c":["十载无双鲤，三秋在五羊。","客居闻傍柳，诗梦每临塘。","举世推能手，终身泣雁行。","不知违侍从，玄鬓几经霜。"]},{"t":"麦叔夏斋中作","f":"五言律诗","c":["小园深巷里，一岁一来过。","花木自春色，其如长叹何。","命知休百念，老识保元和。","复有闲身累，留连苦不多。"]},{"t":"何文止垂示经蔚园长句兼辱寄篇依韵奉答","f":"七言律诗","c":["先公遗构此溪滨，叹息年年在比邻。","帐罢管弦曾几日，史书名姓即千春。","画图旧壁真生草，如镜方塘渐起尘。","多谢瑶篇远相问，疏慵不称负薪人。"]},{"t":"甘竹滩上留别何皇图即送之罗浮","f":"七言律诗","c":["一棹横滩拍拍轻，两崖相揖隔滩声。","已伤此地苍茫别，却羡名山自在行。","碧落敛云峰影满，秋溪凋叶瀑流明。","他时念汝仙坛上，夜半歌成日已生。"]},{"t":"初春送林叔吾入都","f":"七言律诗","c":["一鞭丝雨百花生，花信随君北到京。","欲借寇君还百姓，暂囊姜被别诸兄。","春江雪水开茶色，夜店佳人漉酒声。","好熟黄金台下路，马蹄终要自家行。"]},{"t":"送何不偕","f":"七言律诗","c":["离杯怅惜粤天春，远色青青稻叶新。","江海渐无高卧地，莺花如笑未行人。","多年攻玉同山石，万里辞根学水蘋。","南北路歧难定计，许身须念白头亲。"]},{"t":"握山唁予新塘率尔写怀因寄止斋寒塘两兄","f":"七言律诗","c":["频年兄弟得相依，散诞江乡共掩扉。","薄酒上颜开卷后，竹竿持艇探泉归。","眠贪笑语横支枕，出忘形骸乱著衣。","今日对君唯有叹，鹣鹣只翼不成飞。"]},{"t":"岁暮有作","f":"七言律诗","c":["死前生后事无涯，只系皇天不系才。","得酒直须千日卧，摊书空过十年来。","身同海燕家长寄，日与河鱼夜并开。","深掩柴门对童稚，一冬飞尽故园梅。"]},{"t":"寄李相如","f":"七言律诗","c":["南方归客尽能传，玉貌虬须各宛然。","马上诗成临战处，幕中筹算未形先。","天悬山驿三千里，醉别江船十八年。","莫讶双鱼频不到，昆池流水入西偏。"]},{"t":"客亭逢屈泰士","f":"七言律诗","c":["山阁依依杨柳新，别君同惜少年身。","追寻许事如前日，已觉相逢是老人。","仗剑几时回鸟道，攀髯无复望龙鳞。","秋江酒醒还分手，各掩柴门到好春。"]},{"t":"下华首台留别旋庵海发上人","f":"七言律诗","c":["木绵花发似春风，不信登临是岁终。","百粤晴江山色外，六时行径水声中。","自来下土为游子，肯料东林别远公。","他夜相思何处望，白云天上佛灯红。"]},{"t":"木绵花歌","f":"古风","c":["粤江二月三月来，千树万树朱华开。","有如尧时十日出沧海，又似魏宫万炬环高台。","覆之如铃仰如爵，赤瓣熊熊星有角。","浓须大面好英雄，壮气高冠何落落。","后出棠榴枉有名，同时桃杏惭轻薄。","祝融炎帝司南土，此花无乃群芳主。","巢鸟须生丹凤雏，落英拟化珊瑚树。","岁岁年年五岭间，北人无路望朱颜。","愿为飞絮衣天下，不道边风朔雪寒。"]},{"t":"南海神祠古木绵花歌","f":"古风","c":["祝融帝子天人杰，凡材不敢宫前列。","挺生奇树号木绵，特立南州持绛节。","拔地孤根自攫拿，排空直干无旋折。","生气长资渤澥宽，老鳞不受冰霜裂。","青春二月当艳阳，观者千人皆叹绝。","繁英贯日下无阴，丽色烧天炙能热。","堂堂正正势莫当，密密疏疏随所设。","落瓣全铺细草青，飞须欲满游丝缬。","似闻昨日铜鼓鸣，海神黼黻朝天阙。","玉女三千笑口开，电光一夜枝头掣。","受命扶桑捧日车，旌旗片片裁虹蜺。","六龙战胜各归来，髭髯尽化玄黄血，不尔花红何太烈。","君不见四照之枝不可寻，赤松渺矣火井深，为君岁岁呈丹心。"]},{"t":"增阁歌寄薛剑公","f":"古风","c":["吾友薛夫子，好饮还好仙。","酒铛丹鼎杂一室，幽竹白石罗堂前。","更向堂西架新阁，苍翠纷纷坐前落。","七十二峰流水东，青天秀出芙蓉萼。","主人高坐乌皮几，短发萧髾垂两耳。","胸中万卷心豁然，笔下馀霞散为绮。","才高步阔骇世俗，文举杨修尽儿子。","朝见罗浮之鹤飞晴烟，夜见酒旗之星明上天。","举觞招鹤鹤来下，放身八极同周旋。","我闻此阁未得上，疑是华阳洞里三层轩。","会须更作通明客，还就元龙地上眠。"]},{"t":"寄题魏和公吾庐","f":"七言古诗","c":["今之人材可屈指，魏季宁都隐君子。","放舟溟海六月风，茧足幽州八千里。","巨鱼吞舟人食人，白浪黄沙入睚眦。","危途曾不废啸歌，壮心已觉齐生死。","往时为我言翠微，诸峰秀出旁无依。","丹崖劖削下绝地，石窦委曲中开扉。","蚍行猿引步且伏，径尽高原见茆屋。","分星牛斗即比邻，福地金精若奴仆。","良朋或近或远方，伯兄仲兄齐雁行。","干戈之际独无事，花下往往闻宫商。","盈阶况复美子弟，讲德馀暇兼文章。","有时雄辨相奔射，偏师角立还坚壁。","有时急难相周旋，首尾皆至如率然。","嗟哉古道久已丧，老矣馀生复谁望。","闻君近者结吾庐，亦拟吾庐结其上。"]},{"t":"送屈翁山之金陵","f":"古风","c":["地何必生山川，天何必有日月。","一升一沉使我老，南北东西令人别。","洪河之水孤蓬根，不知似我还似君。","神州萧条寰宇黑，英雄失路归何门。","文章亦是千秋事，兴则为云降为雨。","雄剑高飞雌剑留，夜上金陵望牛女。"]},{"t":"赠余鸿客","f":"古风","c":["蜀犬不识日，群吠声狺狺。","越人贱章甫，不以易文身。","中原龙战二十载，万事反覆如朝昏。","我行惊惧伏草莽，举国大笑为愚人。","何来年少金陵子，肯道相思满人耳。","三年觅我二樵间，一夕逢君五羊市。","倾山倒海见胸臆，白日照耀肝肠里。","羁贫无酒留君欢，对坐江楼饥不起。","是时积雨江上晴，丹枫乱落寒蝉鸣。","长风驾浪作丘壑，蜃楼海市相峥嵘。","赵佗朽骨为黄土，陆贾诗书亦何补。","朝台空有汉家名，浩叹今人不如古。","今人古人间容发，举足之分邈燕越。","眼前得丧等烟云，身后是非悬日月。","怪君茂龄怀抱奇，严君风义兼能诗。","曾窥一二每心折，安得天马无龙驹。","荒城气黑落日短，强为吾子停斯须。","如君意气复何道，所愿故心终不渝。"]},{"t":"春夜同王说作王东村程周量宿六瑩堂怀主人梁药亭","f":"七言古诗","c":["南州秋色初流火，西方月向梧桐堕。","当时欢会草堂前，一月词人满高座。","主人命倒玉缸春，小奴跪进雕盘果。","飞觥授简恣所为，画地书天无不可。","今夜草堂集朋辈，主人安在在驴背。","梧桐未叶月不明，银灯吐焰空相对。","檐头急雨如扬沙，飞向君前作雪花。","雪中旅店关山路，欲梦何门觅君处。","黄金台畔士如云，几许风期得似君。","明朝便奋南溟翼，老夫不勒北山文。"]},{"t":"送谭天水入闽","f":"古风","c":["蓝关秋高草色黄，清溪枫落兼微霜。","去棹萧萧荻花下，念君可是徒然者。","周郎千骑三山东，画堂邀客飞银骢。","折铛故鼎尚有耳，老夫岂不闻高风。","风尘意气望相识，何况与君心莫逆。","心莫逆，吹笙竽。","见故人，乐何如。"]},{"t":"石湖观梅花分得动字柬罗仲恭罗显哉兼怀湖主人罗澹峰","f":"七言古诗","c":["溪西千树当时种，数尺枝条柔可弄。","不踏湖堤向一年，已觉繁花密无缝。","经过昨日此匆匆，两夕怀思不堪诵。","栽花主人隔千里，花下扁舟与谁共。","虬髯逸兴迥不群，公子翩翩复殊众。","折简相招到石床，新醅不惜开银瓮。","远方英俊兼秦越，满座雄谈杂嘲讽。","是时霜后积水清，湖西滉漾波光动。","四山开朗有佳色，孤屿萧疏欲含冻。","共誇密雪赋梁园，复讶行云入荆梦。","幽光漠漠去岸高，素色鳞鳞压枝重。","拂衣屡爱轻瓣飞，行杯更遣浓香送。","逆风十里气尚满，沿流百步溪犹壅。","高天可厌白日坠，厨人未报清尊空。","老夫短棹欲早归，上客班骓亦停鞚。","开笺意思已潦倒，下笔词章乃狂纵。","寄谢梅花勿笑人，繇来韵险难为用。"]},{"t":"送张南士归山阴","f":"古风","c":["八月从象郡来，九月归稽山下。","天生落落穆穆人，姿形不类风尘者。","广州城西东篱花，酒杯偶共良朋家。","匆匆含意未及道，相视颠毛俱有华。","著书何处期之子，谢公精舍清晖里。","云中黄鹄安可留，目送飞鸿日千里。"]},{"t":"过杨伊水西郊草堂因送之游吴越","f":"七言古诗","c":["君家草堂在西郭，不远人间似岩壑。","浮丘一点下平芜，郁水千峰映篱落。","触热相过五月中，凉飙不道炎蒸恶。","开轩气象已爽垲，入座清言复玄著。","爱君识鉴精莫伦，过目雄雌辨飞鹊。","爱君墨妙不可当，下笔峥嵘走龙蠖。","千年论事直指掌，八法从心绝缠缚。","闲来为我言素怀，便欲从兹理芒屩。","尚平多累粗已毕，吴越清秋有前约。","钱塘怒涛若车马，九华峰峦如剑锷。","揽将明秀入毫端，直取幽奇恣挥霍。","快哉壮志我所同，恨不俱飞比黄鹤。","胸中约结开何时，梦里江山已成昨。","倚栏惆怅见千里，落日回风散城铎。","虞翻故苑空青蝇，赵尉馀基尚丹雘。","远天暮色方掩霭，近寺疏钟满寥廓。","出门一揖因送君，白头好纵青山乐。"]},{"t":"端州阅江楼","f":"七言古诗","c":["牂牁之江千里来，羚羊峡口一线开。","长波鼓荡气不泄，沙边吼怒成风雷。","五月六月西潦至，端州古城昼常闭。","即今水落洲渚高，急流尚作奔扬势。","谁飞杰构临江隈，下有孤石名嵩台。","崇基峥嵘山岳立，古榕诘屈蛟螭回。","百道文窗浮木末，四楼角立何轩豁。","曲阁周流复道长，高廊四注空阶阔。","犹忆登楼发尚髫，楼前亲见海龙朝。","万乘旌旗屯北郭，千官车马聚寒潮。","二十年来重系舸，泪滴阑干独愁我。","白云飞尽苍梧深，满目寒山日西堕。"]},{"t":"赠别陈季长","f":"七言古诗","c":["白玉有美不自言，陈生虽讷何温温。","天球大贝在高阁，见之使我惭轻薄。","问君何来东海滨，蓬莱宫阙浮金银。","峨冠仙人挟龙杖，高步绰约行青云。","觞倾松花大笑起，挥手三招鲁连子。","丈夫济世有苦心，安用辛勤求不死。","回车万里趋南极，神州九点秋烟黑。","离家有子正孩提，发白身长不相识。","夜梦三山芳草春，挂帆辞我别愁新。","重来肯料相见否，尹也东西南北人。"]},{"t":"送程周量起复入都","f":"古风","c":["英英江上云，浩浩江中水。","水流日下云日高，与君离隔情如此。","无钱沽酒赠君别，就君醉饮清歌发。","庭前乍响金风初，碧树离离照新月。","新月西飞向沧海，海中老蚌含光怪。","珊瑚枝长犀有纹，南州之宝无君对。","先君门下三千人，就中程子尝冠军。","即今贤达每不乏，野人于汝偏情亲。","二十年间如电扫，旧时游处今荒草。","屈子能争日月光，王裒分守松楸老。","人生出处各有宜，看君高步何崔嵬。","神龙吐气首万物，大鹏整翮盘天池。","往年被命颁新诏，千骑东方年最少。","磨厓手勒泰山碑，把笔醉题尼父庙。","昨者麻衣反南野，江上聚观群拥马。","盛名往往动时人，及见恂恂一儒者。","沧海终为百谷王，如君气度谁能量。","从此一抔封已毕，报恩身健日偏长。"]},{"t":"寿姚香山熙止","f":"七言古诗","c":["英雄之才久不作，汗简丹青殊寂寞。","君侯飞盖自北来，玉面虬须照南国。","香山孤城在海岛，高舶如山浪如岳。","挥鞭一指招曰来，群盗如麻皆面缚。","虎饱则伏鹰饱飞，千钧弩为鼷发机。","发踪指示略未毕，剧贼已落千重围。","孤城许许吹霜角，君侯左佩莲花锷。","马前亲系叛人头，秋日俘归五羊郭。","能擒能纵古所难，况君生长从儒门。","大兄雄武冠宇内，介弟补衮居言官。","天生材气应无匹，射策长安君第一。","繇来豪俊本为民，一令天涯未言屈。","士元不展称凤雏，缝裾虞诩徒区区。","看君不动声与色，万骨欲朽今重肤。","我为此歌进玉斝，祝君之寿寿天下。","太史在朝稗在野，山人不是谀人者。"]},{"t":"送沈甸华归杭州","f":"七言古诗","c":["边沙作霾曀衢陌，行子居人总成客。","五羊城里三见君，匆匆不得论心迹。","君驱高毂日涉野，我倚长竿钓山下。","毛锥不及带刀人，牧马童儿笑儒者。","夜梦西湖春兴生，归艎正月送君行。","大小岭头雪未尽，南北峰高花始明。","花光雪色遥相接，花残雪尽应停楫。","六桥清浅见泥沙，潜虬何处藏鳞鬣。","倒尽今时别酒樽，余亦著书终闭门。","命驾相思何可易，因风书札倘能存。"]},{"t":"晚饮湛用喈双峰阁即送之北上因寄程周量","f":"古风","c":["秋月已向尽，篱花黄几枝。","北风昨夜吹木叶，一一飞度楼南池。","登楼旷望见千里，廓落天围净无滓。","海色为霞树外明，双峰如黛空中起。","龙鳞相比万室开，中有甲第排云雷。","君家尚书明绝学，自堰长江筑钓台。","闻孙复得任公子，手探骊珠来赤水。","再献君门虽未售，南琛何患无知己。","塞鸿摇曳向南声，行子迢迢更北征。","居人次第起相饯，青衣十五调鸣筝。","饮君酒，送君行。","中路秦淮雪正霁，到日长安花始明。","长安虽乐未西笑，因忆程生最同调。","风雅曾深海上期，声华早擅中原妙。","别来五载音问稀，芙蓉阙下振朝衣。","凭君为寄长相念，便理云翰追逐飞。"]},{"t":"赠郭清霞","f":"七言古诗","c":["丈夫名不千年朽，此身须后千年老。","秦皇汉武尔何人，神仙不在蓬莱岛。","郭侯少小明阴符，胸中热血为洪炉。","铸成宝剑无所用，却羡丹砂来海隅。","尽日著书言易体，竹里柴门长不启。","十年客邸绝经营，百口何曾少薪米。","谁云大道贵同尘，犹自徘徊恋旧恩。","彭泽但题新甲子，灞陵宁识故将军。","雌雄龙吼门前水，文武火凝烟气紫。","白发无忧上鬓生，壮心只惜同灰死。","虽然不死亦奚为，我心未说君应知。","待予手弄扁舟日，乞尔山中五色芝。"]},{"t":"查将军怀孔招同梁药亭屈翁山淩天杓林叔吾尹乔岳宴集东湖作","f":"七言古诗","c":["湖亭日午闻吹角，秋堤柳色开莲幕。","将军飞盖出城来，白驹躞蹀黄金络。","临阶下马肃众宾，先酌金杯揖野人。","紫罗之巾幂新果，翡翠之盘行百珍。","湖中坎坎暮击鼓，玉面童儿自歌舞。","水影拖翻金镂衣，风声促拨银筝柱。","如钩新月挂林低，片片明霞飞向西。","潜鱼跃浪白鸥起，乾坤轩豁呈端倪。","帐前武士环趋走，利剑在腰弓在手。","何物儒生老且狂，葛衣高坐颜胡厚。","将军好士匪自今，脱略礼数披胸襟。","终筵敬爱不知倦，使我入夜无归心。","我闻卫青有揖客，信陵每下侯生色。","意气相倾古不无，文章感召何繇得。","将军善将兼善诗，四郊无事时复为。","风流高会便千古，安俟辛勤岘首碑。"]},{"t":"赠别董苍水","f":"古风","c":["凤凰之美不在毛，山间有鸟名寒号。","区区文采欲自见，使我太息伤吾曹。","丈夫身当能骑臂能射，姓名直冠麒麟画。","不然探取金匮石室书，褒贬千秋壮心魄。","谁能奡奡兀兀作孺生，朝朝暮暮咿唔声。","我之蹭蹬不足道，看君健笔何纵横。","盛时一第易反掌，况君昆弟人皆仰。","何当鼓棹恣闲游，七泽三湘迷所往。","峰头榻得岣嵝碑，苍梧云影飞参差。","与予相见五羊郭，袖中千首南行诗。","争奇竞秀安可极，沧江白石生涟漪。","曳履侯门心不屑，怀刺江城字将灭。","强开笑口学周旋，舌本犹生面颜热。","寓楼正月多寒风，狂潮打岸声汹汹。","痴吟对客自摇首，得句出户犹书空。","咄嗟乎，眼前富贵既无取，身后空名亦徒苦。","天涯此别一潸然，异日期君定何许。","骊龙颔下径寸珠，因风莫惜沉香浦。"]},{"t":"送淩天杓归金陵","f":"七言古诗","c":["前年相识花正飞，今年花下送君归。","珊瑚洲北一挥手，落花如泪沾人衣。","看君长身美如玉，上马顾盼何光辉。","酒间意气横海岳，笔下错落生珠玑。","旧京虎踞龙盘地，往事苍茫足长欷。","秦皇枉用厌陵金，刘生早识兴王气。","前辈风流安可期，羡君归去卧茅茨。","停梭窦妇机初下，奉母潘郎鬓未丝。","东山行乐无时节，南海追游暂应阔。","寄余浩荡千载心，挂向秦淮满船月。"]},{"t":"赠别王础臣","f":"七言古诗","c":["天生豪杰将何益，王郎四十为闲客。","无意初从岭外行，因人更有黔中役。","高牙大旆照江浒，欲驻征帆那可得。","客中沽酒赠别离，可惜荔枝犹未赤。","王郎眼大少所推，长身广颡好髯髭。","数著欲了天下事，千载不受英雄欺。","走笔文章盈百纸，廿史六经如泻水。","魏武才堪捉佩刀，杨修未足称儿子。","去冬相识三城南，一日不见思不堪。","如何弃我复远道，五溪蛮洞多烟岚。","旧谙风土应无疵，万里为亲备甘旨。","醉别天涯日暮心，丈夫未必终如此。"]},{"t":"方邵村以诗序见贻赋此谢之且以送别","f":"古风","c":["大暑已过风初秋，金陵归客停扁舟。","满城冠盖争饮饯，一日三醉尉佗楼。","醉来翰墨无所惜，巨笔如龙飞肘腋。","盈箱绢素积未开，一篇及我山中客。","鸿文铁画光陆离，义心苦调君所知。","枯树王裒今老矣，白头玄晏非公谁。","方公方公何潇洒，十年不复乘骢马。","地生名胜咨幽人，天与闲身作游者。","燕支之北昆明西，罗浮日出闻天鸡。","槟榔荔枝日大嚼，丹砂石髓如红泥。","为君歌，送君归。","不能黄鹄比翼事四海，双犍相伴还扶犁。"]},{"t":"赠别毛行九兼寄其从父子霞","f":"七言古诗","c":["仆不与时为俯仰，虽在人间少还往。","逢君一揖酒未消，当时不及论宗党。","昨来再见通姓名，世交于汝为弟兄。","我父之师君从祖，凤毛麟角相峥嵘。","少年何处求高价，足迹依稀遍天下。","笑谈满座自生风，咳唾为珠皆照夜。","黄鹤高楼十载前，襄阳逋客曾周旋。","君家名辈信杰出，后先卓荦多英贤。","闻将翰墨动天子，三召比来皆称旨。","老翁七十复何求，出处千秋在青史。","如君健足乃绝尘，燕台可以空群伦。","贫来赠别无杯酒，为报襄阳旧隐人。"]},{"t":"题鲍子韶独醉图","f":"古风","c":["古之饮酒人，陶公与阮公。","一觞一咏安足道，高天万里嗟冥鸿。","方其未醉时，五岳横心胸。","酒杯泻作大海水，白日倒落沧溟东。","鲍生能饮不数斗，醺然颜色如花红。","开口慷慨天下事，走马来自燕昭宫。","与予论交有世好，披图使我题其中。","吁嗟乎，天地变化闭塞将复开，如君磊落跅弛真奇才。","把酒独醉胡为哉，急理健翮排九垓。","燕颔书生空愿酒泉郡，青莲居士但筑糟丘台。","君不见沛公王业基，四百壮士鸿门酒一杯。"]},{"t":"赠别查韬荒","f":"古风","c":["去年梅花开，君逾梅岭来。","今年菊花节，君归理兰枻。","天涯客久愿君归，却惜君归即成别。","南山有鸟北张罗，人生知己安能多。","况皆穷贱伏草莽，吴烟越水劳经过。","比者追欢时快意，左把杯盘右文字。","白日未尽红烛催，不肯相逢不沈醉。","南溟波浪生长风，散作高言满箧中。","珠玑错落映四座，星月倒影横霜空。","朝汉高台雉堞古，伏波故道牂牁通。","逢时自见各有以，芟彝割裂皆人雄。","霸图不足迥青睐，麟阁千秋亦谁在。","已甘藿食谢当时，共许著书传后辈。","平生未识已相关，与子年华未老间。","前路尚宽相见日，西风莫损别离颜。"]},{"t":"送郭皋旭归当湖","f":"七言古诗","c":["白日欲尽东方高，寒云黯黯天风号。","故人束装已逾月，欲发不发心劳劳。","北登大庾阻舟楫，西瞻郁水多旌旄。","同人饯送每不及，各自掩户依蓬蒿。","孤帆明发挂珠海，赋诗我独含霜毫。","往时有句用不得，昨日事势非前朝。","夫子文章擅时誉，千金挥洒真人豪。","尽披肝胆与时辈，每思羽翼乘烟涛。","曷不归飞向林皋，岸花三月湖水阔。","为君把钓连巨鳌，请君酌酒倾葡萄。","青天会得开老眼，绿鬓应须减二毛。"]},{"t":"寄李相如","f":"七言古诗","c":["李公十六生虬须，虎头豹眼长身躯。","诸生籍中弄文笔，姓名已自闻江湖。","五花大马黄金络，终日邀人讲兵略。","平原不算是贤豪，季生未许矜然诺。","上书自献城南田，卖作军门犒士钱。","宝刀屡试濡缕血，乌府连分节钺权。","独当一队江南北，入对君王每前席。","边头老将避锋芒，白面儒官论资格。","与君失志复淹留，对卧飞云百尺楼。","狂歌大叫取一醉，凤观虎视轻王侯。","堂前侠客千人食，盎底屡空曾不识。","千金初制鹔鹴裘，脱手赠人无吝色。","我时弱冠君及壮，置身自许云台上。","而今丝发生满头，地北天南一相望。","燕山作客近何如，落拓柴门久阙书。","闻道长斋习禅寂，那能不饮送居诸。"]},{"t":"程周量出守桂林作此寄之","f":"七言古诗","c":["凤凰昨夜衔天语，天遣郎星向荆土。","北阙新辞粉署云，南行且作芃苗雨。","双旌晓出都门高，八桂遥开秦郡古。","一时送者皆太息，千载延之今再睹。","纷纭饮饯日不暇，错落诗篇读旁午。","共惊才子守一麾，岂识仁人利须溥。","天生贤俊以为民，坐保清华独何取。","始安岭外多阻深，戈甲虽销犹疾苦。","生事唯应职荷锄，人家大抵稀环堵。","更加杂处有兵卒，况乃流徙多浮窳。","兼资宽猛昔所闻，丕变诗书亦其矩。","虎符龙节既在操，秋杀春生能自主。","惟君昨在司马日，眼利机明孰能伍。","笔前进退万将帅，阶下驱驰半熊虎。","称旨尝闻西使秦，宣恩往者东临鲁。","囊中馀智办有馀，斗大数州宁足数。","下国聊开历块蹄，天池会理搏风羽。","炎州故人日相忆，十年不见心如许。","方候归艎到海涯，宁知取道从湘浦。","白竹湖头秋月高，为君一把西江橹。"]},{"t":"放歌行答何皇图","f":"古风","c":["君不闻汗血驹，坠地即能走千里。","日食不能满一石，低首盐车鸣不起。","又不闻丹穴雏，览德徘徊天路衢。","积粟如山不一顾，食必竹实栖高梧。","古来志士不草草，易得是饥难得饱。","陶公独为子春歌，此声千载君知道。","池亭细语暮春天，出处之义何皎然。","相门才子有公等，亚夫德裕安能贤。","四诗赠我殊霶霈，三舍犹应避旌旝。","丈夫相得在中心，字句形骸乃其外。","灵洲之气久不开，骄马蹴踏朝汉台。","世风披靡不可道，岂无豪俊多英才。","陈梁丘海四人杰，后生不识为何来。","爱君意气独健举，欲驱短翮乘风雷，披衷置腹无矜猜。","呜呼，即今谁能为此语，君家昔盛君尚孩，安得还君旧府当三台。"]},{"t":"送离患上人住静惠州兼怀叶许山","f":"五言律诗","c":["众水各得月，月光元在天。","道人无去住，临别莫悽然。","暑气当船小，峰形入阁圆。","因依贤地主，一定出何年。"]},{"t":"赠洪药倩虞部","f":"五言律诗","c":["各有千秋志，俱行万里回。","论交为后辈，相见慰从来。","话向杯前满，心当烛下灰。","十年沧海变，老尽济川才。"]},{"t":"卧病五羊闻故人蔡艮若之子约行授室情不自已伏枕上得二律感叹遂多勿作寻常诗读也二首 其一","f":"五言律诗","c":["汝早孤能立，艰虞亦有今。","虽安为圃计，未负带经心。","读易知馀庆，称诗在鼓琴。","先公期望意，正不必华簪。"]},{"t":"卧病五羊闻故人蔡艮若之子约行授室情不自已伏枕上得二律感叹遂多勿作寻常诗读也二首 其二","f":"五言律诗","c":["十载亡吾友，中宵有泪痕。","何曾离梦里，容易闭泉门。","鹤发亲犹健，鹓雏翼渐鶱。","一抔仍未卜，惭负不堪言。"]},{"t":"漫兴三首 其一","f":"五言律诗","c":["借屋增江口，悠悠十八年。","力穷群籍内，身老众人前。","曲巷来风满，闲门得月偏。","有生同是寓，终恋墓边田。"]},{"t":"漫兴三首 其二","f":"五言律诗","c":["简讨吟诗地，江门匝海涛。","渊源洙泗远，磊落楚云高。","近世无真气，斯人也自豪。","文章本情性，笑汝小儿曹。"]},{"t":"漫兴三首 其三","f":"五言律诗","c":["少师生民杰，善谏何雍雍。","马地飞雄笔，龙墀泣剑锋。","独当天下难，乞老海头峰。","百八年来事，良时不可逢。"]},{"t":"出门","f":"五言律诗","c":["未有出门意，篙师候水涯。","故人书适至，江上夕初佳。","白鹭飞闲世，青天入旷怀。","还如张翰去，不复俟同侪。"]},{"t":"所见二首 其一","f":"五言律诗","c":["禁里曾通籍，人前不下床。","未离阿保手，已绾大夫章。","一饭中人产，千金匹马装。","白头蓬室者，只自爱糟糠。"]},{"t":"所见二首 其二","f":"五言律诗","c":["绣袷紫头巾，骁腾马上身。","臂鹰飞啄鸟，手弹远追人。","共窃军符夜，相邀野草春。","不知营一醉，乡曲几家贫。"]},{"t":"侧首","f":"五言律诗","c":["侧首西南望，平生李左车。","依人丹凤阙，近日碧鸡书。","世事那能极，为心尚有初。","虎头今白尽，飞跃更何如。"]},{"t":"西行","f":"五言律诗","c":["挂席春风缓，融融对物华。","远天排雁字，新水育鱼花。","岸曲盘千树，山寒闭数家。","依然西去路，今昔不同嗟。"]},{"t":"宁都魏善伯寄示其兄弟文集率题二诗报之 其一","f":"五言律诗","c":["一面今犹阻，千秋志未孤。","把君兄弟作，仿佛见眉须。","有力牵衰眼，多风激懦夫。","宵分凉不寐，灯影落高梧。"]},{"t":"宁都魏善伯寄示其兄弟文集率题二诗报之 其二","f":"五言律诗","c":["遂以文章著，殊乖作者心。","道犹资化育，价只待璆琳。","大地孤行迥，青山一卧深。","人来问容色，发白已如今。"]},{"t":"赠别赖子弦任切刚归宁都","f":"五言律诗","c":["二子何开朗，来知自翠微。","旅中蔬饭毕，江上布帆归。","路密关心短，情深出语希。","后期能不负，家在荔枝矶。"]},{"t":"送李苍水入国学兼寄相如二首 其一","f":"五言律诗","c":["燕齐一万里，风雪几人来。","岳势晴犹白，河声撼不开。","新吟添倚马，古意满衔杯。","宫是招贤旧，无妨国士才。"]},{"t":"送李苍水入国学兼寄相如二首 其二","f":"五言律诗","c":["古道今芜绝，吾乡尚有人。","老于朋友内，觉汝弟兄真。","岭树寒犹叶，边沙暖不春。","天涯新得叔，风义好相亲。"]},{"t":"送何不偕之桂林","f":"五言律诗","c":["千里西江路，多奇是桂州。","裂山行巨浪，依石上孤舟。","君见他乡叶，都归故国流。","应书得意句，相问海东头。"]},{"t":"秋夜王东村梁药亭刘汉水王蒲衣梁王顾家夔石过宿独漉堂读先司马遗集枉赠名篇赋答二首 其一","f":"五言律诗","c":["九原不可作，古道更谁陈。","夜烛开遗草，寒斋共故人。","星横骑尾气，霜老枕戈身。","一读投湘赋，泉扉自此春。"]},{"t":"秋夜王东村梁药亭刘汉水王蒲衣梁王顾家夔石过宿独漉堂读先司马遗集枉赠名篇赋答二首 其二","f":"五言律诗","c":["千古伤心地，当年洒泪馀。","空还新息革，终负贾生书。","绛阙恩虽满，苍生望尚虚。","乾坤同气在，异代岂云疏。"]},{"t":"月夜姚菊里载酒招同郭清霞陶苦子邹中和简文震重集邹仪生寒玉堂同赋用空字","f":"五言律诗","c":["寂历霜天外，宵来有雁鸿。","树声风自北，池影月方中。","良会复能再，清尊况不空。","登台望星彩，神剑为谁雄。"]},{"t":"李方水疾新愈同唐明犀梁药亭陶苦子吴山带何郢人问之天乐堂分得醒字","f":"五言律诗","c":["故人新勿药，美酒更开瓶。","虽复层城里，何妨一夕停。","空阶行坠叶，疏树上寒星。","细数更筹笑，人间梦未醒。"]},{"t":"题丹霞雪干图为澹归大师寿","f":"五言律诗","c":["绝巘全高寄，孤根压众芳。","已成空谷玉，如带掖垣霜。","世想和羹实，天留暮岁香。","南枝长不老，微笑傍空王。"]},{"t":"人日新晴即事","f":"五言律诗","c":["新年连旧雨，晴好独当人。","兵气昏南纪，天心惜此晨。","远峰偏耸日，一鸟自鸣春。","徵敛村村急，桃花何处津。"]},{"t":"春阴","f":"五言律诗","c":["春色来何处，郊云密自西。","酿花成大叶，催雨作新泥。","野日笼无影，遥峰截欲齐。","良苗今有喜，一为报烝黎。"]},{"t":"丹柯阁留别同梁药亭二首 其一","f":"五言律诗","c":["岂得便归去，江头春正佳。","偶来唯任兴，小别亦伤怀。","履迹朝盈户，吟声夜出斋。","南园今往矣，风雅在吾侪。"]},{"t":"丹柯阁留别同梁药亭二首 其二","f":"五言律诗","c":["大海天将曙，高窗烛未灰。","各呈诗问病，自把历占来。","岸柳随潮映，溪花到郭开。","两人乘一艇，半日是朝台。"]},{"t":"春日过刘汉水李世臣于黄木山堂王东村欧阳伟人林本茅偕至即事分赋兼怀李铎臣西行得青字","f":"五言律诗","c":["轩盖来深巷，芳菲满一庭。","小花丛作白，新柳浅为青。","觅句兼春枕，挥杯到夜星。","永怀西上客，江月自扬舲。"]},{"t":"答任五陵","f":"五言律诗","c":["城阙东西路，相寻不惮劳。","肝肠违世古，诗卷与人高。","玉纸裁轻扇，银钩落细毫。","经年无以报，空自愧投桃。"]},{"t":"送姜山上人游南岳","f":"七言律诗","c":["送师西去重低徊，曾上衡山绝顶来。","夏帝碑芜虫篆遍，楚天峰断雁行回。","灯前鬼芋穿沙出，霁后僧门凿雪开。","正是到时二三月，上方明月下方雷。"]},{"t":"寄程周量","f":"七言律诗","c":["薇省仙郎安好无，别来三见落庭梧。","西风不尽雁初下，明月相思天一隅。","内诏写归金凤纸，新诗擎出木难珠。","故人落魄南江上，稳系藤蓑作老夫。"]},{"t":"李相如自滇池录示近诗率尔赋寄","f":"七言律诗","c":["游子辞乡十九春，诗加畴昔更清真。","粤台风雅稀前辈，蛮国山川老此人。","帐下飞书银箭晓，日边骑马剑花新。","眼中无限英雄泪，尽化明珠寄所亲。"]},{"t":"屈翁山薄游代州镇将赵君妻以姊子本秦人也读其白母书诗以纪怀","f":"七言律诗","c":["寒垣提剑欲从谁，边草年年只早衰。","乌鸟私情愁日短，雁门书札叹秋迟。","新为夫婿逢秦女，自写佳人入楚词。","旦夕彩衣还侍养，一双飞作凤来仪。"]},{"t":"腊月望夜湛用喈水边新阁落成招同诸子月下小饮","f":"七言律诗","c":["回塘天净见诸峰，新阁初开月在东。","倒影自摇窗户里，满轮飞入酒杯中。","孤村岁晚闻长笛，一叶寒声落细风。","渐逼春归幸邻近，花边不使坐成空。"]},{"t":"寄送蒲衣自丹霞之福州","f":"七言律诗","c":["发心初不与人言，二十辞家事世尊。","禽鸟就斋分石钵，猕猴同路上山门。","题诗空谷吟声应，宴坐秋潭瘦影翻。","此去八闽潮水上，荔支青榄似乡园。"]},{"t":"鹤","f":"七言律诗","c":["远视高肩有凤文，生来不称在人群。","朱门香稻长如客，明月沧江总为君。","一种昂藏临水岸，数声清迥落寒云。","碧天路近飞犹懒，自啄霜毛向夕曛。"]},{"t":"尘","f":"七言律诗","c":["似空如色未分明，脉脉冥冥类有情。","钻隙入来知态巧，步虚遥上极身轻。","稍经宿雨销沉尽，又倚西风澹荡行。","最是贵人车马路，一回过去一层生。"]},{"t":"钱","f":"七言律诗","c":["因成形自洪炉里，冷处来希热处过。","贫士橐中千日计，五侯筵上一时歌。","写将妙质传圆月，别出新裁付小荷。","只用上边三四字，从来深愧读书多。"]},{"t":"乞药","f":"七言律诗","c":["痴心未肯死前休，岂有丹方驻黑头。","吟苦望邀来世读，血枯皆代昔人愁。","流连好夜常穿晓，不出青春直过秋。","乞得老来还若此，目精明似电光流。"]},{"t":"寄怀梁无闷","f":"七言律诗","c":["别来弥日把诗篇，壮气高文两浩然。","旧剑弃为龙入水，新方期得鹤登天。","穷通一梦身何预，性命兼言道始全。","竹几蒲团闲永夜，三年不上卧床眠。"]},{"t":"怀罗浮","f":"七言律诗","c":["琪树西风粤国秋，十年前记住罗浮。","山光一半来蓬岛，海色三更上石楼。","云护药苗侵腊长，寺分泉响入房流。","葛洪丹井分明在，一下人间渐白头。"]},{"t":"同方蒙章酌秋月下怀梁药亭","f":"七言律诗","c":["空阶布席共良宵，村浦千家带晚潮。","秋色苍凉风在树，水光摇漾月当桥。","虫经晏岁吟偏苦，酒得高谈力尽消。","江海论心几人在，碧天相望雁行遥。"]},{"t":"送家中洲之青原访药地禅师","f":"七言律诗","c":["老依江徼谢名称，门径苍苔日渐增。","远兴忽生黄菊节，旧心期对白头僧。","吟过晓岸风千树，舟并寒山夜一灯。","想到吉州携手地，石桥新瀑半为冰。"]},{"t":"寄青原药地禅师","f":"七言律诗","c":["骆驼峰外宝钟撞，十八滩声涌法幢。","旷代才名流下界，半天人卧在高窗。","新疏瀑水虹千尺，迥立寒阶鹤一双。","犹有为霖旧时望，雨花空自满西江。"]},{"t":"伍重驹移居佛山寄之","f":"七言律诗","c":["闲云何地不堪行，近卜村居远郡城。","邻曲共知元亮宅，市人先识伯休名。","每为禽戏聪明长，渐见鹓雏羽翼成。","到处顿教无疾苦，笑他儒术济苍生。"]},{"t":"苦雨偶成柬家牧止","f":"七言律诗","c":["湿云寒雨苦相仍，便是篮舆出未能。","沟水绕门前后路，砌苔缘壁两三层。","身牵旅梦痴难晓，屐印春泥重不胜。","徒忆高楼垂柳下，昨来名论对陈登。"]},{"t":"寄罗若庵","f":"七言律诗","c":["眉须如画马征南，虽是闻声意已深。","旌节一移沧海上，风流犹系县人心。","珠官古郡通鹑尾，铜柱高标隔象林。","身作长城无一事，东风铃阁想高吟。"]},{"t":"送家明敬","f":"七言律诗","c":["不成麟阁写朱颜，仙佛门中见一斑。","少学斋心求大药，老思行世礼名山。","玄猿共戏当清夜，白鸟随舟下碧湾。","莫到天台便长往，匣中犹有大刀环。"]},{"t":"赠胡韶先","f":"七言律诗","c":["匡庐归路不盈旬，岭外山川久寄身。","一叹未忘投笔日，十年长作曳裾人。","篇章每夺词流气，甲子唯书酒国春。","生岁同君馀亦似，少来多难老来贫。"]},{"t":"赠沈方邺兼送之罗浮二首 其一","f":"七言律诗","c":["夫君枉驾相寻久，贱子卑栖出见迟。","袖里故人劳远字，卷中频日捧新诗。","水成波澜平难得，木有文章病可知。","各是天涯同世难，一杯重把定何期。"]},{"t":"赠沈方邺兼送之罗浮二首 其二","f":"七言律诗","c":["挂帆东近列仙家，瑶室璇房路已赊。","高瀑倚风时作雨，远峰含日半成霞。","山人散住茏葱竹，旅食多烹巨胜花。","知有妇翁为鲍靓，不劳丹灶问丹砂。"]},{"t":"立秋日送梁素子之丹阳","f":"七言律诗","c":["一叶桐声坠短樯，絺衣江上试新凉。","路人共乞龙蛇字，诗笔相携翡翠床。","第二泉香吴市近，小孤峰霁楚天长。","临邛令尹能迎客，不遣尊前忆粤乡。"]},{"t":"送曾周士还宁都兼柬翠微诸兄","f":"七言律诗","c":["一回相见一情亲，语默周旋并是真。","早得于师承学正，似难为弟较兄贫。","还从合浦探珠满，别指梅关落木新。","不远翠微山下路，年年空送往来人。"]},{"t":"题方龙媒园亭","f":"七言律诗","c":["几日空亭坐不回，主人相为扫莓苔。","庵分茗火连僧至，井汲香泉带月来。","高树蝉寒秋叶减，方池鱼跃水萍开。","闲园物色皆堪赋，羡尔江南庾信才。"]},{"t":"送杨伯建归丰城","f":"七言律诗","c":["岭头乱石老松根，来去年年不惮烦。","古道照人如可赠，青山得汝始能言。","时提佛号轮珠串，爱向词场请墨痕。","江上暂归须有约，新秋吾亦倚柴门。"]},{"t":"寄叶许山","f":"七言律诗","c":["闻君高卧江城里，宅后园林载一峰。","中岁身曾官小凤，先公名在补山龙。","多题逸句镌新竹，自领闲僧坐古松。","白鹤观前湖月满，扁舟何夕此相从。"]},{"t":"赠岑梵则","f":"七言律诗","c":["江乡深径引茅茨，十载无忘独到时。","高柳秋阴笼日薄，小堂寒磬出花迟。","丹砂不秘还童诀，白发尤工幼妇词。","今夕三城笑相看，先生如旧我长髭。"]},{"t":"送魏和公归宁都","f":"七言律诗","c":["隔年相见即依依，知尔全家住翠微。","穷海访人兵后去，孤身携剑雪中归。","滩平横浦寒流浅，枫照淩江晚叶稀。","贫贱别离那可道，寸心遥与片帆飞。"]},{"t":"立秋日送雪槱和尚开法曹溪","f":"七言律诗","c":["济上家风得大机，白云高坐见人稀。","绝无言处千花绕，欲有行时一叶飞。","溪水生香迎桂棹，岭猿随众候山扉。","宫中赐出袈裟在，礼向西来旧祖衣。"]},{"t":"赠吴韶著","f":"七言律诗","c":["恬淡无营古所难，十年闻著一儒冠。","坐来门巷皆成僻，静到须眉亦带寒。","读易止寻迁善理，观心还得养生丹。","西樵山色依然在，黄菊篱边倚杖看。"]},{"t":"送任克家归皖江时将遏选二首 其一","f":"七言律诗","c":["秋来往往动归思，陆贾装中半是诗。","鸿雁声高相别处，凤凰池好待飞时。","乘车载笠将何日，楚尾吴头更对谁。","想得到家初雨雪，岭梅先有寄人枝。"]},{"t":"送任克家归皖江时将遏选二首 其二","f":"七言律诗","c":["楚国千峰入小楼，阑干环映大江流。","梦中明月经年客，归兴吴山昨夜秋。","菊径乍开人并上，秫田多熟酒新篘。","家园乐事遥堪羡，作赋潘郎未白头。"]},{"t":"春日登粤王台","f":"七言律诗","c":["花发高台磴道遥，粤王曾此拜中朝。","谁云七郡初归汉，古者南交已宅尧。","江势急流宗渤澥，山光相望忆箫韶。","炎州文物从来事，霸气千年倍寂寥。"]},{"t":"送家巩宁","f":"七言律诗","c":["家世儒官独典军，紫髯三十坐高轩。","战旗指处无坚垒，仕路从来有孟门。","剑长涩苔收杀气，马骄沙草散蹄痕。","旧时赠客金钱尽，更向谁人受此恩。"]},{"t":"送何不偕之潮州兼怀家巩宁","f":"七言律诗","c":["醉敲如意短歌笺，鹢首东行岁渐寒。","霜下参差闻坠叶，月中深浅见澄滩。","龙川地古那逢令，鳄渚鱼多不避官。","犹有故人闲射猎，秋田骑马好追欢。"]},{"t":"春夜集丹柯阁听虫分赋得心字","f":"七言律诗","c":["方塘千尺在堂阴，一片春虫语渐深。","出蛰惊雷喧昨夜，洗兵疏雨过前林。","希微拟共寒更转，断续如知座客吟。","况是将军铃阁下，闻声倍切式蛙心。"]},{"t":"市桥春望","f":"七言律诗","c":["海门东尽不生澜，景物登台极大观。","红蕊点村千室曙，碧天围水数峰寒。","珊瑚多入渔人网，玉食先归野客盘。","倘许闲身坐垂钓，客星不拟落严滩。"]},{"t":"赠林孟易","f":"七言律诗","c":["传家世世有忠贞，斯世真堪作老生。","圣学久窥墙数仞，佛门新礼磬三声。","轻身似鹤偏宜寿，全德如鸡孰敢争。","五十年来无限事，白头不负泰阶平。"]},{"t":"早雁","f":"七言律诗","c":["一声初度自衡湘，断续天边见几行。","似有惊疑同避弋，只应来去为随阳。","高飞关塞何曾阻，久宿蒹葭渐有霜。","白首苏卿无恙在，北风时节倍思乡。"]},{"t":"送魏善伯之潮州","f":"七言律诗","c":["岭头秋尽枉高车，便向潮阳应辟书。","行迹欲同沙塞雁，文章应走恶溪鱼。","中宵剪烛论心地，十载传缄识面初。","幸是英豪为共事，故人无复叹离居。"]},{"t":"贺胡韶先举孙","f":"七言律诗","c":["昔时见子初生子，今日佳儿已抱儿。","家庆便多庭下彩，乡书遥慰鬓边丝。","灰馀炉火重增焰，霜后高松渐著枝。","三十年来天一转，深杯相对好开眉。"]},{"t":"彭飞云刺史见访","f":"七言律诗","c":["今世须才致治平，古人机略见先生。","剖符旧化三巴俗，伏轼曾降七十城。","幕府每闻飞健檄，席门何自枉高旌。","天南贱子能扪虱，坐听高谈为洗兵。"]},{"t":"送张穆之移家东安","f":"七言绝句","c":["村浦停舟倚浪花，叩门辞我日将斜。","殷勤说与相寻路，千岁藤边独一家。"]},{"t":"舟夜","f":"七言绝句","c":["夜寒犹自拥秋衣，水底星河数雁飞。","空得家书无一字，满缄稠叠寄当归。"]},{"t":"题画二首 其一","f":"七言绝句","c":["真山须似画安排，画出如真也自佳。","借我壁间悬数日，清猿凉月满书斋。"]},{"t":"题画二首 其二","f":"七言绝句","c":["深山深处有人争，拟寄闲身画里行。","净扫柴门无个事，碧溪寒叶一声声。"]},{"t":"蚓","f":"七言绝句","c":["一声一恨在涂泥，虽有清操未有知。","待化羽衣吟露日，世人方信饮泉时。"]},{"t":"蟏蛸","f":"七言绝句","c":["独将一面候虫过，饥任微生饱在他。","村舍久知无好客，劳君门外更张罗。"]},{"t":"蜂","f":"七言绝句","c":["穿花度叶日纷纷，出自知时处有群。","独佩秋兰何处献，惭卿一食不忘君。"]},{"t":"江上曲","f":"五言绝句","c":["双蛾画不成，十五背娘行。","独自摇兰桨，横塘月未生。"]},{"t":"秋夕过湛泉长同贤从迪周饮于荷舫","f":"七言律诗","c":["宅边池馆似舟居，布置溪桥亦自如。","疏树映门凉雨后，曲栏涵水夜星初。","秋来算亩收黄菊，烛下轮刀鲙白鱼。","酒罢分题群从散，新篇相许寄吾庐。"]},{"t":"月夜同湛用喈过泉长纵饮梅花下","f":"七言律诗","c":["似云孤起鹤孤飞，一片空明立小池。","过客只惭依玉树，见花何必羡琼枝。","月当瘦影徘徊见，酒引浓香寂寞知。","落得满头君莫笑，鬓毛非久亦如斯。"]},{"t":"游侠词三首 其一","f":"五言绝句","c":["左刀如白虎，右剑象苍龙。","直走长城北，风云满路中。"]},{"t":"游侠词三首 其二","f":"五言绝句","c":["相见一杯酒，天涯即弟兄。","出门赠百万，上马不通名。"]},{"t":"游侠词三首 其三","f":"五言绝句","c":["十年居委巷，上有白头亲。","此别逢知己，微躯亦借人。"]},{"t":"移家西归留别湛克正克茂外弟兼柬同人二首 其一","f":"七言律诗","c":["西还虽得迩乡园，最是难分汝弟昆。","春酒自浇离别地，东风含叹鹡鸰原。","多年瘗玉烟犹暖，当日倾巢卵幸存。","白发渐生吾老矣，幽冥将负丈人恩。"]},{"t":"移家西归留别湛克正克茂外弟兼柬同人二首 其二","f":"七言律诗","c":["四十无成客此都，将归何以答揶揄。","添来垒垒两坟上，携去双双众小雏。","南岭溪山清绝地，东江舟楫坦然途。","春来省墓兼童稚，千载过从定不诬。"]},{"t":"新苗","f":"五言古诗","c":["高田易为瘠，下田易为肥。","高田苗欲密，下田苗欲稀。","春阳三二月，阴雨来霏霏。","无论高与下，青青同一时。","疏如雁行列，密若羊毛披。","清风飒然至，荡漾生涟漪。","回旋合万舞，荏弱不自持。","遥遥极天碧，望望深人怀。","先王制四民，士首农次之。","非时尚不役，矧乃鞭与笞。","一夫不播种，世有受其饥。","须知元元命，系此青青丝。","贱子为老农，敢以告有司。"]},{"t":"修禊后十日石濂禅师招同诸公雅集长寿禅林即事赋","f":"五言古诗","c":["真妄非二途，愚智各有适。","同此闻见中，心目异喧寂。","西郊亦人境，静者得幽僻。","交错引翠条，萧疏布林石。","春事满高窗，鸟声在檐隙。","悠然古招提，旷若新开辟。","嘉招及令序，竟日随飞锡。","论诗陋休远，析理兼玄易。","既丧我于吾，焉知主为客。","欲别闻清钟，溪山暮云碧。"]},{"t":"送罗五湖","f":"五言古诗","c":["与君初一揖，未语神先跃。","磁石受金针，大小都不却。","船头一尊酒，颇尽新知乐。","秋风吹长棘，半载成乖各。","匪伊动忍谋，苍天亦云虐。","惓惓君子心，直可高云薄。","君家在何所，巴水明西郭。","才为此身累，不得耽丘壑。","游踪遍西土，美政流南国。","五马今何之，甘棠尚如昨。","无因一出送，益我怀中恶。","男儿事蓬矢，岂可辞芒屩。","同行得良友，未足为寂寞。","中州英贤地，大雅应有作。","何时遗之音，愿附罗浮鹤。"]},{"t":"狱中送郭清霞兼寄李相如","f":"五言古诗","c":["轻风驱行云，中天日雷电。","霖潦在康衢，积阴曀城县。","良朋当远适，冒雨来相见。","未言先慰藉，恐我泣如霰。","拜送圜土中，握手情恋恋。","凤鸟览德辉，高飞使人羡。","雊雉集山梁，色举何其善。","嗟哉云中鹄，今作泥巢燕。","江头路几许，不获衔杯饯。","况闻故人返，万里期言宴。","如何二纪别，良晤乖一旦。","九州不盈掌，日月双丸转。","流萍合有时，鬒发将无变。","因君谢故人，努力千秋传。"]},{"t":"狱中值林叔吾生日赠之","f":"五言古诗","c":["我生长于君，为日百五十。","何期来狱门，初度亦相及。","来时秋未徂，不觉春风入。","鱼沫尚相濡，虫鸣已离蛰。","衰柳落复生，燕雏去还集。","眷言南冠士，不作岐途泣。","醉则相和歌，昏犹把书立。","吾道岂云非，高天意难执。","匪兕率柙中，皎驹孰维絷。","幸非修名累，渐尔沈忧戢。","五岳路未遥，故山芝可拾。","相期保百龄，怀哉荷蓑笠。"]},{"t":"古意","f":"五言律诗","c":["去家三十年，昨夜梦归里。","不见旧家门，但见同乡子。","虽非久言笑，亦胜长羁旅。","谁云梦可续，愿奉千金市。"]},{"t":"赠任五陵","f":"古风","c":["任君介然稀所可，客邸杜门终日坐。","三年怀剌已生毛，一旦间关劳问我。","卷中先示禽言歌，嬉笑之下痛哭多。","花下从君读终日，正名纪号皆不磨。","水走云流无定质，不尚高华务平实。","五岳真形笔底看，百家奇秘纷然失。","如君好事古有谁，九州车辙安足奇。","穆王空有八骏马，岂谓书生能得之。","三闾大夫远游者，足迹未能遍中夏。","虚无阊阖叫不开，枉用离骚继风雅。","能游能赋两足矜，半生蹑屩还担簦。","计功而食不妄取，神寒骨峻门如冰。","试与极言当世计，达变通经还审势。","如此人居草泽间，苍生岂得无凋弊。","与君交好二年来，天轰地裂奔风雷。","相逢一度一鼓掌，笑杀时无英杰才。","坐使神州沦劫灰，念之不觉心魂哀。","守持廉节止自了，天生我辈何为哉。","宁为夷吾小器匡天下，莫作西山高蹈终蒿莱。"]},{"t":"送朱子蓉归嘉兴兼柬其兄子葆","f":"七言古诗","c":["七年之间三别子，两在山中一城里。","休论心迹未能并，可惜头颅只如此。","风尘拓落何所为，东溪片月当茅茨。","老兄能歌弟能和，松花酒熟清堪携。","北方苦旱南征伐，无事区区一吴越。","高天且陨不自忧，杞国狂夫空白发。"]},{"t":"赠萧壮行","f":"七言古诗","c":["朝来白发梳千下，一卷道书眠亦把。","谁是人间无累人，君乃闲中最闲者。","芒鞋短袷坐新秋，不冠不袜轻王侯。","城中馆舍非不美，归心思濯淩溪流。","淩溪流水清如酒，子善为箕孙酌斗。","门前一步是风波，身后千秋我何有。"]},{"t":"登大士岩纪事","f":"七言古诗","c":["寒来未试登山脚，积雨初消好行乐。","大士岩前一揖馀，四望风光殊不恶。","川原百里辨纤毫，渚稻皆收野岸高。","人家小梅日皦皦，疏林赤叶风飕飕。","龙江水绕山根出，诸峰秀美真无匹。","上悬峭壁下崎岩，森若文人多气骨。","何来五色罗浮禽，飞鸣下上好其音。","洞天福地不栖息，得无有意来相寻。","朱明洞口华台寺，十九年前山里事。","出山如送入山迎，三人见者今馀二。","岂有他奇副昔闻，巅毛种种日争新。","临高且共命尊酒，不使仙禽笑妄人。"]},{"t":"朱廉斋以张穆之画册索题为作磨痒马歌赠其象郡之行","f":"古风","c":["铁桥老笔多生趣，画马解作痒磨树。","三足作力一足拳，短鬣萧萧首回顾。","兰筋不动尾丝垂，竹耳双高目光怒。","吁嗟神物宜千里，散放平皋独何故。","战士场中不一嘶，瑶池可到谁为御。","虽辞衔勒得天真，未免蹉跎损高步。","古今万物一马也，朱公索我为长句。","顿觉风生尺幅间，疏林叶脱天霜露。","海头一州大如斗，骏足骖驔岂堪驻。","何不负图自出圣人前，何不籋云直上高天路。","世间岂无伯乐与王良，为君歌此画马章。"]},{"t":"集长寿禅林咏西番莲花歌","f":"七言古诗","c":["西方佛有青莲眼，西番花有青莲产。","朱丝作蔓碧玉英，缭绕疏篱意何限。","世间只尚紫与黄，此花无色能久长。","百花香者争高价，此花不售自开谢。","唯有幽人最惬怀，竟日盘桓倚僧舍。"]},{"t":"送胡韶先归南昌","f":"古风","c":["惆怅为此别，寸心安可言。","如何相见来，落落三十年。","长为贫贱不足恨，乾坤黯淡多烽烟。","君生十七去乡井，楚粤东西共萍梗。","阙下上书恒报罢，军中借箸无为省。","碧血空传先世名，热肠已化寒灰冷。","英雄失路欲谁投，不妨胡越亦同舟。","世人安识徐元直，指心不为曹公谋。","独将至性交良友，间复沉酣托杯酒。","因事长留济物恩，活人每试回天手。","岭南岭北千里中，人人皆道胡长公。","贫贱之交常满座，挥金如土囊时空。","浮生百年一倏忽，快意当前便须歇。","丈夫非爱七尺躯，无人肯买千金骨。","草堂新构西山西，东风三月花盈溪。","秫田得岁酒方熟，童孙壮子行相携。","天伦况复美群从，旧德日觉生光辉。","忠臣之后世必大，浮云于我何为哉。","薜萝带，芰荷衣。","泪滴先公坟下土，三十三年游子归。"]},{"t":"三月晦日同张默庵梁无闷蓝公漪过贺秋卿于西竺禅房即事各赋","f":"古风","c":["飞花欲尽羊城南，乍晴乍雨天青蓝。","青春尚馀此一日，炎风忽暑殊难堪。","偶同故人步郊郭，有客客寓城西庵。","门前对立木棉树，谁家系马骄骖驔。","高槐近窗窗纸绿，殿角风铃细相触。","枝间小鸟时一鸣，对此翻疑在空谷。","问君何来来扬州，轻帆破浪长江秋。","长星在天影落水，芒寒气黑鱼龙忧。","北风其凉日苦短，歇棹珠江应酬懒。","图书彝鼎共一床，促膝论交客常满。","从来神骏不受羁，去就之间何侃侃。","莲花幕府谢珠盘，落叶僧房对茶碗。","与君未识相知名，及乎一见心胆倾。","中怀万种安可尽，挥杯笑视双青萍。","君思买山时未可，我既无山仍轗轲。","短歌长啸各未终，欲去不去风雷过。","翻盆之雨何其大，君不见来时靸履去乘舆，丈夫未得长高卧。"]},{"t":"以端溪水岩小砚寄戴观察怡涛系之以长歌","f":"古风","c":["昔人只重端溪紫，今之水岩胜于始。","始犹所采皮肉间，山骨琢尽兹其髓。","一阳生后天益寒，牂牁江落风林乾。","崖枯峡浅洞门出，中有积水蛟龙蟠。","良工斤斧重泉下，石室无光朝亦夜。","千枝列炬照人行，万指悬壶向江泻。","金钱之费日不訾，冬春之际能几时。","瑕瑜况复不相掩，非具大力安能为。","崇祯之中熊开府，迩者名藩亦时取。","后先疏凿分东西，文采精华并千古。","往时蕉白称极佳，今人指点寻青花。","以兹相石亦未尽，必有生气如云霞。","拊不留手柔无骨，墨质愈坚磨愈发。","宋坑宣德虽尚存，粗则伤毫细则滑。","伯乐一顾冀马空，世间所患无追风。","寄公一片虽小品，由来亦自蛟龙宫。","茆斋久伴书生穷，咿唔吟啸不可终。","去兹卑陋依尊崇，使君声韵如钟镛。","挥毫落纸生蜺虹，况今持宪出乘骢。","秋霜春露一言中，非汝孰与成厥功。","呜呼，挽回造化良不易，补天亦属人能事，五色之石将无是。"]},{"t":"积雨柬何玉其","f":"五言律诗","c":["积雨村边路，溪潮长石痕。","蛎房环结屋，龙目细垂园。","旧友仍羁寓，新秋好晤言。","楼高虽可望，各自闭柴门。"]},{"t":"题绣佛斋诗 其一","f":"五言律诗","c":["遭逢虽不造，文采独堪誇。","姑妇成双节，诗篇属大家。","苦心追正始，真调脱铅华。","世业闻孙在，芳兰不妄芽。"]},{"t":"题绣佛斋诗 其二","f":"五言律诗","c":["玉洁因成色，金坚遂有声。","古人言不朽，皆自性情生。","寡鹤夜中唳，哀猿申旦鸣。","何须立文字，闻者尽沾缨。"]},{"t":"送梁言公之惠州","f":"五言律诗","c":["丰湖清绝地，乱后几人行。","秋水明诸壑，官桥带两城。","少年初旅食，多艺盛时名。","佐幕前贤事，良才斫始成。"]},{"t":"园居杂诗三首 其一","f":"五言律诗","c":["有月鸣莺早，无风乳燕高。","倚檐花刺帽，循竹露沾袍。","散诞从吾得，驱驰与世劳。","晓凉开卷罢，耕凿语儿曹。"]},{"t":"园居杂诗三首 其二","f":"五言律诗","c":["野色浮千树，池光鉴一峰。","高标人外秀，新绿雨边浓。","此地颇安堵，他乡时举烽。","楼头数杯酒，伫立到昏钟。"]},{"t":"园居杂诗三首 其三","f":"五言律诗","c":["乾鹊来何处，高巢占一桠。","可能知喜气，空自恋贫家。","就食雏争母，教飞翼碍花。","老夫图稳卧，未许报窗纱。"]},{"t":"狱中杂纪二十六首 其一","f":"五言律诗","c":["铃柝鸣终夜，星河耿暮秋。","但令圭未玷，休问杼曾投。","东海仍秦帝，南冠号楚囚。","此身翔不下，何处学轻鸥。"]},{"t":"狱中杂纪二十六首 其二","f":"五言律诗","c":["土室分东半，疏篱别作房。","灶烟凝几研，窗雨滴帷床。","昼鼠游无惮，宵虫网不妨。","故人知更甚，消息隔重墙。"]},{"t":"狱中杂纪二十六首 其三","f":"五言律诗","c":["把钓时临水，为园少近郊。","本非羊慕蚁，真有鹿悬庖。","多病寻方药，无才愧易爻。","古今同一梦，玄白不须嘲。"]},{"t":"狱中杂纪二十六首 其四","f":"五言律诗","c":["圜扉今半月，佳节报重阳。","粤俗人登墓，秋风稼在场。","天遥唯见雁，地苦已飞霜。","书札询儿辈，溪花几处黄。"]},{"t":"狱中杂纪二十六首 其五","f":"五言律诗","c":["今年月食既，叠向夏秋看。","晦魄冥无色，虚轮侧未安。","阴消如有象，候满欲何端。","三复修刑戒，能无儆有官。"]},{"t":"狱中杂纪二十六首 其六","f":"五言律诗","c":["南生期免戮，葛相戒求闻。","一自违丹阙，唯知恋白云。","蝉无遮噪叶，豹有害身文。","将老婴缧绁，深惭父母坟。"]},{"t":"狱中杂纪二十六首 其七","f":"五言律诗","c":["柳底看棋出，篱门步月开。","偶因闲得乐，旋以寂生哀。","世岂祥凶物，人应弃死灰。","如何文字债，犹到狱中来。"]},{"t":"狱中杂纪二十六首 其八","f":"五言律诗","c":["古塔标虞苑，高城号尉佗。","青蝇犹宿昔，黄屋久消磨。","午梦书能送，秋吟酒易多。","死生闻有命，缄口欲如何。"]},{"t":"狱中杂纪二十六首 其九","f":"五言律诗","c":["已是伤心客，那堪太息声。","隔墙来断续，入耳怨分明。","世俗趋倾险，神州尚甲兵。","何时瞻化日，青草狱门生。"]},{"t":"狱中杂纪二十六首 其十","f":"五言律诗","c":["栩栩梦中蝶，飞飞霜后萤。","半床书共寝，永夜月同醒。","觅纸题新句，笼灯课旧经。","已忘身是系，只作户长扃。"]},{"t":"狱中杂纪二十六首 其十一","f":"五言律诗","c":["初度寻常度，今兹倍怆神。","伤哉居秽地，不敢礼先人。","乱日生何乐，馀年死与邻。","只愁来世事，难定报恩身。"]},{"t":"狱中杂纪二十六首 其十二","f":"五言律诗","c":["一旬双讳日，近接我生初。","泪滴重泉下，身从九死馀。","为禽填苦海，作蠹饱尘书。","已比先人老，千秋愧不如。"]},{"t":"狱中杂纪二十六首 其十三","f":"五言律诗","c":["九月寒如此，今年闰较催。","萧条天外雨，飞洒粤王台。","风定闻新雁，人来说早梅。","江山寥落处，登望几时开。"]},{"t":"狱中杂纪二十六首 其十四","f":"五言律诗","c":["往哲居忧患，皆为进德门。","鄙人无意志，一卷自朝昏。","渴得楂梨快，寒加襆被温。","近邻贤首领，间日送清尊。"]},{"t":"狱中杂纪二十六首 其十五","f":"五言律诗","c":["烽火兼舟楫，艰危四十馀。","几为弓外鹄，一葬海中鱼。","债岂他生偿，名应狱吏书。","闲来寻旧将，追问乱离初。"]},{"t":"狱中杂纪二十六首 其十六","f":"五言律诗","c":["一夜江城雨，萧萧长鬓华。","入心鸣万点，为润想千家。","倍助天昏黑，如兼客叹嗟。","乡园归未得，催尽小梅花。"]},{"t":"狱中杂纪二十六首 其十七","f":"五言律诗","c":["三旬行万里，奏使旧能任。","驿路无淹骑，秋风有报音。","迟留关厄数，速免或他侵。","死地寰中满，为忧岂独今。"]},{"t":"狱中杂纪二十六首 其十八","f":"五言律诗","c":["神签曾信手，消息一阳初。","始日深愁远，而今虑且虚。","灰寒终应管，云暗可劳书。","天地心谁见，乾坤莽自如。"]},{"t":"狱中杂纪二十六首 其十九","f":"五言律诗","c":["多虑凭天遣，深寒到酒消。","掩书吟竟夜，辞客卧终朝。","霜角思江槛，风铃隔丽谯。","向来临眺地，红树一萧萧。"]},{"t":"狱中杂纪二十六首 其二十","f":"五言律诗","c":["举世悲先烈，虚名萃眇身。","局天非一日，画地又何人。","不献邹阳作，终知石父伸。","从来黄与绮，秦汉未称臣。"]},{"t":"狱中杂纪二十六首 其二十一","f":"五言律诗","c":["身世犹如昨，风威只觉寒。","数为百日满，序是一年残。","北使归何缓，南音操已阑。","敝衣行卒岁，省事且为安。"]},{"t":"狱中杂纪二十六首 其二十二","f":"五言律诗","c":["春前殇两稚，灾祸不云孤。","岂谓妻孥泪，居然泣老夫。","往来询动履，肥瘦寄衣襦。","会有生还日，张仪舌在无。"]},{"t":"狱中杂纪二十六首 其二十三","f":"五言律诗","c":["一岁聿云暮，万方劳未还。","济师江上戍，转粟雪中山。","身等齐民列，名蠲力役班。","合将经月系，消折半生闲。"]},{"t":"狱中杂纪二十六首 其二十四","f":"五言律诗","c":["昨日报春初，今朝是小除。","旧枯泉脉润，新脱柳芽舒。","生态看星鬓，忧端卜历书。","家家勤祀灶，儿女望何如。"]},{"t":"狱中杂纪二十六首 其二十五","f":"五言律诗","c":["已歇霏霏雨，初回习习风。","日车朝渐北，斗柄夜方东。","大梦过前事，长愁到老翁。","羁栖频度岁，只欠狱门中。"]},{"t":"狱中杂纪二十六首 其二十六","f":"五言律诗","c":["岁旦明朝是，天书昨夜归。","岂应违咫尺，无处问恩威。","且学餔糟醉，从嗔食覈肥。","入春开笑口，不复有危机。"]},{"t":"贺何不偕新翁","f":"五言律诗","c":["与君皆老矣，继美在弓裘。","即此夭桃赋，无非式谷谋。","百年宁复事，五岳续为游。","颇忆曹丕语，成翁未白头。"]},{"t":"走笔送袁士旦归江南兼怀魏凝叔和公杨长苍二首 其一","f":"五言律诗","c":["积雨日未已，客中怀可知。","如何相见地，即咏送行诗。","半月赵佗国，三秋文献祠。","好游年少事，搔首鬓如丝。"]},{"t":"走笔送袁士旦归江南兼怀魏凝叔和公杨长苍二首 其二","f":"五言律诗","c":["一见即投分，相知宁在多。","吾尤推意气，人共诵诗歌。","卞璞终应剖，南圭近已磨。","谁能记微贱，为报幸无他。"]},{"t":"送罗仲牧移家车陂","f":"五言律诗","c":["陂上家家好，清溪带绿筠。","近闻诗社里，添汝白头人。","门向何峰住，樽堪席地陈。","太平遗曲在，为我拂龙唇。"]},{"t":"别后寄方蒙章陶苦子兼柬何不偕梁药亭吴山带黄葵村定邮诗之约二首 其一","f":"五言律诗","c":["别时蟾兔缺，不觉渐成圆。","旅梦犹高馆，生涯在钓船。","风轻中酒后，夜永一阳前。","为有邮诗约，寒灯颇废眠。"]},{"t":"别后寄方蒙章陶苦子兼柬何不偕梁药亭吴山带黄葵村定邮诗之约二首 其二","f":"五言律诗","c":["曲江千载下，作者未全湮。","笔墨无生气，光芒愧昔人。","谁能师日月，何以喻清新。","大海波澜在，骊珠自不贫。"]},{"t":"祝杨敏叔","f":"五言律诗","c":["白雪须眉在，青山日月深。","贫能持定力，老不负初心。","清磬夜当梦，梅花寒出林。","一阳来复后，甲子又从今。"]},{"t":"郊行","f":"五言律诗","c":["春郊一尊酒，且以乐朝昏。","远水澄珠寺，遥峰闭石门。","鼓鼙莺语地，烽火杏红村。","短鬓丝将遍，能销几处魂。"]},{"t":"闰中秋夜阻雨不得赴方蒙章之约枉诗见贻赋此答之","f":"五言律诗","c":["人间无好月，天上又中秋。","雨点微沾瓦，箫声渐闭楼。","遂违杯酒约，空枉夜珠投。","旅宿蒹葭外，伊人不易酬。"]},{"t":"后一夕同庞祖如方止止陶苦子庞毅子亮子罗颢甫颐甫宿亦庵","f":"五言律诗","c":["尚满中秋月，微开昨夜云。","古墙杉影落，净地佛灯分。","坐久须眉见，天空语笑闻。","几时还闰八，重得对诸君。"]},{"t":"过弼唐感旧赠庞祖如二首 其一","f":"五言律诗","c":["策杖秋方晚，村桥日欲斜。","树风喧万叶，山影静千家。","瘠土安淳俗，澄溪漾细沙。","拟寻庞氏隐，还种邵侯瓜。"]},{"t":"过弼唐感旧赠庞祖如二首 其二","f":"五言律诗","c":["他日谁青史，当年易姓名。","门人思李固，孤子寄程婴。","我愧前贤事，君犹古道行。","白头怀宿昔，竟夕自沾缨。"]},{"t":"初月","f":"五言律诗","c":["银河谁下钓，天道自张弓。","色借桑榆日，凉生玉笛风。","山光开半面，人影在墙东。","不俟居弦望，清辉万国同。"]},{"t":"送屈本庵入都","f":"五言律诗","c":["白首皇都客，兹游亦壮哉。","夏云凝岱岳，秋色在金台。","万里何穷路，三闾未易才。","岭头无可恋，应为荔枝回。"]},{"t":"寿何克谏","f":"七言律诗","c":["洞口桃花落雨馀，清溪流出引樵渔。","姓名不愧何徵士，甲子终虚宋永初。","七字题诗传白社，千峰采药散比闾。","知君妙得还童诀，玄鬓朝来渐满梳。"]},{"t":"岁暮送区鱼山归香山","f":"七言律诗","c":["长将笔舌代耕芸，海岛焉能绝世尘。","百里暂归贫有母，一年将尽老催人。","潮光似火船头晓，梅子如珠屋角春。","乱日相期无可祝，早占熊梦慰慈亲。"]},{"t":"寿雷峰天然禅师","f":"七言律诗","c":["孤高如月万方看，至道无言仰颂难。","垂老尚闻勤梵行，太平先已薄儒官。","身为硕果时方剥，书满名山墨未乾。","曾住朱明洞天上，仙人不敢爱还丹。"]},{"t":"雨后冯再来中丞招同王长文姜坤侯何涟若陈继袁诸子泛舟谒南海神祠登浴日亭望海是日晴霁诘朝复雨即事赋谢二首 其一","f":"七言律诗","c":["南人谁不颂芃苗，百里行春路未遥。","雁翅城开云尚渍，虎头山出雨初消。","元戎小队移轻舸，大海微风入短箫。","天为吾曹晴一日，江花林月好相招。"]},{"t":"雨后冯再来中丞招同王长文姜坤侯何涟若陈继袁诸子泛舟谒南海神祠登浴日亭望海是日晴霁诘朝复雨即事赋谢二首 其二","f":"七言律诗","c":["千秋吏部文章在，三月中丞节钺来。","庙压平潮诸岛没，天横峰影海门开。","布衣未敢辞高宴，赤舄无嫌踏野苔。","南国禹功元不到，安流须仗济川才。"]},{"t":"狱中柬黄畏斋杨巍材陈是庵","f":"七言律诗","c":["埋名不免堕圜扉，枉作山中老布衣。","尚有高人能命驾，岂应吾道遂全非。","夏侯未死犹传业，叔夜如生亦采薇。","岁尽乡园归得否，紫梅花落钓鱼矶。"]},{"t":"邑中同人招饮西山草堂即事","f":"七言律诗","c":["名园重得聚英豪，暑月杯盘敢告劳。","匝水松阴铺地阔，出墙山色带城高。","时光老去深知惜，笔砚愁来渐懒操。","同是少年吟啸地，新霜看上鬓边毛。"]},{"t":"过六贞女墓","f":"七言律诗","c":["昆冈生玉总无瑕，列女贞魂是一家。","一夕便成千古事，孤坟空与后人嗟。","乘鸾合上三珠树，化雪应为六出花。","处子立名青史少，曹娥江水在天涯。"]},{"t":"李苍水司训长乐以罗浮蝶茧数双及茧布见寄云布即蝶茧所成翼日蝶出茧中五色纷翍玩对之间因成一律寄谢其意","f":"七言律诗","c":["仙遗衣化罗浮蝶，蝶化山蚕复作衣。","栩栩未离庄叟梦，丝丝还上玉人机。","质无绮丽宜于隐，生有文章不愧飞。","多谢良朋远相寄，东方蝉蜕亦依希。"]},{"t":"夏至夜即事","f":"七言律诗","c":["初晴天气便炎蒸，小阁风多最上层。","腊酒旧藏椎髻妇，春茶新惠住山僧。","频探落月移湘簟，自惜流萤掩夜灯。","一岁算来今夕短，老夫犹为几回兴。"]},{"t":"仲冬十三日赣儿受室率成一律示之","f":"七言律诗","c":["灯红月皎两相宜，且放中怀入酒卮。","万种未完为子事，百年过半作翁时。","山寒渐入青春色，梅老偏高白雪枝。","莫道传家无素业，先公犹有一经遗。"]},{"t":"赣儿受室承诸公赠诗赋答","f":"七言律诗","c":["千秋名立举家捐，心死灰寒四十年。","直为诗书存此脉，重劳尘土作诸缘。","羲爻始叶包蒙吉，韩奕多承缵祖篇。","若使析薪讥可免，钓竿吾在五湖船。"]},{"t":"送孔樵岚宰乐昌","f":"七言律诗","c":["复挂征帆去此都，劳劳终日在驰驱。","十旬三上二禺峡，百里连分五岭符。","南楚烽烟嗟往昔，东风民物望来苏。","关门锁钥须公等，骨气昂藏一丈夫。"]},{"t":"送何不偕","f":"七言律诗","c":["少年无远不同游，比者输君已数筹。","酒后独寻燕市筑，雪中曾买建陵舟。","九州未必容闲客，五岳何常笑白头。","我亦从兹理帆席，大江明月记清秋。"]},{"t":"行路难 其一","f":"古风","c":["君不见天上之星坠为石，又不闻地中有雷生霹雳。","星有光芒犹可避，雷无定所谁能测。","杀人岂必干与戈，尺地寸天皆局蹐。","重城高寝自谓安，中夜思之眠岂得。","何能变化为蟭螟，飞入睫中人不识。"]},{"t":"行路难 其二","f":"七言律诗","c":["翩翩之雁来天隅，中有一者飞而孤。","自丧其雄不并宿，江中警夜甘为奴。","江滨之人少慈惠，一网高张百禽殪。","不虞永断匹偶恩，食肉卖毛为得计。"]},{"t":"行路难 其三","f":"古风","c":["君不闻蜀山多阴稀见日，群犬吠之盈万室。","又不闻野人有妇一目偏，出见举世皆不妍。","是非好恶何有定，昨者高岸今为渊。","劝君且自酣杯酒，劝君不用狂开口。","正言自古有戈矛，上士闻之皆却走。"]},{"t":"行路难 其四","f":"古风","c":["君不见五陵年少插两弓，左射右射皆能工。","金丸如星羽如月，骄马蹴踏鸣秋风。","林中走兽猎已尽，仰面四顾苍天空。","千年老鹤青田产，昨日瑶池衔玉简。","未回劲翮排天门，莫使霜毛刺人眼。"]},{"t":"行路难 其五","f":"七言古诗","c":["卞和入山得璞玉，献之未售先刖足。","秦王易以十五城，赵国不与终受兵。","从来至宝物所忌，锥刀之末今人争。","小民止可求粗足，朝饭糟糠暮饘粥。","轻裘肥马不易誇，有司视尔如仇家。"]},{"t":"行路难 其六","f":"古风","c":["隰有桑，阪有漆，朝朝斤斧无虚日。","社西老树且千年，于人无益已则全。","美材岂合终弃置，用之贵得逢英贤。","昨者公家求大木，匠石顾之蒙见录。","已辞根柢落高云，却伴沙泥委空谷。"]},{"t":"行路难 其七","f":"古风","c":["葡萄酒，黄金卮，玉箫瑶瑟声参差。","佳人长袖为君舞，今时不饮将何时。","是与非，得与失，百年都是攒眉日。","刘伶一醉死便埋，嗣宗多事犹咏怀。","畏首畏尾身馀几，智士畏名如畏鬼。","君不闻隋家白鹤自拔毛，周庙牺鸡啄其尾。"]},{"t":"行路难 其八","f":"七言古诗","c":["孔雀之血能杀人，翠钿金尾光彻身。","古来贤圣不外饰，蛙声紫色能乱真。","一人独坐深宫里，拜跪满前皆有以。","谁悬明镜照中心，为佞为忠总相似。","仲尼一语君勿谖，先观其行后其言。","君子温温如白玉，利口便便中有毒。","其毒愈甚文愈高，请君记取孔雀毛。"]},{"t":"行路难 其九","f":"古风","c":["落花一别树，安择清波与污泥。","自古皆有死，刀兵床第无高低。","梦中得食醒难饱，夷齐身饿名不朽。","流芳一日不易为，遗臭万年安足道。"]},{"t":"献大司马制府吴公一百韵","f":"五言古诗","c":["北极盱长策，南天眷重臣。","节移闽海近，恩及岭头新。","睇望云霓久，沾濡雨露匀。","旌旗皆改色，闾井自生春。","地阔衡庐接，星分斗庙邻。","滇流东注海，横浦北封秦。","旧俗民瑶杂，遗风邹鲁醇。","威行千里肃，纲举百城振。","文武趋莲府，溪山望画轮。","诗须传乐部，德俟纪贞珉。","往日弦歌暇，清篇字句真。","飞腾珠不胫，磊落笔如神。","世诵吟灯作，官闻酌水贫。","孤标诚绝俗，高义久惊人。","法重催科考，时兼荐馑臻。","后先羁旧尹，三五及迷津。","相戒车前辙，谁从井有仁。","赖公垂恻隐，遂得免颦呻。","数万金钱负，多年簿责频。","下车皆遣去，重任畀于身。","汤网开穷鸟，庄波借涸鳞。","即云于物利，未或以财徇。","侠气过朱郭，名流仰乐歅。","各期空冀野，争得望车轮。","银烛连开宴，瑶阶九列傧。","攀留常累月，酬唱动兼旬。","阳羡多栽茗，江东自足莼。","四鳃鱼入馔，千日酒沾唇。","白雪操常凛，芳兰佩自纫。","骥才终必展，龙屈理须信。","令誉通黄叟，能声彻紫宸。","九重恩破格，万里檄征闽。","爰自神明宰，高超岳牧伦。","六条持法慎，九伐纪功纯。","堠火飞猿峻，妖氛紫帽屯。","逆萌生带砺，缓死冀宵晨。","徵士时缄剑，搜财或算缗。","莫为分玉石，终见共胥沦。","不枉闻清论，如丝拜御纶。","绣衣明獬豸，高印跃麒麟。","受节初开府，兼官属代巡。","澄清徐揽辔，光霁俨垂绅。","一鼓更弦瑟，先移曲突薪。","万民歌乐只，多士荷陶甄。","桃李三山遍，韬钤列校悛。","岛人宵自遁，荒土日加畇。","边计奇难测，雄功立不泯。","撝谦师大树，克让协同寅。","忆昨杉关出，将过粤海漘。","香花连水驿，涕泣洒山榛。","父老追邪谷，舆歌继洧溱。","尚思崇俎豆，岂惮走嶙峋。","岭峤人何幸，皇天若汝亲。","矧当凋瘵后，初过乱离辰。","乡落朝无火，郊原夜有燐。","三毛名饭毳，百结号衣鹑。","元气公能补，民心愿莫因。","经时虚远想，一旦下高旻。","疾痛难更仆，吁嗟自郁氤。","顷从藩镇始，遂使利源湮。","淩杂供求取，纤毫见怒嗔。","生民如草芥，王度渐缁磷。","丛借还无日，狐威假不驯。","骄矜行自绝，骨肉且相狺。","竟启东南衅，同归朴灭均。","馀波仍污染，囹圄日嚣龂。","孰市田文义，谁从郑侠陈。","脂膏原粤物，鞭朴亦吾民。","世幸销兵革，恩宜用抚循。","输将前不易，旸潦近加辛。","即尽敲民髓，何裨秉国钧。","富强须有术，山海况多珍。","夷舶原交市，遐方旧贡蠙。","有无通物产，声教暨弦夤。","盐铁书何密，耕屯计可抡。","兵民如复合，风俗庶能淳。","夫子今豪杰，文章古孟荀。","学能全体用，巧不事组紃。","诗礼趋庭得，风规昔驯遵。","先公开棨戟，大节挺松筠。","善述真无忝，仁声美有洵。","会吹寒谷律，终解捧心颦。","贱子何为者，其生亦已迍。","在金惭跃冶，于木更轮囷。","好著登山屐，常冠折角巾。","行藏依草野，出入远城闉。","欹案看书卧，颓颜揽镜皴。","何知年冉冉，只爱石粼粼。","东渐曾过浙，西行未到岷。","遥登太行上，亦泛五湖滨。","处处闻风烈，超超远世尘。","溯洄心未已，向往足犹踆。","行部干旌出，防边介士蹲。","飞扬明铁铠，镗鎝响金錞。","并集三江鹢，初停六辔骃。","霜应生白简，风欲起青蘋。","北斗瞻今近，南溟气自申。","扶携观教化，洗涤待咨询。","幕府多英俊，贤君爱笑嚬。","肯容狂狷士，长揖列嘉宾。"]},{"t":"走笔送家紫驭孝廉","f":"古风","c":["薄暮山归力殊惫，小童报子将于迈。","披衣急欲走送君，东西城隔愁无奈。","君来几日秋已穷，黄花开残多朔风。","摩天黄鹄却垂翅，鹰隼横厉盘高空。","我闻志士有如弓在挽，其屈愈深发弥远。","看君才气固落落，世上何人在心眼。","明朝闻道理帆樯，短歌相送不成章。","飞扬之望属吾子，仆不如人今老矣。"]},{"t":"客有自粤西来者以石遗吾家宗虞曰此某将军所宝为王祥卧冰石也同人多为诗予歌以和之","f":"七言古诗","c":["吾家介弟饶花石，有石陂陁不盈尺。","白章黄质理灿然，仿佛中间有人迹。","身如转侧面右向，左袂蒙茸覆衣上。","四周环匝白皑皑，云是王祥卧冰状。","冰间有物不可名，是鱼非鱼如有情。","石于天地最顽钝，岂亦慕义师高行。","扁舟载石来千里，人孰无亲亲有子。","感兹雪里得嘉鳞，各向高堂备甘旨。","爱君能养赠君家，一时乡曲争相誇。","言似不似者各半，将无画足添于蛇。","吾闻李广善射虎，草间有石射饮羽。","至诚所感金石开，是虎非虎君试猜。"]},{"t":"赠别王础尘","f":"古风","c":["昔年与子珠江别，太白有芒宵八月。","今来送子五羊城，土木双星守不行。","徘徊往复似有恋，毋乃类我故人情。","昔年见子须如漆，今来白发参差出。","死生万变十年中，唯有两心尚如一。","不肯低头就一时，不曾失足受磷缁。","只将热酒浇怀抱，下士闻而大笑之。","君不见天上之星密如雨，亮天之工才有五。","世间豪杰岂能多，碌碌因人自终古。"]},{"t":"端州七星岩题名歌","f":"古风","c":["娲皇未补星辰漏，神人驱石为云走。","赭鞭鞭断云不前，天风吹落西江口。","西江波涛千里来，雷霆霹雳蛟龙吼。","洞府沉深绝照临，奇象怪形多所有。","少阳数七老阳九，艮止为山折如斗。","一开一阖相蔽亏，天枢天轴通关纽。","质如白玉贞且坚，雨积苍皮光不垢。","绝无寸土可栽培，况有灵根作林薮。","中虚或类鼙鼓鸣，下垂乃可金钟扣。","磴道遥盘霄汉间，阴崖忽出他山后。","扶啸台东千尺?，下视诸峰若培塿。","过雁声高每倒闻，行人路窄难回肘。","百曲湖光绕寺门，一片山城挂窗牖。","尚忆曾游少壮时，今来不觉成衰丑。","吴山越水多俊人，天涯此会诚非偶。","为君小试燕然手，兴酣落笔无蝌蚪。","八分瘦硬高崖陡，奋臂大书人某某，石老天荒同不朽。"]},{"t":"甲子重阳后四日蒋莘田大参招同潘亚目屈翁山登城北诸峰望全粤形胜还饮酒粤王台上时有建复镇海楼之议即事赋呈","f":"七言古诗","c":["衡岳东走千万峰，南支五岭为其宗。","龙川浈水在左右，中有都会为番禺。","海天清迥见万里，旷望可以开心胸。","重九已过秋爽至，大夫车骑来雍容。","高峰表里临城北，下视朝台犹咫尺。","霸业升沉已几回，文风极盛馀三百。","将军犹纪廖与朱，当日何公献版图。","楼名镇海故有以，五层特立当城隅。","自从楼废烽烟逼，人事萧条多瓦砾。","整顿欣逢子大夫，九衢三陌生颜色。","即今海宇无纤埃，乾坤元气须人培。","杖藜父老各翘首，何时重见高崔嵬。","且当酾酒临高台，松风谡谡帟幕开，甘棠勿剪桃李栽。","先公作宰趋庭地，白首乘骢使节来。","人生所贵有称述，羊公岘首今蒿莱。","令名直与天壤偕，馀子碌碌安在哉。","后来不朽应吾侪，为君满引手中杯。"]},{"t":"扶胥歌送王阮亭宫詹祭告南海事竣还都兼柬徐健庵彭羡门王黄湄朱竹垞诸公","f":"古风","c":["扶胥之口水所归，青山浮出如无依。","长波际天不可极，白日夜半扬其晖。","东风吹上木棉树，片片尽作红霞飞。","南海之神绂冕古，琼楼玉殿开朱扉。","前驾赤虬后文螭，左驱天吴右冯夷。","虹蜺架道雨师洒，蛟龙夹毂瞻旌麾。","九重秩礼来南纪，谁持玉节渔洋子。","天上连宵动使星，世间久矣传诗史。","归舟暂泊珠江南，问奇访古多所探。","都将十载相思梦，并作江城半月谈。","唐诗三变犹堪把，明诗三变风斯下。","落落乾坤得数公，尽扫榛芜归大雅。","羡门子，竹垞生，与君意气遥相倾。","徐公渊博能下士，黄湄慷慨多秦声。","我抱区区君所察，来时更枉群公札。","山阳叔夜懒何堪，吴下阿蒙目犹刮。","送君有作兼群公，凤凰今已飞梧桐。","和鸣律吕赖公等，且放野鹤闲云中。"]},{"t":"何克谏八十","f":"七言古诗","c":["青萝山中有茅屋，土墙蛎径幽人筑。","春来屋内屋外花，客坐前山后山竹。","盎头良酝开数升，架上素书闲一束。","落落乾坤觉汝贤，箨冠萝服望如仙。","正逢渭叟投竿日，应见希夷大笑年。"]},{"t":"寿王大将军孝扬","f":"七言古诗","c":["汉代诸侯谁第一，仲华年少封高密。","晋家武库杜当阳，临边著述何洋洋。","将军独立千载下，颉颃二子兼其长。","两河作镇始弱冠，大江节钺临荆扬。","楚波西来不敢狂，吴人高枕忧可忘。","清歌彻夜调笙簧，雄风披拂台岭傍。","岛夷跪拜献明珰，旅獒驯象来梯航。","翠禽白雉笼千双，将军所宝唯文章。","清斋万轴函缥缃，军中多暇加丹黄。","时挥翰墨祖二王，虎龙戏跃剑弩张。","阶前爪士森两行，竦立汗下叹莫当，一画力敌千钧强。","去年忆在三江口，司马舟中联句久。","中央置研傍大斗，一人赋诗二饮酒。","飞觞授简迭奇偶，秋菊新花映窗牖。","夜阑刻烛复数首，清风白雪传林薮。","如此惊才古希有，况兼制行一无苟。","高堂色养有寿母，鸡鸣问寝垂紫绶。","雁羽参差列前后，甘棠树老兰英秀。","公家世德天所厚，立功立言同不朽，以兹三爵为公寿。"]},{"t":"寄赠卓火传传经堂歌","f":"古风","c":["卓侯寄我一尺书，细行小字千言馀。","开缄意气溢毫楮，烟云缭绕生吾庐。","鸟翼欲搏南溟浪，剑锋直射牛斗墟。","不平之鸣有若此，何况龙光凤彩扬天衢。","伊昔休明代，朝野交驩虞。","公卿折节下韦布，草野高谈皆庙谟。","天南地北未相见，一字若得隋侯珠。","故家文献今未坠，君门累叶名通儒。","况闻忠烈有令祖，月黑归家夜骑虎。","燕山潜邸龙未飞，一流南移真逆睹。","终知神器固天授，不惜麋躯共殉主。","文皇儿戏视方黄，独谓先生言可取。","时殊世易三百年，儿孙尚守高曾矩。","堂开吴越号传经，四方投赠诗盈庭。","吾闻六经之传有明晦，时晦则晦明而明。","壁于秦火出于汉，蝌蚪尽作丝竹声，至今大义如日星。","善传善述必有以，请君为我侧耳听，请君为我侧耳听。"]},{"t":"夜雨有怀柬张桐君兼寄董无休","f":"古风","c":["醉来不觉和衣卧，小楼未灭看书火。","梦回四壁走风涛，空床听雨三更坐。","忽忆少时吟兴狂，君与董侯同过我。","席门蓬径话终朝，宝马高车停道左。","董侯欲去君且留，予时更鼓潇湘舵。","落落风尘老渐来，萧萧白发生无那。","君才自足奋桑榆，致身不肯游青琐。","屈伸潜跃各有时，南北东西何不可。","董侯屡寄山阴书，君来日剥离支果。","从前屈指几烟云，吾辈幸存非坎坷。","君不见五羊城下阴雨中，刘苑荒芜赵台堕。"]},{"t":"嘉鱼二首 其一","f":"五言律诗","c":["嘉鱼潜石穴，终岁气常寒。","本欲承珠露，宁知上玉盘。","有无通雅咏，咫尺隔风湍。","未必名为累，隆冬泽易乾。"]},{"t":"嘉鱼二首 其二","f":"五言律诗","c":["嘉鱼吾旧识，高价市人争。","似鲫身微削，如鲮鬣乍生。","细肪凝石乳，兼味著霜橙。","未入宵来馔，吟诗久不成。"]},{"t":"送王蒲衣采诗惠湖","f":"五言律诗","c":["树树熟离支，殊非远别时。","新蝉湘子庙，初日海王祠。","路记双江合，文犹八代衰。","时无采风使，草野亦陈诗。"]},{"t":"送周德涵","f":"五言律诗","c":["便作天涯别，重逢未可期。","快闻经世论，兼读过庭诗。","骐骥宜千里，鹪鹩且一枝。","野人头已白，不复问当时。"]},{"t":"赠别黄忍庵太史四首 其一","f":"五言律诗","c":["百年无作者，之子擅奇才。","岂谓黔中使，翻从岭上回。","衡文时望重，握手老怀开。","更喜居停近，深宵亦往来。"]},{"t":"赠别黄忍庵太史四首 其二","f":"五言律诗","c":["东郭淹游迹，南园接古祠。","乘车为客日，闭户著书时。","怯醉开椰酒，从酸剥荔支。","海隅多异物，嵇陆未能诗。"]},{"t":"赠别黄忍庵太史四首 其三","f":"五言律诗","c":["学到难穷地，文能不愧名。","虽为今太史，犹似老诸生。","江海心常下，山林迹未并。","一时称盛事，千里聚同声。"]},{"t":"赠别黄忍庵太史四首 其四","f":"五言律诗","c":["暂为乡井别，十日惜分携。","观化俄生柳，看书亦杖藜。","心知龙节返，路出海云西。","会买扁舟送，渔家水满堤。"]},{"t":"病中承彭子安见过别后奉怀","f":"五言律诗","c":["度岭年殊少，轩车满路光。","病中吾见汝，秋后客何乡。","伏枕违清论，开篇得妙方。","愈风文檄在，继述有诸郎。"]},{"t":"送林敬臣","f":"五言律诗","c":["南雁去不极，北风声正喧。","何堪衰草日，还是送王孙。","再世依耕凿，空山矢寤言。","与谁登冠石，放眼望中原。"]},{"t":"病足舟中即事","f":"五言律诗","c":["兴剧思凭览，人扶上小舠。","客囊携薏苡，乡酒寄松毛。","少食肌时减，多眠骨屡高。","可怜中夜梦，跃马尚能豪。"]},{"t":"送温茂长","f":"五言律诗","c":["三秋违侍养，万里赴京华。","江路闻霜叶，天门照雪花。","亲存宜薄禄，年少且辞家。","芜绝金台上，看君步玉骅。"]},{"t":"送钱目天","f":"五言律诗","c":["度岭三年客，归心四月天。","别离良未易，须鬓况苍然。","古笔追秦汉，深杯得圣贤。","似君何不可，高咏满吴船。"]},{"t":"挽汤惕庵先生","f":"五言律诗","c":["大雅久云没，中原尚此人。","晨星方在望，宿草已逾春。","便自成千载，何繇赎百身。","唯馀召公树，蔽芾粤江滨。"]},{"t":"初春江行有感","f":"七言律诗","c":["人日吟诗坐客船，白髭临水一茫然。","西来山坼云中峡，北上江明雪后天。","几处小帘春市酒，谁家新月夜鸣弦。","郊原颇记从军地，草草东风又十年。"]},{"t":"过钟莘野留赠","f":"七言律诗","c":["万峰东走峡门青，岩石苍苍见列星。","游子偶来停短棹，故人高卧有闲亭。","花明栏槛朝长倚，月满溪桥夜不扃。","四十年前文酒会，白头相对记趋庭。"]},{"t":"寄周平山","f":"七言律诗","c":["介节清风最起予，此心虽迩迹常疏。","青春莲府衔杯罢，明月茆斋入梦初。","七国奇才多在客，六朝名士总能书。","何因报我瑶华句，一纸寒山慰索居。"]},{"t":"寄叶许山","f":"七言律诗","c":["荔枝曾自小园分，荔子红时倍忆君。","短发细梳凉夜月，虚窗高掩后山云。","狂书往事追狐史，梦寄闲身到鹤群。","十载别来今大耋，鳄湖觞酌更须勤。"]},{"t":"寄叶犹龙","f":"七言律诗","c":["门功先世在安边，少执金吾汉帝前。","宝带尚存天府赐，箧书犹是异人传。","闲中岁月耽山水，乱后文章托管弦。","长记黄塘好风景，近来添得几湖船。"]},{"t":"梁颙若池中莲开一花红白各半索赋三首 其一","f":"七言律诗","c":["半红半白两相加，开向城西处士家。","何处更寻连理树，一枝全胜并头花。","朗如弦月犹衔魄，清比江云欲变霞。","知道先生真诀得，石床相伴养丹砂。"]},{"t":"梁颙若池中莲开一花红白各半索赋三首 其二","f":"七言律诗","c":["金行为白火为红，大冶元多锻炼功。","朱粉并施邻女美，色香齐现法轮空。","高怀濯濯居人外，巧笑盈盈立水中。","记得六朝王俭府，一江南北互相雄。"]},{"t":"梁颙若池中莲开一花红白各半索赋三首 其三","f":"七言律诗","c":["岂曰卑栖意自殊，亭亭泥滓不曾污。","一茎擢出仙人掌，二气凝为太极图。","发为丹心常早白，玉缘泣血半成朱。","雌雄好是芙蓉剑，南斗光芒近有无。"]},{"t":"宋嵋庵招饮南围即事赋别","f":"七言律诗","c":["客里深劳命酒杯，南围腊月正梅开。","城根倒影夕阳落，桥下寒声潮水来。","千里宾朋萍迹合，百年怀抱鬓毛催。","沧江白社吟诗地，送尔风流宋玉才。"]},{"t":"答张桐君","f":"七言律诗","c":["数月逡巡未报诗，十年离索更何为。","雄心老去成灰烬，白雪吟多上鬓丝。","虞苑青蝇嗟往事，陆生车马记前时。","只应共撷东篱菊，买醉南园浊酒卮。"]},{"t":"至日同温茂长侄汝侯雨中入高峡","f":"七言律诗","c":["寒雨从朝歇也无，酒杯相命且狂呼。","长风直破西江浪，短日多行百里途。","峡势益奇霜既落，山容如赭草全枯。","年年此地犹为客，愧见峰头石望夫。"]},{"t":"祝张二尹文宿","f":"七言绝句","c":["郭边潮水日潺潺，官舍无如少尹闲。","一卷新诗是公事，夕阳支枕对西山。"]},{"t":"又","f":"七言绝句","c":["昌黎曾为记蓝田，君较蓝田一倍贤。","钜竹老槐俱不有，窗间松树已十年。"]},{"t":"送周维念","f":"七言律诗","c":["西江秋水正汤汤，暑气初销小阁凉。","归客过逢初泊舫，病身相送不离床。","关山别路无杯酒，书札京华少报章。","卧写新诗不成字，故人休讶懒嵇康。"]},{"t":"送叶渊发","f":"七言律诗","c":["家门七叶金貂盛，之子由来是冷人。","一偈安心居士法，半年餐荔岭南身。","秋江有酒鲈鱼美，碧落无云雁路新。","不向津头望归棹，病来哀乐总伤神。"]},{"t":"赠别刘肩庵","f":"七言律诗","c":["相逢未得数追倍，见说曾从绝国来。","凤诏到时蛮女拜，龙神祭日海云开。","班生自有飞扬志，汉武唯求跅弛才。","斯世升平须俊杰，看君非久滞蒿莱。"]},{"t":"献祝大司马制府吴公三首 其一","f":"七言律诗","c":["清风此日满南隅，文武兼权是丈夫。","百粤诸侯趋使节，八蛮君长拜兵符。","腰横牛斗星边气，句得骊龙颔下珠。","浙水自来多俊杰，几回封爵属通儒。"]},{"t":"献祝大司马制府吴公三首 其二","f":"七言律诗","c":["海门曾报射长鲸，身作东南万里城。","彩笔不妨裁露布，素丝随处建干旌。","令如山岳军皆肃，心在冰壶政自清。","幸托乐郊何以赋，家家弦诵答升平。"]},{"t":"献祝大司马制府吴公三首 其三","f":"七言律诗","c":["水清沙碧石粼粼，千里舟车赴令晨。","棨戟葱茏高峡曙，梅花消息定山春。","一阳复后天开子，维岳生初岁在申。","会见作霖苏九有，先为膏雨慰南人。"]},{"t":"送高谡园廷评","f":"七言律诗","c":["桂江犹带劫馀灰，主试深烦作赋才。","麋鹿竹边骑马过，鹧鸪声里放船回。","逢人便问端溪石，作客徒登赵尉台。","不得留君到初夏，枝头红荔正花开。"]},{"t":"送杨荆湖观察内擢京卿二首 其一","f":"七言律诗","c":["夹道笙歌万姓喧，俱来江上送高轩。","三年预试调羹手，两粤兼承化雨恩。","内诏即今趋凤阙，名流何处望龙门。","桃花院宇论文地，岘首山前片石存。"]},{"t":"送杨荆湖观察内擢京卿二首 其二","f":"七言律诗","c":["荆扬相接气原通，南北新花次第红。","粤峤尚悬卿士月，楚帆先满大王风。","济时妙略忧能远，传世清篇老愈工。","此去明良庆相得，赓歌遥在九天中。"]},{"t":"伏日同王础尘张桐君朱子成周文康梁药亭林叔吾董克灌王紫巘集潘亚目视苍楼分赋因寄董无休","f":"七言律诗","c":["池连深树暑皆消，酒得良朋兴更遥。","片席领风来极浦，断虹将雨下青霄。","楼名赵尉高相望，山有安期坐可招。","三十年前同赋客，白头书札到今朝。"]},{"t":"送朱子成之赣州","f":"五言律诗","c":["仆仆南中路，穷游亦壮游。","义能存故友，分不见诸侯。","五岭天磨蝎，双江地咽喉。","何心成聚散，吾道正悠悠。"]},{"t":"寿林远峰","f":"五言律诗","c":["与尔为同病，蹉跎四十秋。","尚垂孤子泪，已白少年头。","漫学穷弥壮，唯应老莫休。","长生知有地，居处近罗浮。"]},{"t":"寿刘沛叔","f":"五言律诗","c":["章贡千峰里，当年羽檄飞。","死生从舅氏，辛苦脱重围。","马骨招无日，虬须拔渐稀。","白头持寿酒，莫道不沾衣。"]},{"t":"送张超然","f":"五言律诗","c":["相送已云再，风花今仲春。","重寻来日路，又老一年人。","楚水趋吴远，闽山与越邻。","便归何不可，诗卷未常贫。"]},{"t":"诃林雅集得青字","f":"五言律诗","c":["何地堪相约，南宗有祖庭。","倚栏梁树古，开阁越山青。","高咏宽颓暮，深杯免独醒。","年年二三月，车马此频经。"]},{"t":"送施子寓归杭州","f":"五言律诗","c":["诗思清如水，人闲澹似秋。","此来非有谓，何以客炎州。","旧浦香难问，今年荔不收。","闻君住河渚，归去棹扁舟。"]},{"t":"为徐序仔题画","f":"五言绝句","c":["君爱岭南山，虽好携不得。","安得怀袖间，有此英州石。"]},{"t":"送善丹青者吴碧山","f":"七言绝句","c":["纱巾长啸复何之，文采风流杜老诗。","颇怪世间男子少，烦君多为着须眉。"]},{"t":"为严藕渔宫允题绿端砚五首 其一","f":"七言绝句","c":["似是花砖渍古苔，碧云何意下嵩台。","曹家旧瓦誇铜雀，飞作鸳鸯入梦来。"]},{"t":"为严藕渔宫允题绿端砚五首 其二","f":"七言绝句","c":["五色曾闻鍊女皇，至今调绿用玄黄。","一从补后星辰稳，天地精华萃此方。"]},{"t":"为严藕渔宫允题绿端砚五首 其三","f":"七言绝句","c":["端溪雊眼最精荧，龙尾金光带列星。","别向人前开宝匣，倚天元自有青萍。"]},{"t":"为严藕渔宫允题绿端砚五首 其四","f":"七言绝句","c":["汉武淩云思欲飞，相如词赋有光辉。","仙人掌上分馀沥，滴露研朱对绿衣。"]},{"t":"为严藕渔宫允题绿端砚五首 其五","f":"七言绝句","c":["巧匠何年琢翠屏，一泓秋水在闲庭。","岣嵝绿字遥相待，细写文章入汗青。"]},{"t":"筑室谣和何不偕三首 其一","f":"古风","c":["杵声缓，杵声急。","不畏筑墙低，只畏囊羞涩。","墙低有土犹可锄，囊空人笑不丈夫。"]},{"t":"筑室谣和何不偕三首 其二","f":"古风","c":["少小师前修，安能事一室。","老为妻子累，艰难结蓬荜。","十年迁播数易居，匪自求之天我兀。","谁怜鸠拙不能巢，只闻兔狡存三窟。"]},{"t":"筑室谣和何不偕三首 其三","f":"古风","c":["故人自有屋，屋小人日多。","我已无家四十年，偶然卜隐来城阿。","同时各有筑室叹，杵声橐橐遥相和。","杵声缓，杵声急。","未成仰屋筹，只自面墙立。"]},{"t":"真际上人小影","f":"七言绝句","c":["道在宁知白发生，禅房阒寂好经行。","月明满地无人会，消受菩提叶叶声。"]},{"t":"赠徐道冲","f":"七言律诗","c":["雍喈声已满朝阳，雏凤今看起后行。","继世才名徐孝穆，慰亲词赋鲁灵光。","楝花风里过三楚，荔子香时到五羊。","车辙肯来寻负郭，老生头白尚能狂。"]},{"t":"寄答华商原","f":"七言律诗","c":["曾泊端溪共醉歌，霜天凉月映藤蓑。","数茎鹤发生来早，千里鱼书别后多。","已付形骸同土木，尚劳心力纪关河。","终篇不觉逌然笑，壮志真惭马伏波。"]},{"t":"送李嗣公","f":"七言绝句","c":["昔年曾醉鹤楼中，江汉双流直向东。","君去扬帆秋正好，楚台今日有雄风。"]},{"t":"题彭艾庵画舫","f":"七言绝句","c":["酒船来去好相招，朝是山林暮市朝。","夹柳画桥金络马，入城秋水木兰桡。"]},{"t":"冬日端江舟中杂咏五首 其一","f":"七言绝句","c":["数家修竹旧临湍，门径今劳仰面看。","记得秋初曾借泊，维舟刚在赤栏干。"]},{"t":"冬日端江舟中杂咏五首 其二","f":"七言绝句","c":["黄鹤嵩台伯仲间，东南名胜莫能班。","牂牁小让三巴水，石室奇于大别山。"]},{"t":"冬日端江舟中杂咏五首 其三","f":"七言绝句","c":["小湘峡口雾连天，三尺渔竿两桨船。","钓得嘉鱼送官舫，老夫不是买无钱。"]},{"t":"冬日端江舟中杂咏五首 其四","f":"七言绝句","c":["滇桂源头万里遥，一秋无雨涨全消。","端坑水涸初开砚，羚峡门高暗长潮。"]},{"t":"冬日端江舟中杂咏五首 其五","f":"七言绝句","c":["黄冈村里砚成堆，市估争携趁客回。","浪说老夫能识石，更无人向小舟来。"]},{"t":"送蔡亦介归博罗","f":"五言律诗","c":["归去罗阳水，千峰是故庐。","但令耕有地，休念出无车。","浊酒三秋后，闲身百战馀。","亲前犹孺子，更读圯桥书。"]},{"t":"寿伯母梅太君","f":"七言律诗","c":["过来三万又三千，百岁期颐在目前。","两子白头相孝友，一家全盛见曾玄。","能言神庙升平事，尚记吾翁始学年。","今日并成前代史，谁知犹有地行仙。"]},{"t":"题画马","f":"七言绝句","c":["枥下林边寄病身，渥洼龙性本难驯。","休嫌奔走空皮骨，世上谁为买骏人。"]},{"t":"题画鹰","f":"七言绝句","c":["搏击西风力有馀，高枝独立意何如。","羽毛已具飞扬势，莫老磻溪待后车。"]},{"t":"题八骏图","f":"七言绝句","c":["日行三万力何长，博得瑶池一夕觞。","画谱至今图八骏，史书空自笑周王。"]},{"t":"送王子玉归南昌二首 其一","f":"七言绝句","c":["梅关北下水如汤，十日南风是豫章。","归去滕王新阁上，更将文记次三王。"]},{"t":"送王子玉归南昌二首 其二","f":"七言绝句","c":["西畴螟螣不成禾，南海先秋己自波。","莫讶送君无好句，诗怀枯寂比人多。"]},{"t":"赠别潘稼堂简讨二首 其一","f":"七言律诗","c":["向来高步渺群儒，名在新篇势莫逾。","凤羽尚思翔万仞，鹤书争遣下三吴。","横竿笠泽江边卧，直宿文昌殿后趋。","为见为潜君并得，天涯相见话菰芦。"]},{"t":"赠别潘稼堂简讨二首 其二","f":"七言律诗","c":["去是新秋来是冬，一年踪迹岭云中。","犹同遁世人无闷，独有名山路未穷。","采砚每逢蕉叶白，买舟频系荔支红。","罗浮括入归囊里，曾否江门梦钓翁。"]},{"t":"送潘涵观之潮阳二首 其一","f":"五言律诗","c":["郭中犹积暑，江上已重阳。","不惜人千里，其如水一方。","篇章添采菊，消息迩维桑。","亦是淹留地，无忘寄八行。"]},{"t":"送潘涵观之潮阳二首 其二","f":"五言律诗","c":["三年珠海客，怀抱几曾开。","此日人将别，高天雁正来。","边风过细柳，羌笛思残梅。","帷幄堪前箸，宁唯草檄才。"]},{"t":"九日登镇海楼","f":"七言律诗","c":["清尊须醉曲栏前，飞阁临秋一浩然。","五岭北来峰在地，九州南尽水浮天。","将开菊蕊黄如酒，欲到松风响似泉。","白首重阳唯有笑，未堪怀古问山川。"]},{"t":"次先司马韵寄吴尔景","f":"七言绝句","c":["月下论诗夜不眠，鲤庭同试凤山泉。","平陵歌入千秋史，头白门人说往年。"]},{"t":"夜度黄脊沙漫成寄示赣励","f":"七言律诗","c":["无穷志业总成赊，老去吾生渐有涯。","秋秫未登频卧疾，菊花临发又离家。","风吹野柝来虚舫，月应寒潮上浅沙。","报汝三冬宜共勉，莫耽朋酒负年华。"]},{"t":"五色笔歌为王础兄纪梦","f":"七言古诗","c":["十月江清不成冻，寒潮入峡微风送。","峡里停舟待故人，故人书至翻言梦。","梦中授笔何老翁，峨冠广袖言雍容。","为言房隘笔毫损，宽之所以全其锋。","故人受笔欣然久，五色光芒犹在手。","既醒而寐复见之，六十衰年义何取。","我持书札三四看，为君喜气横眉端。","不闻帝命司徒契，五教之敷惟在宽。","天人至理数必五，天曰五行人五事。","包罗万有入纤毫，驱使六经为臂指。","江淹鲍照不知此，中书君老而秃矣。","为君大封管城子，夷吾器小安足齿。","研用补天五色石，书用尚方五色纸。","舂陵霸上云气多，会写龙文入青史。"]},{"t":"题严滩垂钓图","f":"七言绝句","c":["饮水严滩亦汉臣，偶然伸脚动星辰。","寻常裘钓家家有，只少人间共卧人。"]},{"t":"题虬髯客图","f":"古风","c":["九州可赠，百万何惜。","骑驴出门，书生失色。"]},{"t":"别翁约似广文","f":"七言律诗","c":["皋比一坐鬓苍苍，俸入虽微喜近乡。","高峡云山初假馆，三城风雨旧同堂。","康成善饮仪弥谨，阮籍能吟醒亦狂。","还拟花时共沉醉，清溪聊且放归航。"]},{"t":"偶过六瑩堂十一侄以画轴索题时方七龄好尚如此知为英物也二首 其一","f":"七言绝句","c":["长眉高隼骨铮铮，杖锡胡僧意气横。","稳坐蛟龙方濯足，不知风雨夜来生。"]},{"t":"偶过六瑩堂十一侄以画轴索题时方七龄好尚如此知为英物也二首 其二","f":"七言绝句","c":["七龄俊迈异常童，揖请新诗独向侬。","知有文章齐老凤，不须图画羡真龙。"]},{"t":"题四无禅师","f":"五言律诗","c":["邀瀑孤亭上，安禅尚少年。","旧游成梦幻，一悟彻人天。","古貌何超绝，真机但默然。","老来诗更好，都任世间传。"]},{"t":"寄送刘海阳静伯","f":"七言律诗","c":["几年音问渺天涯，别路茫茫系我思。","空际飞凫人莫睹，市中成虎世谁知。","狂多在醒何须酒，穷到能工定有诗。","片剌相投俱不值，倏闻车马又东驰。"]},{"t":"寄黄忍庵太史","f":"七言律诗","c":["菖蒲涧水记浮觞，别后音书枉数行。","近日铜龙老宾客，几年金马校文章。","网罗异代归迁史，羽翼高飞倚夏黄。","江左岭南多轶事，颇曾为论辨兴亡。"]},{"t":"春日王也夔招游蒲涧即事作","f":"七言律诗","c":["何处春郊布绮筵，菖蒲涧口接濂泉。","竹分山色为门径，石咽溪声似管弦。","野寺苍凉怀古地，东风晴暖试花天。","闲来偶共山僧笑，不醉溪桥又五年。"]},{"t":"向恬庵携酒西山是日适热发不得痛饮赋此答谢","f":"七言律诗","c":["谁走银鞍挈玉壶，西山亭沼对城隅。","人言梁国佳公子，仆是高阳旧酒徒。","鱼戏新荷筒尚卷，月疏杨柳叶全枯。","时来望雨忧如渴，清句居然起病夫。"]},{"t":"佘兼五招同梁巨圃刘倬之梁耋符刘惇予小饮池亭大雨适至即事分赋得花字","f":"七言律诗","c":["旬来忧旱每成嗟，两度甘霖值尔家。","高树领风多在柳，小池添水半为花。","凉声入耳能销酒，香气浮杯好试茶。","况是主人文字饮，篝灯拈韵兴何涯。"]},{"t":"端江五日写怀六首 其一","f":"五言律诗","c":["五月牂牁水，今年少浊波。","堤连沙衍出，山落石痕多。","仰食资畬米，均输恃海鹾。","东陲膏雨足，西土定如何。"]},{"t":"端江五日写怀六首 其二","f":"五言律诗","c":["炎荒为泽国，海舶壮军威。","跋浪如山立，乘风若电飞。","雉曾重译贡，马已华阳归。","恃有长城在，南人解铁衣。"]},{"t":"端江五日写怀六首 其三","f":"五言律诗","c":["江阔山为岸，奔流直向东。","最愁炎暑月，多作石尤风。","不有藏舟地，徒劳拯溺功。","可能开别港，羁泊免途穷。"]},{"t":"端江五日写怀六首 其四","f":"五言律诗","c":["厓门三百里，洄溯未为遥。","西水秋无力，南风夜有潮。","豫防闻往哲，列戍自前朝。","海徼波涛地，毋云兵已销。"]},{"t":"端江五日写怀六首 其五","f":"五言律诗","c":["少日趋庭过，中年闭户居。","耻为无用学，必读有源书。","衰白心徒苦，经纶事已虚。","客途犹秉烛，终恐负居诸。"]},{"t":"端江五日写怀六首 其六","f":"五言律诗","c":["处处吊灵均，当年一逐臣。","迹疏犹恋国，道直不谋身。","日月悬词赋，风涛泣鬼神。","湘流殊未极，来者又何人。"]},{"t":"端州华严庵送何孟门陶握山王紫巘游鼎湖二首 其一","f":"五言律诗","c":["一月江城住，茅庵共菜根。","更寻名胜地，仍是给孤园。","高峡连峰影，清溪到院门。","不能同买棹，相送亦难言。"]},{"t":"端州华严庵送何孟门陶握山王紫巘游鼎湖二首 其二","f":"五言律诗","c":["尚记登临日，春王正月中。","冰霜凝野寺，灯火彻行宫。","未续青山梦，居然白发翁。","鼎湖名尚在，惆怅泣遗弓。"]},{"t":"送陶虎侯二首 其一","f":"七言绝句","c":["昨夜明河澹欲流，纤纤凉月报新秋。","似君七夕天南路，牛女星边一叶舟。"]},{"t":"送陶虎侯二首 其二","f":"七言绝句","c":["三十闲身百战馀，新诗唯有问樵渔。","赠君此别如何道，饱看名山胜读书。"]},{"t":"送程荆山归富平为其尊人寿二首 其一","f":"七言律诗","c":["平生游未到秦川，每送秦人一黯然。","四姓帝居雄自古，二崤关路险如天。","河冰坚处行归骑，霜月圆时泊客船。","不必更论南越橐，卷中曾补白华篇。"]},{"t":"送程荆山归富平为其尊人寿二首 其二","f":"七言律诗","c":["源溪苓塞近何如，华子高栖善著书。","归奉晨昏千里外，正当天地一阳初。","罗浮大药光生鼎，太华晴峰雪照庐。","自昔五陵游侠窟，送君临发重踟躇。"]},{"t":"己巳九日镇海楼作","f":"古风","c":["自我移居到南郭，登高三上三城北。","城隅杰阁五层开，六合分明在胸臆。","二江洋洋趋向东，五岭气与珠厓通。","青天四垂海波立，烟云变幻生长风。","故人相约酬佳节，歌舞冈前高宴列。","东西南北一萍蓬，永啸长吟各雄杰。","仙人亭馆石为台，文窗四启无纤埃。","木棉古树垂百仞，清阴覆地秋声来。","座边埤堄连天起，万垒青青皆秀峙。","龙盘虎踞势未殊，为霸为王皆有以。","昔人歌舞尚留名，今人歌舞不成声。","广武城头发浩叹，千秋阮藉称狂生。","君不见高皇用武平方国，百粤怀柔独文德。","斯楼结构自初年，其废其兴岂人力。","雕甍刻桷此重新，地转天旋多气色。","为君酾酒兴何极，半酣起舞忘头白。","倚天长剑又何人，侧身四望乾坤窄。"]},{"t":"罗浮道中值王础尘生日寄之","f":"七言律诗","c":["别时不谓便逾旬，此日高天见雁群。","黄菊篱边谁对酒，朱明洞口倍怀君。","生多忧患常同遘，齿在桑榆愧未闻。","已定穷通数年计，白头相伴老飞云。"]},{"t":"赠别任道爰","f":"七言律诗","c":["隐居虽隔岭头云，廿载相知只耳闻。","三度南来初值我，一秋游兴又违君。","生涯事事成蛇足，行迹年年似雁群。","未必白头皆若此，酒阑携手望星文。"]},{"t":"挽张桐君四首 其一","f":"五言律诗","c":["举世醒皆醉，斯人迩亦遐。","五车梁惠子，七叶汉张家。","每有乘桴叹，常深彼黍嗟。","乾坤无故国，白首尚天涯。"]},{"t":"挽张桐君四首 其二","f":"五言律诗","c":["北海开尊久，南溟世泽深。","萍蓬无定聚，松竹本同林。","未免艰虞日，多承缱绻心。","夜台今不作，寂寞叹人琴。"]},{"t":"挽张桐君四首 其三","f":"五言律诗","c":["灯下文犹草，宵中馆已捐。","有生终是化，无疾即为仙。","胤子来千里，归舟动隔年。","知君丈夫志，不死女儿边。"]},{"t":"挽张桐君四首 其四","f":"五言律诗","c":["交君兄与弟，并是廿年前。","五岭非深阻，双棺乃后先。","长途号白马，中夜泣啼鹃。","恸绝南州客，贫无絮酒钱。"]},{"t":"送彭艾庵流漳州","f":"七言律诗","c":["东郊此别莫销魂，千里闽中路易言。","老泪数行唯母在，馀生一日是君恩。","往来潮水通双鲤，去住云山隔断猿。","到日枫亭秋渐近，荔支红处似家园。"]},{"t":"寄怀王阮亭兼索其南海集","f":"七言律诗","c":["酷似高人王右丞，在官萧散意如冰。","时名兄弟堪方驾，家学文章是一灯。","沧海乘槎曾独到，越山怀古记同登。","南来新咏多如许，纸贵衡阳写未能。"]},{"t":"题甘衷素小影","f":"七言绝句","c":["青松白石不沾尘，野服科头意自真。","一坐空山非易得，十年南北倦游人。"]},{"t":"续王础尘少莱子歌为屈翁山寿","f":"古风","c":["老莱子有五色衣，少莱子有五色笔。","衣舞班斓有尽时，笔飞青简无穷日。","每常中夜起鸡声，亦曾草檄母窥屏。","子年六十母九十，母头全白子全青。","阶前幼稚立四五，长者能文少者语。","人生快意岂在多，莫惜堆盘献鸡黍。","君不见叔皮避地河西居，王命论成还著书。","汉家纪传定义例，作者何必皆石渠。","平津六十初应诏，再至太常方见召。","奇才伟貌众所推，得君何必皆年少。","君家有书非野史，碧血荧荧光透纸。","笔端生气万古存，君与人人皆不死。","少莱子，老布衣，世上好恶多是非。","三闾之后若无子，日月谁与争光辉。","请簪此笔立殿陛，可以上报三春晖。"]},{"t":"庚午九日歌和础兄","f":"七言古诗","c":["前年九日登高回，月入南斗光徘徊。","今年九日西风急，昨夜斗中月仍入。","上天垂象每若斯，安用樽前百忧集。","斗杓如柄挹银河，酌河为酒未言多。","今年九日且已过，明年九日当如何，请酌大斗还高歌。"]},{"t":"送李孝先之蕲州扶其先大夫相如先生旅榇归粤三首 其一","f":"五言律诗","c":["滇楚千峰断，当年立马看。","那堪亡国泪，还洒故人棺。","彭蠡扁舟小，淩江素旐寒。","首丘凭孺子，辛苦涉惊澜。"]},{"t":"送李孝先之蕲州扶其先大夫相如先生旅榇归粤三首 其二","f":"五言律诗","c":["四十年长别，三千里寄居。","生时知有子，归日已无书。","老仆寻先冢，荒畬绕旧庐。","要离虽可近，未若返于初。"]},{"t":"送李孝先之蕲州扶其先大夫相如先生旅榇归粤三首 其三","f":"五言律诗","c":["惜汝风尘早，艰虞及弱龄。","诵诗悲陟岵，闻礼梦趋庭。","剥极终来复，蓝深或出青。","蕲黄张楚地，早愿返松扃。"]},{"t":"寄姚云望","f":"七言绝句","c":["江北江南雪色昏，白头骑马向中原。","不知天地寒如此，犹有遗民问寝园。"]},{"t":"送何孟门之琼州","f":"七言律诗","c":["曾歌燕筑金台上，又泛朱厓大海中。","老脚天涯殊复健，白头吾道未终穷。","首春问路纤纤草，二月扬帆细细风。","此去乡南更千里，好音惟恨隔邮筒。"]},{"t":"博罗令陶雪樵解组将归过予于五羊以罗浮新志见贻诗以送之","f":"七言律诗","c":["解印深辞郡县劳，却烦车骑问蓬蒿。","幽人逸致行藏古，名世新编卷帙高。","未老闲身依净社，方春疏柳映林皋。","罗浮不让匡庐胜，归去先生又姓陶。"]},{"t":"依依图送王础尘之虔州三首 其一","f":"七言绝句","c":["绾烟含雾一丝丝，写出东风赠别离。","莫向尊前吹玉笛，此声曾入采薇诗。"]},{"t":"依依图送王础尘之虔州三首 其二","f":"七言绝句","c":["去年新柳百篇多，今日临岐且复歌。","地隔梅关才一步，水分南北欲如何。"]},{"t":"依依图送王础尘之虔州三首 其三","f":"七言绝句","c":["一篙新水带遥岑，弱缕轻笼万树深。","不是长亭空折赠，依依元是故人心。"]},{"t":"送础尘至黄脊沙舟中复题三首 其一","f":"七言绝句","c":["心似长条不自持，东风摇飏几千丝。","六年舍下同吟地，一宿江头送远时。"]},{"t":"送础尘至黄脊沙舟中复题三首 其二","f":"七言绝句","c":["叶叶枝枝吹自东，乘潮西去更乘风。","还如老马能千里，大笑舟中两老翁。"]},{"t":"送础尘至黄脊沙舟中复题三首 其三","f":"七言绝句","c":["南柳花飞北尚含，片帆杯酒且同酣。","送君心比春风远，万里青青过赣南。"]},{"t":"寿岑金纪","f":"五言律诗","c":["二十始相识，西樵七十峰。","峰峰挟春酒，坐听山门钟。","海日竟不上，白头还几逢。","相看两不变，心与双芙蓉。"]},{"t":"花朝后五日同梁药亭屈本庵吴山带李方水集石公离六堂即事书怀二首 其一","f":"五言律诗","c":["春半花犹未，农时雨不来。","言寻方丈约，笑为老僧开。","古井人争水，空池鹤印苔。","隐忧惭素饱，钟罢且徘徊。"]},{"t":"花朝后五日同梁药亭屈本庵吴山带李方水集石公离六堂即事书怀二首 其二","f":"五言律诗","c":["西畴延夕照，篱落见层层。","塔影千年寺，琴声百岁僧。","风枝翻弱絮，香蕊结垂藤。","妙法离言说，南宗此一灯。"]},{"t":"李孝先就婚西村即事赠诗勉之二首 其一","f":"五言律诗","c":["百曲西村水，三春合卺杯。","夭桃花路近，连理树门开。","择对元难偶，题诗自得媒。","尊君风义在，朋旧总能来。"]},{"t":"李孝先就婚西村即事赠诗勉之二首 其二","f":"五言律诗","c":["故人有才女，之子产燕京。","万里各南北，一朝为弟兄。","高门曾列戟，灵榇望归旌。","燕尔今方始，无忘楚国行。"]},{"t":"送吴制军至三水因纪昔游作百韵赠别","f":"古风","c":["未别不忍言，将别常蹙蹙。","旌旗在前路，不获展心曲。","维时月在午，雨潦犹未足。","高原土尚坼，平野苗稀绿。","处处桔槔声，未敌炎蒸酷。","斗米逾百钱，农夫遂枵腹。","忆公下车始，颇亦忧饘粥。","旧染污未除，遐陬莽犹伏。","冥心运元化，大力旋坤轴。","三江匝五岭，九载皆秋熟。","西开官田戍，东建花城筑。","海滨弛苛禁，万艘衔舻舳。","贵贱通有无，梯航极倭竺。","珍奇溢都市，技巧眩心目。","南溟潮汐地，岛屿浮如鹜。","潮生尽淹浸，及退仍为陆。","船行洲渚下，支络相洄澓。","奸徒棹?䑠，捷径飞驰逐。","意外一疏防，坦途闻叫哭。","自公严汛守，尺守皆有属。","摇飏芦苇外，雕戈间红纛。","徒旅晓夕行，孤客投灯宿。","相谓百年来，太平此时独。","海关新榷税，使者忧盈缩。","算课及渔舟，弃舟乃无屋。","妻儿爨野岸，寝处巢林木。","减米获生全，赖公为补牍。","牂牁数千里，发源自滇筑。","攒峰割云日，铦利侔刀镞。","盘据百粤西，大半苗蛮族。","君长世相承，中华频改卜。","其人殊倔强，其性同麋鹿。","得失几微间，赴死如蛾烛。","有明中叶后，每每用杀戳。","泰山压群卵，安有不摧覆。","于德乖好生，于武为已黩。","内地况骚然，所得焉足赎。","岂闻抵恶鸟，辄以荆山玉。","公威久已著，更用恩为育。","召其黠桀者，赐坐与酒肉。","貂裘及锦带，照曜归穷谷。","传谕与而曹，邻好宜修睦。","毋自启衅端，祸及诸伯叔。","君长咸感怀，稽首望辇毂。","边烽绝无警，一路蒙公福。","粤于丙丁际，后乱而先复。","五营与有劳，恃功颇难畜。","前人务优容，军政渐不肃。","及公明号令，童牛初就牿。","戢其骄悍气，帖耳事轮辐。","亲随多骁健，功在征闽录。","夹持类蓬麻，臂指从所欲。","乃知养士效，远虑素所蓄。","从来成功人，土视金与粟。","恩赏既以行，有罚敢不服。","公令重如山，其照明如旭。","东西山海隅，萑苻罔遗毒。","朝发夕已擒，群奸畏神速。","大象本无形，政理难更仆。","睹此一方民，安和异曩夙。","足知良工苦，非取悦时俗。","往者破厦门，举世共瞻瞩。","谋断本独行，功成让先告。","是知大臣心，舍己期相勖。","世人见浅近，事事求表暴。","安识国手棋，下着关全局。","粤疆乱甫定，培养宜先笃。","休息以无为，治世之蔘茯。","去其害马者，所以称良牧。","老眼阅古今，或颇辨麦菽。","识时在俊杰，屈指不五六。","怀刺每生毛，素耻事干渎。","长揖入军门，荷公不见督。","疏狂谬宾礼，啸咏无拘束。","尚记数年前，维舟值秋菊。","在坐王将军，酒阑命笺幅。","中间置几砚，杯斝罗四角。","联诗公首唱，以次相赓续。","一人操笔吟，二客飞觞促。","雕盘减玉馔，小品珍蔬蔌。","华灯继落晷，夜月生江澳。","公才敏且健，珠玑泻千斛。","不离古典型，别出新机轴。","于时有公会，百政方蔟蔟。","偶此一日闲，雅事洵难复。","平沙列大幕，万马鸣山麓。","扁舟此追送，仿佛犹前躅。","南北一分途，飞潜隔寒燠。","老态傍青门，生事依黄犊。","目极车骑行，心为苍生祝。","朝端望风采，功伐存山竹。","九重思鼓鼙，天厩归骅騄。","及此涉川时，扬帆发南隩。","湘漓水清漪，洞庭秋沕穆。","想到黄金台，寒风已谡谡。","童叟咽江湄，挥涕成霢霂。","何时天上霖，重作南人谷。","伸章欲抒写，瞀乱笔先秃。","以质不以文，将为后世读。","拜别还空山，云中望鸿鹄。"]},{"t":"屈翁山寓楼老谷树为大风所摧诗以伤之索予同赋","f":"五言古诗","c":["君家寓园西，最好此老树。","无风亦飕飗，有壁劳遮护。","况当赫曦时，密荫登楼路。","往者得屡过，凭栏必回顾。","大叶类桑麻，古干如雕塑。","刺之出白乳，胶漆同黏固。","楚人谓乳㪍，名实本相符。","山木且自伐，矧兹城与圃。","遍体刀斧瘢，中空复来蠹。","莫识始植年，主人更已屡。","稽之抱朴子，赤实颜能驻。","视夜见鬼神，轻身追马步。","每欲托园丁，升斗为收聚。","昨夜时雨过，新诗枉毫素。","伤树有名篇，清阴绝良晤。","天地乃不仁，风伯何相妒。","岂有精魅凭，致干阴阳怒。","倾压及邻家，砍斫烦童孺。","充君厨下薪，琴材亦难具。","草木虽无灵，修短固其数。","昔闻伊陟相，其君帝太戊。","有谷一夕拱，修政知所惧。","曰妖不胜德，终尔枯且锢。","殷道以复兴，汤孙世延祚。","家国匪异观，灾祥或同度。","慰君用自广，伸纸为赓赋。"]},{"t":"罗浮黄龙洞对雪","f":"五言古诗","c":["淅淅天上风，吹我白日没。","飞瀑渐无声，寒溪遂生骨。","仰视老人峰，云中玉为笏。","嵚崎积已平，飘洒殊未歇。","回旋若翔舞，廉纤乱毫发。","客子宿茅茨，居然见冲突。","重檐及户牖，堆压不可掘。","南州炎德在，况此仙灵窟。","丹火伏不兴，初阳动犹蹶。","判此始衰年，拥衾坐明发。","赖逢酒力良，未使吟声竭。","夜久迥闻钟，山晓不待月。","始知蓬岛来，往事非荒忽。","请看朱明天，化作金银阙。"]},{"t":"客有之琼州者属其访丘文庄海忠介二公祠宇","f":"五言古诗","c":["积水淼四溟，坤维有时绝。","珠厓隔华风，灵气久不泄。","悠悠秦汉来，青史独旷缺。","一旦逢休明，千秋两人杰。","丘相博古今，海公树风节。","独立三百年，后先罕其列。","作史正世纲，严统示予夺。","创论每惊人，深思竟难越。","衍义续成书，文章乃馀屑。","用未究当时，功实裨前哲。","世庙圣之威，金丹晚旒缀。","直言天下事，闻者皆吐舌。","拚死批逆鳞，岂惟槛可折。","沈薶犴狴底，忠爱日胶结。","方饮闻宾天，一恸数斗血。","刚方古有人，至诚孰能埒。","仰止匪自今，瓣香独遥爇。","君行渡琼海，跋浪如丘垤。","二公所钓游，野老犹能说。","经过祠庙下，为我停车辙。"]},{"t":"闻王惠州紫诠筑子日亭于罗浮绝顶歌以寄之","f":"七言古诗","c":["我昔深春上衡岳，千峰万峰如玉琢。","雪压松篁尽倒垂，杖头一拨飞冰雹。","祝融古殿在中峰，皎若琼瑶生四角。","石墙铁瓦大如席，巨木为椽全不桷。","侧听唯有风怒号，仰视分明天一握。","南归与客入罗浮，腊尽绵衣寒未觉。","三更观日坐飞云，露宿终宵殊龊龊。","福地那能久寂寥，使君五马来河朔。","山灵留意俟奇人，大雪飞空洒行幄。","诸溪生骨不成流，有酒如渑亦须涸。","同行宾客多英贤，儒衣僧衲皆沾渥。","豪吟总作金石声，瑶池直奏钧天乐。","纪游示我诗一卷，更道新亭命工斫。","亭成榜以子日名，盛事千秋良不数。","蓬瀛来此几星霜，绝顶谁为问硗埆。","童儿垒石作浮图，樵斧无时加击㧻。","一朝杰构得未曾，四百名峰增卓荦。","元阳之生正在子，天心来复还先剥。","日月精华吸最初，神仙老易非殊学。","重檐深覆欲经久，土墄因仍制宜朴。","石楼大小互相望，上界仙坛为犄角。","雨馀飞瀑响渐多，暖后黄精亦堪斸。","为公拟续春深游，亭中卧待天鸡喔。"]},{"t":"梁殿一殿章招饮雨花洞即事","f":"七言律诗","c":["五峰处处有名区，最是君家似画图。","已割山光来屋里，不妨楼外即城隅。","香垂峭壁千花细，石透盘根老树孤。","两世过从今几度，快听春鸟劝提壶。"]},{"t":"春日同吴又札梁耋符郭公鹫游东郊倪公堤观徐邑侯新修石桥松路","f":"七言律诗","c":["杏花风里酒旗翻，郭外新堤带远村。","双塔云生偏荫路，九桥潮长各争门。","童年捧杖还谁在，老大归心未易言。","待得小松高百尺，与君春雨更携尊。"]},{"t":"林叔吾六十次己未韵寿之","f":"五言古诗","c":["祝君昔何所，计月百六十。","不谓生初年，循环亦俱及。","春从笑语深，霜自须眉入。","天地已惊雷，龙蛇未离蛰。","寄此一篇诗，茫然百忧集。","想见举案间，当欢或成泣。","有兄共白头，有子幸能立。","此外复何求，一觞聊自执。","溟鲲易变化，隙驷难维絷。","蟠溪有钓叟，老见干戈戢。","君家有林类，百龄歌且拾。","穷通理若何，仰视天如笠。"]},{"t":"嘲剔牙杖","f":"五言绝句","c":["甘苦全无与，平生薄自居。","齿牙虽得利，骨肉渐应疏。"]},{"t":"剔牙杖答","f":"五言绝句","c":["纤弱诚无状，唯君实使之。","若能无间隙，轻薄亦奚施。"]},{"t":"壬申清明即事次杜韵同王础尘二首 其一","f":"七言古诗","c":["故阡松柏有新烟，欲上江乡两桨船。","老去登临知几度，时来醒醉且随缘。","扶筇得得身能健，插柳依依态可怜。","两月又过真倏尔，一尊相对各陶然。","春城市肆犹争米，薄俗穷民不要钱。","且喜今朝晴最好，登秋岂独庆丰年。"]},{"t":"壬申清明即事次杜韵同王础尘二首 其二","f":"七言古诗","c":["久无消息岭云东，有药休教为已聋。","北塞坚冰犹在野，南州新草漫连空。","百年饮恨孤儿在，三月伤心万国同。","老泪只应镌楚竹，招魂空自赋江枫。","金陵佳气松楸里，铜柱高标指顾中。","莫向春光怨迟暮，与君同是白头翁。"]},{"t":"送李方水之官新兴","f":"七言律诗","c":["新州江水昔曾尝，且喜西行路未长。","绛帐生徒兼稚子，青山风物是家乡。","官闲勿厌开缃帙，身健先须捡秘方。","不必强为儒佛辨，南能生处近宫墙。"]},{"t":"龙船行","f":"七言古诗","c":["朔日二日天尚晴，江上寥寥金鼓声。","五日六日雨正急，官点龙船如点兵。","金声号呶鼓声怒，百里刻期齐竞渡。","家家合米作行粮，里正科钱犒中路。","海珠寺边古树牢，官船系缆风颾颾。","江中金锁连舶艚，氍毹铺出歌台高。","上头列坐獬豸袍，横江开宴停旌旄。","太平乐事非为扰，最是小民难户晓。","往年官禁船尚多，今日官催船却少。","上官出赏树锦标，银牌如纸悬红绡。","有司供鸭日三百，龙船角逐声喧嚣。","锦标夺归插里社，纵有能名无得者。","虽云夺鸭不足誇，明日卖钱还借家。"]},{"t":"寿罗颢甫","f":"七言绝句","c":["南风吹送荔香新，寿酒初开五十春。","马齿相看吾更老，白头羡尔倚闾人。"]},{"t":"寄何孟门时客琼南二载矣三首 其一","f":"七言绝句","c":["醉别江头解袷衣，别来两度见芳菲。","海南节序无寒暑，空使王孙不记归。"]},{"t":"寄何孟门时客琼南二载矣三首 其二","f":"七言绝句","c":["唱和谁同水一方，今年稀得见篇章。","看君亦是虬须客，莫到扶馀便自王。"]},{"t":"寄何孟门时客琼南二载矣三首 其三","f":"七言绝句","c":["年年相约荔支红，挥扇高谈几老翁。","挂绿凝冰知在念，未堪邮寄海船风。"]},{"t":"秋园十首 其一","f":"五言律诗","c":["凿池供版筑，杯水在堂坳。","有室如悬磬，为生且系匏。","近秋桐影薄，深夜药苗交。","自喜忘机久，窗前鸟亦巢。"]},{"t":"秋园十首 其二","f":"五言律诗","c":["隔城闻欸乃，舟子理帆樯。","夜气消群动，江声到小堂。","远心秋外炯，孤烛梦边长。","卧起歌残月，沧浪兴未忘。"]},{"t":"秋园十首 其三","f":"五言律诗","c":["屺岵瞻何及，干戈遂至今。","生无一日乐，老负百年心。","息影依林浅，寻源凿井深。","犹馀种瓜地，锄笠尚堪任。"]},{"t":"秋园十首 其四","f":"五言律诗","c":["万寿炎方果，朝来叶渐添。","摇风重夏扇，遮日却湘帘。","虚质抽茎直，苍皮着子黏。","书斋终藉汝，地窄不伤檐。"]},{"t":"秋园十首 其五","f":"五言律诗","c":["小雨才收点，高林渐透光。","风摊书满案，水载月摇墙。","清簟凉消酒，深炉夜贮香。","贫居多所累，笔砚为人忙。"]},{"t":"秋园十首 其六","f":"五言律诗","c":["近郭非吾意，为园亦有初。","本无锥可立，差免穴而居。","就架扶丛菊，分泉育小鱼。","今年盐价长，不必莳瓜蔬。"]},{"t":"秋园十首 其七","f":"五言律诗","c":["以管窥能几，深疑甘石经。","日中开叠晕，天午见孤星。","赤地兼秦晋，流人尽梗萍。","海隅今得雨，稽首谢高冥。"]},{"t":"秋园十首 其八","f":"五言律诗","c":["王子罗浮去，空斋倍寂寥。","月悬高卧榻，风响饮泉瓢。","晚实林方茂，春红卉尽凋。","宵来唯独啸，鸾鹤未堪招。"]},{"t":"秋园十首 其九","f":"五言律诗","c":["玩世金茅子，违时独漉翁。","篇章情各惬，栖宿偶能同。","座为求书满，尊惭近市空。","时凭写生手，绘尽小园风。"]},{"t":"秋园十首 其十","f":"五言律诗","c":["鲍守馀双履，浮丘即旧墟。","仙人皆已矣，何者是吾庐。","果熟携孙摘，诗成命子书。","白头闲亦得，终自惜居诸。"]},{"t":"送区兴甫之阳江二首 其一","f":"七言绝句","c":["暑中挥汗枉经过，病眼难开奈别何。","莫道阳江非远道，白头相见苦难多。"]},{"t":"送区兴甫之阳江二首 其二","f":"七言绝句","c":["岭头相送昔何时，十六年来尚若斯。","今日莫论天下事，只须长保鬓边丝。"]},{"t":"同邑中诸子登钟楼小酌","f":"七言律诗","c":["飞楼跨路石门开，新筑城东百尺台。","碧水远明朱槛外，数峰青入女墙来。","霜归晚叶催华发，月上初弦落酒杯。","故国旧知无限乐，夜钟鸣尽未知回。"]},{"t":"荷池偶题二首 其一","f":"五言绝句","c":["今日花始开，昨日花尚好。","欲知花故新，但看蜂多少。"]},{"t":"荷池偶题二首 其二","f":"五言绝句","c":["方池不见水，但见红与碧。","小雨芰荷翻，一声何处得。"]},{"t":"答袁二玉即送之归馀杭兼柬季伟公","f":"七言古诗","c":["十月黄花犹在径，拥褐徐行黄没胫。","清晨有客叩我门，童子贪眠呼不应。","病身出揖小亭西，袖有新篇为我赠。","临风玉树既皎如，满把骊珠光照乘。","闻君家住西子湖，浩然动我曾游兴。","山色周遭郭外青，波光一片衣间凝。","春烟秋月几衔杯，故国旧家同堕甑。","羡君生长久承平，往事何堪入聪听。","南来诗卷气有馀，展读终朝语清醒。","不嫌老马问修途，自愧霜蹄早蹭蹬。","季生闻说寓兰溪，母老儿娇室悬磬。","君年方壮渠尚强，好上湖船共深订。"]},{"t":"小禺二集刘显之六十赠之","f":"七言律诗","c":["白发频添不自休，杜门终日事穷搜。","三千高第中分鲁，七略群书总萃刘。","未拟河汾还献策，无妨匡鼎亦封侯。","生来年齿差相若，经学于君逊一筹。"]},{"t":"寄题王阮亭西城别墅十三咏 其一 石帆亭","f":"五言古诗","c":["大壑有藏舟，兹帆负而走。","不觉动波涛，但见移星宿。","寄谢济川人，清风在岩岫。"]},{"t":"寄题王阮亭西城别墅十三咏 其二 樵唱轩","f":"五言古诗","c":["日落山更空，孤亭惬幽赏。","一声何处歌，松风递馀响。","不必问其辞，悠然绝心想。"]},{"t":"寄题王阮亭西城别墅十三咏 其三 半偈阁","f":"五言古诗","c":["妙法非有无，一偈何可说。","小阁坐默然，花光满林樾。","目送海岱云，西飞过吴越。"]},{"t":"寄题王阮亭西城别墅十三咏 其四 大椿轩","f":"五言古诗","c":["世无千载人，大椿寿谁算。","黄帝甲子来，才及春之半。","独有观棋人，还家柯已烂。"]},{"t":"寄题王阮亭西城别墅十三咏 其五 双松书坞","f":"五言古诗","c":["双龙何夭峤，屹立竦毛发。","兴至一摊书，爱此松下月。","有时清梦中，风涛坐超忽。"]},{"t":"寄题王阮亭西城别墅十三咏 其六 小华子冈","f":"五言古诗","c":["溪山不自名，胜地因人有。","不知今古人，梦寐相反否。","丸丸华子冈，小大俱不朽。"]},{"t":"寄题王阮亭西城别墅十三咏 其七 小善卷洞","f":"五言古诗","c":["舜以天下让，善卷固弗取。","茅茨与土阶，何用分出处。","想见洞中人，高风迈巢许。"]},{"t":"寄题王阮亭西城别墅十三咏 其八 春草池","f":"五言古诗","c":["年年春草芳，绿遍陇与亩。","一入池塘梦，遂为谢家有。","不惜绿更黄，但惜离居久。"]},{"t":"寄题王阮亭西城别墅十三咏 其九 三峰","f":"五言古诗","c":["三山不可即，林中恍如对。","世无痴神仙，要当属吾辈。","羡门与子乔，安知不在内。"]},{"t":"寄题王阮亭西城别墅十三咏 其十 啸台","f":"五言古诗","c":["天地本一气，至音唯可通。","金石与笙箫，喤喤徒乱聪。","为君一登啸，玄鹤来高空。"]},{"t":"寄题王阮亭西城别墅十三咏 其十一 石丈","f":"五言古诗","c":["晋国昔能言，泰山曾自立。","神异即不无，幽奇讵能及。","拔起若兴云，濛濛翠犹湿。"]},{"t":"寄题王阮亭西城别墅十三咏 其十二 竹径","f":"五言古诗","c":["结根幸在兹，绿筠长可保。","涌翠为波涛，秋声满晴昊。","三径净无尘，风影自能扫。"]},{"t":"寄题王阮亭西城别墅十三咏 其十三 绿萝书屋","f":"五言古诗","c":["雨霁闻鸟声，春阴覆林莽。","碧藓印阶明，绿萝缘壁上。","中有读书人，千秋遂孤往。"]},{"t":"癸酉人日偕王础尘王新侯王立安过石公精舍惠州王使君紫诠挈其诸孙已先在同登怀古楼即事作","f":"五言古诗","c":["献岁酬酢劳，郊坰未曾出。","今与良朋偕，方知值人日。","东风动高怀，幽事期禅室。","欢然集童冠，不暇计六七。","长文抱着车，荀彧幼在膝。","入林钟乍鸣，清梵磬未毕。","隔篱辨主宾，近牖闻琴瑟。","石径绝纤埃，板桥度残蔤。","登楼一舒眺，日月飞何疾。","万古浩茫茫，天步无停跸。","石门犹汉垒，香浦非前率。","陇亩半青黄，沧波一洄潏。","寒花采玉兰，圃树攀霜橘。","老大习酸辛，稚子甘崖蜜。","聊为虎溪笑，且试玄卿笔。","即事非古今，至道忘儒佛。","询知吏为隐，亦有民名逸。","冀留金石篇，来者为可述。"]},{"t":"钟纯臣广州寓斋赏牡丹作","f":"七言律诗","c":["自是群芳第一流，谁移嘉卉到炎洲。","明霞剪出千重瓣，紫玉堆成十二楼。","仙子未堪同淖约，化工何必太雕锼。","经旬宴赏犹能好，欲笑芙蓉不耐秋。"]},{"t":"五六七言绝句为朱竹垞题小影三首 其一","f":"五言绝句","c":["识君三十前，貌比今时好。","独有千古心，不共流年老。"]},{"t":"五六七言绝句为朱竹垞题小影三首 其二","f":"古风","c":["发薄未胜藤笠，身闲稳称秋衫。","归梦一竿何处，荻花烟艇江南。"]},{"t":"五六七言绝句为朱竹垞题小影三首 其三","f":"七言绝句","c":["霜雪侵颜日渐新，文章写出是天真。","占星帝座非无客，避世金门自有人。"]},{"t":"同朱竹垞梁药亭屈翁山过诃林南公房观唐僧贯休画罗汉歌","f":"古风","c":["二月八日天晴晻，故人特地停舟舰。","相约菩提树下行，吁嗟霜雪枝条斩。","千秋古迹罕复存，石幢宝历犹唐錾。","南公为我开一轴，先朝赐物珍如琰。","对之不觉形神敛，胡僧端坐当轩槛。","低首写经不见颔，目睛注视光犹焰。","鼻尖下垂唇欲掩，大笔如椽指端揽。","贝叶行间才数点，砚旁堆叶散不捡。","童子侍侧出半脸，倚柱静观如未厌。","老猿休心寂百感，阶前假寐坐不敢。","拥彗而立毛髧髧，长衣被体色黤黯。","足爪着地纤如剡，绢素云生朝惨澹。","款识年深失姓名，葆藏幸且无尘玷。","图形正面古所难，况兼蹙缩加饶减。","相传画手是贯休，不是高流无此胆。","君不见羲皇一画直至今，文章日日趋奇险。"]},{"t":"别朱竹垞三十六年矣癸酉二月复会于广州三日别去送之以诗","f":"七言绝句","c":["三日江边驻客船，菩提坛下又离筵。","如何三十六年别，一日分为十二年。"]},{"t":"除夕咏橄榄同王紫诠使君梁药亭屈翁山吴山带季伟公作四首 其一","f":"五言律诗","c":["嘉果防中酒，华筵列几枚。","色迎青帝近，甘自隔年回。","弱蒂因盐落，微香夺茗开。","深宵人不远，相劝尽馀杯。"]},{"t":"除夕咏橄榄同王紫诠使君梁药亭屈翁山吴山带季伟公作四首 其二","f":"五言律诗","c":["正有文园渴，生津尔所优。","添将牙后慧，藏作掌中钩。","苍玉春王佩，丁香汉署求。","明朝期献岁，一一记更筹。"]},{"t":"除夕咏橄榄同王紫诠使君梁药亭屈翁山吴山带季伟公作四首 其三","f":"五言律诗","c":["果中推异品，地远乃名夷。","岁岁无为赏，青青欲赠谁。","车箱归北客，花实又南枝。","消尽人间毒，渔翁只自知。"]},{"t":"除夕咏橄榄同王紫诠使君梁药亭屈翁山吴山带季伟公作四首 其四","f":"五言律诗","c":["事后思忠谠，嘉名比直臣。","病从苦口利，寒到尽头春。","作弹驱群疠，堆盘杂五辛。","谏书稀圣世，笑尔美芹人。"]},{"t":"题西洋画二首 其一","f":"七言绝句","c":["西番画法异常伦，如雾如烟总未真。","酷似少翁娱汉武，隔帷相望李夫人。"]},{"t":"题西洋画二首 其二","f":"七言绝句","c":["丝丝交织自成文，不画中间画四邻。","亦是晋唐摹字帖，偏于无墨处传神。"]},{"t":"题迟灵山屏万行乐","f":"古风","c":["德行之方如面，诗卷之高等身。","三仕三迁仙吏，一琴一鹤其人。"]},{"t":"惠州代泛亭雨后望西湖","f":"七言律诗","c":["高亭下视极人寰，积水遥连埤堄间。","一线绿分湖上路，几重青出郡西山。","坐临胜地如曾到，名在千秋自不删。","不是使君闲着眼，后人何处得跻攀。"]},{"t":"方毛氏节烈歌","f":"古风","c":["君就木，妾坠楼，此心一日为千秋。","死同穴，谷异室，此心十年如一日。","严滩新冢高崔嵬，一棺两圹同时开。","祝宗祈死亦太拙，粒米不入生何来。","经旬礼佛饥无怠，正气在中能不馁。","重泉一笑好相迎，易箦之言今尚在。","吾翁吾父幸勿悲，舍生取义当如斯。","承祧有子墓有碑，一死较胜坠楼时。"]},{"t":"镇海楼同梁药亭送黄忍庵归太仓毛会侯归严州季伟公归杭州分得都字","f":"七言律诗","c":["重构飞楼壮此都，朝台送客又吾徒。","文章未沫张丞相，霸气全销越老夫。","万壑归潮明槛外，千峰凉雨散城隅。","天涯一别分吴越，后会苍茫定有无。"]},{"t":"哭王础尘十首 其一","f":"七言绝句","c":["素车相送粤江边，生死论交二十年。","牛斗之间光尚在，如何埋得向黄泉。"]},{"t":"哭王础尘十首 其二","f":"七言绝句","c":["武昌江上覆舟时，天道悠悠莫可知。","总是人间不成事，廿年重活更何为。"]},{"t":"哭王础尘十首 其三","f":"七言绝句","c":["金台建业两纷纷，麦秀成歌昔所闻。","欲望龙髯无处所，东西南北且为云。"]},{"t":"哭王础尘十首 其四","f":"七言绝句","c":["献策曾承相国知，三加亲为结冠緌。","痛来礼数从兹绝，不独西台恸哭时。"]},{"t":"哭王础尘十首 其五","f":"七言绝句","c":["长将行迹寄天涯，三十鳏居不自嗟。","客有问君君大笑，丈夫无国更何家。"]},{"t":"哭王础尘十首 其六","f":"七言绝句","c":["高行唯与古为徒，戆直常师汲大夫。","身后有人思苦口，当时来毁更来谀。"]},{"t":"哭王础尘十首 其七","f":"七言绝句","c":["天才敏妙不烦思，斗酒青莲信有之。","犹记小斋新柳发，三更和尽百篇诗。"]},{"t":"哭王础尘十首 其八","f":"七言绝句","c":["十行一目古谁如，强记宁惟七箧书。","一盏青灯人白发，病中犹不负居诸。"]},{"t":"哭王础尘十首 其九","f":"七言绝句","c":["眉须如画发高吟，至理清言尽德音。","忆雪楼前风雨后，广陵一曲绝于今。"]},{"t":"哭王础尘十首 其十","f":"七言绝句","c":["才了先人土一抔，便思终老向炎洲。","骨肉即今还父母，衣冠长此葬罗浮。"]},{"t":"送蔡汉长入都","f":"七言绝句","c":["君去须登郭隗台，凭将杯酒酹荒苔。","黄金骏骨招何日，赤汗龙驹只自来。"]},{"t":"送怡然上人汀州省母次梁药亭韵","f":"七言绝句","c":["不惜芒鞋踏路尘，九龙滩上独行身。","吾生早作无依子，世外偏怜有母人。"]},{"t":"送林赤见北上","f":"五言古诗","c":["与君父子交，骨肉兼朋友。","于君出处间，踌躇亦已久。","富贵非所欣，长贫难独守。","昂昂七尺躯，砚耕日糊口。","甘旨安所供，庭闱俱白首。","应举为文章，如狂逐日走。","空役一生心，岂足传身后。","既作献玉人，莫若求先剖。","庶几少息肩，馀力堪攻取。","君禀绝异姿，立行尤不苟。","在器为干将，在星为枢斗。","应机立能断，遇物操其纽。","以此驭世纷，艰钜复何有。","帝京英贤会，九垓共奔走。","方骋千里蹄，直抉开天手。","勉矣树令名，三立期不朽。"]},{"t":"题王蒲衣琵琶图二首 其一","f":"七言绝句","c":["抱月怀风倍可怜，更劳芳袖拂清弦。","谢郎自足真人想，为尔移情北牖前。"]},{"t":"题王蒲衣琵琶图二首 其二","f":"七言绝句","c":["一曲乌孙马上音，高弹促节且娱心。","琵琶妙手王摩诘，不买鸾胶续断琴。"]},{"t":"边月","f":"五言律诗","c":["神龙衔烛地，顾兔亦乘轮。","共此中闺照，分随出塞人。","露漙光不匝，野阔影无邻。","候满年年事，空嗟归梦频。"]},{"t":"边雪","f":"五言律诗","c":["烟尘一以灭，高下玉为台。","牧马来无所，同云黯不开。","冻凝青海浪，路失白龙堆。","奉使丁年客，从今又几回。"]},{"t":"边柳","f":"五言律诗","c":["绝域谁相赏，阿那自得名。","叶间穿旧箭，原上列新营。","白日风枝折，残春雪眼明。","南朝大司马，空复涕金城。"]},{"t":"边笛","f":"五言律诗","c":["微风传妙曲，清切若为酬。","谁挟终南琯，来添塞北愁。","关山无尽月，天地不禁秋。","何日闻歌凯，征人下戍楼。"]},{"t":"边马","f":"五言律诗","c":["塞上传烽警，将军赋出车。","千群新草外，八月上膘初。","云籋龙为友，风生虎不如。","为君威海内，安用事诗书。"]},{"t":"边雁","f":"五言律诗","c":["南北家何在，其生无定居。","避人犹有弋，寄汉已无书。","沙碛将难久，江湖迥自如。","岁寒天路永，归翮莫徐徐。"]},{"t":"边烽","f":"五言律诗","c":["夕烽传顷刻，千里到云端。","气足苍山暝，光添紫塞寒。","万方专视听，一点是平安。","莫取佳人笑，诸侯怒目看。"]},{"t":"边草","f":"五言律诗","c":["何心荣与悴，今古恨无穷。","雪散烧痕上，青归战血中。","天长垂大漠，地远后东风。","独有明妃冢，年年似汉宫。"]},{"t":"边尘","f":"五言律诗","c":["人间何处免，北塞独先飞。","似得风云气，全欺日月晖。","曳柴传战法，望锐亦兵机。","差胜京华客，终年化素衣。"]},{"t":"修先墓作六首 其一","f":"五言律诗","c":["白头良已矣，子职竟茫然。","负此一抔土，于今四十年。","恤忠馀往典，纪事有新编。","寂寞松楸下，丰碑谁为镌。"]},{"t":"修先墓作六首 其二","f":"五言律诗","c":["文渊犹藁葬，正则且沈身。","古者无修墓，非言患难人。","报唯存此日，举必念千春。","黾勉从微力，伤哉由也贫。"]},{"t":"修先墓作六首 其三","f":"五言律诗","c":["不辰吾最甚，十二丧慈闱。","对食啼葱叶，当秋泣线衣。","国忧才隔岁，泉路幸先归。","赐葬仍同穴，丝纶灼有辉。"]},{"t":"修先墓作六首 其四","f":"五言律诗","c":["峰西频倚杖，一上一徘徊。","筋力今如此，馀生能几来。","彼苍诚有感，积雨喜全开。","十日松间坐，涛声总是哀。"]},{"t":"修先墓作六首 其五","f":"五言律诗","c":["固安唯至愿，尺寸自经营。","墓是无穷事，人兼不朽名。","发祥如有本，凭吊所从生。","虽乏青囊术，滕公自得城。"]},{"t":"修先墓作六首 其六","f":"五言律诗","c":["万山青不极，旷绝此登临。","大化自通塞，吾人为古今。","风摇千亩绿，云散一溪阴。","转盼皆陈迹，弥伤志士心。"]},{"t":"白鸠","f":"七言律诗","c":["奇毛远致自南交，异物何须论九苞。","霁后有声来屋角，月中无影立梅梢。","曾为汤瑞同丹鸟，不入周诗乱鹊巢。","宿世鹰扬心尚在，白旄黄发未全抛。"]},{"t":"赠程立方国学","f":"七言古诗","c":["君家职方吾老友，其人爱士不离口。","往时寄我都下书，君名每见新篇后。","十四年来宿草生，而君为客五羊城。","三四过我始一值，长身赤面神尤清。","卞和几刖连城璧，杜甫方为老宾客。","日观东寻泰岳碑，天津西笑长安酒。","徘徊岭外再经秋，车马因人遍十州。","海天万里豁心眼，珊瑚火齐资冥搜。","新诗示我殊开爽，往帙虽多今更长。","只将妙笔写高深，不与时流为俯仰。","平生意气已心倾，况是山阳晚笛声。","如何咫尺仍千里，不及东风共听莺。"]},{"t":"送方葆宇","f":"五言律诗","c":["瓠落馀生在，嘤鸣旧好存。","夫君怀远别，昨日枉高轩。","小驿梅迎客，寒溪草闭门。","无能具鸡黍，相送亦何言。"]},{"t":"西湖观打鱼同王紫巘若云立安朱开黄作四首 其一","f":"五言律诗","c":["沙际添新涨，桥边响细风。","同人来雨后，尺鲤出湖中。","竹筏渔家屋，藤蓑鹤发翁。","献鲜知有客，贾勇更张罿。"]},{"t":"西湖观打鱼同王紫巘若云立安朱开黄作四首 其二","f":"五言律诗","c":["拨棹争先后，平湖望渺然。","安知人在水，只似马行天。","叶泛舟形小，云飞网势圆。","得鱼邀上赏，公子不论钱。"]},{"t":"西湖观打鱼同王紫巘若云立安朱开黄作四首 其三","f":"五言律诗","c":["峰转仍波浪，源通忽石林。","直拚三日棹，方尽两湖深。","朴俗无台榭，贫家有织纴。","村村悬敝笱，知不患年侵。"]},{"t":"西湖观打鱼同王紫巘若云立安朱开黄作四首 其四","f":"五言律诗","c":["系舸黄塘外，亭边水一篙。","昔时僧院闭，前月浪痕高。","短笛调新曲，行厨进浊醪。","未堪穷胜事，饥溺愧吾曹。"]},{"t":"病足经时郑迈公以桑寄生见贻渐有起色赋此戏柬","f":"七言绝句","c":["寓形宇内已无多，寓木深承起积疴。","吾道不行非一日，妙方端的更如何。"]},{"t":"答林敬臣","f":"七言律诗","c":["岭南岭北岁频烦，知有先人素业存。","偶著茶经唐处士，别分藜火汉王孙。","同心千里能回驾，病足三秋未出门。","空荷瑶华枉相祝，白头衰谢更何言。"]},{"t":"送王虹友归太仓","f":"七言律诗","c":["病中才一望容辉，岂谓残年便送归。","作客只今多白眼，旧家何处问黄扉。","岭头诗卷梅花瘦，吴下扁舟木叶稀。","天路雁行飞已尽，羡君唯守钓鱼矶。"]},{"t":"送王紫诠使君观察川南兼以为寿","f":"五言古诗","c":["箕尾出东隅，牛斗在其侧。","如何分野内，燕越殊南北。","与君隔万里，衰晚始相识。","鸿飞与虬潜，事异中心得。","君才具匡济，少小富学殖。","方壮已为郎，纂修曾借职。","雍容著作场，出入东西掖。","禄养逮高年，公馀事登陟。","家近盘山阳，子春有遗洫。","青鞋结两耳，健足生八翼。","一线天门开，三潭龙雾黑。","长啸踏烟萝，高吟呵鬼蜮。","虎穴亦偶眠，僧厨频寄食。","越险倍骁腾，耽奇忘偪仄。","细写北岳真，传之子卿墨。","九重有眷命，五马来南国。","始至合江楼，溪山似能忆。","丰鳄涤胸怀，罗浮在封域。","时当废弛后，万绪纷如织。","公事有期程，案牍常充塞。","然膏继落晷，伏枕思嘉则。","频年滋汗漫，一旦皆修饰。","驱车四百峰，聊以适吾适。","维时建子月，落木飞淅沥。","野烧断复明，溪声浅犹激。","南中冬向暖，雪下俄盈尺。","煮茗斫层冰，题诗坐孤石。","韵窄语有神，杯寒酒无力。","夜宿就禅衣，朝行共山屐。","兹山信奇秘，抱朴初来宅。","近揖鲍使君，远招浮丘伯。","三十二代仙，并注长生籍。","家老野人黄，孙子真人白。","相示有新铭，至理符玄易。","遂造飞云巅，夜半光赫赫。","初日上空濛，重昏顿昭晰。","建亭名子日，用示丹砂的。","至后一阳生，夜气中宵觌。","大道本目前，世人自沉溺。","真机一似握，百感无不寂。","坦步任穷通，直心以行德。","见义勇于为，与民共休息。","宏才旋气化，远略销奸慝。","干旌孑四郊，羔裘丝五緎。","湖桥时命舫，郡阁频留客。","风流古有人，文采今谁敌。","席门寄穷巷，往往劳熊轼。","唱和靡不同，篇章渐盈百。","吾生丘壑志，赖以遣晨夕。","内顾何所长，诸郎谬求益。","去岁雨为灾，及秋更其剧。","野吏古亭西，书斋寸苔积。","一跌出不虞，右股几成躄。","师资谅非据，造物来深责。","卧疾十馀旬，至今犹怵惕。","送君川之南，远想萦肝膈。","洞庭四际天，巫峡双悬壁。","扁舟溯浩渺，百丈行荆棘。","白帝古高城，竹王旧疆域。","仍当度泸水，葛相曾于役。","使节此经临，所向皆名迹。","边陲况少事，行迈多馀隙。","妙笔发幽妍，闲心恣摹画。","文章自千古，物色增高格。","西蜀宦游人，杜陆为巨擘。","花溪与剑南，鼎足看今昔。","弱冠事远游，中岁聊停策。","河汉一沿洄，衡庐常艺植。","裹足太行西，北睇徒踧踖。","峨嵋心所往，拟得同探索。","药石更精奇，仙灵留采摘。","兔丝下有苓，乌头小为荝。","绝壑长空青，方流饶水碧。","老态未龙钟，馀生况鸡肋。","去志乃勃然，儿曹阻行色。","今晨届弧矢，几日移旌戟。","四座称万年，下民歌九罭。","语别在须臾，重期莫能测。","各为南北人，复作东西隔。","人生感知己，握手殊悯默。","何以赠仁言，高明尚柔克。"]},{"t":"寄佘杞亭广文乞康州何首乌","f":"七言律诗","c":["作传曾闻李习之，农经百草未尝知。","成纹自蹙如山势，引蔓能交入夜枝。","五岭诸州康最好，一筐相惠赤尤宜。","年来病足资奇效，不为霜髯变黑丝。"]},{"t":"佘齐枢先生有曾孙之庆过其园亭题诗志喜","f":"七言律诗","c":["苍松翠竹五峰西，百福偏于晚节齐。","四叶孙枝花始见，三重堂构燕双栖。","诗成先许诸郎和，酒熟堪酬好鸟啼。","最好石桥门外路，入城潮水绿盈溪。"]},{"t":"与潘子登佘兼五有中元宿云阁之约以暑极不能久偕梁巨川卢俊斯放舟先归却柬潘佘二子","f":"七言律诗","c":["山夹深江入海涛，扁舟来往未云劳。","新松倚岸疑阴浅，短杖随身怯路高。","塔顶千灯明昨夜，天中孤月待吾曹。","却缘惮暑参差甚，虚阁谁飞白兔毫。"]},{"t":"送王叔琬季如奉川南使君命送家之宜兴时立安自都门奉太翁南来将至","f":"七言律诗","c":["西行路远北归贫，百口分为去住身。","阳羡寄家初僦屋，粤江移棹暂违新。","清秋正熟黄花酒，紫气应来白发人。","到日华筵开四代，德星今在太湖滨。"]},{"t":"乙亥生日归锦岩先祠许伯玉乔梓载酒相饷同潘子登梁巨川卢俊斯集饮即事","f":"七言律诗","c":["老矣犹堪斗百篇，生初长记在亲前。","黄花又值三三月，白首今逾八八年。","古岫石林元壁立，新祠风木尚萧然。","劳君载酒能相饷，且为停杯一问天。"]},{"t":"读梁高士寒塘辞世诗次韵哭之二首 其一","f":"七言律诗","c":["绝无沾滞绝根尘，肤发完归与两亲。","蝴蝶梦中醒睡客，白莲花里去来身。","天边星已占方朔，谷口名犹说子真。","不恨夜台多好友，西山薇蕨渐无人。"]},{"t":"读梁高士寒塘辞世诗次韵哭之二首 其二","f":"七言律诗","c":["寂寞空斋闭竹门，寒塘西畔暗云屯。","心从灰后仍馀热，水到穷时自得源。","作传敢辞朋友责，遗经深幸子孙存。","朱明丹火西樵月，照尔千秋处士魂。"]},{"t":"家务铉载酒移菊过耋符菊篱同虚斋巨川俊斯诸子共酌次日复同诸子过虚斋西山赏菊醉后即事","f":"七言律诗","c":["昨宵载酒人携菊，今夕扶筇客就花。","斯世有谁称隐逸，此身连日在云霞。","言寻西岭无多路，不觉东篱属两家。","霜蟹秋英堪尽醉，归时新月落窗纱。"]},{"t":"为大严禅人母比丘尼六十寿","f":"七言绝句","c":["四十年前识若翁，闻歌桃叶比花红。","而今老作城东母，亲见如来十指中。"]},{"t":"谢何宗鼐惠鹤","f":"七言律诗","c":["胎禽驯久不知龄，移赠山池适性灵。","引吭独鸣高顶赤，侧身徐步老拳青。","曾依处士能迎客，欲拟幽人别筑亭。","仙峤翱翔他日事，朝来临水自梳翎。"]},{"t":"过梁殿一殿章山园三首 其一","f":"七言绝句","c":["百寻藤蔓老龙形，千岁松根下有苓。","峭壁尚粘霜叶赤，一峰分入几楼青。"]},{"t":"过梁殿一殿章山园三首 其二","f":"七言绝句","c":["怪石参差筑作台，冰纹疏密上阶苔。","请君亭畔时删竹，城外山光要入来。"]},{"t":"过梁殿一殿章山园三首 其三","f":"七言绝句","c":["五峰相望水回环，翠色林香杳霭间。","怪得过君皆大醉，主人家住是中山。"]},{"t":"梁叠石广文奉节母冯夫人还自琼南喜作","f":"古风","c":["长林欲静风不息，谁家母子俱头白。","闻君奉母海外还，使我悠然生喜色。","君家有母世所无，生年二十鸾镜孤。","呱呱黄口始匍匐，高堂尚有翁与姑。","况经丧乱兼寇贼，绸缪牖户多艰虞。","孝养能成义能教，俾君卓立恢弘图。","海潮之东朱厓北，虎皮高坐为师儒。","板舆迎母就官舍，薄禄聊作反哺乌。","母为喜慰开一笑，苍天不负吾区区。","解簪脱珥置学产，琼人勒石婺山隅。","春秋献祝皆俎豆，自兹庙食终不渝。","五十年来冰雪操，三千里外舟车途。","鲸波鹏浪往复返，鬼神呵护良非诬。","瑶池青鸟会献果，丹山小凤还将雏。","有司褒异表节行，闾里传述为楷模。","呜呼，君家有母世所无，人间宁得此丈夫。"]},{"t":"药亭入峡有月亲高峡烧星夹远江灯之句索予同赋别后出峡目睹其妙因为继作","f":"五言律诗","c":["摇飏孤舫夕，欸乃片帆兴。","野烧难分月，江星不碍灯。","添衣听戍鼓，把酒念良朋。","自判中流袂，吟诗久未能。"]},{"t":"月夜家园小台酌别吴山带","f":"七言律诗","c":["已戒征航香浦间，小台聊共此时闲。","风声自沸阶前茗，月色遥分郭外山。","笑语从容天渐曙，别离南北鬓俱班。","儿孙引领听春信，消息真传一解颜。"]},{"t":"刘汉水六十","f":"七言律诗","c":["离乱相依二十年，老来犹幸返林泉。","旧颜渐皱唯存笑，新句能佳不喜传。","闲按茶经寻水脉，自穿芒屩踏莎田。","往常谓汝生儿晚，五岳今游在目前。"]},{"t":"寄黄问溪八十","f":"七言律诗","c":["寄书南去涉琼波，为讯先生大耋过。","白发剩来曾几许，黄花开日尚能歌。","一竿无意还占虎，大笑何时更坠骡。","我少于君逾一纪，年年中酒病偏多。"]},{"t":"彭艾庵寄水晶眼镜率笔赋谢","f":"五言律诗","c":["水晶为镜好，寄我重兼金。","得此虚明质，如传妙密心。","纤毫无隐尔，少壮忽于今。","万卷荒疏久，从兹更一寻。"]},{"t":"家山农母杨孺人贞烈纪事","f":"古风","c":["儿虽在，夫受累，此身不惜为夫代。","夫既离，儿有依，此身不死将奚归。","璜溪一曲清无滓，白日在天身在水。","浩然正气面如生，怀二之人心尽死。","噫吁嘻，地坼天崩此一时，世间曾得几须眉。"]},{"t":"赠山农二首 其一","f":"七言绝句","c":["旅舍濠西曲巷偏，扁舟来往爱君贤。","亲尝百草归游橐，自写青山不卖钱。"]},{"t":"赠山农二首 其二","f":"七言绝句","c":["死国当年尚有孤，为忠为节义何殊。","白头吟望天南路，老泪相逢各未枯。"]},{"t":"丙子生日归锦岩先祠次去年韵","f":"七言律诗","c":["老作书鱼钻简篇，伤心长是小春前。","祠开梓里才期月，归对篱花已二年。","昧谷日斜难却返，昆池灰冷不重燃。","生前生后何穷事，泪洒西风罔极天。"]},{"t":"冬夜同川南王使君舟泊樵溪骤雨有雷","f":"七言律诗","c":["数载篇章唱和同，将分仍得共游踪。","雷鸣南海初冬夜，月落西樵七十峰。","乍泊且尝他国酒，不眠遥听隔山钟。","芒鞋未怯青泥滑，树杪应添瀑百重。"]},{"t":"寻碧玉洞瀑布同王川南作","f":"五言古诗","c":["昔余寓西樵，兹泉最心赏。","及乎匡庐游，三叠差争长。","各在岭一隅，无由较修广。","夜来歇孤棹，不寐心养养。","肩舆历翠微，旧路多榛莽。","谷深无耕樵，厓欹隔轮鞅。","偪侧不可立，况乃通来往。","旁睨已战兢，下视殊惚恍。","未见瀑布飞，先闻风雨响。","安得趫捷躯，猿猱同下上。","从行数童子，体轻时用罔。","奋身独先下，绝叫咸鼓掌。","使君益兴发，手卓青藤杖。","挟扶有力士，羽翼兼兵仗。","驾肩或并腾，驻足不容两。","更番叠送迎，老脚亦能强。","遂造磐石颠，列坐首皆仰。","白练明高空，银河垂晃朗。","峭壁立如墉，激流更奔放。","横敷半百尺，直下七十丈。","轻风吹馀沫，散作仙翎氅。","云轻玉龙池，珠泻天人帑。","耳目为一新，神形顿萧爽。","维时初冬候，雨潦收田瀼。","壮观虽未殊，浩涆仍非曩。","威凤见一毛，或可得其仿。","慨此万古流，不息同天壤。","谁能探其源，悠然发遐想。"]},{"t":"西樵道中三首 其一","f":"七言绝句","c":["山半云生石作根，古墙薜荔自为村。","儿童处处皆开塾，流水家家总到门。"]},{"t":"西樵道中三首 其二","f":"七言绝句","c":["翳门关路上崚嶒，半坐蓝舆半自登。","老脚尚堪鞭策在，来时忘却日南藤。"]},{"t":"西樵道中三首 其三","f":"七言绝句","c":["硗埆纵横总植茶，平原无土不桑麻。","罗浮四百能如此，富尽循州百万家。"]},{"t":"送赵秋谷之潮州","f":"五言古诗","c":["半月五羊城，紫梅开尚浅。","何以乐新知，青尊共游衍。","良俦唯二三，美酝无沈湎。","时寻广莫野，或命岢峨艑。","古寺搜碑遗，清溪候潮转。","悠然发长啸，倏尔飞雄辩。","归来读君诗，烛下终长卷。","如有神物凭，顿使心目展。","东海与泰山，真形入裁剪。","人言之子傲，我独钦其善。","群惊叶县龙，信有蜀州犬。","性情虽各适，去取良无舛。","倘君非不狂，即我狂难免。","寒冬为此别，宿约诚须践。","昌黎驱鳄地，风教今重阐。","首路指龙川，君家旧疆畎。","怀古一沈吟，新篇会非鲜。","引领望归艎，芳郊及春饯。"]},{"t":"答刘考功省庵","f":"五言古诗","c":["日月本同升，东西异圆缺。","此心有同然，岂必岐秦越。","之子赤帝胄，盛年列簪笏。","驷马来天南，声华振穷发。","使节暇有馀，仙舟停未发。","访我步蓬蒿，招游望溟渤。","寒梅香始飞，野寺钟初歇。","挥觞互献酬，利涉忘津筏。","自惭朽钝姿，所有空皮骨。","壮也不如人，老矣行多蹶。","何以副深期，欲赋情先竭。","煌煌金石篇，风雅相扬淈。","八水得清深，三峰同屹崒。","仍飞白兔毫，出自蛟龙窟。","贻我比琼瑶，光辉到薇蕨。","前旌已戒道，列宿还归阙。","都人咏絷驹，祖席思投辖。","宁知倦客心，一日如三月。","申章报未成，及渴泉方掘。","诚非和氏珍，敢避荆人刖。"]},{"t":"赠樊昆来太史","f":"古风","c":["董狐之后无良史，千古是非成彼此。","诸葛曾蒙入寇名，涑水犹然况馀子。","缅忆当年天柱折，龙蛇起陆坤维裂。","一二孤臣川岭间，泣尽穹苍还继血。","只期不负方寸心，宁知姓氏千秋列。","与君先世有同符，异地殊功元一辙。","淩烟旧画已荒芜，返日雕戈更谁说。","君持史笔入兰台，自有鸿文纪前哲。","所嗟江左及闽滇，十六年中统三绝。","身膏草野几何人，毅魄贞魂总英杰。","非无蹈海葬波涛，亦有高栖守岩穴。","稗官野乘世有之，益部黔南事多缺。","呜呼，天地之立维三纲，斯人之死而不亡。","表往所以劝方将，大书特书吾所望，其副寄我山中藏。"]},{"t":"题把酒问天图","f":"五言绝句","c":["梦梦无醒日，高高独奈何。","酒旗天上有，醉客更应多。"]},{"t":"李广文方水葬于东郊哭之以诗二首 其一","f":"五言律诗","c":["一揖青郊外，从兹隔九原。","及于棺下送，犹胜梦中言。","避地频同旅，移家近对门。","平生期许意，今日更何存。"]},{"t":"李广文方水葬于东郊哭之以诗二首 其二","f":"五言律诗","c":["直谅今谁及，经纶世未知。","禄微为养日，官小作人师。","琼海麻衣返，庐溪素旐驰。","六年长别泪，滴入数行诗。"]},{"t":"戊寅元旦家园漫成","f":"七言律诗","c":["云物春城佳有馀，小台搔首立踟蹰。","百年驹过三分二，一岁人闲正月初。","生态可知霜后树，旧交唯有蠹残书。","东风掩户教儿辈，霄汉新翎看鹤梳。"]},{"t":"锦岩先祠有梅一树春将半犹盛花在粤中为希有与巨川俊斯咏之","f":"七言律诗","c":["桃时杏日各争开，何意林中尚见梅。","密叶已兼青子出，数花如待主人来。","枝横自昔难为咏，头白而今不用催。","应惜和羹才未尽，先公祠下与徘徊。"]},{"t":"外姑湛节母冯太君八十大寿时旌表初至二首 其一","f":"七言律诗","c":["方圆并画古难能，况挽颓晖转日升。","宗祏已新先世庙，佛龛勤礼六时灯。","心空万虑皆如烛，泪尽他年尚作冰。","犹有橐装馀产在，春秋留得与云仍。"]},{"t":"外姑湛节母冯太君八十大寿时旌表初至二首 其二","f":"七言律诗","c":["先公高义人间少，节孝天生梱内才。","再世漂摇为砥柱，百蛮聋俗有惊雷。","西台使者飞霜笔，南国词流祝寿杯。","五十年前皋庑下，白头无复孟光来。"]},{"t":"送林桐叔归石岳","f":"五言律诗","c":["岳势雄诸郡，奇踪閟二樵。","瀑从天属地，潭跨石为桥。","俗朴无今古，厓高失暮朝。","拟同吾子去，深处托鹪鹩。"]},{"t":"题四皓图二首 其一","f":"七言绝句","c":["万峰青处不飞尘，三秀林中日日春。","四老共成诗十句，未知谁是首倡人。"]},{"t":"题四皓图二首 其二","f":"七言绝句","c":["青宫安后汉几危，事在高人合早知。","闻说留侯多秘计，当时别有四须眉。"]},{"t":"题徐虹亭看奕图","f":"五言绝句","c":["大地一楸枰，日月黑白子。","借问看奕人，置身局表里。"]},{"t":"中元前后约过徐虹亭寓斋夜话连阻暴雨比晴则无月矣夜坐赋柬","f":"七言律诗","c":["咫尺相期话月明，几宵频负寺钟鸣。","雷驱星汉迷天路，雨走江湖满郡城。","暑气暗销三伏候，豪吟长和五更声。","晴来已是银蟾缺，击柝重门不易行。"]},{"t":"九日小集风幡堂同姚敦仁梁药亭王蒲衣迟徐虹亭不至分得灯字","f":"七言律诗","c":["茗宴风前快不胜，江城佳节况良朋。","言寻西土千年树，还问南宗第一灯。","金塔绣深微辨字，石幢身老已无棱。","清觞拟待陶公醉，绕径黄花开未能。"]},{"t":"秋帘","f":"五言律诗","c":["袅袅西风里，萧萧倦客途。","香传金凿落，人在酒家胡。","秫亩年方熟，旗星夜未孤。","不知佣作内，还有长卿无。"]},{"t":"秋寺","f":"五言律诗","c":["野日黄方落，溪云白尚飞。","世情何处冷，秋色在禅扉。","钟罢闻蝉语，林疏见鹤归。","老僧三五辈，闲坐补山衣。"]},{"t":"秋灯","f":"五言律诗","c":["朔风犹未入，暑月已全过。","不有青灯对，其如良夜何。","听鸡时独舞，偶影或成歌。","知我应唯尔，人间岂易多。"]},{"t":"秋原","f":"五言律诗","c":["茫茫衰草色，极望与云平。","三壤今犹赋，高原人未耕。","风蓬如轴转，夜烧似龙行。","且喜东南豁，无山月易生。"]},{"t":"秋社","f":"五言律诗","c":["农祥传月令，赛社及秋徂。","树下趋童稚，坛中杂史巫。","雁来排碧落，燕去掠平芜。","宰肉陈孺子，而今作老夫。"]},{"t":"秋屋","f":"五言律诗","c":["骚人摇落意，今古得无同。","未减三时月，唯多四壁风。","砌虫吟蟋蟀，阶叶走梧桐。","天宇何寥廓，谁堪老此中。"]},{"t":"秋渔","f":"五言律诗","c":["乘潮秋渚上，月下一竿横。","自有天堪问，何妨水至清。","龙螭西伯猎，醒醉楚臣行。","亦各为千载，长歌怀濯缨。"]},{"t":"秋瀑","f":"五言律诗","c":["空林何浩浩，石壁有悬泉。","直泻黄姑渚，横飞白帝天。","声从千仞落，风散万珠圆。","莫惜离山浊，西成待满田。"]},{"t":"秋簟","f":"五言律诗","c":["桃笙吴赋重，冰字碧纹连。","静拭丹帷内，凉生玉枕前。","梦魂曾共适，芗泽尚依然。","未可同纨扇，西风一弃捐。"]},{"t":"秋塘","f":"五言律诗","c":["行吟池上影，来去日纷纷。","风岸堆残叶，晴波度片云。","雁行闲可数，鱼跃静偏闻。","春草他时梦，园林秋又分。"]},{"t":"秋戍","f":"五言律诗","c":["汉皇犹自将，率土敢言劳。","共命唯良马，馀生托宝刀。","寝霜秋柝冷，占气夜天高。","未见功成日，还家已二毛。"]},{"t":"秋猎","f":"五言律诗","c":["无事空腾饱，秋田且合围。","鹰盘霜野击，马逆朔风飞。","甲帐毛为雨，归人血点衣。","好凭诛异类，原兽已知威。"]},{"t":"秋菜","f":"五言律诗","c":["荒畦犹有菜，弱架已除瓜。","不少去来蝶，还寻黄白花。","雨馀收落子，霜下卷新芽。","抱瓮劳劳者，于陵是一家。"]},{"t":"秋镜","f":"五言律诗","c":["对镜意茫茫，为躯七尺强。","如何千载下，空让昔人长。","面目吾犹尔，妍媸汝不藏。","因之还自见，敢恨有秋霜。"]},{"t":"秋楼","f":"五言律诗","c":["巍楼雄郭外，虚牖敞云中。","静纳银蟾影，寒生玉马风。","地高秋最早，天迥望何穷。","未得惊人语，终朝忆谢公。"]},{"t":"秋衫","f":"五言律诗","c":["萧萧霜露色，木叶下江皋。","越葛辞团扇，齐纨落剪刀。","晓寻西寺约，老怯北风高。","坐泛黄花酒，还添大布袍。"]},{"t":"秋蝶","f":"五言律诗","c":["凤子文为羽，仙人锦作衿。","有生同物化，而汝独秋深。","不及芳菲日，弥伤迟暮心。","因知漆园叟，所感亦犹今。"]},{"t":"秋烟","f":"五言律诗","c":["秋空不可极，极望转生烟。","日抱游尘外，晴曛晓露前。","微微依静渚，漠漠映遥天。","何处功臣阁，临风一惘然。"]},{"t":"秋琴","f":"五言律诗","c":["金行天地肃，视听此为真。","一对高山奏，如逢太古人。","宣情通万类，解愠及吾民。","杳矣谁知者，冰弦空复陈。"]},{"t":"吴又札七十七举子诗以贺之","f":"五言古诗","c":["周武九十三，诸子皆象勺。","尚父八十馀，有女登椒阁。","家国属当兴，瑞气因回薄。","老蚌毓明珠，枯丛秀花萼。","君德厚且长，琴书久无托。","同人咸注望，熊梦果不错。","于兹近八旬，得震才一索。","揆之昔圣贤，兴符自今作。","足为寿考徵，岂独生儿乐。","不见群飞雏，出自千年鹤。"]},{"t":"送徐虹亭归吴江因柬严藕渔朱竹垞彭羡门潘稼堂","f":"七言古诗","c":["此山甘曳涂中尾，百年抛掷空山里。","知交海内几人存，书札懒来无一纸。","羡君肯作罗浮游，天南重见生狂喜。","青鞋直入四百峰，竹杖身登七十里。","我衰不复能相从，客诵新篇日盈耳。","如何去我将有行，梅花岭上花方始。","君住松陵水一湾，澉浦鸳湖咫尺间。","言归将作白头社，尊酒扁舟时往还。","论交却得朱公叔，作赋安仁鬓仍绿。","垂竿严濑复有人，好古彭■老弥笃。","一回聚首一声诗，洛社香山事可追。","惜无鸿雁双飞翼，浩荡江湖同所之。"]},{"t":"放云","f":"五言律诗","c":["触石看初上，囊盛偶共归。","不堪贻好友，只自掩柴扉。","岁旱人同望，龙灵尔所依。","开轩纷五色，应近日边飞。"]},{"t":"放驴","f":"古风","c":["青脊?驴子，平生能苦辛。","疾行虽后马，远到亦如人。","刍秣岂云薄，衰迟宁久驯。","从今卧春草，饮龁是天真。"]},{"t":"放鹤","f":"五言律诗","c":["放尔为骐骥，仙人与御风。","翮盘三岛外，声落九天中。","远影凝云白，还丹入顶红。","苏耽遗井在，不必语辽东。"]},{"t":"放鹰","f":"五言律诗","c":["北斗摇光散，西风健翮高。","顺天行搏击，报德用贪饕。","世每求虞网，吾惟解臂绦。","桐柯方待凤，无处立而曹。"]},{"t":"放牛","f":"五言律诗","c":["幸免为牺用，未将文绣加。","青留函谷树，白转法王车。","长角终何取，花蹄不足誇。","小童吹短笛，归老老农家。"]},{"t":"放猿","f":"五言律诗","c":["岂忍相羁久，哀吟损性灵。","自然千载物，生有老人形。","引臂山泉白，攀藤月峡青。","何年成剑术，毛发已星星。"]},{"t":"放萤","f":"五言律诗","c":["数点来中夜，低飞近客床。","灯疏无复焰，星乱不成行。","岂以干霄气，而依腐草光。","林根须早去，屋上有新霜。"]},{"t":"放蝶","f":"五言律诗","c":["抱茧初观化，笼纱为尔开。","好寻花底去，或许梦中来。","五彩难为画，双飞不用媒。","罗浮原有洞，葛鲍御风回。"]},{"t":"放鸭","f":"五言律诗","c":["畜此非吾意，浮沈看尔曹。","赋形虚羽翼，天性善波涛。","江色辽阳绿，军声雪夜高。","因人书史册，未必在奇毛。"]},{"t":"放鱼","f":"五言律诗","c":["升斗皆能活，人间迩杀机。","急流窥进退，浊水羡甘肥。","尔向江湖去，谁施网罟威。","神鳞多变化，岂必尽成飞。"]},{"t":"题梁枳山笏斋","f":"五言律诗","c":["差胜梁鸿庑，鹪鹩有此枝。","花唯栽一树，井日汲三时。","起舞鸡飞桀，行吟户碍眉。","暇中常教子，墙外亦闻诗。"]},{"t":"至日遥和梁药亭夜集之作同用东韵","f":"七言律诗","c":["子半阳生羲画中，此心遥与故人同。","日添一线行将北，月到三更上自东。","茗熟未销文武火，梅开不厌往来风。","草堂各有吟诗客，白发萧萧两老翁。"]},{"t":"小除后同廖南炜梁药亭王蒲衣王也夔秦钦文暨各家子弟集东林啸公方丈重修社事分得能字","f":"七言律诗","c":["柳眼朝来已渐增，小桥流水不曾冰。","百年短褐冲残腊，半日闲身对定僧。","疏磬出林风断续，寒云依岫晚崚嶒。","渊明未得陶然醉，即事成诗似未能。"]},{"t":"小禺三集新篁次吴大司马","f":"五言律诗","c":["汗青犹可俟，荏苒夕阳西。","高节含新箨，清风满旧溪。","扫阶林影薄，拂水翠云低。","会入伶人采，凭添乐府题。"]},{"t":"听莺次吴大司马","f":"五言律诗","c":["芳郊行竟日，莺语不曾无。","物色春将老，离声鸟亦殊。","绪风吹近远，交影入烟芜。","未免萦怀抱，衰颜赖酒扶。"]},{"t":"赠李立斋总戎","f":"七言律诗","c":["作镇炎方万里清，风流儒将早知名。","骅骝日永嘶长路，鼓角秋高满郡城。","旧向词坛称绣虎，曾从沧海射长鲸。","盛年才擅兼资美，麟阁遥开待勒铭。"]},{"t":"送郑子源之香山二首 其一","f":"七言绝句","c":["上林桃子洛阳梨，更向增城问荔支。","海内知君行欲遍，卷中多有故人诗。"]},{"t":"送郑子源之香山二首 其二","f":"七言绝句","c":["荔枝花事未曾阑，作赋相如客倍闲。","好去临邛寻令尹，横琴山在海中间。"]},{"t":"龚雨亭都谏挽诗","f":"七言律诗","c":["乞归连岁尚踟躇，得请旋为得疾初。","杜甫久闻焚谏草，所忠无复问遗书。","倚闾落日悲黄发，过岭秋猿泣素车。","卧病江干不能吊，生刍一咏倍愁予。"]},{"t":"蒋雨亭主政来粤拜其先祖父祠部参政公遗爱祠还日奉赠二首 其一","f":"七言律诗","c":["何期旌旆到茅庐，十载秦中一纸书。","方报循良徵北阙，却从休沐理南车。","两旬旅寓青春浅，三世论交白发馀。","酹酒先公祠下土，于门高大信非虚。"]},{"t":"蒋雨亭主政来粤拜其先祖父祠部参政公遗爱祠还日奉赠二首 其二","f":"七言律诗","c":["大江中隔岭头梅，世泽偏深在粤台。","山甫缵戎今再见，相如乘驷此重来。","土风并是童时习，人士多于祭日陪。","握别津亭思往事，万民争送使星回。"]},{"t":"题山带画为张宗肃","f":"七言绝句","c":["野桥枯石水磷磷，几叠苍松似小春。","恰好赠归词客手，竹边添个撚须人。"]},{"t":"送袁密山归平乐三首 其一","f":"七言绝句","c":["东来言送故人轺，一岁维舟得此朝。","同是挂帆分两地，西行人迩北人遥。"]},{"t":"送袁密山归平乐三首 其二","f":"七言绝句","c":["年来敛尽旧锋棱，寓客门前冷似冰。","住久不知君是客，雪山如对坐禅僧。"]},{"t":"送袁密山归平乐三首 其三","f":"七言绝句","c":["桂江山水极雕锼，奇峭参天带急流。","便欲束装从此去，唱酬三月共扁舟。"]},{"t":"题萧叔兼行乐","f":"七言绝句","c":["草际相呼立渚禽，茅堂萧寂不须深。","图书左右堪怡悦，脱屣浮云物外心。"]},{"t":"题吴山带潇湘三峡图送王紫诠使君之川南","f":"古风","c":["君不见双流江汉岷山来，潇湘九面衡岳开。","大别山前神禹凿，长江东走如轰雷。","荆梁万派此奔汇，溯流千里其艰哉。","君持旌节川南路，一年理棹今方赴。","涉尽人间翻覆澜，瞿塘滟滪宁堪顾。","吴生放笔为此图，神光离合超有无。","气吞云梦者八九，笔挟造化为前驱。","数峰便具万仞势，片帆直指蚕丛都。","巴东三峡定远近，耳边似听猿猱呼。","鱼腹八阵日在眼，峨眉古雪明高衢。","锦水文章多哲匠，司马杨王最其上。","千篇更有浣花翁，两表犹传卧龙相。","羡君此去得其源，继美千秋岂多让。","即今吴生已入燕，送行反在君行先。","君行向西伊向北，我独南滞朱明天。","人生聚散寻常事，所惜诗篇远难致。","作歌送君并索吴，新图分寄西南隅。"]},{"t":"梁聘妻黎贞女诗","f":"七言律诗","c":["天上修文帝阙深，人间琴瑟不成音。","素车白马来何事，大节宏纲力自任。","同穴有期归下土，双栖无梦到高林。","生前未识郎君面，不隔幽明是此心。"]},{"t":"走笔送梁台佐赴粤西幕府二首 其一","f":"七言绝句","c":["书记翩翩昔所闻，牂牁西去许从军。","封侯本是书生事，铜柱高标在岭云。"]},{"t":"走笔送梁台佐赴粤西幕府二首 其二","f":"七言绝句","c":["草堂过别语悬河，侠士肝肠世未多。","前路有人能问我，一竿头白对藤蓑。"]},{"t":"贺梁药亭新翁","f":"七言律诗","c":["七十巅毛未见丝，百龄五岳岂云迟。","阿巢老凤双栖日，斗气津龙始合时。","玉树连行枝并发，牙签万轴架新移。","豪吟亦是东山事，安石从来自教儿。"]},{"t":"题佟子小影","f":"七言绝句","c":["郁郁长松谡谡风，一囊更自抱丝桐。","知音岂患人间少，流水高山在目中。"]},{"t":"题陈子行乐","f":"七言绝句","c":["珠玉为心貌亦如，谢家芝草满阶除。","少陵一语堪为赠，年少今开万卷书。"]},{"t":"题潘子小影","f":"七言绝句","c":["柳底清阴竹叶杯，诸峰遥入座中来。","人生乐事无过此，满径黄花对酒开。"]},{"t":"献李提军奠原三首 其一","f":"七言律诗","c":["仙李盘根代有贤，将军名氏榜先传。","官登八座今三世，禄自先朝几百年。","岭海喜过千里足，日车新拜六龙鞭。","安壤一借长城略，沧海南边得晏眠。"]},{"t":"献李提军奠原三首 其二","f":"七言律诗","c":["万乘旌旗狩朔边，国威还藉重臣宣。","金鞍久侍龙颜侧，玉食颁从黼帐前。","每见借筹论战伐，时闻聚米指山川。","一辞丹陛来南服，御札黄封几度传。"]},{"t":"献李提军奠原三首 其三","f":"七言律诗","c":["画角风清静海涛，郊坰共喜见干旄。","金方气肃崆峒壮，南斗功成日月高。","姬旦吐哺元自贵，卫青揖客不言劳。","天涯贱子能扪虱，怀剌空惭有二毛。"]},{"t":"送林赤见北上兼柬吴山带","f":"七言律诗","c":["乡园篱菊已将阑，马上梅花北去寒。","岂谓少年须早达，只缘微禄好承欢。","水荒畿辅今闻熟，堤溃河淮合渐乾。","到日更寻年谱旧，东风同向杏林看。"]},{"t":"送刘虚舟孝廉北上柬史耕岩学士","f":"七言律诗","c":["东去京华总及春，青袍如旧榜名新。","诗篇好诵词流口，先泽犹存帝里民。","禄阁分灯元汉裔，黄梅传钵自江滨。","溧阳学士闻声久，曾向人前问野人。"]},{"t":"潘母陈太君挽诗","f":"七言律诗","c":["日暮谁能不倚闾，夫人贤哲古无如。","介山隐日曾承命，江左行时未绝裾。","老去每闻加饭报，病中犹寄缓归书。","天涯孙子分南北，恸哭寒原走素车。"]},{"t":"送詹仙洲莫百川北上","f":"七言律诗","c":["数点寒梅渐报春，岭头北去雪花新。","丰城并跃双龙剑，燕市同游两酒人。","道有屈伸权在命，文无今古诀唯真。","只须了却经生事，一第何常可救贫。"]},{"t":"寄俞介石别驾","f":"七言律诗","c":["使君生有梅花约，庾岭罗浮屡剖符。","水部诗中频共赏，美人林下未应无。","一枝春色聊堪寄，两地香风总不殊。","欲挂片帆冬日下，三枫亭畔对冰壶。"]},{"t":"题周耐庵匡庐托钵图","f":"七言绝句","c":["诗人标格老僧装，大地无非选佛场。","最是匡庐宜乞食，虎溪前去是柴桑。"]},{"t":"赵秋谷自潮州至即归其乡诗以送之","f":"七言律诗","c":["春来望尔海东头，及到翻成送去舟。","岭路过时梅未摽，乡园归日麦应秋。","地留胜迹供高咏，天放闲身作远游。","九土芒芒行已半，后期相对又何州。"]},{"t":"送樊简讨昆来还都","f":"七言律诗","c":["论文连月得相亲，握别临期意倍真。","高盖南来持节客，二毛憔悴种瓜人。","羽林旧籍同声在，桃李新阴异代春。","书报高堂江汉上，为言沧海有遗民。"]},{"t":"送刘静庵","f":"七言律诗","c":["贵竹千峰骥足开，岭头五马久徘徊。","渐看南国棠阴遍，却喜东风鹢首催。","汉武求贤期绝域，燕昭来士有高台。","定知此去多奇遇，谁得如君八面才。"]},{"t":"题忆雪楼江山无尽图送紫诠王使君之官川南次留别原韵 其一","f":"七言古诗","c":["东坡手书默化堂，不知堂后山泽藏。","使君冷眼忽觑得，架楼收尽天苍苍。","楼基正与城头敌，窗外远见风帆扬。","我来舣舟此城下，楼花飞落船头香。","宾朋共识庾亮兴，小民窃比燕公棠。","前轩后户卷帘幕，良宵胜日传杯觞。","云峰四起若邻并，蒸炎三伏来清凉。","北窗企脚望不极，千叠万叠皆山光。","象头白水古佛迹，朱明七洞仙人乡。","虹蜺隐见占雨至，烟岚出入因风狂。","聚如稠人互窥瞷，纷如舞袖相低卬。","天池鹏翼击巨浪，斗间剑气明干将。","云阴穿漏或显晦，松声断续流清商。","不知汉晋是何代，陶铸尧舜其秕糠。","常拟腰镰刈葵藿，每思寄梦炊黄粱。","登临万象极富有，忘却四壁和雕墙。","使君家在燕冀北，思亲恋阙皆同方。","霞生想像斑斓彩，屏列如对黼扆张。","归心欲蹑双飞燕，省稼时乘五色羊。","擢巡西蜀忽留滞，万事险阻皆经尝。","回思楼上昔坐啸，明月直入无猜防。","欲舂灵药问顾兔，拟摘桂蕊呼吴刚。","安知俗态工贝锦，遂使仕路成羊肠。","赖君雅志在吟咏，南中久驻无嗟伤。","溪山四远皆游陟，图书万轴增丹黄。","集名忆雪三百首，隋珠卞玉森成行。","气齐五岳争耸峭，才如海若奔汪洋。","或于谐谑寓规讽，时同星日舒光铓。","浣花老洁可企及，剑南平易应来降。","此行所遇多古意，笔仗况复俱精良。","图形尽归大禹鼎，切玉不啻昆吾钢。","孤舟三峡上百丈，七年大郡宜轻装。","西听猿啼易寂寞，北念鹤发增徊徨。","连天别绪语不尽，数日解缆仍嫌忙。","膝前侍列子若弟，特达不异圭与璋。"]},{"t":"题忆雪楼江山无尽图送紫诠王使君之官川南次留别原韵 其二","f":"七言古诗","c":["移家暂寓虎踞石，门巷复见乌衣王。","雏凤长鸣协钟吕，宏音亮节皆琅琅。","东西各驾青雀舫，山水收以古锦囊。","巫山之高不可极，长江之水难为量。","悬帆今月已春暮，计程到日应秋阳。","送君不妨屡水宿，几人同卧舟中床。","问年我已逾耳顺，将髭君亦添新霜。","九州宇宙本窄狭，后期未可云渺茫。","将寻幽约指吴越，更揽宿莽过沅湘。","待君旌节自蜀出，玺书惠下云天长。","新篇不厌读数回，老脚尚可同趋跄。","且题此卷作后验，恍如身复当楼窗。","迷濛远近翠欲滴，不辨扬越并燕梁。","高歌激昂以赠我，平生意兴因飞翔。","安得如鸟有羽翼，从君唱和逾三泷。"]},{"t":"走笔送程德基归黄山兼怀其弟立方","f":"七言律诗","c":["一编圮下尚深藏，爱写仙人肘后方。","朱邸每因游宴入，白头仍为著书忙。","徘徊五岭谁为伍，归去黄山菊正黄。","介弟到来今十载，报书应讶懒嵇康。"]},{"t":"柬吴拔庵元戎","f":"七言律诗","c":["菊时曾得奉金钟，竹里相寻惜未逢。","新句近知添俊逸，归心还望许从容。","城开百粤三千里，峡束长江数百峰。","大树清阴人共望，白头休谢酒泉封。"]},{"t":"送李竹君广文之官香山","f":"七言律诗","c":["半日风帆到有馀，江城原亦是山居。","似过别墅之邻邑，却借闲官读父书。","李下蹊成垂荫远，莲峰秋好着花初。","交君三世今头白，重见南溟化巨鱼。"]},{"t":"送顾瑞长司教澄迈","f":"七言律诗","c":["去岁龙门点额回，鱼笺寄我报难裁。","尚悬白璧连城价，今见珠厓绛帐开。","海国晴空标五指，郡山回首望三台。","天池自是鲲鹏地，看尔抟风击浪才。"]},{"t":"送吕载蕃归山阴","f":"七言律诗","c":["风木萧萧满若耶，暑中遥泛独归槎。","东山卧挹千岩秀，南国新留几县花。","血泪自沾慈母线，黄扉人识相臣家。","白头相送浑忘老，计日还迎驷马车。"]},{"t":"海珠寺谒李忠简公祠追次先府君韵二首 其一","f":"七言律诗","c":["谁移古寺到波心，往哲遗踪竟至今。","珠号摩尼从佛得，江浮明月正东吟。","一丘偃盖情何远，半壁河山泽尚深。","四百馀年存俎豆，清风犹自满双林。"]},{"t":"海珠寺谒李忠简公祠追次先府君韵二首 其二","f":"七言律诗","c":["百年能立即千春，不朽天南代有人。","痛哭书生曾伏阙，出师丞相亦纶巾。","遗篇在卷难为和，往事伤心莫可陈。","文献比来凋落尽，馀光今幸借西邻。"]},{"t":"赋送顾禹二首 其一","f":"七言绝句","c":["新秋岭外好回车，水湛长江落木初。","已啖离支三百颗，钓竿须鲙四腮鱼。"]},{"t":"赋送顾禹二首 其二","f":"七言绝句","c":["二毛一变作霜巅，不听吴歌四十年。","君到山塘秋已半，千人石上月依然。"]},{"t":"口占送家木月","f":"五言律诗","c":["久客将归日，新秋暂泊船。","别离良不易，须鬓各苍然。","乡酒鲈登市，边风雁在天。","家庭多乐事，莫忘尺书传。"]},{"t":"送学使王十州复命","f":"七言律诗","c":["梧桐一叶报秋生，霜节随君恰到京。","五岭诞敷文德地，九重亲贺圣功成。","帆开别浦旌旗色，身拜彤墀佩玉声。","莫谓使星从此远，即看卿月万方明。"]},{"t":"题笪瀛仙行乐","f":"古风","c":["风度萧然尘表，姓名隐著图间。","谓是竹中高士，何殊海外仙山。"]},{"t":"寄贺蔡萃长之官昌邑","f":"七言律诗","c":["搏风羽翮久翱翔，新绾铜符近海疆。","善交尚存平仲里，著书人识郑公乡。","天边仙岛三山见，涧下清流万岁长。","况是京华来去路，嘉声容易到维桑。"]},{"t":"围猎图为王云庵题二首 其一","f":"七言绝句","c":["万辔群飞走玉骢，数枝鸣镝响雕弓。","高堂益壮三军气，四壁如吹大野风。"]},{"t":"围猎图为王云庵题二首 其二","f":"七言绝句","c":["平沙围猎合还开，踪指何常不用才。","自是将军亲阅历，谁人绘得阵图来。"]},{"t":"贺广州冯使君二首 其一","f":"七言律诗","c":["天怀高旷世谁如，却为酬知更剖符。","北阙除书来五岭，东风游兴尚三吴。","新添诗卷传人口，旧管黔黎候旅途。","家有傅岩先命在，暂将霖雨到南隅。"]},{"t":"贺广州冯使君二首 其二","f":"七言律诗","c":["南北犹悭相见缘，仁声先自异方传。","棠阴未剪灵山下，骥足曾开禹穴前。","莘野有勋仍相陟，韦侯世守亦承贤。","今时盛事宁殊古，白首宁忘野史编。"]},{"t":"口占送向恬庵","f":"七言绝句","c":["归舟暂泊五羊城，一揖相辞万里行。","竟夜吟诗不成句，新鸿飞过两三声。"]},{"t":"送蔡汉长之官泷西二首 其一","f":"七言律诗","c":["吾侪何必叹离居，一札新传最起予。","南北异邦为政处，弟兄同日拜恩初。","邑当海徼方游刃，地僻山中好著书。","泷水东流三百里，君诗容易到乡闾。"]},{"t":"送蔡汉长之官泷西二首 其二","f":"七言律诗","c":["干将雄气迥难干，莫谓师儒是素餐。","骐骥取途须待饱，蛟龙为雨贵能蟠。","百年况味尝应遍，万里曾行眼亦宽。","入道久知无别诀，半安随处总安安。"]},{"t":"为王云庵题知止轩 其一","f":"七言绝句","c":["急流勇退复何人，知止空闻老氏言。","岂似圣经知至善，修齐事业盖乾坤。"]},{"t":"为王云庵题知止轩 其二","f":"七言绝句","c":["陶公止酒偶然歌，止观天台又若何。","知止知君深得力，平生志本不求多。"]},{"t":"运心轩","f":"七言绝句","c":["相生奇正本无穷，制胜全资整暇功。","一矢雍容升揖地，甲兵千万在胸中。"]},{"t":"哲思轩","f":"七言绝句","c":["哲人邈矣复何思，道德文章总我师。","夜寐夙兴勤所事，保身唯咏仲山诗。"]},{"t":"澹恬堂","f":"七言绝句","c":["上弦新月蔼清晖，恬澹无营世所希。","绿竹黄花秋正好，一觞遥唱鹤南飞。"]},{"t":"九日喜家紫驭至","f":"七言律诗","c":["短歌言别昔何时，尘路茫茫久系思。","一第相期君不负，十年重见我尤衰。","雁来天外新成阵，菊试篱边未满枝。","南海荒残今更甚，高车从此又何之。"]},{"t":"题丁勖庵秋江垂钓图","f":"七言绝句","c":["百年舒卷岂难期，七尺渔竿一钓丝。","不择水清鱼少处，秋江端可鉴须眉。"]},{"t":"送卢达夫之任邵阳","f":"七言律诗","c":["湖南清绝古来称，君莅南梁第一城。","雪色千重催去骑，梅花一路引行旌。","归猿峒外生徒送，回雁峰前候吏迎。","到日龙池高处望，县山先有故乡名。"]},{"t":"呈左学使我庵","f":"七言律诗","c":["文风一变此南隅，十郡生徒仰大儒。","海内声华推二妙，卷中词赋继三都。","青天手放惊人鸟，明月全收不夜珠。","谁道盛明持节日，门前修剌有潜夫。"]},{"t":"送人入夔州二首 其一","f":"七言绝句","c":["欲折梅花寄一枝，送君犹觉挂帆迟。","巫山巫峡三千里，春雪春风是到时。"]},{"t":"送人入夔州二首 其二","f":"七言律诗","c":["书札频归识远情，别来两度见秋生。","旌旗西入巴人国，锁钥东临白帝城。","三尺青萍占夜气，一篇黄石是家声。","盛年功伐寻常事，好勒麒麟阁上名。"]},{"t":"赠宜新宁逊庵","f":"七言律诗","c":["百里仁声满郡中，家门奕叶有重封。","勋名汉代推三杰，兄弟高阳号八龙。","纪竹已书天上史，栽花新遍海头峰。","识韩有愿非今日，穷巷车声未易逢。"]},{"t":"送卢卜子之官延平","f":"七言律诗","c":["溪山雄丽绝闽天，记得曾游四十年。","万户水声分涧竹，一方城影落江船。","参军自昔多闲日，趋府今时得大贤。","知子此行将有合，剑津只在郡门前。"]},{"t":"繻葛程符氏殉节挽歌","f":"七言绝句","c":["请代何能格上天，千秋同穴志元坚。","馀生枉作仪髦赋，一死当君属纩前。"]},{"t":"送詹意友之潮阳扶其父祖旅榇还闽二首 其一","f":"七言绝句","c":["两世遗骸涨海边，首丘唯赖子孙贤。","客来岭外三千里，泪滴棺前十二年。"]},{"t":"送詹意友之潮阳扶其父祖旅榇还闽二首 其二","f":"七言绝句","c":["水木根源有此身，十年泉路不知春。","看君近泪无乾土，自有连舟解赠人。"]},{"t":"送王令诒赴都补官","f":"七言古诗","c":["老不出门行蹩躠，只是年年送人别。","白髭一别几茎生，老笔难工反成拙。","犹记去年春酒开，君驰驷马从西来。","四方朋好日高会，玉笙银管宵中催。","是时君有潘州役，所至葱葱若遗迹。","今年相送入罗浮，已谢为邦作嘉客。","丰鳄湖边山绕城，著书仍是旧经生。","封章却自天曹下，车马还从帝里行。","珠江八月炎威解，数幅蒲帆向风挂。","路迥唯凭叶县凫，舟轻欲笑坳堂芥。","往时朋旧各分飞，赋别江头老布衣。","虽乏骊珠佐行色，犹当洗耳待金徽。"]},{"t":"贺家植普进士","f":"七言律诗","c":["妫水渊源代有文，江门家学更逢君。","长风破浪时千里，大翼翀天见五云。","昼锦正宜孺子舞，新篇超绝众人群。","玉堂有客相期甚，书札南来慰我闻。"]},{"t":"送李检讨伯猷二首 其一","f":"七言律诗","c":["程江归到正秋新，便挂轻帆北问津。","子舍暂违衣彩地，玉堂还作读书人。","游经万里文增壮，史在千秋笔贵真。","岭海迩来寥落甚，相期风度继先民。"]},{"t":"送李检讨伯猷二首 其二","f":"七言律诗","c":["都门遥奉白头归，四叶承欢世所希。","诗礼庭前时独对，鹡鸰原上更双飞。","年来多黍香醪美，秋在澄溪鲙鲤肥。","供膳有人行自得，报恩唯补衮龙衣。"]},{"t":"赠张翁源泰亭","f":"七言律诗","c":["七叶金貂代有雄，西铭家学绍无穷。","奇文早已传天上，黄绶新垂出汉宫。","邑近曲江唐相度，地连韶石舜弦风。","期君手播灵池水，仁寿同依乐国中。"]},{"t":"送李丽侯司教化州","f":"七言律诗","c":["绛帐新移溟海头，之官尤喜及清秋。","仙山家近传仙李，化雨飞时又化州。","出箧篇章珠径寸，趋庭诗礼雪盈头。","知君四世承欢在，不羡京华作宦游。"]},{"t":"送何叶文入都","f":"七言律诗","c":["独骑匹马向燕台，便是闲游亦壮哉。","中路诗情生白雪，一年归计及黄槐。","都人尚系渐离筑，上客难逢郭隗才。","纵有知音在霄汉，高堂屈指待君回。"]},{"t":"送佘振西梁凝掞入都","f":"七言律诗","c":["凤城裘马自轻肥，少俊今时似子希。","诗礼庭中推二妙，扶摇风里羡皆飞。","南辞庾峤桐初下，北到金台雁始归。","好及弱龄承祖武，老亲犹着老莱衣。"]},{"t":"欣赏斋见吴山带画","f":"七言绝句","c":["欣赏斋中赏不希，故人遗墨一沾衣。","双凫出浴翎犹湿，高柳摇风絮尚飞。"]},{"t":"赠李植公行乐图二首 其一","f":"七言绝句","c":["碧栏干外敞云屏，一簇笙箫在水亭。","传语佳人诵新句，李郎停笔酒初醒。"]},{"t":"赠李植公行乐图二首 其二","f":"七言绝句","c":["桥西新水縠文生，洞府神仙境最清。","一炷名香烟未散，梧桐深有下棋声。"]},{"t":"赠家天池","f":"古风","c":["昔君十五青青衿，姿颜如玉能鼓琴。","再三祈请一挥手，四座宾客皆倾心。","尊君虬须古侠客，坐拥楼船通绝域。","我从海外一见之，及到君堂始相识。","酣歌永啸乐未终，其如世事犹汹汹。","君挽长弓射白雁，身骑大马能追风。","珊瑚合挂渔人网，姓名忽列鹰扬榜。","北台买骏尚悬金，西郭栽花还自赏。","蹉跎五十鬓未霜，有子能诗与父长。","看君不复愁衰老，惟忧无以答苍苍。","去年荐饥民最苦，四郊就赈愁风雨。","君募蓬茅数十区，瘠子愁妻各其所。","荒原或有不归魂，掩之以棺埋以土。","吁嗟乎，使君食禄就一官，职守所拘宁有补。","不如逍遥落拓作闲人，足使饥嬴有宁宇。"]},{"t":"题钮高明玉樵行乐图二首 其一","f":"七言绝句","c":["名在循良世莫如，天南凫舄到方初。","传来诗句工尤甚，闲倚栏干未废书。"]},{"t":"题钮高明玉樵行乐图二首 其二","f":"七言绝句","c":["家于笠泽接香溪，何地堪樵亦偶题。","一令山城最深处，西樵七十二峰西。"]},{"t":"驾高郡丞摄番禺","f":"五言古诗","c":["葭管动飞灰，梅花处处开。","寒轻沧海上，春自一阳回。","霁色明雄郡，欢声满越台。","双凫仙令地，五马使君来。","莅政垂三绶，兼人备四才。","剖符虽叠叠，游刃更恢恢。","好尚从宽猛，风云待化裁。","看公经纬略，计日列三台。"]},{"t":"题赠闵萃庵","f":"五言绝句","c":["闵子大隐流，其性何澹荡。","不知十八滩，何如古汶上。"]},{"t":"送佟恩平赴都补官","f":"七言律诗","c":["仁声十载遍炎陬，春草生时共献酬。","车盖更飞何处雨，风帆今到海门秋。","多收端石经年凿，偶听吴歌永夕留。","满载奇书充箧笥，未教人识是虚舟。"]},{"t":"次答朱颖实","f":"七言律诗","c":["家集年来遍粤洲，因君弥复景前修。","孤忠有后今三世，一面相期隔几秋。","吴粤云山非异地，纪群夙昔许同游。","未缘披豁闻高论，诗句多为第一流。"]},{"t":"别罗雄州水裕","f":"七言律诗","c":["梅花岭上一麾偏，南北清风二十年。","执法如山人可近，守身如玉道能坚。","摊书未歇挑灯夜，读礼曾无闭户钱。","寂寞茅斋期再遇，暂时相送上江船。"]},{"t":"次答丁勖庵","f":"七言律诗","c":["震泽南边一硕儒，西风相见此城隅。","奇书自识常三箧，重器人称是六瑚。","古笔淋漓今作者，壮怀萧瑟老吾徒。","十旬不雨心如醉，无计留君酒不觚。"]},{"t":"刘沛叔真赞二首 其一","f":"七言绝句","c":["双江战血染朱轮，五十年前即此身。","剩有箪瓢归陋巷，不劳名姓上麒麟。"]},{"t":"刘沛叔真赞二首 其二","f":"七言绝句","c":["须眉不觉尽为霜，尚借戎装作道装。","肘后未曾离组绶，斗酒犹自现干将。"]},{"t":"题静像善琴","f":"七言绝句","c":["一卷慵开独坐吟，不冠不袜坐松阴。","天涯何患无知者，流水高山共此心。"]},{"t":"寿张方伯枢侯二首 其一","f":"七言律诗","c":["金貂七叶向来传，身列崇班尚少年。","白简有风存北阙，紫薇新泽满南天。","树人岁育三千士，赈米朝糜百万钱。","犹说报恩怀未尽，欲将心力更筹边。"]},{"t":"寿张方伯枢侯二首 其二","f":"七言律诗","c":["无成六十鬓萧萧，折柬空劳使者招。","古寺疏钟陪永日，清斋长烛语良宵。","野人且可论三祝，倦鸟何堪问九霄。","愧乏嘉言供采择，平生踪迹是刍荛。"]},{"t":"送陈郡侯飏言","f":"七言律诗","c":["宝玉从来号此乡，臣心如水照穹苍。","政闲只有围棋客，官罢兼无养鹤粮。","颍守到时神爵集，陶公归日菊花黄。","翳桑不少重生者，泣送江边几万行。"]},{"t":"送沈丹山入都补御史","f":"七言律诗","c":["博洽家声有自来，帝廷曾叹沈郎才。","六年一令风雩地，万里重登市骏台。","鲁雉亲人朝尚集，鲍骢行步日方开。","朝端引领瞻霜简，鹢首西风好为催。"]},{"t":"送霍友山省觐春州","f":"七言律诗","c":["舟入卢溪秋已分，西风吹叶落纷纷。","清波倚棹人如玉，中路看山石似云。","衣彩每同昆弟舞，学诗兼与及门闻。","春州引望崆峒近，鸣和天边鹤一群。"]},{"t":"次答宗人育璞","f":"七言律诗","c":["衡山西下洞庭东，泪竹斑斑万古同。","曾记狂歌荆国日，早将身拜舜皇宫。","采芝且免忧高盖，结柳何堪送五穷。","知子共为妫水后，此心相喻不言中。"]},{"t":"题黄君球行乐二首 其一","f":"七言绝句","c":["一树浓阴号大椿，白头仍是彩衣身。","秋来太史占乾象，南极星中几老人。"]},{"t":"题黄君球行乐二首 其二","f":"七言绝句","c":["百年世禄焕纶丝，身隐新朝志未衰。","姓氏下邳桥上客，一篇仍似授书时。"]},{"t":"冬日承屈四会凤山见过别后柬寄","f":"七言律诗","c":["短褐苍凉曝早暄，北风吹叶满平原。","素丝忽望干旄色，白发空惭负郭门。","一顾骅骝增壮气，片时酬酢奉高言。","珠江浈水无多路，雪里邮诗敢惮烦。"]},{"t":"次答董汉竹二首 其一","f":"五言律诗","c":["白头逢世好，佳句使人惊。","往事思先甲，流年阅后庚。","老馀家国泪，交见死生情。","借问张平子，何时赋二京。"]},{"t":"次答董汉竹二首 其二","f":"五言律诗","c":["游踪同雪爪，世语半兰奢。","各述先人旧，弥增两鬓华。","夙兴君不忝，身外我何加。","愧乏江都笔，名山勒一家。"]},{"t":"寄答马卧仙都阃","f":"七言古诗","c":["秋日枉诗今未报，窗外梅花开正闹。","君麾日驻海头城，我老犹思雪中棹。","横琴山外晓风清，万里沧茫见日生。","高标铜柱千年在，犹见君家旧勒铭。","君流膏泽周遐邑，已饥已溺常汲汲。","如何歌颂满天南，终日思归时伫立。","思亲翘首望云飞，更许轻骑到小扉。","贫家客至无多地，已命山童拂钓矶。"]},{"t":"立春日送黄蒲园谒选都门","f":"七言律诗","c":["初年车马发河干，椒酒犹馀膝下欢。","岂为荣亲须就禄，却缘行志在能官。","迎春彩仗舟前出，新绿江山雪下看。","京国旧多交好在，云司吟和共登坛。"]},{"t":"立春日送徐艺初御史归吴门","f":"七言律诗","c":["东风此别未惊魂，绛仗迎春骑吹繁。","几处早花明水郭，一帆新绿去江村。","每因声气思畴曩，愿得雍容接晤言。","骢马暂留知不可，六龙巡狩正南辕。"]},{"t":"寄王阮亭总宪","f":"五言古诗","c":["煌煌太微廷，执法列其右。","夜来视星文，光荣殊昔有。","闻君掌兰台，北向遥沥酒。","知己非独欢，苍生望来久。","平生恬澹志，中立无所苟。","在德固罔愆，于言良不朽。","由来风纪地，所尚非绳纠。","但令源本端，足使民俗厚。","君家自青齐，先世属台斗。","赓飏明盛日，廓落经纶手。","继起今有人，联飞自相友。","看花岁最先，劲柏凋弥后。","人称独坐三，位冠群乡九。","泥涂吾曳尾，霄汉君骧首。","颇忆十年前，春宵同剪韭。"]},{"t":"次答吴彤本","f":"七言律诗","c":["老凤巢边和鹤鸣，别来无念不萦萦。","水从庾岭分南北，书寄扬州隔死生。","歆向文章元继美，纪群先后见交情。","不缘步屧能相过，门径东风长绿荆。"]},{"t":"陶奉长以大父仲调简讨文集见贻且请作传次其来韵二首 其一","f":"七言律诗","c":["才既无双数亦奇，高鸿难慕羽堪仪。","长沙旧是陶公族，遗集重开晋义熙。","良璞不售多在楚，灵珠无价本名隋。","虽惭司马藏山笔，此志争光自可推。"]},{"t":"陶奉长以大父仲调简讨文集见贻且请作传次其来韵二首 其二","f":"七言律诗","c":["此身终隐复何名，应候哀吟自物情。","本为诗书延一脉，偶从锋镝得馀生。","沈埋我愧干霄气，继好君寻异代盟。","正拟深谈逢积雨，把诗枯坐到三更。"]},{"t":"次答刘百原二首 其一","f":"七言律诗","c":["九面湘流绕岳斜，更乘山屐过丹霞。","谁分太乙仙人火，来问长贫孺子家。","南土柔条先着柳，东风新律正飞葭。","自怜黄发同摩诘，三径荒芜对五车。"]},{"t":"次答刘百原二首 其二","f":"七言律诗","c":["浮湘昔日有知音，昨得清篇竟夕吟。","便续楚些齐旷代，更于兰臭见同心。","雁回万里衡阳峻，海到三春岛屿深。","我老愧无娱客地，一尊何以豁烦襟。"]},{"t":"寄寿何慎思邑侯","f":"五言古诗","c":["沧海起飞鸿，黄鹂语晓风。","山光城外内，水碧县西东。","胜事张灯复，良宵聚酺同。","三时闲节序，百戏走农工。","羔酒公庭献，金章彩服通。","韶华官柳绿，嘉燕烛花红。","永誉神明宰，遐龄鹤发翁。","大慈堪范俗，善事即移忠。","汉柱名方重，邭苗雨正融。","部人歌令德，矫首咏高崧。"]},{"t":"韶阳战绩诗为闫将军赋二首 其一","f":"七言绝句","c":["百战功高贼始摧，九成台下陈云开。","天南父老犹能说，作赋郎君只自哀。"]},{"t":"韶阳战绩诗为闫将军赋二首 其二","f":"七言绝句","c":["韶石芙蓉几百峰，石如甲胄是军容。","直须青简传千载，早有丹心彻九重。"]},{"t":"题行乐图二首 其一","f":"七言绝句","c":["拍手阶前稚子嬉，南园春色柳丝丝。","郎君修洁人如玉，触目琳琅乐可知。"]},{"t":"题行乐图二首 其二","f":"七言绝句","c":["此日能闲即是仙，湘帘高卷竹风前。","诸童笑语还相和，一部元音胜管弦。"]},{"t":"走笔送家云石二首 其一","f":"七言绝句","c":["南天积雨乱红飞，岭北山川绿尚希。","莫恋长安为客乐，驷车须念过桥归。"]},{"t":"走笔送家云石二首 其二","f":"七言绝句","c":["竹杖扶行拥敝袍，衰龄稀出岂云高。","有人问我门前雪，雪在袁安两鬓毛。"]},{"t":"寄祝张翁源泰亭二首 其一","f":"七言律诗","c":["鸿名宿昔著关中，凫舄今飞到粤东。","孝友世传张仲在，文章人羡景阳工。","九成乐奏高台月，百里花开昨日风。","题柱盛名何以颂，早将霖雨慰宸衷。"]},{"t":"寄祝张翁源泰亭二首 其二","f":"七言律诗","c":["衰颓久矣绝逢迎，卜得山居却带城。","方讶里中惊驷马，岂知门外驻干旌。","雄谈入座师资见，玉树临风意气生。","多谢文章枉相属，江淹才尽老无成。"]},{"t":"沂泽得杖名以珊瑚索赋","f":"五言律诗","c":["瑚瑚洲上叟，有杖号珊瑚。","谁此琼华赠，如分若木株。","坚贞人可比，夭矫画难摹。","老脚今能健，登山不用扶。"]},{"t":"送姚非渔选入国学二首 其一","f":"七言律诗","c":["赵尉楼边百草芳，黄金台畔柳初黄。","遥携四百峰头月，还就三千弟子行。","上国骅骝争道路，六堂风雨盛文章。","看君珥笔彤墀内，不为槐花更着忙。"]},{"t":"送姚非渔选入国学二首 其二","f":"七言律诗","c":["风流文采本翩翩，万里新行正少年。","鹏海片帆轻似翼，鹤峰春浪远干天。","国门定有悬金览，家学先传述德篇。","若问阿翁膏泽地，九华如黛大江边。"]},{"t":"清明日同霍禹洲家大斌舟入高峡泊阅江楼下即事作","f":"七言律诗","c":["东风乘兴好西行，三月牂牁水尚清。","峡上篙痕穿石细，楼前山色极天横。","花当令节千枝放，酒酹长江百感生。","五十年前龙见处，白头重说与诸卿。"]},{"t":"同禹洲大斌游七星岩作","f":"七言律诗","c":["沥湖西北石桥隈，七十年中几度来。","隔水似迷蓬岛路，际天惟见墨云堆。","神驱海岳星辰落，穴走蛟龙洞府开。","今昔登临人屡换，与君终日暂徘徊。"]},{"t":"宝月台有作","f":"七言律诗","c":["高台宝月旧庄严，胜概登临得尽兼。","积水有涛环四面，数峰如画入重檐。","传衣人远空馀树，铸鼎龙遥久坠髯。","世外世间何限恨，愧无新赋拟江淹。"]},{"t":"锦岩西庵同又札巨川俊斯汝侯","f":"五言律诗","c":["西庵清绝处，一榻可栖禅。","石占闲房地，云过峭壁天。","只疑居邃谷，岂似在郊廛。","不待诸天供，千花红欲燃。"]},{"t":"寿霍朝望司谕","f":"七言律诗","c":["清斋遥隔故园波，大耋今时鬓未皤。","东海有澜文壮阔，南山为祝寿嵯峨。","宫墙数仞门庭峻，桃李重阴子舍多。","再世论交吾亦老，赠君惟有一高歌。"]},{"t":"题纳凉图送吴石仓归西湖次其卷中元韵二首 其一","f":"五言律诗","c":["风柳高亭上，诸贤共一僧。","暑同河朔避，兴似剡溪乘。","乐事唯飞管，群书且架藤。","一时儒与佛，谁得判淄渑。"]},{"t":"题纳凉图送吴石仓归西湖次其卷中元韵二首 其二","f":"五言律诗","c":["归梦悬湖水，经年度庾关。","千篇新著作，一卷旧家山。","自子为羁旅，谁人醉此间。","荷花香有待，挂席暑中还。"]},{"t":"石仓抄其乡沈旬华处士所作先司马及家文忠张文烈诸传见示再次前韵以谢其意","f":"五言律诗","c":["先传劳抄示，他年史所关。","文虽传处士，藏且在名山。","笔足参三立，人堪并两间。","无能酬厚意，珠泪赠君还。"]},{"t":"仁和周氏节孝诗","f":"古风","c":["谁言母有夫，有夫中道归黄垆。","谁言子有母，有母生儿身不久。","母亡有母能抚孤，夫亡教子成室家。","母之报夫在教子，子能事生即事死。","呜呼，节孝萃一门，我欲歌之难为言。"]},{"t":"左母太君寿诗","f":"七言律诗","c":["翟茀霞帔绰有荣，当年曾是庆长庚。","耄期尚授周公礼，令子今题汉柱名。","畿内颂声歌寿母，堂前称兕有门生。","家园自足含饴乐，不要孙曾捧杖行。"]},{"t":"高母夫人寿","f":"七言律诗","c":["鸾冠翟茀映虹霓，母德今时孰与齐。","新泽近周炎海外，门功曾建楚台西。","三春桃实成嘉燕，千里名驹展骏蹄。","身是慈云敷不极，伫为霖雨慰蒸黎。"]},{"t":"题山带遗画为郑珠江","f":"七言绝句","c":["石边丛菊晚香深，澹墨淋漓惜似金。","自是故人先有意，报君一片岁寒心。"]},{"t":"次答欧上闲","f":"七言律诗","c":["饱闻风义十年前，赣广封疆幸接联。","山有枝条原一本，溪流南北遂相悬。","霜蹄自合驰天路，白发唯堪守墓田。","故友云亡高弟在，指薪传火古今燃。"]},{"t":"送吴汉公之都门","f":"七言律诗","c":["都门归到正秋生，半载游踪未暂停。","子舍始过梅子雨，枝间犹惜荔枝青。","薰风挂席三千里，驿路题诗八百亭。","江北江南须着眼，六龙巡幸昨曾经。"]},{"t":"送秦番禺子芳","f":"七言律诗","c":["龙角山高绛水清，循良真不愧家声。","六年莅政人无讟，一旦言归泪满城。","别浦有香流泽远，随身唯鹤去舟轻。","白头闭户蓬蒿里，何日重瞻孑孑旌。"]},{"t":"题鲁思亭小影","f":"五言律诗","c":["画里人殊少，知名十许年。","两行薇省树，一卷白华篇。","芒屩聊为尔，苔阶坐悄然。","凝思在佳句，不谬世间传。"]},{"t":"送秦钦文二首 其一","f":"五言律诗","c":["作此无期别，其如我老何。","云山三晋远，朋好五羊多。","羽翮宜轩翥，圭璋在琢磨。","年年来去雁，莫忘系书过。"]},{"t":"送秦钦文二首 其二","f":"五言律诗","c":["敢曰人伦鉴，居然国士风。","超庭来杜甫，清论得王戎。","学继河汾上，诗多越岭东。","妙龄今若此，惭愧白头翁。"]},{"t":"李裔衮寿","f":"七言律诗","c":["大隐高风世所知，须眉奕奕有仙姿。","五千道德传家学，三百唐宗是本支。","寿偶如宾偕白首，诸郎佩印作人师。","一堂盛事如何颂，仙李盘根杜老诗。"]},{"t":"次韵送吴玉涛","f":"七言律诗","c":["散吏能为汗漫游，苇床书舫日乘流。","溯洄珠海沉香浦，吟望朱明大石楼。","政有弛张唯尚德，文兼华实总成秋。","归来一赋人皆惜，不独吾侪有别愁。"]},{"t":"寄许伯玉","f":"七言律诗","c":["文章先代是宗工，君有无双国士风。","百战功多沧海外，一官身老岭云东。","越庭诗礼皆能学，爱客壶觞不说穷。","凤峤松阴石湖月，至今人想许中戎。"]},{"t":"方作寄潘紫登诗而其书适至即事柬之","f":"七言律诗","c":["握别东风柳始黄，榴花今已满山堂。","正当念汝遗双鲤，恰好来书到五羊。","远道常时通梦寐，把诗终日对琳琅。","自怜白首论交久，独有斯人具肺肠。"]},{"t":"送家恭尚","f":"七言律诗","c":["羚羊峡里共高歌，秋月春风几度过。","策蹇偶寻铜柱路，探骊曾涉海门波。","帆樯又作经时别，杯酒其如易醉何。","犹是塞鸿飞到处，天涯莫厌寄书多。"]},{"t":"先始祖祠宇改建初成承宗戚诸公赐祭卒赋一律志谢","f":"七言律诗","c":["事远难铭魏氏钟，手栽犹见大夫松。","未离故寝成新庙，且喜开门对一峰。","顾我垣墉书阔略，劳君升降礼雍容。","先朝遗俗吾乡在，厚意深惭报莫从。"]},{"t":"刘仰山招同吴玉涛梁药亭家宕侯雨中泛舟半塘迟沈虹石不至同用八庚二首 其一","f":"五言律诗","c":["急雨无朝暮，篙师不敢行。","人为长夏会，天与片时晴。","洲渚烟中市，云山画里城。","几年离别绪，都向酒杯倾。"]},{"t":"刘仰山招同吴玉涛梁药亭家宕侯雨中泛舟半塘迟沈虹石不至同用八庚二首 其二","f":"五言律诗","c":["曲港乘潮入，轻舟与岸平。","村童惊客语，江鹤避棋声。","柳浪家家似，荷珠叶叶并。","所思期不至，八咏且同赓。"]},{"t":"朱玉树以画梅见贻赋谢","f":"七言绝句","c":["玉堂仙子玉髯髭，老笔能飞屈铁枝。","正是雪消明月落，罗浮山下梦醒时。"]},{"t":"晤杨春州止庵于五羊翌日拜良酝之惠赋此奉谢","f":"七言律诗","c":["快瞻风度从今日，得读文章已十年。","赵尉台边怀古地，崆峒岩下早秋天。","凫飞霄汉来容易，邑有神君望俨然。","一席高谈人已醉，醇醪贻我意兼传。"]},{"t":"夏杪杨宝生孝廉招同毛行九司马杨止庵大令梁药亭太史饮于风幡堂次行九韵二首 其一","f":"五言律诗","c":["古树馀千载，劳生又半年。","闲寻白社约，得醉绿阴边。","蝉试迎秋噪，庭分欲暮烟。","是间宜野酌，何必肆长筵。"]},{"t":"夏杪杨宝生孝廉招同毛行九司马杨止庵大令梁药亭太史饮于风幡堂次行九韵二首 其二","f":"五言律诗","c":["吴越同星纪，登临具上才。","一时萍迹合，千里雁行来。","幡影留飞刹，池光照举杯。","白头希乐事，今日老怀开。"]},{"t":"过邹左俞园林","f":"七言律诗","c":["了无纷杂绝纤埃，有此园林倚粤台。","高柳夹门行径永，小桥横水画堂开。","坐疑古洞迷秦晋，日见渔舟自去来。","况是主人髯未白，官闲时得扫苍苔。"]},{"t":"沈左臣惠墨竹赋柬五首 其一","f":"七言绝句","c":["一天烟霭何方雨，满径簩□昨夜风。","中有高人呼不出，早莺飞处月朣朣。"]},{"t":"沈左臣惠墨竹赋柬五首 其二","f":"七言绝句","c":["数竿浓淡复纵横，静对萧萧似有声。","若使伶伦知采伐，不妨吹作凤凰鸣。"]},{"t":"沈左臣惠墨竹赋柬五首 其三","f":"七言绝句","c":["老干欹斜折复萌，小枝还作怒龙形。","等闲自写淩霜节，不待他人纪汗青。"]},{"t":"沈左臣惠墨竹赋柬五首 其四","f":"七言绝句","c":["大笔如椽势莫当，节间一丈末如芒。","君家越志分明载，月落空庭影未长。"]},{"t":"沈左臣惠墨竹赋柬五首 其五","f":"七言绝句","c":["酷暑经时只掩扉，劳君贻赠有苔矶。","萧然四壁如常日，袅袅西风叶自飞。"]},{"t":"次答张损持太史二首 其一","f":"七言律诗","c":["蓬蒿三径谢芳荪，轩盖何期枉见存。","忆鲙几时归海上，吹箫曾记到吴门。","斗牛剑合元同气，南北潮生各异痕。","犹有一人知己在，五羊城下旧虞园。"]},{"t":"次答张损持太史二首 其二","f":"七言律诗","c":["名成仍复爱三馀，香水溪边更结庐。","养疾旧承天子诏，传家元有老人书。","游多胜赏频高会，世诵新篇满比闾。","山月渐凉清露下，小园秋草欲教除。"]},{"t":"闰七月二日长寿石公招同毛匏村司马张损持吉士吴晋涛少尹杨勉庵孝廉唐海门黄兰偶司红暹诸文学雅集离六堂次毛韵二首 其一","f":"七言律诗","c":["十二栏干砌碧瑜，四周流水入萦纡。","似登海蜃烟中阁，同探骊龙颔下珠。","吴越提封馀一览，人天境界岂云殊。","巡檐渐有凉风入，觅句徐行得自娱。"]},{"t":"闰七月二日长寿石公招同毛匏村司马张损持吉士吴晋涛少尹杨勉庵孝廉唐海门黄兰偶司红暹诸文学雅集离六堂次毛韵二首 其二","f":"七言律诗","c":["开社东林事已频，曾将妙偈伏龙神。","多金布地来殊国，古木含风不记春。","暑后溪山初过雨，闰馀鳷鹊再临津。","赋诗此日多豪俊，莫笑衰颓白发人。"]},{"t":"闰七夕后一日远公招同潘稼堂张损持梁药亭毛行九余未及赴诸公分韵见及得心字","f":"五言古诗","c":["四序遒以迫，天宇皛且深。","出郊睇平畴，上有嘉树林。","萧萧风乍劲，萋萋岁已阴。","初秋属馀闰，徂暑方流金。","驾言梵王宫，阒寂期幽寻。","相招有开士，散带遗冠簪。","登楼俯逝川，推窗纳遥岑。","稍歇人外磬，复闻花中琴。","追随昔已屡，违隔忽在今。","空斋散文史，席地聊歌吟。","岂惜车马劳，苦为尘累侵。","群公不遐弃，往往遗之音。","其清若冰雪，有美如璆琳。","谁言一日游，逖矣千载心。"]},{"t":"题张损持太史行乐图","f":"五言古诗","c":["跏趺秋树根，悠然静馀想。","本为著作人，具此幽遐赏。","十年卧沧洲，髭须渐云长。","不以三事荣，易我一日养。","苍生望正殷，林泉聊独往。","新篇岁峥嵘，旧闻入罗网。","高风激颓波，苔石皆萧爽。","五弦何必挥，瀑流有清响。"]},{"t":"初秋日梁药亭招同沈詹山大令家山农隐君潘稼堂检讨张损持吉士毛行九司马吴晋涛少尹林桐叔少府杨勉斋孝廉徐紫凝罗浮山司红暹家献孟诸文学远布心月二上人雅集六瑩堂分得阡字","f":"古风","c":["君不见素馨田，行人采摘成术阡。","又不见菖蒲涧，仙人服食今无传。","世间不贵长生学，只爱花香耳目前。","吹笙击鼓日纵饮，笑杀吾侪无酒钱。","药洲南边杜门者，今日忽然罗众筵。","相邀尽是文章客，吴山越水多英贤。","盈阶况复美花竹，梧桐一叶初秋天。","火云烧空尚炎赫，江湖白浪高于船。","千里命车良不易，兼旬何意成流连。","西郊北郭多古寺，菜根茗碗同枯禅。","长吟短句屡酬酢，千钟百榼无闻焉。","主人家酝号玄碧，奇方得自安期仙。","饮酣棋罢各授简，鸲鹆大砚青松烟。","倾玉盏，拂华笺，劝君大醉方谋篇。","良俦嘉会不尽兴，异日相思年复年。"]},{"t":"次和梁叠石发塾诗","f":"五言律诗","c":["所爱宁容易，慈言况共持。","发肤原一体，长短几千丝。","塔与卢能并，峰连婺女奇。","谁怜头顶上，霜雪已垂垂。"]},{"t":"口占送徐紫凝三首 其一","f":"七言绝句","c":["挂帆江上试新凉，纤月依微带夕阳。","想见孤山风落木，梦魂无夜不家乡。"]},{"t":"口占送徐紫凝三首 其二","f":"七言绝句","c":["每逢岐路一沾巾，五岭东西几度春。","游子本为归养计，故山无复倚闾人。"]},{"t":"口占送徐紫凝三首 其三","f":"七言绝句","c":["怀吴正忆浮瓜侯，访戴还须棹雪舟。","君见二君烦致语，白头难复到杭州。"]},{"t":"赠沈詹山","f":"七言律诗","c":["一尺长髭已皓然，目如岩电古稀年。","南中久住丹砂令，海外曾归玉局仙。","老骥未忘歌伏枥，高鸿何必志摩天。","时来渐有西风入，好读磻溪卜猎篇。"]},{"t":"呈冯太守","f":"七言律诗","c":["得依仁政已三年，曾奉高谈接绮筵。","五马清风珠海上，满轮明月桂花前。","今时地望谁能及，往日诗篇世共传。","家有傅岩三命在，即看霖雨到中天。"]},{"t":"赠云在青","f":"七言律诗","c":["忙中常自领闲机，须鬓年来白渐希。","过客不时停玉勒，高窗长日抚金徽。","清池映竹留青霭，怪石当门挂薜衣。","秋好正宜将寿酒，即看庭下凤雏飞。"]},{"t":"赠黎普济","f":"七言绝句","c":["慈心到处有奇方，苦海逢君便得航。","世上疮痍非一日，分身须是上岩廊。"]},{"t":"送高少府","f":"七言律诗","c":["板舆遥向帝都回，远送于南彩鹢开。","秋月上弦沧海外，西风行部峡山来。","雁行比翼排霄汉，菊蕊延年入寿杯。","白首狂歌杜陵老，题诗唯羡达夫才。"]},{"t":"重阳前五日高中含司马招同刘卓崖主考屈四会凤山张广宁鹤洲杨阳春止庵钱茂名蔗山张翁源泰亭高东莞菉园田英德克五雅集云半阁时闱事初竣","f":"七言律诗","c":["使车高盖总能来，云里轩窗俯粤台。","秋水满前人自照，碧天无际雁初回。","酒边赤叶迎风醉，阁后黄花傍节开。","白首疏狂虚授简，愧无诗句可追陪。"]},{"t":"寄潘涵观","f":"七言律诗","c":["三年别日未云多，甲子于君忽再过。","白发到来皆若此，青山归计近如何。","久无薇蕨留孤竹，剩有松楸废蓼莪。","只隔岭梅南北路，一枝相寄且为歌。"]},{"t":"生生图送家山农归云间","f":"七言律诗","c":["扁舟归去岭梅初，久住天南绰有誉。","慈幼近开三亩宅，活人曾著十年书。","竹篱透石冬抽笋，池水通潮昼跃鱼。","不敢相留唯有愿，到秋遥望再来车。"]},{"t":"己卯八月十四日五羊城南联句同毛端士司红暹梁药亭张损持同拈十三职韵","f":"古风","c":["地胜秋亦佳，人间醉常得。","深帘却花影，欹槛上苔色。","凉云淡不飞，白日光稍匿。","是时月几望，平分景未昃。","天空肃万象，霄迥联千翼。","过水划明沙，排阊觐炎国。","江城霸气散，海甸瘴烟熄。","舟通珊瑚宫，星定女牛域。","黄屋竟何在，青袍此相即。","同游皆妙选，抽思尽奇特。","挥洒衍波笺，淋漓客卿墨。","长驱役今古，清辩洗雕饰。","几案杂古欢，杯盘列珍食。","酒?罗浮春，果擘诃梨勒。","客身翻夺主，南风竞淩北。","豪吟卷宿雾，深坐催宵刻。","风战矮檐梧，漏侵园院棘。","规月欠微痕，清辉渺无极。","林栖鸟忽惊，穴处鲛犹织。","大地漫金波，虚府敞琼阈。","露冷吴刚斧，飙驶纤阿轼。","桂华一以睹，蓬梗嗟未息。","昨泛海珠滨，频过花田侧。","千门连睥睨，万顷泻胸臆。","浩荡鸥难驯，凄清蛩更唧。","雄剑倚芙蓉，枯禅寄薝卜。","各抱千载心，宁亏九鼎力。","高洁慕蝉饮，龌龊笑鸡肋。","履道任夷惠，得句惊藉湜。","良会永弗忘，先民念遗则。"]},{"t":"题吴山带墨竹送吴晋涛归宜兴二首 其一","f":"七言绝句","c":["故人笔墨醉方工，数叶垂垂亦不同。","画里只今成旧雨，画溪归去是春风。"]},{"t":"题吴山带墨竹送吴晋涛归宜兴二首 其二","f":"七言绝句","c":["别意何如纸上禽，一飞一宿本同林。","凭君折取伶伦管，吹作阳和睍睆音。"]},{"t":"得王立安讣音哭之三首 其一","f":"七言律诗","c":["把书终日恨难平，叹息修文召已成。","督亢陂前新宅兆，罗浮峰下旧师生。","三年已罢升堂瑟，万里难伸自牖情。","爱汝是翁知是我，只应南北各沾缨。"]},{"t":"得王立安讣音哭之三首 其二","f":"七言律诗","c":["朗吟终日捋虬须，七尺昂藏好丈夫。","五字号城真莫敌，百春为咏只须臾。","行虽越众偏能恕，文不求名只自娱。","忆雪楼前风雨散，不堪扶杖过丰湖。"]},{"t":"得王立安讣音哭之三首 其三","f":"七言律诗","c":["金丹炼就谁人识，玉树埋来恨有馀。","几日已为黄壤客，昨朝犹见白门书。","家悬两地星霜久，膝绕诸郎象勺初。","末后数言殊了了，前身应得悟真如。"]},{"t":"题吴山带墨菊为潘受平","f":"七言绝句","c":["清姿妙笔已难期，身后珍如玉树枝。","最是棱棱霜下菊，赠君不少故人思。"]},{"t":"寄题家健夫西峰草堂","f":"七言律诗","c":["不同吟醉几经冬，燕雁频频过越封。","老去未曾忘北路，人来多是说西峰。","诗情日与年华长，酒债全教笔砚供。","特遣儿曹识堂径，天涯痴叔也如侬。"]},{"t":"励儿北上口占示之二首 其一","f":"五言律诗","c":["吾衰良已甚，汝往慎前途。","一骑过河岳，扁舟下楚吴。","眼中新白雪，梦里古皇都。","最是英贤会，同声自不孤。"]},{"t":"励儿北上口占示之二首 其二","f":"五言律诗","c":["文章先世业，用舍百年身。","送尔无他语，思为不朽人。","旧山丛桂老，去路杏花春。","倘谢经生籍，韦编正好陈。"]},{"t":"励儿行后连有南风漫成","f":"七言绝句","c":["江边别汝意怦怦，十日南风为送行。","风度有楼今在否，计程应到曲江城。"]},{"t":"赠李弥朴","f":"七言律诗","c":["曾称祭酒老儒门，邻曲过从岁独尊。","派自有唐三百祀，家传苦县五千言。","诗书善述斯为达，宗祏能修赖有孙。","紫阁玉泉多胜地，百龄期尔醉乡园。"]},{"t":"正月三日过潘子登所寓江楼龚渭臣载酒与潘木公诸君雅集赋潮平两岸阔分得涯字","f":"七言律诗","c":["千樯不动水涟漪，共上江楼好赋诗。","尘世百龄希暇日，沧波开岁是闲时。","渐铺浦溆平如练，益觉乾坤未有涯。","破浪抟风年少事，白头唯有一衔卮。"]},{"t":"次韵答龚渭臣","f":"七言律诗","c":["七十馀生渐有涯，长绳何计系奔曦。","犹能鼓枻沧浪外，不厌逢君唱和迟。","海鸟化来知大翼，须眉渐觉愧男儿。","东风共醉屠苏酒，俯仰江楼极二仪。"]},{"t":"正月六日将归锦岩泊舟潘子登寓楼下新月甚佳因留宿三日两登斯楼亦一快也","f":"七言律诗","c":["偶尔停舟快不胜，江楼今夕又同登。","故园归去逢人日，新月何期对好朋。","竹榻朗吟茶宴罢，低窗高掩浪纹升。","频年衰疾希行往，如此良宵得未曾。"]},{"t":"羽都督殉节诗","f":"七言律诗","c":["金方为教本坚刚，受命先朝卫五羊。","生死只知城下士，姓名不惮羽林郎。","血流大地终成碧，骨化飞尘久亦香。","世禄几家能矢报，为君歌此问苍苍。"]},{"t":"寄何慎思顺德二首 其一","f":"五言律诗","c":["新年频不值，舟楫各西东。","夜月同江上，春灯忆县中。","潮生环郭绿，彩舞间花红。","请以无疆兕，因君献若翁。"]},{"t":"寄何慎思顺德二首 其二","f":"五言律诗","c":["东风开万堞，身坐百花间。","大邑人希暇，平心政自闲。","寝兴承白发，厅事对青山。","并报君亲重，恩酬鬓未斑。"]},{"t":"送汤建孟之永明二首 其一","f":"七言绝句","c":["白头游兴亦雄哉，三楚烟花二月开。","九十甘泉曾若此，祝融峰顶去还来。"]},{"t":"送汤建孟之永明二首 其二","f":"七言绝句","c":["永明潜邸万峰前，君见荆榛亦黯然。","不及钟祥龙起地，至今人尚说承天。"]},{"t":"送家昭德之官长宁","f":"七言律诗","c":["片帆春色上循州，二月东江浪尚柔。","薄俸未能离苜蓿，一官重得对罗浮。","峰云佳处同谁赏，桃李蹊前与士游。","倘到东坡亭下泊，老夫还拟共维舟。"]},{"t":"送左襄南督学试竣还都奉命命视河","f":"古风","c":["我闻丹山赤水之洞天，地脉暗与蓬瀛连。","蓬莱一枝乃独往，直到天池鹏化之南边。","倏然乃与罗浮结，七洞四明如隔绝。","宁知共在斗牛间，天上分星总扬越。","四明狂客贺季真，青莲一见号仙人。","知人自有传心法，能使汾阳屈者伸。","唐代功臣独居首，谁知活自书生手。","君今相士特南来，知人肯落前贤后。","天闲新进渥洼多，更命旌旗理九河。","都将吉甫清风颂，和入河渠瓠子歌。","著书七十罗浮老，汗竹为书频削稿。","方候公闲细评论，如何鹢首催前导。","病中相送不成章，口授儿曹写数行。","迟君赐归鉴湖一曲水，来问天台万仞之石梁。"]},{"t":"同王阮亭宫詹黄忍庵太史高谡苑廷评张超然屈翁山两处士五羊访古作三首 其一 菩提树","f":"五言古诗","c":["访古肃宾朋，淩晨命车驾。","嘉树有清阴，风幡古兰若。","擢干耸苍穹，垂枝笼碧瓦。","坛壝石已朽，盘根自相把。","外质何连卷，中空若刳剐。","一体含菀枯，四气无冬夏。","落叶为轻纱，虚明复堪写。","宗风未西来，神物乃跃冶。","托身炎海南，所贵在知寡。","谁为满百人，羡尔千年者。"]},{"t":"同王阮亭宫詹黄忍庵太史高谡苑廷评张超然屈翁山两处士五羊访古作三首 其二 五仙观","f":"五言古诗","c":["高阁闻午钟，石门倏已启。","抠衣蹑层磴，遥与仙人礼。","俯沼濯幽泉，开轩酌琼醴。","轻风自东来，管弦发朱邸。","未觉所历高，城郭忽在底。","群公济时硕，衔命来丹陛。","嘉会匪前期，东西各旌棨。","奇踪辨羊石，妙墨逢苏米。","不谓荒烟馀，名流今济济。","文章系气运，颓波藉中砥。","酒阑问新题，赋诗效何体。"]},{"t":"菖蒲涧","f":"五言古诗","c":["野草绿未稠，东郊春已暮。","农夫荷锄笠，连阴未成雨。","昨约蒲涧行，颇作沾濡惧。","届晨乃开霁，杲日方东吐。","轩骑出城闉，干旌入深树。","登顿古殿旁，偪侧缘溪路。","风泉递清响，竹石通微步。","神仙渺何所，前贤表遗句。","尚忆征战初，经年六师驻。","樵苏落榱桷，高垒隳陵墓。","孤寺独岿然，文章有灵护。","佳辰及兹游，赏心亦云具。","布席榕阴移，飞觞玉醪注。","歌吟杂谐谑，脱略披情愫。","宾主一代才，登高各能赋。","白雪岂曰酬，青云期可附。"]},{"t":"拟行药城东桥","f":"五言古诗","c":["百行皆有营，一暇不易得。","非无出门时，往往为世役。","兹晨服食罢，曳杖信所适。","蔼蔼涉墟莽，悠悠越阡陌。","芳郊属春和，天宇迥昭晰。","川流扬晓晖，林表霁新色。","旷观既以怡，内省寡所斁。","未羡高鸟翔，安用抟风翼。","息意慕华膴，何心厌衰白。","修名匪岁年，寿考岂金石。","至理有恒期，浮生徒自域。"]},{"t":"闭瓮菜","f":"五言古诗","c":["嘉蔬擢根苗，濯濯在平壤。","甘苦各天性，宁期君子赏。","醢人司四豆，菹以事宾飨。","辛咸适所宜，调剂具分两。","深藏闭风日，揉择劳指掌。","经时色尚青，生意犹可想。","方兹饫醇醲，所贵在萧爽。","徐徐入齿牙，历历有清响。","山珍与海错，对之皆敞罔。","真味异五滋，逸韵殊豪上。","顿令酣醉人，当杯能倔强。","贫居五十年，饮食多卤莽。","黄齑日所亲，荼蓼心所奖。","岂知鼎俎间，非独口腹养。","凡物尽其材，用之斯不枉。","农经极草木，修制存畴曩。","姬公作周礼，纤悉固有仿。","七菹与三臡，供之惟用盎。","得名自古来，赋咏从吾党。"]},{"t":"诃林怀古同诸公作","f":"五言古诗","c":["粤山自北来，西城势宽衍。","阛阓百万家，中有梵王殿。","雄风固所存，古色不自炫。","遥遥三千载，春光递流转。","曾是虞翻宅，昔为赵佗甸。","九州不一姓，兴废如邮传。","如何一塔地，独使卢能擅。","须发彼所捐，宝之若旒弁。","至今菩提树，根基互相禅。","中心半枯朽，万叶犹葱茜。","佛法始东来，经纶多纠缠。","宗风振自兹，宇内为一变。","继以首楞严，羽翼相后先。","奇文阐妙义，笔授留遗砚。","乃知最上乘，枢纽存斯院。","镇以铁浮图，千佛皆身现。","干霄七层起，锢地重台奠。","锡以罗汉画，神彩流唐绢。","听法有睡猿，拥彗向人面。","访古驻干旄，开轩极流眄。","行厨具尊酒，老衲供茶宴。","集木啭黄鹂，拂池度双燕。","朱萼槛外明，青峰楼上见。","遥钟发暮景，刻漏催壶箭。","车马一分镳，将归有馀恋。"]},{"t":"丙子正月晦日袁密山通政史蕉饮梁药亭两吉士王令诒明府王紫诠使君招同蓝公漪史万夫于南溟廖南炜岑金纪屈翁山吴山带王蒲衣梁王顾林赤见家献孟曾秩长黄汉人集使君寓斋分赋","f":"五言古诗","c":["首月已云晦，蓂荚未全落。","既惜节候迁，况有良朋约。","烛下起笙歌，吟间命杯杓。","旷志挟天壤，深思契冥漠。","袁子古纳言，前身老行脚。","理棹下湘漓，经年系青雀。","史氏好弟兄，妙龄各鸣跃。","一时两玉人，维杨并花萼。","南王与北王，车辙相交错。","东行指铜柱，西登铭剑阁。","美政在天隅，后先同一格。","蓝生好牧牛，商声时叩角。","三山及五岭，几度乘芒屩。","吾乡十数子，大半头如鹤。","一二少年郎，赋质皆文弱。","嘉会叶应求，高言成盍各。","朝台霸气散，禹甸淳风薄。","缅忆髫龀初，盛事空如昨。","先哲有遗徽，而今不可作。","遥深怀古情，且尽新知乐。","飞栖雪下鸿，聚散风中箨。","后期杳何所，远道伤离索。","踟躇一搔首，牵率为酬酢。","莫拟送穷文，徒令五鬼噱。"]},{"t":"赠黄葵村","f":"五言古诗","c":["伏暑无所适，散带行前庭。","轻风入檐来，嘒嘒新蝉鸣。","上有梧桐树，参差闻雨声。","浮云忽东驰，霖潦浩纵横。","客心既云乐，况有良友生。","高谈永终日，雅奏和且平。","举世皆泥涂，斯人濯其缨。","古学日以坠，先民犹可程。","前笙与后管，相待成咸英。","朝日与夕月，相续为光明。","勉尔千秋业，慰我怀古情。"]},{"t":"寿邹仪生","f":"五言古诗","c":["受生虽有涯，与君当更倍。","以兹百年内，郁郁三十载。","西登极邛笮，南泛穷溟海。","盾鼻草檄书，儒冠立军垒。","三命滋益恭，百折终无怠。","蹉跎炎瘴间，霜雪颠毛改。","维兹春仲月，览揆辰期逮。","谷风发新晴，蟾兔盈光彩。","持觞候良夜，百卉欣相待。","所叹兰蕙花，含英犹未采。","大器固晚成，神龙靡终悔。","悠悠望六合，正气吾徒在。","剥复理何如，谁能问真宰。"]},{"t":"次答刘沛然兼送之端州","f":"五言古诗","c":["我居天一隅，幸豁千里目。","四海有同心，风期每相属。","之子三吴英，轩车来问俗。","旅病卧孤舟，宾至不及肃。","贻赠一篇诗，恳款见衷曲。","一吟五内宽，再咏双眉蹙。","蹇予生不辰，水深聊自漉。","不无危苦词，敢并骚些读。","岂知堕泪猿，更作求声谷。","义心知调古，直气识节促。","悠然金石音，出自丝桐腹。","为君埽蓬蒿，衔杯泛霜菊。","与君涉牂牁，堆盘进黄独。","旧宫禾黍地，当欢或成哭。","君家太湖上，瑶圃皆积玉。","联飞声满空，手著书盈屋。","徒惊潘令毛，渐叹荆州肉。","迟暮各有怀，古道敢不勖。","传经本儒行，今晨装已俶。","岩高星可占，峡暗云仍畜。","善价倘有时，毋为久藏椟。"]},{"t":"次朱汉源留别韵送之归吴下","f":"五言古诗","c":["人言双车轮，可以生四角。","人言方寸内，可以起五岳。","丈夫未得志，文采从驳荦。","往往见轗轲，行行自吟踔。","纵穷阿井胶，莫止黄河浊。","之子骐骥姿，望古振高躅。","六辔既如丝，千里岂云邈。","南来溟海上，为日不数数。","言寻朱明天，丹砂师抱朴。","著论等逍遥，儒墨供剽剥。","况复富于年，足用竟其学。","胜赏每登临，大雅相磨琢。","彼此互唱酬，古今屡扬搉。","如何欢会地，告别殊刺龊。","离舟系叶儿，归马歌皇驳。","犹馀柏叶酒，初度春王朔。","九州虽比邻，中心能不懪。","岭路雪岧峣，江涛时萦灂。","既抱连城珍，会待成风斫。","力田必有秋，至道不盈握。","勉矣树令名，天休日滋渥。"]},{"t":"送吴山带北上","f":"五言古诗","c":["吴子澹荡人，其性不汲汲。","及乎为文章，孤军遂深入。","精思涉混茫，妙语离沿袭。","缥缈三神山，飞尘莫能及。","积雪峨眉巅，晶瑩照原隰。","无意当世知，声名乃遥集。","游戏翰墨间，生机勃然立。","适兴一流连，当饥或忘粒。","如何此行迈，风雪趋皇邑。","岂无惜别心，白驹勿维絷。","黄金古有台，青紫芥可拾。","每爱太冲诗，功成独长揖。","埽石越溪南，为君理蓑笠。"]},{"t":"祝刘太翁","f":"五言古诗","c":["赤帝歌大风，横汾继其轨。","中垒较群籍，七略奏于子。","由来放勋裔，文思有攸始。","况乎漆沮间，西京原帝里。","夫子综古今，六经得源委。","神龙潜且确，雏凤翔而起。","嘉遁既以贞，耄期亦伊迩。","容颜迈少壮，视听无衰毁。","烛下作细书，千言盈寸纸。","吾闻兹泉旁，姜牙有遗址。","石室足栖迟，垂钓应得鲤。","鲤中有奇文，用介杯中旨。"]},{"t":"送陈大涉还长沙","f":"五言古诗","c":["我衰日闭户，况兹炎暑时。","偶然步林竹，小卧园东陲。","有客来叩门，童子例云辞。","醒来见名剌，客远不及追。","寻君就旅次，兼读所贻诗。","如睹渥洼龙，神骨森权奇。","如运成风斤，挥斥罔不宜。","忆昔少壮年，君乡曾久羁。","徘徊上衡岳，沿溯越湘漓。","潭州多遗逸，唱咏夕忘疲。","日月不相俟，烽烟中间之。","屈指四十载，存者皆孙枝。","君来何所闻，欣欣如见思。","老马纵识途，筋力已不支。","何以赠君言，良时今在兹。"]},{"t":"锦石歌为梁药亭赋","f":"古风","c":["梁生昨日归自吴，手中满把骊龙珠。","玉盘静注天华水，落手光芒水中起。","或如初日生鸿濛，或如淡月沉寒空。","或如虎豹在大泽，昂首斑斑雾中出。","或如骏马浴江湖，赭白连钱半有无。","或如霜岸晓，逝水流云交缭绕。","或如园林春，李桃花落凝锦茵。","或如越王胆，甘之如饴看不厌。","或如窦妇机，周回委曲盘五丝。","或如远山暮天赤，或如断砌新苔碧。","或如瘗玉尸血侵，或如古鼎丹砂蚀。","方圆盈缺各异形，腹背廉隅非一色。","谽谺窍穴具吐吞，浅淡深浓相照射。","天地生物何太奇，神工鬼斧谁能为。","或云星陨乃化石，此物前身是奎壁。","不然锻鍊自女娲，补天馀力生精华。","不然布阵逐诸葛，旌旆摇摇相掩夺。","问君得之于何方，六合之县州维扬。","满堂宾客为君赋，形容未极徒嗟伤。","因忆夜来江上雨，泥沙之中复无数。","作歌不得吾与汝，男儿固当择所主。"]},{"t":"乌金千佛塔歌","f":"七言古诗","c":["赤堇山裂流金精，万夫斫尽罗浮薪，南方帝子驱丙丁。","洪炉如山飞烈火，千佛乘莲火中坐。","浮图八层层八门，佛身摺动衣裳痕。","当时出冶立汉殿，汉主雄心割南甸。","后宫争出礼白毫，八百如花罗四面。","面上东隅纪铸时，龙文龟画光陆离。","土人读之半不识，字底千年藓花碧。"]},{"t":"罗浮山水图歌为陈岱清司李","f":"七言古诗","c":["六鳌不守蓬瀛东，海中夜走仙人宫。","如何君家素屏上，突兀乃见飞云峰。","我曾候日坐峰顶，花开万壑当深冬。","群鸡不动夜方半，水面火色烧天红。","此时天地顿消释，白日荡荡生胸中。","谁人具此大笔力，不写幽奇写标格。","卷将素练十二寻，收拾罗浮送归客。","罗浮山高人所钦，罗浮水清君子心。","罗浮之外君何有，归对罗浮尽日吟。"]},{"t":"为梁药亭题新得白水山人山水图歌","f":"七言古诗","c":["白水山人癯如鹤，神姿虽妙形何弱。","拂笺词翰势若流，对客清吟复能谑。","最工图画懒莫比，十日不能成一水。","姓氏而今作古人，诸公往往争遗纸。","梁君好事晚得兹，秋山一叠当茅茨。","使我枕簟坐其下，当暑忽有清风来。","石高气骄苔藓黑，疏林索莫生寒色。","心魂密与空谷幽，耳目顿觉群峰逼。","为谁画此空嶙峋，外无题识中无人。","幸离俗手免毁裂，得入君家如有神。","即今大暑方如焚，安得此图化为真。","清溪一曲无纤尘，与君高戴华阳巾。"]},{"t":"赠大木上人经略芝冈熊公之孙","f":"古风","c":["十年之前读国史，神熹皇间叹未已。","吁嗟熊公经纶才，疆场同辜直而死。","曹沫三败犹有为，李广自刭岂数奇。","当时是非且勿论，不知公死谁代之。","我怀此语未出齿，今日衡山见孙子。","摧颓但有神骨存，僧衲不完冬不被。","旧家王谢自不同，少罹患难诗能工。","小雏毛羽今已具，何不飞去淩长风。","五十慈亲日西落，念子不归生靡乐，愿君毋为恋丘壑。","吁嗟乎，君不见岳王祠庙崇千秋，秦氏儿孙讳长脚。"]},{"t":"高固斋以长歌赠别赋答","f":"七言古诗","c":["我生不辰稀所慰，唯以同心作同气。","同心海内几人存，白首尘中觉无谓。","与君相知三十年，未曾识面心先传。","穷通夷险每在眼，眉宇笑貌依希然。","去年握手仙羊石，今年大醉嵩台驿。","狂呼绝叫许谁闻，座有王生老髯客。","三山五岭本同风，千里帆樯指顾中。","朱明之末赵宋似，车辙幸不厓门同。","田横岛上多义士，无成无败皆英雄。","高牙大戟今满地，独少毛锥为表忠。","高侯好事古希有，油素铅椠不离手。","引商刻羽固所能，水澨山陬恣求取。","前年北谒十三陵，鬓丝如雪须有冰。","长安公卿争请乞，小书夜夜篝寒灯。","长歌赠我声声泪，虎卧龙跳千百字。","途穷时暮予何言，忠搆身危当日事。","升沉何必问君平，大有同人偶复呈。","火天上下固一揆，卦序后先如弟兄。","且将欢笑乐今日，莫使临岐感叹生。"]},{"t":"水岩双砚歌柬药亭","f":"古风","c":["玉则美矣磨于物，砺能磨物粗其质。","其温如玉润可磨，端溪紫石真无匹。","唐家中叶始得名，宋坑宣德已云精。","石工斧凿越江底，耳边仰听闻涛声。","蛇行鼠穴日益下，燃膏不借三光明。","琼浆玉髓恣求取，青花蕉白如脂凝。","水岩擅美匪自古，依稀记得明崇祯。","与君两砚本一石，当时割玉为双璧。","分藏箧笥三十春，往往兴云成五色。","为君不胫走文章，为君得路通仙籍。","笔飞墨舞信有神，载事纪言世谁敌。","共形岂复计菀枯，同调何常异肝膈。","君不见干将莫邪出延津，为跃为潜各龙德。"]},{"t":"西郊赠岑梵则","f":"七言古诗","c":["郊外新晴暮钟歇，江引霞光动林樾。","浮丘丈人坐秋风，玉兔泠泠照仙骨。","自言夙昔值升平，快意遨游正玄发。","千金买醉五羊城，匹马独行双凤阙。","老眼何曾着贵人，壮心足使吞溟渤。","而今万事付儿孙，寂寞荒丘采薇蕨。","唯有新诗似少年，夜夜高吟松下月。"]},{"t":"送徐仲内","f":"古风","c":["四月梅雨来，空山道弥左。","城中故人寄尺书，闻君昨理将归舸。","言扶微疾强出送，有姊之丧行未可。","徘徊中夜不成声，欲泣欲歌愁绝我。","生平忼慨好言诗，于君不敢轻为辞。","生平孟浪颇自许，不敢君前多一语。","识深鉴洞既莫伦，烁古澄今目如炬。","白头南北意何如，箧里羲爻一卷书。","潜思静玩日有得，天人至理匪玄虚。","即今归卧江上庐，大江北去连淮徐。","中州地广气坦舒，渭河汴洛王者居。","况君生长秦故墟，蟠溪卜猎逢老渔。","空同问道回帝车，六经所纪斯权舆。","访古出入骑蹇驴，鞍傍挂酒燔枯鱼。","俯仰自得乐有馀，慎勿遗我音信疏。"]},{"t":"珠江春泛","f":"七言律诗","c":["赵佗城下趁归航，片席盈盈挂夕阳。","一郭映山花竞发，万家临水柳争长。","金尊且自论贤圣，青史谁能辩霸王。","闻说海滨今弛禁，钓竿随处有沧浪。"]},{"t":"送劳书升观察赴召入都便道归石门省觐二首 其一","f":"七言律诗","c":["黔山一线走滇池，转粟曾供百万师。","盖代勋劳天上识，暂时膏雨岭南知。","盛年早定千秋业，信宿真成九罭诗。","当日声名推第一，即看雄略又如斯。"]},{"t":"送劳书升观察赴召入都便道归石门省觐二首 其二","f":"七言律诗","c":["石门秋好片帆间，十载王程此日还。","常恋白云依子舍，暂移卿月到家山。","麒麟作脯餐能具，獬豸为衣舞亦斑。","双白堂前开一笑，吾儿功已著平蛮。"]},{"t":"冬至后一日同吴园次曹石闾吴隼庵柯寓匏集梁药亭六瑩堂分得齐字","f":"七言律诗","c":["出郭青樽不俟携，东南名俊一时齐。","星占牛斗双龙外，地是仙人五石西。","令节易过宜纵饮，彩笺相命更传题。","只愁车马催归早，一线能添日已低。"]},{"t":"送沈太史典试贵州事竣还都","f":"七言律诗","c":["双飞鸾凤翼天居，近典文章出石渠。","夜竹已开多士榜，岭梅遥度使臣车。","惔焚岁月三秋后，历乱云山百战馀。","此去彤庭知有献，天涯唯读治安书。"]},{"t":"与柳州江使君磊庵再晤于五羊适有西川督学之擢赋此送之","f":"七言律诗","c":["雪里题诗共烛花，二年春色各天涯。","梦寻愚岛先生柳，身系东陵处士瓜。","泽国岂期逢五马，文星从此又三巴。","独怜别后风流远，丝竹无因问绛纱。"]},{"t":"送陈省齐学宪复命还都便道归武昌省觐","f":"七言律诗","c":["三吹鹤曲进离杯，岐路西风鹢首催。","游子欲为春草报，乡人争看使星回。","文章后劲诸郎得，桃李新花百粤开。","且向鹤楼娱鹤发，九天不久鹤书来。"]},{"t":"端州道中望峡口积雪分得知字","f":"七言律诗","c":["峡中飞雪浪能为，雪积高林又一时。","行客欲沽江上酒，青山如笑鬓边丝。","天心复后阳犹战，地气南来世未知。","赖有兔园同授简，郢歌能和莫教迟。"]},{"t":"沥湖冬泛","f":"七言律诗","c":["蔬圃人家渐作林，沥湖名胜只于今。","堤连双峡为开阖，气与长江共浅深。","故国豪华年少梦，片帆风雪老来心。","杖头尚识星岩路，十里荷香未可寻。"]},{"t":"玉屏风看梅","f":"七言律诗","c":["玉屏风峭客来稀，玉树珑珑透夕晖。","无土亦应湿石乳，有花唯是点仙衣。","鸟迷雪色栖难定，云恋寒香驻不飞。","莫倚罗浮曾入梦，和羹人自梦岩扉。"]},{"t":"龟峰白云为徐凤池赋四首 其一","f":"五言绝句","c":["龟趺结苔发，虬松长鳞鬣。","寂寞丘垄平，秋虫吊寒月。"]},{"t":"龟峰白云为徐凤池赋四首 其二","f":"五言绝句","c":["涕泣谁家儿，白马来何处。","不识阿母坟，三匝坟前树。"]},{"t":"龟峰白云为徐凤池赋四首 其三","f":"五言绝句","c":["一蹶陨平芜，神灵为汝道。","下有思子人，上有伤心草。"]},{"t":"龟峰白云为徐凤池赋四首 其四","f":"五言绝句","c":["负土即旧茔，招提开法雨。","谁知青莲花，结子中心苦。"]},{"t":"送蒋莘田大参之任河南提学五首 其一","f":"七言绝句","c":["珠江甘雨晓来收，五两轻风引使舟。","父老夹衢齐下拜，福星从此又中州。"]},{"t":"送蒋莘田大参之任河南提学五首 其二","f":"七言绝句","c":["暑风泥雨遍城闉，多少无家太息人。","亲为遗黎寻旧屋，绿萝坡上驻车轮。"]},{"t":"送蒋莘田大参之任河南提学五首 其三","f":"七言绝句","c":["半为民舍半为兵，箕帚刀锥日有争。","犹识汉廷强项在，八旗低首避骢行。"]},{"t":"送蒋莘田大参之任河南提学五首 其四","f":"七言绝句","c":["昔时荒草接城东，今日弦歌满郭中。","三十六年兵燹后，赖公重启太平风。"]},{"t":"送蒋莘田大参之任河南提学五首 其五","f":"七言绝句","c":["连开书院育人文，南海宫墙气象新。","曾是童年灯火地，门前桃李两重春。"]},{"t":"明妃怨","f":"五言绝句","c":["生死归殊俗，君王命妾来。","莫令青冢草，生近李陵台。"]},{"t":"题乌丝红袖图为王黄湄都谏三首 其一","f":"七言绝句","c":["花雨林烟自暮朝，清溪流水入红桥。","蛮笺捧出纤纤手，如此诗人未寂寥。"]},{"t":"题乌丝红袖图为王黄湄都谏三首 其二","f":"七言绝句","c":["榛苓常有美人思，今日披图若见之。","孤凤自鸣天上疏，一阳阴管卷中诗。"]},{"t":"题乌丝红袖图为王黄湄都谏三首 其三","f":"七言绝句","c":["北仕燕都西住秦，南来使节动星辰。","多年已作罗浮梦，满眼梅花树底人。"]},{"t":"题烟波渔父图","f":"七言绝句","c":["卷却丝纶付一竿，世间无处问严滩。","客星自落江湖上，只有孤山处士看。"]},{"t":"题枫江渔父图为徐虹亭二首 其一","f":"七言绝句","c":["烟雨江头一钓丝，扁舟行止更由谁。","渔人已入兴王梦，枫叶芦花似未知。"]},{"t":"题枫江渔父图为徐虹亭二首 其二","f":"七言绝句","c":["燕台风月不曾孤，爱写吴山入画图。","威凤偶然来阿阁，白鸥原只恋江湖。"]},{"t":"题翁小愚大参小影二首 其一","f":"七言绝句","c":["蒲团高坐此为谁，戴笠乘车各一时。","欲为天人开眼目，正须儒者旧须眉。"]},{"t":"题翁小愚大参小影二首 其二","f":"七言绝句","c":["受命当年记饮冰，此心无染即禅灯。","紫薇分省含香署，风味居然一老僧。"]},{"t":"冬夜高峡同屈翁山联句二十韵","f":"五言古诗","c":["食雾嘉鱼出，含风顾兔摇。","冲寒从郁水，首路指高要。","入峡乘寒月，依沙候早潮。","榜人愁梦短，渔子恨歌遥。","石束牂牁势，山分大庾条。","双厓高易削，半壁涨难消。","上下多猿影，潺湲似凤箫。","峰留天一角，霞作海孤标。","化石怜贞女，看棋忆古樵。","羚羊潜水裔，鸲鹆閟山椒。","白玉参差笋，丹砂尺寸苗。","霜苞开橘柚，土布卷巴蕉。","金渡龙须席，琼州孔雀翘。","舳舻争入贡，洲岛已全招。","虎豹关门壮，鼋鼍窟宅骄。","飞楼淩缥渺，涌塔出云霄。","建节雄枢府，回岩俨斗杓。","黄门喧鼓吹，赤社盛弓弨。","鲙鲤筵方启，羹梅味正调。","野人趋宴喜，竟夕倚兰桡。"]},{"t":"阅江楼晚眺分赋","f":"古风","c":["高楼雄近郭，古驿带长堤。","石室横当北，梧江抱自西。","光摇虚壁动，青入画阑低。","缥缈云生牖，崚嶒石作梯。","四隅回曲阁，三叠跨长蜺。","朱拱浮花满，明窗落照齐。","佳哉行乐地，久矣困征鼙。","虽复橐弓后，犹闻伏枥嘶。","风高团赤叶，苔浅涩青泥。","屋角闲铃语，檐牙寄鸟栖。","晚帆归习习，霜?远凄凄。","幸有朋俦聚，还同笔砚携。","读铭思跃马，临渚忆燃犀。","胜会诚难得，新诗好遍题。","莫嫌冬日短，今夕月如圭。"]},{"t":"雯光宴集用吴刺史园次扇头原韵即席赋","f":"七言律诗","c":["送客分题是隔年，客来已度九秋烟。","似从岭海酬诗债，先向端溪问砚田。","寒雪未回中夜棹，暖风初试小梅天。","使君地主能开社，菊径犹多泛酒钱。"]},{"t":"寄王将军孝扬","f":"七言律诗","c":["海陬别日枉新诗，妙画清才举世知。","鸟在榆枋吾自笑，凤翔霄汉见何期。","巫贤益大先臣业，吉甫曾将六月师。","岭外小民怀世泽，几时膏雨更南垂。"]},{"t":"哭庞甥东侣孝廉二首 其一","f":"七言律诗","c":["把书不禁泪盈盈，年与而翁本弟兄。","一自玉楼天有召，喜看秋榜汝成名。","祝鸠命氏初贻□，鸿雁联飞日迈征。","及识君家今五世，可堪垂暮哭吾甥。"]},{"t":"哭庞甥东侣孝廉二首 其二","f":"七言律诗","c":["见汝成童外祖前，今看行状倍潸然。","传书止有中郎女，作赋才过贾谊年。","貂敝长安频是客，凫飞叶县未成仙。","白头老母伤何极，奉养犹资汝弟贤。"]},{"t":"题惠倅俞介石行乐图时摄篆","f":"七言绝句","c":["骥足方开迥绝尘，弦歌随处有阳春。","知君不愧罗浮吏，满目梅花梦里人。"]},{"t":"赠顾六纪 其一","f":"七言绝句","c":["三城夜燕共衔杯，日出东方未拟回。","海内故人吴地遍，因君一一问年来。"]},{"t":"赠顾六纪 其二","f":"七言绝句","c":["海不扬波已十春，时来西北又边尘。","凭君下笔开生面，借取淩烟阁上人。"]},{"t":"送梁叠石广文之任定安","f":"七言律诗","c":["骅骝俱是取长途，琼岛迢迢海一隅。","黎母山前新绛帐，老人峰下旧师儒。","地非异域风全隔，路有同心调不孤。","虽曰倚闾应念远，粤乡犹胜仕皇都。"]},{"t":"送引眉侄","f":"七言绝句","c":["东归且勿叹途迷，大鸟将飞翼自低。","六月正宜鹏羽息，九天终见雁行齐。"]},{"t":"杂诗","f":"五言古诗","c":["二月桃始华，鸣鸠拂其翰。","何以遣忧伤，青樽命游观。","客有燕赵人，临流发清弹。","一鼓霜霰零，再鼓凝冰散。","萧萧徵羽声，举坐皆窃叹。","归来酒力薄，安寐不至旦。","雄剑鸣鞘中，夜起视星汉。"]},{"t":"写碑惠州泮宫屡醉叶御六卫立组学署即事赋柬","f":"七言律诗","c":["白头游兴未能忘，几度西湖上画航。","失路久为狂阮籍，写经仍是懒嵇康。","宵来泮水添圆月，雨后遥峰近女墙。","谁道广文官独冷，醉人新酿荔支香。"]},{"t":"送黎方回归耕罗浮二首 其一","f":"七言绝句","c":["先世诗篇刻已成，罗浮归去好躬耕。","知君幽意无终极，更向丹崖自勒铭。"]},{"t":"送黎方回归耕罗浮二首 其二","f":"七言绝句","c":["丰啬从来理必均，况于取义与成仁。","舍生已是前人事，应将长生与后人。"]},{"t":"题梁叠石母冯太君节孝册","f":"七言律诗","c":["结缡七月已无夫，身后初生藐尔孤。","矢死诗成辞父母，未亡人在有翁姑。","三冬对火寒书荻，孤幌残灯夜辟纑。","今日俸钱能反哺，佳儿名已列师儒。"]},{"t":"祝黎方回","f":"七言律诗","c":["板桥东望是扶胥，照水无劳拔白须。","此日合为山院长，当年曾是羽林孤。","柳栽宣武围皆抱，柏近王裒树亦枯。","酌酒寿君还自笑，一般霜雪各头颅。"]},{"t":"梁药亭招集六瑩堂观六瑩古琴同诸公作歌","f":"古风","c":["昔人斫琴贵其声，梁君得琴堂以名。","六瑩堂诗走天下，人因诗好知琴精。","酒酣拂拭呈上客，四座观之皆动色。","断纹半作龙蛇形，古漆总如金铁蚀。","梁君得此三十春，书斋终日伴闲身。","发扬宫徵在笔墨，清风沕穆还天真。","陶公无弦得其意，君琴有足一无二。","不遇其人不敢修，旧新杂糅虞非类。","吾闻舜琴五弦象五行，当年揖让称平成。","少宫少商自文武，三千年内多戈兵。","乃知极备不如缺，为君一弹再三歇。"]},{"t":"以香瘿杯为魏和公寿系之以歌","f":"古风","c":["南州炎德多芳草，丹桂玉兰皆合抱。","珠厓有树更绝伦，独发清芬自枯槁。","松枝成珀待千年，朽木为芝质屡迁。","此香凝结乃异是，皮肤脱落馀贞坚。","寄君瘿杯大如斗，为君满引无疆寿。","箕瓢可挂不闻声，惠瓠能容宁用掊。","翠微腊月梅花浓，散作琼瑶落酒钟。","万里知交各南北，几人同上金精峰。","君不见南极老人旁，客星每夜生光芒。","其占为世多寿者，斗牛之野斯其昌。","更闻月出天街北，天下从兹皆喜色。","犯座应须太史陈，此星或是严滩客。","举杯邀月月何言，饮罢看杯意独存。","既用馨香比明德，还因错节念同根。"]},{"t":"王础尘载酒北郊招同诸子集白云庵即事成歌","f":"古风","c":["北风日夜来，萧萧满城铎。","扶筇拥褐欲何之，我欲升高望南国。","千峰飞舞向朝台，白云小院叩复开。","门前古木立千尺，竹阴埽地无尘埃。","溪水韸韸野田下，断续山桥度车马。","半为斑白半少年，尽是平生素心者。","山亭布席大白浮，野花折取传觥筹。","酒酣客起迭击鼓，鼓声悲壮惊林丘。","斯亭昔是名王垒，石阙遗碑勒胡字。","四十年来骨已灰，行人尚洒三城泪。","何不令九牛倒曳掷泥沙，何不令牧儿一炬为平地。","天河尽挽洗山川，红日高飞走魑魅。","为君击鼓击复催，一阳天地今将回。","愿进中山千日之酒杯，杞人之忧安在哉。"]},{"t":"西湖秋月歌题臧介眉卷","f":"七言古诗","c":["月之可爱虽在水，有水无山非备美。","人间好月是西湖，湖光即在山光里。","三十年前湖上游，十度月圆湖外起。","霜飘忽满六桥中，镜飞直印三潭底。","四山隐映出楼台，百尺虚明见鳣鲔。","是时丝竹在湖船，棹入琉璃水际天。","闻歌或泊山边寺，煮茗遥深石上泉。","君游与我谁先后，把卷沉思叹良久。","何年高谢罗浮云，会须更买馀杭酒。"]},{"t":"题薛孝穆小影","f":"古风","c":["薛生今世之狂简，人定不为天所限。","半生好作访古游，千载独具论文眼。","西游彭蠡溯湘沅，北过二陵寻灞浐。","逢碑下马辄自抄，得钱随手皆镂版。","结交欲尽一世豪，其家不及中人产。","年来更和击缶歌，赋中屡有伤心撰。","看君意兴殊落落，复上石楼穷?嵼。","与予相见五羊城，花边往往同飞盏。","问君之生烈皇末，日月无光天道反。","七日即为国破时，赋命其间宁不蹇。","阴阳剥复理有然，大器从来成在晚。","终期落日戈可挥，莫谓颓风力难挽。","谁人画此蕉与鹤，中有一翁坐来稳。","把将如意缺唾壶，直著山衣傲华衮。","蕉心万束不易开，鹤寿千龄孰能损。","君不见中孚九二鸣在阴，子和之声闻最远。"]},{"t":"答别季伟公","f":"七言古诗","c":["十年君作归山思，预算别时无限事。","及到君行既有期，匆匆不暇言文字。","君来之日父在堂，一官转侧浮山阳。","危疆百战功未录，举家幸脱豺与狼。","客庭诗礼三城下，英妙年中推作者。","中郎倒屐赠图书，王孙飞盖同游冶。","岂期留滞事多艰，旅榇悲凉百粤间。","浈江南下分台岭，章水东流隔玉山。","四望乾坤何乃狭，西行且欲弹长铗。","月中联句共星岩，雪里移舟傍高峡。","循州太守仙人徒，著书日日临丰湖。","长歌短韵互赓答，争雄角胜相瑕瑜。","石楼大小闻曾陟，有石如台高百尺。","登台列坐拔其梯，不是诗成归不得。","君才峻险多锐思，月胁天心未足奇。","马卿善病尚能赋，原宪长贫徒尔为。","乡园昨日传消息，八叶恃君延一脉。","三月谁耕墓下田，六桥已废先人宅。","因兹感叹急言旋，及此清秋理客船。","章贡滩平收潦后，维扬江静刮风前。","馀杭形胜称都会，好结茅茨向郊外。","鹤发慈亲倚杖看，斑衣稚子提携拜。","文章前辈几人存，继起今知有后昆。","访旧不妨寻白社，怀才应复向都门。","一言为赠何容苟，况子青年余白首。","昔贤汲汲惜分阴，古圣皇皇惟敬口。","时来已怆别离心，避暑贪眠又废吟。","酬君长句惭牵率，莫当诗看只当箴。"]},{"t":"赠别史蕉饮吉士次其僧字诗二十九韵","f":"七言古诗","c":["枯坐欲似参学僧，日钻故纸如窗蝇。","白头兀兀尚若此，面目自照殊可憎。","曾上罗浮宿绝顶，中宵见日得未曾。","二曜何常一安处，以此自慰还自绳。","因之仰首叩阊阖，■词既竭天不应。","星宿坠地化苍狗，下界逐肉飞鹯鹰。","海上三山淼难即，胸中五岳高崚嶒。","鲍公遗履直欲借，列子风御如可乘。","方思翱翔周八极，物色英俊开群瞢。","爱君才名早艳发，文坛拔帜时先登。","虚中若谷每能下，大器善受惟不矜。","南来往往有佳句，见者动色相嗟称。","谁言为道贵日损，山海未厌涓埃增。","过河之鱼戒鲂鱮，希有之鸟遇大鹏。","淹留残腊倏已尽，地气正月乃上腾。","枯条冻卉各生意，争奇竞巧无不能。","当歌岂复问昼夜，纵饮不必论斗升。","那能老大更束缚，蛟龙反受鱼人罾。","杯阑烛跋语未息，斋厨茶灶烟不兴。","城角乌乌觉残梦，日光杲杲生觚棱。","一时车马各星散，室中尚有孤吟灯。","从来沈忧发易白，我已白尽仍不惩。","鞭心入里欲近道，蕉皮剥尽空层层。","春江少雨石尽见，百尺潭水犹清澄。","归舟唱和昆若弟，南北都会邗与升。","鱼鸟亲人自飞跃，垂杨匝水丝鬅鬙。","长途兴会或有得，一篇示我南中朋。","等身之集未敢请，衡阳纸贵难为誊。"]},{"t":"为黄驭远题其祖黄文简公画像次其自题元韵","f":"七言古诗","c":["百年天地真如寄，达士千秋名自异。","与时用舍有机衡，过眼浮云等游戏。","黄公岳岳立先朝，直道不逢真宰忌。","玉殿传胪简在心，词场掉鞅如丝辔。","六卿掌礼协神人，九重入告回天地。","和羹鼎鼐到何难，脱屐山林归若弃。","祖道争看少傅疏，徵书屡召山人泌。","退身所幸属时平，遗荣岂必须年至。","家似金张七叶貂，姓同黄绮商山四。","绘工初写颊边毛，诗笔自抽囊底智。","仙姿道骨落丹青，铁画银钩传指臂。","先正风流渺莫攀，后生愿睹何由觊。","文孙相遇五羊城，开函使我生遐思。","章服如瞻汉代仪，纪年尚识神皇字。","满前光霁蔼可亲，纸上须眉殁犹视。","别写持竿著鹿冠，想见当年好幽致。","尹生公后百馀年，不偶于时甘弃置。","江海难消涕泪痕，斗牛自掩干将气。","皓首无从博酒温，终身已分餐菱芰。","不敢披公第一图，愿与别图居第二。"]},{"t":"端溪别黄驭远","f":"七言律诗","c":["半年聚散不曾停，十日端州倚称情。","洗砚高卑分品格，解衣磅礴论平生。","空江秋涨洄洄急，古寺菩提叶叶声。","有约重阳能到否，扁舟先下五羊城。"]},{"t":"同王孝扬将军集吴大司马三水舟中次韵","f":"五言律诗","c":["星座临双峡，霜威肃九秋。","有人乘野舫，昨夜度江流。","天静山如画，风高白可浮。","庾公清兴在，不用赋登楼。"]},{"t":"吴大司马泊舟三水予挈白菊遗之适王将军在坐即事联句十一韵","f":"五言古诗","c":["良会秋将尽，维舟日尚长。","江山瞻节钺，草木被文章。","海国从无冻，絺衣未觉凉。","残阳移岭外，新雁度洲旁。","西北双流合，参差万幕张。","倚窗杯在手，对菊月横床。","冷艳依人淡，寒英入座香。","堆盘疑积雪，拂槛欲凝霜。","珍重高贤赠，苍茫逸思狂。","兴馀仍秉烛，风定更闻榔。","归路吟清句，怀中有夜光。"]},{"t":"答叶桐初","f":"七言律诗","c":["虎丘南望得浮丘，千里脂车路已悠。","暑月见君从北至，清秋闻说又东游。","长贫可有青山买，善病如将白发谋。","多谢高飞云外鹄，忘机吾已狎沙鸥。"]},{"t":"送张两如归河南兼柬蒋莘田学使","f":"七言律诗","c":["平原莽莽草连空，二十年前识汴宫。","嵩室数峰明野外，黄河一曲落天中。","含香旧署归何远，过岭新篇调尽工。","相送海头何限意，因君遥问鲍家骢。"]},{"t":"送曾韬人太史归晋江省觐","f":"七言律诗","c":["一时车马咽河津，继世论交意倍亲。","五岭旧阴棠树在，八闽归兴彩衣新。","江乡菊酒消长夜，驿路梅花放小春。","到日趋庭问遗逸，芦中休道更无人。"]},{"t":"献祝大司马吴公","f":"七言古诗","c":["南交命宅古尧封，司马临边乐事重。","地束西江为两峡，天垂北斗作诸峰。","遐陬斥堠宵无警，绝岛梯航岁自供。","淡淡水田馀滞穗，疏疏梅蕊点深冬。","寒轻小郭晴光满，野霁浮烟瑞气浓。","千里藉裾听鼓角，一方黎献乐陶镕。","沙场宿将输兵略，当代词流避笔锋。","行处管弦鸣马上，坐时歌舞在艨艟。","雕栏并立人言鸟，金埒群嘶血汗龙。","海内声华推泰岱，卷中诗句拟芙蓉。","尽分月奉归贫士，间采刍言及老农。","共颂我公清似水，更歌天保茂如松。","伫为曲蘖调神鼎，已见勋猷勒景钟。"]},{"t":"端州至日黄敬旃进士招同叶渊发周维念集七星岩","f":"七言律诗","c":["吴越相思心万重，扁舟何意聚萍踪。","青尊节序当长至，红树溪山属暮冬。","怪石嵯峨飞作室，乱云奇变叠成峰。","老夫屡到犹难舍，上客天涯得几逢。"]},{"t":"送何左王入罗浮兼答留别之作","f":"七言律诗","c":["寰中花鸟正春新，四百罗浮日日春。","送子不堪临水别，昔年曾是住山人。","紫芝三秀餐无尽，灵药千溪采未匀。","况复冥鸿谁得慕，白鸥虽近亦难驯。"]},{"t":"赠远斋和尚","f":"五言律诗","c":["度岭为游子，飘然二十春。","重逢成老大，一悟彻天人。","无缝衣常暖，非台镜不尘。","桃花今又发，消息可谁真。"]},{"t":"清明后一日舟泊端江骤雨忽至望王础兄寓阁不得相就承诗见贻次韵奉答","f":"七言律诗","c":["潇潇淅淅满河干，小阁扁舟各坐看。","旧雨恰来云自合，新烟初试食犹寒。","悠扬逝水心俱远，只尺行泥路亦难。","自有晴空生旭日，高天不用羡飞翰。"]},{"t":"上巳后一日王孝扬将军招同张桐君梁药亭屈翁山张超然家献孟集倚剑堂时牡丹盛开即事分赋","f":"七言律诗","c":["折简相招路未遐，群贤毕至兴弥嘉。","春风好续兰亭会，南国今开洛下花。","戏彩衣边疑舞袖，惊人诗里见馀霞。","明朝定有江郎笔，传出山阴内史家。"]},{"t":"又得五歌","f":"七言律诗","c":["身在簪缨志薜萝，登坛年少古谁过。","彤弓棨戟清风在，曲槛疏帘暇日多。","会向交南标一柱，曾从天上挽明河。","青春解带尊垒外，坐对名花奏雅歌。"]},{"t":"四月十日潘亚目招同王础臣汪寓昭查德尹徐序仔梁药亭林叔吾王紫巘集视苍楼送春分得八庚","f":"七言律诗","c":["郭中登阁万峰呈，笑指江帆历越城。","远道未知芳草歇，高窗先见夏云生。","衰年作别唯须酒，空谷相求岂待莺。","尚有此宵春不尽，归途无惜月同行。"]},{"t":"送查德尹","f":"七言古诗","c":["前年君自潇湘至，江上维舟初擘荔。","今年荔子尚青青，数日扁舟不肯停。","问君此别将何适，五月风涛下洞庭。","君山一点青在眼，江汉双流何限情。","送君心已登黄鹤，更向天边念脊令。"]},{"t":"赠汪寓昭","f":"古风","c":["三十年来心未已，一片西湖梦中水。","闻君宅外有名园，湖山移入杭城里。","花边放棹夜不归，日上高春眠正美。","人生快意须行乐，世上浮云空复尔。","君不见东方大夫神仙子，金马陆沉饥欲死。","公孙开阁号平津，共宿故人犹布被。","羁縻薄禄固不堪，溪刻终身亦何以。","何如丝竹卧东山，时来乃为苍生起。"]},{"t":"胡绢庵宪长入觐都门便道省亲事后还治赋之","f":"七言律诗","c":["归国还乡共一行，豸冠龙节有馀荣。","晨昏子舍欢何极，玉帛天门礼已成。","万里春风张相宅，满车甘雨赵佗城。","谁人解献中和颂，白发狂歌一老生。"]},{"t":"送胡绢庵宪长擢任楚藩","f":"七言律诗","c":["才见朝天息八驺，又闻恩命下炎陬。","紫薇卿月临荆楚，棠树清风接岭头。","千里溟濛沾旧雨，一帆轻便挂新秋。","家庭且喜平安近，数日书邮是蓟州。"]},{"t":"寄欧阳香山石臣","f":"七言律诗","c":["几度逢君在客踪，每从人口识仁风。","独培元气蛮烟外，手播阳和海县中。","九老溪山同白傅，大家文字继忠公。","寄来珠玉新盈箧，昨夜光芒屋角东。"]},{"t":"朱式金招同王础尘张桐君潘函观朱子成周夏声周维念王紫巘集东郊珠会亭分得五歌","f":"七言律诗","c":["新结茆亭匝碧波，清尊邀客更能过。","天连浦溆帆争入，山杂云霞晚渐多。","暑气乍消闻急雨，野风轻度送馀歌。","升平旧事从今复，胜赏其如白发何。"]},{"t":"送严止峰归拜双亲寿","f":"五言律诗","c":["海上浮蓬岛，遥遥到惠阳。","君寻三秀草，归奉万年觞。","崖石铭应遍，天鸡听未忘。","故滩垂钓地，老脚为谁长。"]},{"t":"寄贺王花县","f":"七言律诗","c":["万峰深处邑城开，经始今烦盖代才。","彩凤远衔丹诏出，双凫遥共驷车来。","上公府外棠阴迥，大将坛边雁阵回。","伫见循良封卓茂，一家勋业满云台。"]},{"t":"蒋莘田学使自河南寄示新刻赋寄二首 其一","f":"七言律诗","c":["敢言汉代朱槐里，善述龙门太史公。","已化文风来岭外，更移时雨到天中。","新栽桃李春争发，一顾骅骝野遂空。","闻说河清方献颂，大梁佳气正葱葱。"]},{"t":"蒋莘田学使自河南寄示新刻赋寄二首 其二","f":"七言律诗","c":["别来吟兴定何如，老树庭边客渐疏。","积水在门梅雨后，新蝉依岸荔香初。","中州纸贵今时赋，少室峰高昨日书。","犹记去年相送地，粤人千里拜干旟。"]},{"t":"魏子冲司马擢理军府时令子官桂林赋此志贺","f":"七言律诗","c":["桂江云接粤江云，小凤文如老凤文。","两地山川非远隔，九皋鸣和日相闻。","新开骥足俱千里，更绾铜符理六军。","魏绛自来多胜算，歌钟先见锡殊勋。"]},{"t":"过徐拜石横潭村居","f":"七言律诗","c":["云满空江覆渚葭，诸峰佳处不全遮。","十年有约横潭路，一棹初寻处士家。","深巷暮蝉和细雨，短篱疏树带高花。","此来卜隐兼耕读，相过从今未有涯。"]},{"t":"次答闻一老僧","f":"五言律诗","c":["行脚轻千里，高年近百春。","虽云方外士，犹是老成人。","水笔随山笠，孤琴伴独身。","曹溪亲到后，何者是埃尘。"]},{"t":"送陆英德之官云州且以为寿","f":"五言律诗","c":["英州三百里，处处石如云。","何事云州去，清猿夜夜闻。","砂从勾漏得，路到岭头分。","别后思仁政，梅花是使君。"]},{"t":"柬佟静公","f":"五言律诗","c":["时来常善病，几月掩柴扉。","闻发西江棹，新从象郡归。","远知鸿鹄志，秋及雁行飞。","千里埙篪合，新诗定不稀。"]},{"t":"为李立斋题其尊人茂林先生像","f":"五言律诗","c":["冠履非畴昔，丰仪尚俨然。","凤池身拜日，鸠杖独归年。","笔下啼山鬼，诗成泣蜀鹃。","开元旧供奉，原是李青莲。"]},{"t":"送李茜为孝廉谒选都门便道萍乡访尚渑其王孙","f":"七言律诗","c":["风前一揖五羊城，树树寒梅送子行。","计日便为民父母，多年犹恋老师生。","楚江地迥收萍实，燕市歌长散筑声。","若到青春怀茂宰，王孙芳草总含情。"]},{"t":"赠孙观察","f":"七言律诗","c":["昨从公宴识清颜，高论超超出世间。","书案前头唯紫石，射堂南面是青山。","珠官星纪分三楚，玉节风行带百蛮。","不为遐方资伟略，老成应已列崇班。"]},{"t":"端州雨中乏香率成二绝句柬翟五吉广文二首 其一","f":"七言绝句","c":["湿云和雨下空堂，至后阴阳亦觉长。","今日旅中寒袖手，拟从荀令乞馀香。"]},{"t":"端州雨中乏香率成二绝句柬翟五吉广文二首 其二","f":"七言绝句","c":["黄旗峰下千年树，石室斋头独坐人。","虽是广文毡最冷，一星遗火亦成春。"]},{"t":"题真际上人坐石图","f":"七言绝句","c":["真中真际果谁真，一串珠随七尺身。","坐断石头庵外路，年年滑尽去来人。"]},{"t":"李华西司马招饮郡斋赋谢","f":"七言律诗","c":["五羊城里枉过从，帝里归来此再逢。","几案纷然开万轴，郡斋闲甚对诸峰。","公馀自酌唯杯水，客至何劳命酒钟。","犹带凤池高格在，李膺门地本名龙。"]},{"t":"次和严藕渔宫允南归述怀四首 其一","f":"七言律诗","c":["朝回犹著住山衣，如此行藏古亦稀。","双阙有云龙乍见，九皋无恙鹤还飞。","闲携青史新书草，笑问黄花旧钓矶。","滩上羊裘今在否，秋风鲈鲙未云非。"]},{"t":"次和严藕渔宫允南归述怀四首 其二","f":"七言律诗","c":["高卧宁期召命催，廿年名字满蒿莱。","经陈黼座身遥入，宴赐龙楼语未回。","纶綍新裁非往昔，冰霜清操是从来。","江湖此日归渔父，买断磻溪作钓台。"]},{"t":"次和严藕渔宫允南归述怀四首 其三","f":"七言律诗","c":["早将章奏达高旻，车骑雍容此问津。","天上赐来闲岁月，江东归去老词人。","千峰驱走供渲染，八法精妍杂草真。","体物咏怀应有作，岭头添得几重春。"]},{"t":"次和严藕渔宫允南归述怀四首 其四","f":"七言律诗","c":["客程能许几时留，缱绻中来不自休。","数月为开栽菊径，两旬相并看梅舟。","龙蛇君是东方朔，款段吾从马少游。","爱此清篇聊属和，未堪传向凤池头。"]},{"t":"盐梅二律祝吴大司马 其一","f":"七言律诗","c":["雪色霜姿迥绝尘，生从天一许谁论。","已于润物瞻全德，更用馀波养世人。","傅说命来王政远，夷吾书在霸图新。","南溟天阔风涛壮，国计边防倚重臣。"]},{"t":"盐梅二律祝吴大司马 其二","f":"七言律诗","c":["天与和羹绝异才，年年称祝见寒梅。","自缘冬日宜人久，故著南枝向暖开。","香和清风传五岭，霜笼烟月下嵩台。","他时结实垂垂长，霖雨还能应节来。"]},{"t":"人日喜晴招王础尘洪药倩潘函观王紫巘集得一山房分得十三元","f":"七言律诗","c":["春归何处不书元，小筑初开近郭门。","万里故人同此会，一年新日到前轩。","欢无不合宁须酒，忧未能忘且树萱。","城市古来多隐地，买山非欲拟桃源。"]},{"t":"题顾汉小影","f":"七言绝句","c":["出山云似住山间，南北东西独往还。","十载识君曾一笑，卷中仍是旧时颜。"]},{"t":"黎立臣救溺纪事二首 其一","f":"七言绝句","c":["腊月寒风塞峡门，山僧为我说迷津。","谁知白浪孤舟里，苦海回头尚有人。"]},{"t":"黎立臣救溺纪事二首 其二","f":"七言绝句","c":["一棹乘危岂易料，是时风雨正潇潇。","知君善庆今无限，及第当年但蚁桥。"]},{"t":"双涌文阁落成赋寄黄咸淑郑澹斐诸子","f":"七言律诗","c":["杰阁初开彩翠重，双溪新水跃鱼龙。","牂牁远至三千里，云谷高连七十峰。","尽敛烟霞归牖户，更罗星宿入心胸。","知君本自饶堂构，且绘麒麟第一重。"]},{"t":"题徐道冲观泉图","f":"七言绝句","c":["本自无心止与行，出山何似在山清。","知君爱坐源头上，流彻千年是此声。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其一","f":"七言律诗","c":["嘉实真能副盛名，一株长作百筐倾。","时来野鸟皆舟穴，日至居人自火城。","远使定知冰可齧，近车须信夜能明。","南天风雨今年恶，大嚼都疑未称情。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其二","f":"七言律诗","c":["树南树北各持竿，掇取枝头颗颗丹。","珠玉在前疑我秽，肝肠如此为君寒。","根移汉苑栽非易，路隔梅关见亦难。","石蜜葡萄那可拟，子桓空羡子乔丸。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其三","f":"七言律诗","c":["潮水村边十万家，短篱高树不全遮。","风前似醉酡颜酒，膜里如封系臂纱。","匠手剖将和氏璞，清泉浮出魏王瓜。","骊珠探后馀鳞甲，片片阳林二月葩。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其四","f":"七言律诗","c":["离枝五日不成筐，色味何能到玉堂。","汉驿枉教劳马足，李家空复舞霓裳。","止堪作脯供茶宴，合取馀膏付酒娘。","口腹累人垂炯戒，昔贤一疏自千霜。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其五","f":"七言律诗","c":["不因人热气仍烘，草木遥于大化通。","汉火欲兴符自赤，楚萍将霸实先红。","生无北向非怀土，老守南枝敢论功。","待得馀甜归齿颊，只堪唐突小儿童。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其六","f":"七言律诗","c":["垒垒朱实映清江，树树蝉声绕石幢。","估客满笼归别市，山童一饱卧闲窗。","尝新已办盐鱼饮，消热唯开汗酒缸。","蝴蝶未知无可采，飞来飞去自为双。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其七","f":"七言律诗","c":["谱中诸品遍曾尝，晚熟增江久未忘。","快比哀梨那得滓，清如甘露不成浆。","已知忧至良堪解，见说颜衰可复光。","更有新州香荔好，端溪能隔几城墙。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其八","f":"七言律诗","c":["叶浓波澹好维舟，树底宜披五月裘。","守望客同巢鸟卧，买山人作橘奴收。","壶觞每就重阴布，攀摘都凭结驷游。","胜似虹蜺生落日，石尤风雨过枝头。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其九","f":"七言律诗","c":["王风蔓草已离离，岭海繁花记往时。","赤玉朱衣行月令，明珰翠羽系人思。","一丸满泛端阳酒，万颗轻悬续命丝。","谁是西川杜工部，妓船风浪也成诗。"]},{"t":"次和刘沛然王础尘广州荔枝词十首 其十","f":"七言律诗","c":["王逸当年未尽才，曲江能赋见风裁。","一时胜会逢吴客，七字题诗满粤台。","光焰只应燃火树，圆明端合长珠胎。","侧生诮后天门远，谁遗文章落上台。"]},{"t":"再次严藕渔中允韵送之归无锡四首 其一","f":"七言律诗","c":["京洛休论化素衣，今时能赋见人稀。","蓬蒿自可耽三径，羽猎谁为颂六飞。","几日炎威辞瘴岭，片帆秋色下苔矶。","茗香酒熟家林近，第二泉边事未非。"]},{"t":"再次严藕渔中允韵送之归无锡四首 其二","f":"七言律诗","c":["杜陵常怪汝曹催，孙子成行待舞莱。","野竹笋当家宴出，溪花香为主人回。","鹅归别沼求书去，鹤放高亭报客来。","自是蓬瀛仙伴侣，不妨垂钓任公台。"]},{"t":"再次严藕渔中允韵送之归无锡四首 其三","f":"七言律诗","c":["清露行将变火旻，新凉先已满江津。","数行白鸟非尘世，一路苍葭念故人。","诗谢铅华才愈老，史因游历识弥真。","谁怜皓首狂吟者，埽地山中学子春。"]},{"t":"再次严藕渔中允韵送之归无锡四首 其四","f":"七言律诗","c":["白驹空谷自难留，日日骊歌暮不休。","当暑正思河朔饮，闻琴将附洛阳舟。","拟乘筋力方衰候，尽补平生未及游。","燕赵齐秦俱有约，与君聊别此溪头。"]},{"t":"又次前韵送华子千四首 其一","f":"七言律诗","c":["适体初裁白葛衣，暑中归路客行稀。","曾深冀马空群望，却共南鹏六月飞。","虹报晚风横极浦，雨添新水漫前矶。","长途自足倡酬乐，旅泊劳劳未觉非。"]},{"t":"又次前韵送华子千四首 其二","f":"七言律诗","c":["西飞乌兔苦相催，少壮谁能卧草莱。","五岭远烦车骑至，一年刚及荔枝回。","诗多壮采从心得，笔挟烟岚入纸来。","高格近知加变幻，海滨新见蜃楼台。"]},{"t":"又次前韵送华子千四首 其三","f":"七言律诗","c":["沧江无畔接秋旻，去住寻常不问津。","东下鹭涛催鹢首，北来新雁迓归人。","心闲随地栖皆稳，木落诸峰梦亦真。","莫恋京华游侠窟，金台焦涸未成春。"]},{"t":"又次前韵送华子千四首 其四","f":"七言律诗","c":["炎州无事可淹留，远志知君不自休。","终古盘根资利器，百年吾道任虚舟。","高凰已识翱翔久，大雅谁歌泮奂游。","风雨后期何所定，一杯相别话从头。"]},{"t":"再次前韵送王文安四首 其一","f":"七言律诗","c":["老向京华著布衣，文心侠骨世应稀。","发同野鹤参差出，身似高云自在飞。","沧海路遥多酒伴，太湖家近有渔矶。","晨昏且喜莱衣是，岁月宁论伯玉非。"]},{"t":"再次前韵送王文安四首 其二","f":"七言律诗","c":["今古无端物数催，百年何处见伊莱。","烧残经术言非验，日下江河势不回。","墨守敢云坚壁在，火攻时为阿兄来。","天涯聚散宁容易，莫忘嵩台与汉台。"]},{"t":"再次前韵送王文安四首 其三","f":"七言律诗","c":["西山朝爽控青旻，鸲鹆岩边自得津。","蕉叶润于藏价玉，青花浮似泛萍人。","结髦刘主聊乘暇，好锻嵇生自性真。","一世未知磨几砚，石田开凿过千春。"]},{"t":"再次前韵送王文安四首 其四","f":"七言律诗","c":["归心逝水两难留，永夕衔杯咏未休。","吴楚暮山横数叠，女牛初月在扁舟。","舌存自足期他日，亲老宜能勿远游。","想拜北堂嘉庆后，秋溪新膳进槎头。"]},{"t":"次答苏友燕","f":"五言律诗","c":["老来常善忘，秋病复频年。","笔有千坟秃，胸无一字全。","嘉宾淮海俊，新句夜珠悬。","未遂投桃报，长江竟放船。"]},{"t":"送余信宜初芙","f":"七言律诗","c":["海峤无波郡邑劳，南溟真足养奇毛。","三年奏最珠官远，四字题名玉殿高。","会见鸣珂归侍从，近乘山屐到林皋。","每从良友瞻风义，侠气今时属四豪。"]},{"t":"海南云节母寿诗","f":"七言律诗","c":["八千里外儿寻母，四十年来母见儿。","昔日婴孩今已老，一时惊喜两成疑。","星分婺女光长在，海隔珠厓远不辞。","节孝令人生感激，老夫含泪纪新诗。"]},{"t":"送湛仲宜北上","f":"七言律诗","c":["科名往往在名门，三十年中见祖孙。","鹤和满庭方继响，凤雏新翼已高鶱。","逢时文字偏能老，弱冠年华好受恩。","会见五云生日下，太平天子正临轩。"]},{"t":"赠何东园铨部","f":"七言律诗","c":["四十年来海内名，西风衔命五羊城。","妍媸物象归金镜，进退星辰在玉衡。","高足渐看登要路，旧交犹自念狂生。","炎州秋后波涛浅，想见归舟似叶轻。"]},{"t":"赠陈嵩山观察","f":"七言律诗","c":["登坛三十足称雄，况为维桑立大功。","百战身存长啸外，千篇诗在古人中。","高牙令肃三山月，棨戟寒生五岭风。","海宇升平今偃武，文坛从此又推公。"]},{"t":"送李殿超北上","f":"七言律诗","c":["青山多处一峰尊，手著麟经日满轩。","廿载文坛推宿将，五花骢马自名门。","帆樯驿路新霜叶，冰雪关河旧屐痕。","虽是云边飞舄近，东风鹏翼好高鶱。"]},{"t":"元夜承徐蘋村郑珠江两太史见招以雨不得赴追和诸公韵","f":"七言律诗","c":["雨阻良宵欲树膺，春来佳事莫能承。","东南名俊同千里，师弟文章共一灯。","授简定多传世咏，不眠空似坐禅僧。","江城只尺生雷电，真信龙门未易登。"]},{"t":"文昌阁诗寄张西宁娄涿","f":"七言律诗","c":["三年相望眼犹青，千里音书问驿亭。","已尽南人归化雨，更开新阁礼文星。","地无高下春皆种，家有弦歌夜不扃。","想见使君闲更甚，清溪时倚画阑听。"]},{"t":"赠别何昭侯吏部","f":"五言古诗","c":["之子天下才，在我梦中久。","洎乎相见日，所叹皆白首。","浮云变古今，落月思良友。","示以录别诗，尚忆河梁手。","丈夫系气运，出处原非偶。","渭滨与首阳，异道同不苟。","勿以带女萝，而云傲章绶。","勿以居廊庙，而顾惭林薮。","济物有同心，愿君践台斗。"]},{"t":"再次前韵送徐方虎太史","f":"七言律诗","c":["江花如簇映钩膺，廿四春风片席承。","沧海尚悬丹阙梦，归程初泊石门灯。","橐中长物无过砚，卷里新诗半为僧。","七洞天前野人宅，几时携杖更同登。"]},{"t":"走笔送沈山隐","f":"五言律诗","c":["本为能赋客，书剑亦从军。","近逐随阳雁，天边恋旧群。","五车梁惠子，八咏沈休文。","好到京华日，题笺寄白云。"]},{"t":"次和王孝扬将军留别韵且以送行四首 其一","f":"五言律诗","c":["如何为此别，江上早潮生。","树是甘棠旧，军犹细柳名。","简书恭帝命，杯酒恋朋情。","便挂云帆去，高高隔玉京。"]},{"t":"次和王孝扬将军留别韵且以送行四首 其二","f":"五言律诗","c":["妙龄专节钺，经术历儒生。","星应三台座，期当五百名。","威能兼子惠，高亦近人情。","父老攀留意，犹思入帝京。"]},{"t":"次和王孝扬将军留别韵且以送行四首 其三","f":"五言律诗","c":["清标如玉树，四座觉风生。","语有超超目，居无赫赫名。","上天霖雨梦，九罭衮衣情。","北望张平子，为君赋二京。"]},{"t":"次和王孝扬将军留别韵且以送行四首 其四","f":"五言律诗","c":["开府重临日，当年岳降生。","千秋常自命，三十早成名。","奕世恩威地，童时钓弋情。","羊城非不恋，麟阁在西京。"]},{"t":"寄祝胡朝翰年伯","f":"七言律诗","c":["海隔红尘不闭门，东风携杖木棉温。","今时父辈人无几，先代遗民君独存。","霜雪满头肠自热，水天多浪昼常昏。","著书岂必沉吴井，韦氏传经有子孙。"]},{"t":"送李方水梁叠石两广文还琼州","f":"五言律诗","c":["不惮朱厓远，微官为老亲。","联翩渡海楫，去住倚闾人。","路迥分茅接，天开五指新。","及门方伫望，行矣及深春。"]},{"t":"送翟五吉令宣城","f":"七言律诗","c":["江城如画昔曾游，君去双旌正及秋。","百尺照心供奉水，一帘新雨谢公楼。","地多文藻今维烈，山足茶梨晚始收。","自有仁风扇浮俗，更看清誉满皇州。"]},{"t":"次答汪晋贤","f":"七言律诗","c":["绝无长处但疏慵，三径虚劳上客踪。","行傍野花同踯躅，坐依林竹笑龙钟。","诗能穷我宁论命，酒未忘忧且驻容。","犹喜秋来多快事，联珠贻赠屡开封。"]},{"t":"寄戴念庭三尊","f":"七言律诗","c":["经岁旌旗驻菊坡，罗浮秋色近如何。","三山仙路城头迥，四百名峰入座多。","更借寇君劳主眷，重临黄相起舆歌。","西风开宴调云母，彩服承欢佩绶过。"]},{"t":"重阳前二日李尚卿孝廉过坐晚成堂月下小饮同钟裴仙处士侄汝侯二儿赣励同赋","f":"七言律诗","c":["一杯留子坐更前，沙饭藜羹亦畅然。","节到重阳犹二日，人归万里是经年。","疏篱问菊方抽蕊，新月窥池欲上弦。","莫笑白头狂喜甚，从来风雅贵薪传。"]},{"t":"祝张盐宪二首 其一","f":"七言律诗","c":["父兄关内建侯封，帝用和羹说命重。","丹诏黄河盟一带，青霄华岳见三峰。","著书共许追班马，补阙曾闻侍衮龙。","昨月拜持旌节出，榻前天语赐从容。"]},{"t":"祝张盐宪二首 其二","f":"七言律诗","c":["南天鸿雁俨成行，东土篱花亦渐黄。","英岁未须论献寿，清秋唯报好飞觞。","小山招隐虚文藻，大雅维风属庙廊。","为问荆州张相国，部民谁是孟襄阳。"]},{"t":"客端州得王础尘书次其来韵二首 其一","f":"五言律诗","c":["故人期不至，落月在闲庭。","漫有高山奏，谁同永夕听。","雄文应彩笔，利器忆青萍。","莫但凭双鲤，寒江好放舲。"]},{"t":"客端州得王础尘书次其来韵二首 其二","f":"五言律诗","c":["荒鸡宜剑舞，伤雁怯弦惊。","岂谓方颓暮，犹闻事战争。","春从霜雪长，治以乱离生。","屈指论英俊，乾坤几老成。"]},{"t":"次答吴熙申","f":"七言律诗","c":["桃花源水渺无津，野艇江云是所亲。","宝剑历都逢季札，蓑衣垂钓有玄真。","交投缟纻同声旧，字挟烟岚赠句新。","词赋敢云淩鲍谢，千秋微尚或堪论。"]},{"t":"铙歌 其一","f":"七言绝句","c":["地北天南尽版图，幅员方广古来无。","太平只在修文德，枢府临边是大儒。"]},{"t":"铙歌 其二","f":"七言绝句","c":["两戒河山未易谙，汉关秦塞剩空谈。","而今声教通穷北，天下边防却在南。"]}]};